export function addDays(d: Date, n: number): Date {
  const r = new Date(d.getTime())
  r.setDate(r.getDate() + n)
  return r
}

export type AddInput = {
  source: ProposalSource
  title?: string
  id?: string
  proposals: ReadonlyArray<ProposalInput>
}

export function addMonths(d: Date, n: number): Date {
  const day = d.getDate()
  const r = new Date(d.getFullYear(), d.getMonth() + n, 1, d.getHours(), d.getMinutes(), d.getSeconds(), d.getMilliseconds())
  r.setDate(Math.min(day, daysInMonth(r)))
  return r
}

export function addPaneToMain(state: DockManagerState, p: DockPane, genId: IdGen): DockManagerState {
  if (!state.main) return { ...state, main: tabs(genId, [p], 0) }
  let added = false
  const walk = (n: DockNode): DockNode => {
    if (added) return n
    if (n.type === 'tabs') {
      added = true
      const panes = [...n.panes, p]
      return { ...n, panes, active: panes.length - 1 }
    }
    return { ...n, children: n.children.map(walk) }
  }
  return { ...state, main: walk(state.main) }
}

export function addYears(d: Date, n: number): Date {
  return addMonths(d, n * 12)
}

export type AdvancedFilterCompileContext<TRow> = {
  /**
   * Resolve a column id to its cell value for a row. The grid passes the same
   * accessor the column-menu filter stage uses, so a `cmp` on a `fieldFn` or
   * value-getter column resolves identically in both.
   */
  getValue: (row: TRow, columnId: string) => unknown
  /** Locale for text folding, matching the column filters. */
  locale?: string | ReadonlyArray<string>
  /**
   * The rows entering this stage. Aggregates (`SUM(amount) > 1000`) are folded
   * over exactly these, once, so they see the rows the user is currently
   * looking at rather than the raw dataset.
   */
  rows: ReadonlyArray<TRow>
}

export type AdvancedFilterEngine = <TRow>(
  expr: GridPredicateExpr,
  ctx: AdvancedFilterCompileContext<TRow>,
) => CompiledRowPredicate<TRow> | null

export type AgendaGroup<TData = unknown> = {
  day: Date
  events: ResolvedEvent<TData>[]
}

export function agendaGroups<TData>(
  events: ReadonlyArray<ResolvedEvent<TData>>,
): AgendaGroup<TData>[] {
  const groups: AgendaGroup<TData>[] = []
  for (const e of [...events].sort((a, b) => a.start.getTime() - b.start.getTime())) {
    const last = groups[groups.length - 1]
    if (last && isSameDay(last.day, e.start)) last.events.push(e)
    else groups.push({ day: startOfDay(e.start), events: [e] })
  }
  return groups
}

