export async function aiClassify<
  TFeatures extends TableFeatures,
  TData extends RowData,
>(
  api: AIRowSource<TFeatures, TData>,
  opts: AIClassifyOptions,
): Promise<AIClassifyResult> {
  const data = api.getData()
  const targets = opts.targetRowIndices ?? data.map((_, i) => i)
  const rubric = opts.classDescriptions
    ? Object.entries(opts.classDescriptions)
        .map(([k, v]) => `- ${k}: ${v}`)
        .join('\n')
    : opts.classes.map((c) => `- ${c}`).join('\n')

  const rowsBlock = targets
    .map((i) => `Row ${i}: ${JSON.stringify((data[i] as Record<string, unknown>)?.[opts.inputField] ?? '')}`)
    .join('\n')

  const prompt =
    `You are a strict text classifier. For each row, pick exactly one ` +
    `label from the list. If unsure, pick the closest match and lower the ` +
    `confidence.\n\n` +
    `Allowed labels (with optional rubric):\n${rubric}\n\n` +
    `Rows to classify (text from column "${opts.inputField}"):\n${rowsBlock}\n\n` +
    `Return strict JSON only:\n` +
    `{ "predictions": [{"rowIndex": <number>, "value": "<label>", "confidence": <0..1>}] }`

  const result = await callJSON<{
    predictions: Array<{ rowIndex: number; value: string; confidence: number }>
  }>({
    prompt,
    task: 'classify',
    signal: opts.signal,
    maxOutputTokens: Math.min(2000, 30 + targets.length * 30),
  })

  const allowed = new Set(opts.classes)
  return {
    inputField: opts.inputField,
    outputField: opts.outputField,
    predictions: (result.predictions ?? []).filter((p) => allowed.has(p.value)),
  }
}

export type AIClassifyOptions = {
  /** Column whose free-text we're classifying. */
  inputField: string
  /** Target column the model should write to. */
  outputField: string
  /** Allowed values. The model is constrained to pick one. */
  classes: string[]
  /** Optional one-line description of each class (acts as a labeling rubric). */
  classDescriptions?: Record<string, string>
  /** Rows to classify. Defaults to all. */
  targetRowIndices?: number[]
  signal?: AbortSignal
}

export type AIClassifyResult = {
  inputField: string
  outputField: string
  predictions: Array<{ rowIndex: number; value: string; confidence: number }>
}

export async function aiExplainChart<
  TFeatures extends TableFeatures,
  TData extends RowData,
>(api: SvGridApi<TFeatures, TData>, opts: AIExplainChartOptions = {}): Promise<AIChartExplanation> {
  const spec = opts.spec ?? (api as unknown as { getChartSpec?: () => ChartSpec | null }).getChartSpec?.() ?? null
  if (!spec) return { summary: 'No chart to explain.', insights: [] }
  const summary = chartSummary(spec)
  const cats = spec.categories.slice(0, 50)
  const table = cats.length
    ? `${['category', ...spec.series.map((s) => s.label)].join('\t')}\n` +
      cats.map((c, i) => [c, ...spec.series.map((s) => String(s.values[i] ?? ''))].join('\t')).join('\n')
    : ''
  const prompt =
    `You are explaining a ${spec.type} chart to a busy reader.\n\n` +
    `Reading of the chart: ${summary}\n\n` +
    (table ? `Data (first ${cats.length} categories, tab separated):\n${table}\n\n` : '') +
    `Return strict JSON only: { "insights": ["<2-3 short observations a reader would miss at a glance: comparisons, outliers, what to look at next>"] }`
  const out = await callJSON<{ insights?: unknown }>({ prompt, task: 'explain-chart', signal: opts.signal, maxOutputTokens: 300 })
  const insights = Array.isArray(out.insights) ? out.insights.filter((x): x is string => typeof x === 'string').slice(0, 3) : []
  return { summary, insights }
}

export type AIExplainChartOptions = {
  /** The spec to explain. Default: the grid panel's active chart. */
  spec?: ChartSpec
  signal?: AbortSignal
}

export async function aiExport<
  TFeatures extends TableFeatures,
  TData extends RowData,
>(
  api: SvGridApi<TFeatures, TData>,
  query: string,
  opts: AIExportOptions = {},
): Promise<AIExportPlan> {
  const schema = buildColumnSchema(api)
  const prompt =
    `You are an export assistant for a data grid. Translate the user's request ` +
    `into a strict-JSON export plan.\n\n` +
    `Columns:\n${schemaToPromptBlock(schema)}\n\n` +
    `Output JSON schema:\n` +
    `{ "format": "xlsx"|"xls"|"pdf"|"csv"|"tsv"|"html"|"json"|"xml"|"md", ` +
    `"filters": [{"field":"<column>","operator":"contains"|"equals"|"startsWith"|"greaterThan"|"lessThan"|"isBlank","value":"<string>"}], ` +
    `"sort": [{"field":"<column>","desc":true|false}], ` +
    `"groupBy": ["<column>"], ` +
    `"rationale": "<one sentence>" }\n\n` +
    `Rules: use the format the user names (default "xlsx"); only use column ` +
    `names from the list above; "grouped" / "group by X" -> groupBy. ` +
    `Return JSON only, no prose.\n\n` +
    `User request: ${query}`

  const plan = await callJSON<AIExportPlan>({
    prompt,
    task: 'export',
    signal: opts.signal,
    maxOutputTokens: 500,
  })

  // Defensive validation - drop invented fields, clamp the format.
  const valid = new Set(schema.map((c) => c.field))
  plan.format = EXPORT_FORMATS.includes(plan.format) ? plan.format : 'xlsx'
  plan.filters = (plan.filters ?? []).filter((f) => valid.has(f.field))
  plan.sort = (plan.sort ?? []).filter((s) => valid.has(s.field))
  plan.groupBy = (plan.groupBy ?? []).filter((g) => valid.has(g))
  plan.rationale = plan.rationale ?? ''

  // Optionally mirror the plan onto the grid (opt-in). Off by default so the
  // export never disturbs the user's current view.
  if (opts.apply === true) {
    api.clearAllFilters()
    api.clearSort()
    for (const f of plan.filters) {
      api.setFilter(f.field, { operator: f.operator, value: f.value ?? '' })
    }
    const last = plan.sort[plan.sort.length - 1]
    if (last) api.setSort(last.field, last.desc ? 'desc' : 'asc')
    if (plan.groupBy.length > 0) {
      try {
        api.setGroupBy(plan.groupBy)
      } catch {
        // grouping feature not enabled - the export still groups on its own
      }
    }
  }

  // Planning is always free; WRITING the file uses the export engine registered
  // by @svgrid/enterprise (export-provider seam). Without it, we return the plan
  // so the UI can still show what the AI decided - the download just no-ops.
  const runExport = getExportProvider()
  if (opts.run !== false && runExport) {
    // Compute the export rows from the plan directly (filter + sort + make
    // contiguous by group) rather than reading the grid's reactive displayed
    // rows - so the download always has exactly the intended data.
    const exportRows = applyPlanToRows(api.getData(), plan)
    await runExport(api, {
      format: plan.format,
      filename: opts.filename ?? 'export',
      rows: exportRows,
      ...(plan.groupBy.length > 0 ? { groupBy: plan.groupBy } : {}),
    })
  }
  return plan
}

export type AIExportOptions = {
  /**
   * Also apply the filter / sort / grouping to the grid (mutating the view) so
   * it mirrors the export. Default FALSE - the export is self-contained (it
   * computes its own rows), so the grid is left untouched unless you opt in.
   */
  apply?: boolean
  /** Actually download the file. Default true; set false to preview the plan. */
  run?: boolean
  /** Base filename (no extension). Default 'export'. */
  filename?: string
  signal?: AbortSignal
}

export type AIExportPlan = {
  format: ExportFormat
  filters: AIFilterClause[]
  sort: AISortClause[]
  groupBy: string[]
  /** Plain-English explanation of how the model read the request. */
  rationale: string
}

export async function aiFilter<
  TFeatures extends TableFeatures,
  TData extends RowData,
>(
  api: AIRowSource<TFeatures, TData>,
  query: string,
  opts: AIFilterOptions = {},
): Promise<AIFilterResult> {
  const schema = buildColumnSchema(api)
  const prompt =
    `You are a data-grid filter planner. Translate the user's natural-language ` +
    `query into a strict-JSON plan that the grid can apply.\n\n` +
    `Columns:\n${schemaToPromptBlock(schema)}\n\n` +
    `Output JSON schema:\n` +
    `{ "filters": [{"field": "<one of the columns above>", ` +
    `"operator": "contains"|"equals"|"startsWith"|"greaterThan"|"lessThan"|"isBlank", ` +
    `"value": "<string>"}], ` +
    `"sort": [{"field": "<column>", "desc": true|false}], ` +
    `"rationale": "<one-sentence explanation>" }\n\n` +
    `User query: ${query}\n\n` +
    `Return JSON only, no prose.`

  const result = await callJSON<AIFilterResult>({
    prompt,
    task: 'filter',
    signal: opts.signal,
    maxOutputTokens: 400,
  })

  // Defensive: drop anything that doesn't match a real column. Models love
  // to invent plausible-sounding field names; we'd rather skip a clause
  // than throw at runtime.
  const valid = new Set(schema.map((c) => c.field))
  result.filters = (result.filters ?? []).filter((f) => valid.has(f.field))
  result.sort = (result.sort ?? []).filter((s) => valid.has(s.field))

  if (opts.apply) {
    if (!isGridApi(api)) throw new Error('aiFilter: apply needs the grid api, not a { getData } row source')
    api.clearAllFilters()
    api.clearSort()
    for (const f of result.filters) {
      api.setFilter(f.field, { operator: f.operator, value: f.value ?? '' })
    }
    // Multiple sort clauses get applied last-wins because the public
    // `setSort` is single-key. Multi-sort is on the roadmap.
    const last = result.sort[result.sort.length - 1]
    if (last) api.setSort(last.field, last.desc ? 'desc' : 'asc')
  }

  return result
}

export type AIFilterClause = {
  field: string
  operator: 'contains' | 'equals' | 'startsWith' | 'greaterThan' | 'lessThan' | 'isBlank'
  value?: string
}

export type AIFilterOptions = {
  /**
   * When true, the helper not only RETURNS the plan but also applies it
   * to the grid via `api.setFilter` / `api.setSort`. Defaults to false
   * so callers can show a preview before committing.
   */
  apply?: boolean
  signal?: AbortSignal
}

export type AIFilterResult = {
  filters: AIFilterClause[]
  sort: AISortClause[]
  /** Plain-English explanation of how the model interpreted the query.
   *  Surface this in the UI so the user can confirm or undo. */
  rationale: string
}

export async function aiFindAnomalies<
  TFeatures extends TableFeatures,
  TData extends RowData,
>(
  api: AIRowSource<TFeatures, TData>,
  opts: AIAnomalyOptions = {},
): Promise<AIAnomalyResult> {
  const rows = sliceForTarget(api, opts.target ?? { kind: 'all' })
  if (rows.length === 0) return { anomalies: [], summary: 'No rows in scope.' }

  const MAX_SAMPLE = 40
  const sample =
    rows.length <= MAX_SAMPLE
      ? rows
      : Array.from(
          { length: MAX_SAMPLE },
          (_, i) => rows[Math.floor((i / MAX_SAMPLE) * rows.length)]!,
        )

  const schema = buildColumnSchema(api, 30)
  const prompt =
    `You are a data-quality analyst. Scan the rows below for anomalies: ` +
    `numeric outliers, impossible / inconsistent values, unexpected blanks, ` +
    `and values that break the pattern of the column.\n\n` +
    `Columns:\n${schemaToPromptBlock(schema)}\n\n` +
    `Rows (index is 0-based into this list):\n` +
    `${sample.map((r, i) => `${i}: ${JSON.stringify(r)}`).join('\n')}\n\n` +
    (opts.question ? `Focus: ${opts.question}\n\n` : '') +
    `Return strict JSON only:\n` +
    `{ "anomalies": [{"rowIndex": <number|null>, "field": "<column|null>", ` +
    `"reason": "<why it's odd>", "severity": "low"|"medium"|"high"}], ` +
    `"summary": "<one sentence>" }`

  const result = await callJSON<AIAnomalyResult>({
    prompt,
    task: 'anomaly',
    signal: opts.signal,
    maxOutputTokens: 800,
  })
  return {
    anomalies: result.anomalies ?? [],
    summary: result.summary ?? '',
  }
}

export type AIRequest = {
  /** Full prompt the grid built for the model. Already includes column
   *  schema and any sampled rows where applicable. */
  prompt: string
  /** When 'json', the provider should ask the model to return strict
   *  JSON only - no prose. We parse the response with JSON.parse and
   *  throw a typed error on failure. */
  responseFormat?: 'text' | 'json'
  /** Honored if the underlying transport supports cancellation. */
  signal?: AbortSignal
  /** Free-form tag for telemetry / logging. One of: 'filter',
   *  'smart-fill', 'summarize', 'classify'. */
  task: AITask
  /** Soft hint to the provider about how many tokens we expect back.
   *  Useful for routing small jobs to a cheaper model. */
  maxOutputTokens?: number
}

export async function aiSmartFill<
  TFeatures extends TableFeatures,
  TData extends RowData,
  TValue = unknown,
>(
  api: AIRowSource<TFeatures, TData>,
  opts: AISmartFillOptions,
): Promise<AISmartFillResult<TValue>> {
  if (opts.examples.length === 0) {
    throw new Error('@svgrid/grid ai: aiSmartFill requires at least one example.')
  }
  const data = api.getData()
  const targets =
    opts.targetRowIndices ??
    data
      .map((row, i) => {
        const v = (row as Record<string, unknown>)[opts.field]
        return v == null || v === '' ? i : -1
      })
      .filter((i) => i >= 0)

  if (targets.length === 0) {
    return { field: opts.field, predictions: [], rationale: 'No empty cells to fill.' }
  }

  const examplesBlock = opts.examples
    .map((ex, i) => `Example ${i + 1}: input=${JSON.stringify(ex.input)} -> output=${JSON.stringify(ex.output)}`)
    .join('\n')

  const targetRowsBlock = targets
    .map((i) => `Row ${i}: ${JSON.stringify(data[i])}`)
    .join('\n')

  const prompt =
    `You are filling in a single column of a data grid based on user-provided ` +
    `examples. Match the pattern in the examples exactly.\n\n` +
    `Target column: ${opts.field}\n\n` +
    `Examples:\n${examplesBlock}\n\n` +
    `Rows to fill:\n${targetRowsBlock}\n\n` +
    `Return strict JSON only:\n` +
    `{ "predictions": [{"rowIndex": <number>, "value": <inferred value>, ` +
    `"confidence": <0..1>}], "rationale": "<one-sentence pattern description>" }`

  const result = await callJSON<{
    predictions: Array<{ rowIndex: number; value: TValue; confidence: number }>
    rationale: string
  }>({
    prompt,
    task: 'smart-fill',
    signal: opts.signal,
    maxOutputTokens: 600,
  })

  return {
    field: opts.field,
    predictions: result.predictions ?? [],
    rationale: result.rationale ?? '',
  }
}

export type AISmartFillOptions = {
  /** Target column - the one whose values we want filled. */
  field: string
  /** Index of rows the model should propose values for. If omitted, every
   *  row whose current `field` value is `null`, `undefined` or `''` is
   *  selected automatically. */
  targetRowIndices?: number[]
  /**
   * Worked examples the user has already filled in. Required - the
   * model needs at least one to know the pattern, two or more to lock
   * the schema. We don't pull these from the grid automatically because
   * "edited" vs "untouched" isn't a state SvGrid exposes today.
   */
  examples: AISmartFillExample[]
  signal?: AbortSignal
}

export type AISmartFillResult<TValue = unknown> = {
  field: string
  predictions: Array<{ rowIndex: number; value: TValue; confidence: number }>
  rationale: string
}

export async function aiSummarize<
  TFeatures extends TableFeatures,
  TData extends RowData,
>(
  api: AIRowSource<TFeatures, TData>,
  opts: AISummarizeOptions,
): Promise<AISummary> {
  const all = api.getData()
  const rows: TData[] = (() => {
    const t = opts.target
    if (t.kind === 'row') {
      const r = all[t.rowIndex]
      return r ? [r] : []
    }
    if (t.kind === 'selection') {
      return t.rowIndices.map((i) => all[i]).filter((r): r is TData => r != null)
    }
    if (t.kind === 'group') {
      return all.filter((r) => (r as Record<string, unknown>)[t.field] === t.value)
    }
    return all.slice()
  })()

  if (rows.length === 0) {
    return { text: 'No rows in scope.', bullets: [], highlightedFields: [] }
  }

  // Uniform sample to stay inside a sensible context budget.
  const MAX_SAMPLE = 25
  const sample = rows.length <= MAX_SAMPLE
    ? rows
    : Array.from({ length: MAX_SAMPLE }, (_, i) => rows[Math.floor((i / MAX_SAMPLE) * rows.length)]!)

  const schema = buildColumnSchema(api, 30)
  const prompt =
    `You are summarising a slice of a business data grid for a busy analyst.\n\n` +
    `Columns:\n${schemaToPromptBlock(schema)}\n\n` +
    `Slice size: ${rows.length} row(s). Sampled rows shown below.\n` +
    `${sample.map((r) => JSON.stringify(r)).join('\n')}\n\n` +
    (opts.question ? `User's question: ${opts.question}\n\n` : '') +
    `Return strict JSON only:\n` +
    `{ "text": "<one short paragraph>", ` +
    `"bullets": ["<3-5 punchy bullets>"], ` +
    `"highlightedFields": ["<column names the summary leans on>"] }`

  const result = await callJSON<AISummary>({
    prompt,
    task: 'summarize',
    signal: opts.signal,
    maxOutputTokens: 600,
  })
  return {
    text: result.text ?? '',
    bullets: result.bullets ?? [],
    highlightedFields: result.highlightedFields ?? [],
  }
}

export type AISummarizeOptions = {
  target: AISummarizeTarget
  /** Optional question the user is trying to answer. Helps the model
   *  bias the summary toward the relevant columns. */
  question?: string
  signal?: AbortSignal
}

export type AISummarizeTarget =
  | { kind: 'row'; rowIndex: number }
  | { kind: 'all' }
  | { kind: 'selection'; rowIndices: number[] }
  | { kind: 'group'; field: string; value: unknown }

export type AISummary = {
  text: string
  bullets: string[]
  /** Field names the model thinks are the most load-bearing for the
   *  story it just told. UI can highlight those columns. */
  highlightedFields: string[]
}

export function allManagerIds(state: DockManagerState): string[] {
  const ids: string[] = []
  const walk = (n: DockNode) => {
    ids.push(n.id)
    if (n.type === 'tabs') for (const p of n.panes) ids.push(p.id)
    else for (const c of n.children) walk(c)
  }
  if (state.main) walk(state.main)
  for (const w of state.floating) { ids.push(w.id); walk(w.leaf) }
  for (const e of state.autoHide) { ids.push(e.id); walk(e.leaf) }
  return ids
}

export function allManagerPaneIds(state: DockManagerState): string[] {
  const ids: string[] = []
  if (state.main) ids.push(...allPaneIds(state.main))
  for (const w of state.floating) ids.push(...w.leaf.panes.map((p) => p.id))
  for (const e of state.autoHide) ids.push(...e.leaf.panes.map((p) => p.id))
  return ids
}

export function allPaneIds(root: DockNode): string[] {
  if (root.type === 'tabs') return root.panes.map((p) => p.id)
  return root.children.flatMap(allPaneIds)
}

export function appendPoints(spec: ChartSpec, points: ChartPoint | ReadonlyArray<ChartPoint>, opts: AppendPointsOptions = {}): ChartSpec {
  const list = Array.isArray(points) ? (points as ReadonlyArray<ChartPoint>) : [points as ChartPoint]
  if (!list.length) return opts.window ? trim(spec, opts.window) : spec
  const categories = [...spec.categories, ...list.map((p) => p.category)]
  const ohlcOwner = spec.series.findIndex((s) => s.ohlc)
  const series = spec.series.map((s, si) => {
    const next: ChartSeries = { ...s, values: [...s.values] }
    for (const p of list) {
      const v = Array.isArray(p.values) ? (p.values as ReadonlyArray<number>)[si] : (p.values as Record<string, number>)[s.label]
      next.values.push(typeof v === 'number' ? v : Number.NaN)
    }
    for (const key of PER_CATEGORY_SERIES_KEYS) {
      if (key === 'values') continue
      const has = s[key] !== undefined
      // A key the series does not carry is only created when a point brings
      // it (a candle, a volume), so a plain line stays a plain line.
      const brings = list.some((p) =>
        (key === 'ohlc' && p.ohlc !== undefined && si === (ohlcOwner < 0 ? 0 : ohlcOwner)) ||
        (key === 'volumes' && p.volume !== undefined && si === (ohlcOwner < 0 ? 0 : ohlcOwner)) ||
        (key === 'rowIds' && p.rowIds?.[si] !== undefined) ||
        (key === 'upperValues' && p.upper?.[si] !== undefined) ||
        (key === 'lowerValues' && p.lower?.[si] !== undefined) ||
        (key === 'lowValues' && p.low?.[si] !== undefined) ||
        (key === 'targets' && p.target?.[si] !== undefined))
      if (!has && !brings) continue
      const base: unknown[] = has ? [...(s[key] as unknown[])] : new Array(s.values.length).fill(gapFor(key))
      for (const p of list) {
        let v: unknown = undefined
        if (key === 'ohlc' && si === (ohlcOwner < 0 ? 0 : ohlcOwner)) v = p.ohlc
        else if (key === 'volumes' && si === (ohlcOwner < 0 ? 0 : ohlcOwner)) v = p.volume
        else if (key === 'rowIds') v = p.rowIds?.[si]
        else if (key === 'upperValues') v = p.upper?.[si]
        else if (key === 'lowerValues') v = p.lower?.[si]
        else if (key === 'lowValues') v = p.low?.[si]
        else if (key === 'targets') v = p.target?.[si]
        base.push(v === undefined ? gapFor(key) : v)
      }
      ;(next as unknown as Record<string, unknown>)[key] = base
    }
    return next
  })
  let out: ChartSpec = { ...spec, categories, series }
  for (const key of PER_CATEGORY_SPEC_KEYS) {
    const arr = spec[key] as unknown[] | undefined
    if (arr) (out as unknown as Record<string, unknown>)[key] = [...arr, ...list.map(() => false)]
  }
  if (opts.window) out = trim(out, opts.window)
  return out
}

export type AppendPointsOptions = {
  /** Keep only the last `window` categories after appending. */
  window?: number
}

export function applyChartFormat(spec: ChartSpec, format: ChartFormatState | null | undefined): ChartSpec {
  if (!format) return spec
  const out: ChartSpec = { ...spec }
  if (format.title !== undefined) out.title = format.title || undefined
  if (format.subtitle !== undefined) out.subtitle = format.subtitle || undefined
  if (format.caption !== undefined) out.caption = format.caption || undefined
  if (format.palette) out.palette = format.palette
  if (format.seriesLabels !== undefined) out.seriesLabels = format.seriesLabels
  if (format.style) out.style = { ...spec.style, ...format.style }
  if (format.compactBelow != null && format.compactBelow > 0) {
    out.responsive = [...(spec.responsive ?? []), CHART_RESPONSIVE_PRESETS.compact(format.compactBelow)]
  }
  const axis = (base: ChartAxisConfig | undefined, f: NonNullable<ChartFormatState['yAxis']> | undefined): ChartAxisConfig | undefined => {
    if (!f) return base
    const next: ChartAxisConfig = { ...base }
    if (f.min !== undefined) { if (f.min === null) delete next.min; else next.min = f.min }
    if (f.max !== undefined) { if (f.max === null) delete next.max; else next.max = f.max }
    if (f.title !== undefined) next.title = f.title || undefined
    if (f.gridLines !== undefined) next.gridLines = f.gridLines
    if (f.format !== undefined) next.format = f.format
    return next
  }
  if (format.xAxis) {
    const next: ChartAxisConfig = { ...out.xAxis }
    if (format.xAxis.title !== undefined) next.title = format.xAxis.title || undefined
    if (format.xAxis.gridLines !== undefined) next.gridLines = format.xAxis.gridLines
    if (format.xAxis.labelRotation !== undefined) next.labelRotation = format.xAxis.labelRotation
    out.xAxis = next
  }
  if (format.yAxis) out.yAxis = axis(out.yAxis, format.yAxis)
  if (format.y2Axis) out.y2Axis = axis(out.y2Axis, format.y2Axis)
  if (format.series) {
    out.series = spec.series.map((s) => {
      const f = format.series![s.label]
      if (!f) return s
      const next: ChartSeries = { ...s }
      if (f.color) next.color = f.color
      if (f.type) next.type = f.type
      if (f.axis) next.axis = f.axis
      if (f.marker) next.marker = f.marker
      if (f.strokeWidth !== undefined) next.strokeWidth = f.strokeWidth
      if (f.dash !== undefined) next.dash = f.dash || undefined
      if (f.smooth !== undefined) next.smooth = f.smooth
      if (f.stack !== undefined) next.stack = f.stack || undefined
      return next
    })
  }
  return out
}

export function applyGroupAggregate<TData extends RowData>(
  agg: GroupAggregator<TData>,
  columnId: string,
  rows: ReadonlyArray<Row<TData>>,
): unknown {
  // One pass, no intermediate arrays.
  //
  // This used to build a `raw` array, then a coerced one, then a filtered one -
  // three allocations per aggregated column PER GROUP - before reducing. On a
  // 100k-row grid grouped two levels deep, aggregation was about two thirds of
  // the total grouping cost (213ms with three aggregators against 81ms with
  // none), and each additional aggregated column added roughly 80ms.
  //
  // `count` first: it never needs to look at a value at all.
  if (agg === 'count') return rows.length

  if (agg === 'first') {
    return rows.length ? rows[0]!.getCellValueByColumnId(columnId) : undefined
  }

  if (agg === 'countDistinct') {
    const seen = new Set<string>()
    for (const row of rows) seen.add(String(row.getCellValueByColumnId(columnId) ?? ''))
    return seen.size
  }

  if (typeof agg === 'function') {
    // Custom aggregators keep their contract: the finite numbers, then the
    // original row objects. Note `Number(null)` is 0 and therefore finite, so
    // nulls DO reach the callback as zeros - long-standing behaviour.
    const nums: number[] = []
    for (const row of rows) {
      const n = Number(row.getCellValueByColumnId(columnId))
      if (Number.isFinite(n)) nums.push(n)
    }
    return agg(nums, rows.map((r) => r.original))
  }

  // sum / avg / min / max / extent share one accumulation pass.
  let count = 0
  let sum = 0
  let min = Infinity
  let max = -Infinity
  for (const row of rows) {
    const n = Number(row.getCellValueByColumnId(columnId))
    if (!Number.isFinite(n)) continue
    count++
    // Left-to-right, matching the previous `reduce`, so float rounding is
    // bit-identical rather than merely close.
    sum += n
    // Math.min/max on scalars rather than `<`, which differs on -0, and rather
    // than the old `Math.min(...nums)` - spreading a whole group throws
    // RangeError once the bucket is big enough to exhaust the argument stack.
    min = Math.min(min, n)
    max = Math.max(max, n)
  }
  if (!count) return undefined
  switch (agg) {
    case 'sum':
      return sum
    case 'avg':
      return sum / count
    case 'min':
      return min
    case 'max':
      return max
    case 'extent':
      return `${min} – ${max}`
    default:
      return undefined
  }
}

export function applyMask(value: string, pattern: string): { formatted: string; filled: number } {
  let out = ''
  let vi = 0
  let filled = 0
  for (let pi = 0; pi < pattern.length; pi++) {
    const token = pattern[pi]!
    if (!isToken(token)) {
      // Literal: emit it only once we have (or will have) more input to place.
      out += token
      // Skip a matching literal the user may have typed.
      if (value[vi] === token) vi++
      continue
    }
    // Advance through input until a char fits this token.
    while (vi < value.length && !matches(token, value[vi]!)) vi++
    if (vi >= value.length) break // no more input for this token
    out += value[vi]!
    vi++
    filled++
  }
  // Drop any trailing literals with no following data char.
  return { formatted: trimTrailingLiterals(out), filled }
}

export function applyRowPredicate<TRow>(
  rows: ReadonlyArray<TRow>,
  keep: (row: TRow) => boolean,
  isGroup: (row: TRow) => boolean,
): TRow[] {
  // Fast path: no grouping in play, so every row is a leaf.
  let hasGroup = false
  for (const row of rows) {
    if (isGroup(row)) {
      hasGroup = true
      break
    }
  }
  if (!hasGroup) return rows.filter(keep)

  // Any leaf under a banner, through its subRows (the banner is collapsed).
  const anyLeaf = (row: TRow): boolean =>
    ((row as Tree<TRow>).subRows ?? []).some((sub) => (isGroup(sub) ? anyLeaf(sub) : keep(sub)))

  // One forward pass. `open` holds the banners above the current row; a kept
  // row keeps every one of them, and only them.
  const keepFlags = new Array<boolean>(rows.length).fill(false)
  const open: number[] = []
  const keepOpen = () => {
    for (let k = open.length - 1; k >= 0 && !keepFlags[open[k]!]; k -= 1) keepFlags[open[k]!] = true
  }
  for (let i = 0; i < rows.length; i += 1) {
    const row = rows[i]!
    const depth = depthOf(row)
    while (open.length && depthOf(rows[open[open.length - 1]!]) >= depth) open.pop()
    if (isGroup(row)) {
      open.push(i)
      const next = rows[i + 1]
      const collapsed = next === undefined || depthOf(next) <= depth
      if (collapsed && anyLeaf(row)) keepOpen()
    } else if (keep(row)) {
      keepFlags[i] = true
      keepOpen()
    }
  }

  const out: TRow[] = []
  for (let i = 0; i < rows.length; i += 1) if (keepFlags[i]) out.push(rows[i]!)
  return out
}

export function arcPath(cx: number, cy: number, r0: number, r1: number, a0: number, a1: number): string {
  const TAU = Math.PI * 2
  const span = Math.max(0, Math.min(TAU, a1 - a0))
  if (span <= 0 || r1 <= 0) return ''
  const px = (r: number, a: number) => `${round(cx + r * Math.cos(a))},${round(cy + r * Math.sin(a))}`
  if (span >= TAU - 1e-6) {
    // Two half-arcs, because a single arc cannot describe a full circle.
    const outer = `M${px(r1, a0)} A${round(r1)},${round(r1)} 0 1 1 ${px(r1, a0 + Math.PI)} A${round(r1)},${round(r1)} 0 1 1 ${px(r1, a0)} Z`
    if (r0 <= 0) return outer
    return `${outer} M${px(r0, a0)} A${round(r0)},${round(r0)} 0 1 0 ${px(r0, a0 + Math.PI)} A${round(r0)},${round(r0)} 0 1 0 ${px(r0, a0)} Z`
  }
  const large = span > Math.PI ? 1 : 0
  if (r0 <= 0) {
    return `M${round(cx)},${round(cy)} L${px(r1, a0)} A${round(r1)},${round(r1)} 0 ${large} 1 ${px(r1, a1)} Z`
  }
  return (
    `M${px(r1, a0)} A${round(r1)},${round(r1)} 0 ${large} 1 ${px(r1, a1)} ` +
    `L${px(r0, a1)} A${round(r0)},${round(r0)} 0 ${large} 0 ${px(r0, a0)} Z`
  )
}

export function atr(ohlc: ReadonlyArray<OhlcBar | null | undefined>, period = 14): number[] {
  const n = ohlc.length
  const p = Math.max(1, Math.floor(period))
  const out = nanArray(n)
  if (n < p) return out
  let sum = 0
  for (let i = 0; i < p; i += 1) {
    const tr = trueRange(ohlc, i)
    if (!Number.isFinite(tr)) return out
    sum += tr
  }
  let prev = sum / p
  out[p - 1] = prev
  for (let i = p; i < n; i += 1) {
    const tr = trueRange(ohlc, i)
    if (!Number.isFinite(tr)) { out[i] = Number.NaN; continue }
    prev = (prev * (p - 1) + tr) / p
    out[i] = prev
  }
  return out
}

export type AutoHideEntry = {
  id: string
  side: DockSide
  leaf: DockTabs
  /** Fly-out panel size in px along the reveal axis. */
  size: number
}

export function autoHideLeaf(
  state: DockManagerState,
  tabsId: string,
  side: DockSide,
  size = 260,
): DockManagerState {
  if (!state.main) return state
  const { root, leaf } = removeLeaf(state.main, tabsId)
  if (!leaf) return state
  const entry: AutoHideEntry = { id: `ah-${tabsId}`, side, leaf, size }
  return { ...state, main: root, autoHide: [...state.autoHide, entry] }
}

export function autoHidePaneToSide(
  state: DockManagerState,
  paneId: string,
  side: DockSide,
  genId: IdGen,
  size = 260,
): DockManagerState {
  const moving = findPaneObject(state, paneId)
  if (!moving) return state
  const stripped = stripPane(state, paneId)
  const entry: AutoHideEntry = { id: genId(), side, leaf: tabs(genId, [moving], 0), size }
  return { ...stripped, autoHide: [...stripped.autoHide, entry] }
}

export function autoHideWindow(
  state: DockManagerState,
  windowId: string,
  side: DockSide,
  genId: IdGen,
  size = 260,
): DockManagerState {
  const w = state.floating.find((f) => f.id === windowId)
  if (!w) return state
  const entry: AutoHideEntry = { id: genId(), side, leaf: tabs(genId, w.leaf.panes, w.leaf.active), size }
  return { ...state, floating: state.floating.filter((f) => f.id !== windowId), autoHide: [...state.autoHide, entry] }
}

export function autoMapColumns(
  headers: string[],
  columns: ReadonlyArray<ImportGridColumn>,
): ImportColumnMap {
  const byKey = new Map<string, string>()
  for (const c of columns) {
    const field = c.field ?? c.header
    if (!field) continue
    // Field name is the strongest signal, so register header first then let
    // the field key overwrite on a collision.
    if (c.header) byKey.set(normalizeHeader(c.header), field)
    if (c.field) byKey.set(normalizeHeader(c.field), c.field)
  }
  const map: ImportColumnMap = {}
  for (const h of headers) {
    const hit = byKey.get(normalizeHeader(h))
    if (hit) map[h] = hit
  }
  return map
}

export function autoUpdate(reference: Element, floating: HTMLElement, update: () => void): () => void {
  if (typeof window === 'undefined') return () => {}
  const ancestors = scrollParents(reference)
  for (const a of ancestors) a.addEventListener('scroll', update, { passive: true })
  window.addEventListener('scroll', update, { passive: true })
  window.addEventListener('resize', update)

  let ro: ResizeObserver | undefined
  if (typeof ResizeObserver === 'function') {
    ro = new ResizeObserver(update)
    ro.observe(reference)
    ro.observe(floating)
  }

  update()

  return () => {
    for (const a of ancestors) a.removeEventListener('scroll', update)
    window.removeEventListener('scroll', update)
    window.removeEventListener('resize', update)
    ro?.disconnect()
  }
}

export function axisScale(
  dataMin: number,
  dataMax: number,
  axis: { min?: number; max?: number; nice?: boolean; tickCount?: number; tickInterval?: number } = {},
): NiceScale {
  let min = axis.min ?? dataMin
  let max = axis.max ?? dataMax
  if (!Number.isFinite(min) || !Number.isFinite(max)) {
    min = Number.isFinite(min) ? min : 0
    max = Number.isFinite(max) ? max : min + 1
  }
  const nice = axis.nice !== false
  const interval = axis.tickInterval
  if (interval && interval > 0 && Number.isFinite(interval)) {
    // An explicit interval is the whole axis: the ends land on multiples of it
    // (unless pinned) and every tick is one interval apart.
    if (nice && axis.min == null) min = Math.floor(min / interval) * interval
    if (nice && axis.max == null) max = Math.ceil(max / interval) * interval
    if (max <= min) max = min + interval
    const ticks: number[] = []
    const first = Math.ceil(min / interval - 1e-9) * interval
    // Cap the count so a tiny interval on a huge domain cannot hang the layout.
    // `+ 0` turns the -0 that `Math.ceil` hands back at the origin into a plain 0.
    for (let v = first, n = 0; v <= max + interval * 1e-6 && n < 1000; v += interval, n += 1) ticks.push(round(v) + 0)
    return { min, max, step: interval, ticks }
  }
  if (nice) {
    const ns = niceScale(min, max, axis.tickCount ?? 4)
    if (axis.min == null && axis.max == null) return ns
    // A pinned end wins over the rounding, and ticks past it go.
    const lo = axis.min ?? ns.min
    const hi = axis.max ?? ns.max
    return { min: lo, max: hi, step: ns.step, ticks: ns.ticks.filter((t) => t >= lo - 1e-9 && t <= hi + 1e-9) }
  }
  if (max <= min) max = min + 1
  const n = Math.max(1, Math.round(axis.tickCount ?? 4))
  const step = (max - min) / n
  const ticks = Array.from({ length: n + 1 }, (_, i) => round(min + step * i))
  return { min, max, step, ticks }
}

export const BASE_ROW_METHODS = {
  getCanExpand(this: BaseRowState<RowData>) {
    return false
  },
  getIsExpanded(this: BaseRowState<RowData>) {
    return Boolean((this[ROW_CTX].store.state.expanded ?? {})[this.id])
  },
  toggleExpanded(this: BaseRowState<RowData>) {
    const id = this.id
    this[ROW_CTX].grid.setExpanded((prev) => ({ ...prev, [id]: !prev[id] }))
  },
  getIsSelected(this: BaseRowState<RowData>) {
    return Boolean((this[ROW_CTX].store.state.rowSelection ?? {})[this.id])
  },
  toggleSelected(this: BaseRowState<RowData>) {
    const id = this.id
    this[ROW_CTX].grid.setRowSelection((prev) => ({ ...prev, [id]: !prev[id] }))
  },
  getAllCells(this: BaseRowState<RowData>) {
    return this[ROW_CELLS] ?? buildBaseRowCells(this)
  },
  getCellValueByColumnId(this: BaseRowState<RowData>, columnId: string) {
    const idx = this[ROW_CTX].columnIndexById.get(columnId)
    if (idx === undefined) return undefined
    if (!this[ROW_VALUES]) this[ROW_VALUES] = baseRowValues(this)
    return this[ROW_VALUES][idx]
  },
}

export type BaseRowCtx<TData extends RowData> = {
  grid: SvGrid<TData>
  store: { state: Record<string, any> }
  columns: Array<Column<TData>>
  columnCount: number
  columnIndexById: Map<string, number>
}

export function binValues(
  values: ReadonlyArray<number>,
  opts: { bins?: number; binWidth?: number; method?: 'sturges' | 'fd' | 'sqrt'; min?: number; max?: number } = {},
): ChartBins {
  const v = values.filter((n) => Number.isFinite(n))
  if (!v.length) return { categories: [], counts: [], edges: [], width: 0 }
  const lo = opts.min ?? Math.min(...v)
  let hi = opts.max ?? Math.max(...v)
  if (hi <= lo) hi = lo + 1
  let count: number
  if (opts.bins && opts.bins > 0) count = Math.round(opts.bins)
  else if (opts.binWidth && opts.binWidth > 0) count = Math.max(1, Math.ceil((hi - lo) / opts.binWidth))
  else if (opts.method === 'sqrt') count = Math.ceil(Math.sqrt(v.length))
  else if (opts.method === 'fd') {
    const iqr = percentile(v, 75) - percentile(v, 25)
    const w = iqr > 0 ? (2 * iqr) / Math.cbrt(v.length) : 0
    count = w > 0 ? Math.ceil((hi - lo) / w) : Math.ceil(Math.log2(v.length) + 1)
  } else count = Math.ceil(Math.log2(v.length) + 1)
  count = Math.max(1, Math.min(1000, count))
  const width = opts.binWidth && opts.binWidth > 0 ? opts.binWidth : (hi - lo) / count
  // Precision from the width: a 0.25 width keeps two decimals, a 10 width none.
  const decimals = width >= 1 ? 0 : Math.min(6, Math.ceil(-Math.log10(width)) + 1)
  const fix = (n: number) => Number(n.toFixed(decimals))
  const edges: number[] = []
  for (let i = 0; i <= count; i += 1) edges.push(fix(lo + i * width))
  const counts = new Array<number>(count).fill(0)
  for (const n of v) {
    let i = Math.floor((n - lo) / width)
    if (i >= count) i = count - 1
    if (i < 0) i = 0
    counts[i] = (counts[i] ?? 0) + 1
  }
  const categories = counts.map((_, i) => String(fix(lo + (i + 0.5) * width)))
  return { categories, counts, edges, width }
}

export type BlockCacheState = {
  /** Rows after filtering, or `null` while the backend has not said. */
  rowCount: number | null
  /** False while the end of the data is still being discovered. */
  lastRowKnown: boolean
  /** True while at least one block is in flight. */
  loading: boolean
  /** Blocks whose fetch rejected. Empty unless something went wrong. */
  failedBlocks: number[]
}

export type BlockFetchResult<TData> = {
  rows: ReadonlyArray<TData>
  /**
   * Total rows after filtering. Omit it (or send `-1`) when the backend cannot
   * count cheaply - the cache then discovers the end from the first short
   * block, and `lastRowKnown()` stays false until it does.
   */
  rowCount?: number
}

export type BlockState = {
  blockIndex: number
  startRow: number
  endRow: number
  status: 'loading' | 'loaded' | 'failed'
  /** Monotonic counter of when the viewport last covered this block. */
  lastTouched: number
}

export function bollingerBands(values: ReadonlyArray<number>, period = 20, k = 2): { middle: number[]; upper: number[]; lower: number[] } {
  const n = values.length
  const p = Math.max(1, Math.floor(period))
  const middle = simpleMovingAverage(values as number[], p)
  const upper = nanArray(n)
  const lower = nanArray(n)
  for (let i = p - 1; i < n; i += 1) {
    const m = middle[i]!
    if (!Number.isFinite(m)) continue
    let ss = 0
    let count = 0
    for (let j = i - p + 1; j <= i; j += 1) {
      const v = values[j]!
      if (!Number.isFinite(v)) continue
      ss += (v - m) * (v - m)
      count += 1
    }
    const sd = count ? Math.sqrt(ss / count) : 0
    upper[i] = m + k * sd
    lower[i] = m - k * sd
  }
  return { middle, upper, lower }
}

export type BorderSpec = {
  /** Thickness in pixels. Default 2. */
  width?: number
  /** CSS border-style. Default 'solid'. */
  style?: 'solid' | 'dashed' | 'dotted' | 'double'
  /** CSS color. Falls back to currentColor (i.e. text color). */
  color?: string
}

export function boxStats(sample: ReadonlyArray<number>, whisker = 1.5): BoxStats | null {
  const v = sample.filter((n) => Number.isFinite(n)).slice().sort((a, b) => a - b)
  if (!v.length) return null
  const q = (p: number) => {
    const pos = (v.length - 1) * p
    const lo = Math.floor(pos)
    const hi = Math.ceil(pos)
    return lo === hi ? v[lo]! : v[lo]! + (v[hi]! - v[lo]!) * (pos - lo)
  }
  const q1 = q(0.25)
  const median = q(0.5)
  const q3 = q(0.75)
  const fenceLo = q1 - whisker * (q3 - q1)
  const fenceHi = q3 + whisker * (q3 - q1)
  const inside = v.filter((n) => n >= fenceLo && n <= fenceHi)
  const outliers = v.filter((n) => n < fenceLo || n > fenceHi)
  return {
    // `inside` can only be empty if every point is an outlier, which the fence
    // rule makes impossible (q1 and q3 are always within it) - but a degenerate
    // sample should still produce a box rather than `undefined` coordinates.
    min: inside.length ? inside[0]! : v[0]!,
    q1,
    median,
    q3,
    max: inside.length ? inside[inside.length - 1]! : v[v.length - 1]!,
    ...(outliers.length ? { outliers } : {}),
  }
}

export type BoxStats = {
  min: number
  q1: number
  median: number
  q3: number
  max: number
  /** Values outside the whiskers, drawn as individual points. */
  outliers?: number[]
}

export function bringToFront(state: DockManagerState, windowId: string): DockManagerState {
  const top = maxZ(state)
  return { ...state, floating: state.floating.map((w) => (w.id === windowId ? { ...w, z: top + 1 } : w)) }
}

export function bucketStart(date: string | number | Date, bucket: ChartTimeBucket): string {
  const t = date instanceof Date ? date.getTime() : typeof date === 'number' ? date : Date.parse(date)
  if (!Number.isFinite(t)) return ''
  const d = new Date(t)
  const y = d.getUTCFullYear()
  const m = d.getUTCMonth()
  let out: Date
  switch (bucket) {
    case 'day':
      out = new Date(Date.UTC(y, m, d.getUTCDate()))
      break
    case 'week': {
      // Monday-based, which is what a business calendar reads.
      const day = (d.getUTCDay() + 6) % 7
      out = new Date(Date.UTC(y, m, d.getUTCDate() - day))
      break
    }
    case 'month':
      out = new Date(Date.UTC(y, m, 1))
      break
    case 'quarter':
      out = new Date(Date.UTC(y, m - (m % 3), 1))
      break
    default:
      out = new Date(Date.UTC(y, 0, 1))
  }
  return out.toISOString().slice(0, 10)
}

export function bucketsToChartSpec(
  buckets: ReadonlyArray<{ category: string; series?: string; value: number }>,
  type: ChartType,
  hasSeries: boolean,
): ChartSpec {
  const cats: string[] = []
  const catIdx = new Map<string, number>()
  const seriesMap = new Map<string, number[]>()
  for (const b of buckets) {
    let ci = catIdx.get(b.category)
    if (ci === undefined) {
      ci = cats.length
      catIdx.set(b.category, ci)
      cats.push(b.category)
    }
    const key = hasSeries ? (b.series ?? '') : 'value'
    let arr = seriesMap.get(key)
    if (!arr) {
      arr = []
      seriesMap.set(key, arr)
    }
    arr[ci] = (arr[ci] ?? 0) + b.value
  }
  return {
    type,
    categories: cats,
    series: [...seriesMap.entries()].map(([label, values]) => ({ label, values: cats.map((_, i) => values[i] ?? 0) })),
  }
}

export function buildChart(input: ChartSpec, theme: 'light' | 'dark' = 'light'): ChartGeometry {
  const width = input.width ?? 520
  const height = input.height ?? 300
  // Size rules first, so every family sees the patched spec.
  const spec = resolveResponsive(input, width, height)
  // A pareto is a bar chart with a cumulative-share line on the right axis,
  // sorted by value. Build that spec and lay it out as the combo it is.
  if (spec.type === 'pareto') return buildChart(paretoSpec(spec), theme)
  const palette = spec.palette ?? DEFAULT_PALETTE

  const stacked = !!(spec.stacked || spec.stacked100)
  const series: ResolvedSeries[] = spec.series.map((s, i) => ({
    ...s,
    // A null is a gap unless the series (or the spec) says it is a zero. Done
    // here, once, so every family and every overlay sees the same numbers.
    values: (s.nullAs ?? spec.nullAs) === 'zero' ? s.values.map((v) => (Number.isFinite(v) ? v : 0)) : s.values,
    color: s.color ?? palette[i % palette.length]!,
    kind: kindOf(s, spec.type),
    axis: s.axis ?? 'left',
  }))
  const frame = chartFrame(spec, width, height)
  const axes = resolveAxes(spec)
  const legend: ChartLegendItem[] = series.map((s) => ({ label: s.label, color: s.color }))

  const empty: ChartGeometry = {
    type: spec.type,
    width,
    height,
    plot: { x: 0, y: 0, w: width, h: height },
    axes: null,
    frame,
    grid: { x: false, y: false },
    referenceBands: [],
    bars: [],
    candles: [],
    boxes: [],
    errorBars: [],
    stems: [],
    arcs: [],
    chordRibbons: [],
    bullets: [],
    drawings: [],
    seriesLabels: [],
    polarAxes: [],
    polarRings: [],
    lines: [],
    slices: [],
    yTicks: [],
    y2Ticks: [],
    hasRightAxis: false,
    xTicks: [],
    categoryGroupTicks: [],
    xLabelRotated: false,
    xLabelAngle: 0,
    legend,
    donut: null,
    referenceLines: [],
    scatterPoints: [],
    orientation: 'vertical',
    valueTicks: [],
    catTicks: [],
    referenceLinesV: [],
    overlays: [],
    annotations: [],
    heatmapCells: [],
    heatmapRowTicks: [],
    heatmapColTicks: [],
    heatmapLegend: [],
    funnelSegments: [],
    radarRings: [],
    radarAxes: [],
    radarSeries: [],
    radarCenter: null,
    treemapCells: [],
    calendarCells: [],
    calendarMonthTicks: [],
    calendarLegend: [],
    gauge: null,
    sankeyNodes: [],
    sankeyLinks: [],
  }

  const ctx: LayoutCtx = { spec, theme, width, height, palette, stacked, series, legend, empty, frame, axes }
  if (spec.type === 'waterfall') return layoutWaterfall(ctx)
  if (spec.type === 'funnel') return layoutFunnel(ctx)
  if (spec.type === 'radar') return layoutRadar(ctx)
  if (spec.type === 'calendar') return layoutCalendar(ctx)
  if (spec.type === 'gauge') return layoutGauge(ctx)
  if (spec.type === 'treemap') return layoutTreemap(ctx)
  if (spec.type === 'sankey') return layoutSankey(ctx)
  if (spec.type === 'heatmap') return layoutHeatmap(ctx)
  if (spec.type === 'pie') return layoutPie(ctx)
  if (spec.type === 'scatter') return layoutScatter(ctx)
  if (spec.type === 'sunburst') return layoutSunburst(ctx)
  if (spec.type === 'radial-bar') return layoutRadialBar(ctx)
  if (spec.type === 'radial-column' || spec.type === 'nightingale') return layoutRadialColumn(ctx)
  if (spec.type === 'chord') return layoutChord(ctx)
  if (spec.type === 'bullet') return layoutBullet(ctx)

  // ---- Horizontal bars ----------------------------------------------------
  // Categories run down the left, bars grow rightward. Bars-only (no combo).
  const horizontal =
    spec.orientation === 'horizontal' && spec.type !== 'histogram' && series.length > 0 && series.every((s) => s.kind === 'bar')
  if (horizontal) return layoutHorizontalBars(ctx)
  return layoutCartesian(ctx)
}

export function buildChartPdf(
  jpeg: { bytes: Uint8Array; width: number; height: number },
  opts: Pick<ChartPdfOptions, 'page' | 'orientation' | 'title' | 'subtitle' | 'caption'> = {},
): Uint8Array {
  const [pw0, ph0] = PAGES[opts.page ?? 'A4']
  const landscape = opts.orientation ? opts.orientation === 'landscape' : jpeg.width / jpeg.height > pw0 / ph0
  const pw = landscape ? ph0 : pw0
  const ph = landscape ? pw0 : ph0
  const margin = 40
  const title = (opts.title ?? '').trim()
  const subtitle = (opts.subtitle ?? '').trim()
  const caption = (opts.caption ?? '').trim()

  // Text block at the top, image below it, caption at the foot.
  let y = ph - margin
  const content: string[] = []
  const line = (text: string, size: number, gray: number) => {
    y -= size + 4
    content.push(`BT /F1 ${size} Tf ${gray} g ${margin} ${y.toFixed(2)} Td ${pdfText(text)} Tj ET`)
  }
  if (title) line(title, 16, 0)
  if (subtitle) line(subtitle, 11, 0.4)
  if (title || subtitle) y -= 8
  const footer = caption ? 20 : 0
  const availW = pw - margin * 2
  const availH = y - margin - footer
  const scale = Math.min(availW / jpeg.width, availH / jpeg.height)
  const iw = jpeg.width * scale
  const ih = jpeg.height * scale
  const ix = margin + (availW - iw) / 2
  const iy = y - ih
  content.push(`q ${iw.toFixed(2)} 0 0 ${ih.toFixed(2)} ${ix.toFixed(2)} ${iy.toFixed(2)} cm /Im1 Do Q`)
  if (caption) {
    const size = 9
    const text = textWidth(caption, size) > availW ? caption.slice(0, Math.floor(availW / (size * 0.5)) - 3) + '...' : caption
    content.push(`BT /F1 ${size} Tf 0.4 g ${margin} ${(margin - 4).toFixed(2)} Td ${pdfText(text)} Tj ET`)
  }
  const stream = content.join('\n')

  const objects: Array<Uint8Array | string> = []
  const offsets: number[] = []
  let length = 0
  const push = (part: Uint8Array | string) => {
    objects.push(part)
    length += typeof part === 'string' ? part.length : part.length
  }
  push('%PDF-1.4\n%âãÏÓ\n')
  const obj = (n: number, body: string, bin?: Uint8Array) => {
    offsets[n] = length
    push(`${n} 0 obj\n${body}\n`)
    if (bin) {
      push('stream\n')
      push(bin)
      push('\nendstream\n')
    }
    push('endobj\n')
  }
  obj(1, '<< /Type /Catalog /Pages 2 0 R >>')
  obj(2, '<< /Type /Pages /Kids [3 0 R] /Count 1 >>')
  obj(3, `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pw.toFixed(2)} ${ph.toFixed(2)}] /Resources << /XObject << /Im1 4 0 R >> /Font << /F1 5 0 R >> >> /Contents 6 0 R >>`)
  obj(4, `<< /Type /XObject /Subtype /Image /Width ${jpeg.width} /Height ${jpeg.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpeg.bytes.length} >>`, jpeg.bytes)
  obj(5, '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>')
  obj(6, `<< /Length ${stream.length} >>`, latin1(stream))
  const xref = length
  push(`xref\n0 7\n0000000000 65535 f \n`)
  for (let n = 1; n <= 6; n += 1) push(`${String(offsets[n]).padStart(10, '0')} 00000 n \n`)
  push(`trailer\n<< /Size 7 /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`)

  const out = new Uint8Array(new ArrayBuffer(length))
  let at = 0
  for (const part of objects) {
    const bytes = typeof part === 'string' ? latin1(part) : part
    out.set(bytes, at)
    at += bytes.length
  }
  return out
}

export function buildGroupedPdfBody<TData extends RowData>(
  cols: ReadonlyArray<ExportColumn<TData>>,
  rows: ReadonlyArray<TData>,
  groupBy: ReadonlyArray<string>,
): PdfBodyRow[] {
  const out: PdfBodyRow[] = []
  const headerOf = (field: string) => cols.find((c) => c.field === field)?.header ?? field
  // Put the "Subtotal" label in the first NON-numeric column; if every column
  // is numeric, -1 means "don't overwrite a sum with the label".
  const labelColIdx = cols.findIndex((c) => !isSummableColumn(c))

  const recurse = (subset: ReadonlyArray<TData>, level: number) => {
    if (level >= groupBy.length) {
      for (const r of subset) {
        out.push({ kind: 'data', cells: cols.map((c) => String(cellValueFor(c, r, false) ?? '')) })
      }
      return
    }
    const field = groupBy[level]!
    // Preserve first-seen order of group keys.
    const buckets = new Map<string, TData[]>()
    for (const r of subset) {
      const key = String((r as Record<string, unknown>)[field] ?? '')
      const bucket = buckets.get(key)
      if (bucket) bucket.push(r)
      else buckets.set(key, [r])
    }
    for (const [key, groupRows] of buckets) {
      out.push({ kind: 'group', label: `${headerOf(field)}: ${key} (${groupRows.length})`, level })
      recurse(groupRows, level + 1)
      // Subtotal row for the numeric columns of this cluster.
      const hasSummable = cols.some(isSummableColumn)
      if (hasSummable) {
        const cells = cols.map((c) => {
          if (!isSummableColumn(c)) return ''
          const sum = groupRows.reduce(
            (a, r) => a + (Number((r as Record<string, unknown>)[c.field]) || 0),
            0,
          )
          return formatValueForExport(sum, c.format)
        })
        if (labelColIdx >= 0) cells[labelColIdx] = `Subtotal (${key})`
        out.push({ kind: 'subtotal', cells })
      }
    }
  }
  recurse(rows, 0)
  return out
}

export function buildLinePath(
  pts: Array<{ x: number; y: number; defined: boolean }>,
  smooth: boolean,
  opts: { connectNulls?: boolean; step?: Step } = {},
): string {
  const runs = definedRuns(pts, !!opts.connectNulls)
  return runs.map((run) => runPath(run, smooth, opts.step)).filter(Boolean).join(' ')
}

export function buildLinkResolver<TData extends RowData>(
  cols: ReadonlyArray<ExportColumn<TData>>,
  rows: ReadonlyArray<TData>,
): ((rowIdx: number, colIdx: number) => string | undefined) | undefined {
  if (!cols.some((c) => c.link)) return undefined
  return (rowIdx, colIdx) => {
    const col = cols[colIdx]
    const row = rows[rowIdx]
    if (!col?.link || !row) return undefined
    return col.link(row) || undefined
  }
}

export function buildPivotResultColumns(
  fields: ReadonlyArray<string>,
  aggregations: ReadonlyArray<ServerAggregation>,
  options: PivotResultColumnOptions = {},
): Array<ColumnDef<any, any>> {
  const sep = options.separator ?? '_'
  const width = options.width ?? 120
  const header = options.valueHeader ?? ((a) => `${a.fn}(${a.col})`)
  const root: Node = { key: '', children: new Map(), leaves: [] }

  // Longest aggregation column first, so `net_amount` wins over `amount` for
  // a field ending in `_net_amount`.
  const aggs = [...aggregations].sort((a, b) => b.col.length - a.col.length)

  for (const field of fields) {
    const agg = aggs.find((a) => field === a.col || field.endsWith(sep + a.col))
    if (!agg) continue
    const keyPart = field === agg.col ? '' : field.slice(0, field.length - agg.col.length - sep.length)
    const keys = keyPart === '' ? [] : keyPart.split(sep)
    let node = root
    for (const key of keys) {
      let next = node.children.get(key)
      if (!next) {
        next = { key, children: new Map(), leaves: [] }
        node.children.set(key, next)
      }
      node = next
    }
    node.leaves.push({ field, agg })
  }

  const leafColumn = (field: string, agg: ServerAggregation): ColumnDef<any, any> => {
    const base = { id: field, field, header: header(agg), width, align: 'right' } as ColumnDef<any, any>
    return options.pivotResultColumn ? options.pivotResultColumn(field, base) : base
  }

  const emit = (node: Node, path: string[]): Array<ColumnDef<any, any>> => {
    const out: Array<ColumnDef<any, any>> = []
    for (const child of node.children.values()) {
      const childPath = [...path, child.key]
      out.push({
        id: `pv_group_${childPath.join(sep)}`,
        header: child.key,
        columns: emit(child, childPath),
      } as unknown as ColumnDef<any, any>)
    }
    for (const leaf of node.leaves) out.push(leafColumn(leaf.field, leaf.agg))
    return out
  }

  const out = emit(root, [])
  if (options.rowTotals) {
    out.push({
      id: 'pv_group_total',
      header: typeof options.rowTotals === 'string' ? options.rowTotals : 'Total',
      columns: aggregations.map((a) => leafColumn(a.col, a)),
    } as unknown as ColumnDef<any, any>)
  }
  return out
}

