export function chartScales(geo: ChartGeometry): ChartScales | null {
  const a = geo.axes
  if (!a) return null
  const { x: px, y: py, w: pw, h: ph } = geo.plot
  type Dom = { min: number; max: number; log: boolean; reversed?: boolean }
  const yFor = (dom: Dom) => (value: number) => {
    let t = project(value, dom.min, dom.max, dom.log)
    if (t === null) return Number.NaN
    if (dom.reversed) t = 1 - t
    return py + ph - t * ph
  }
  const left = yFor(a.y)
  const right = a.y2 ? yFor(a.y2) : left
  const invFor = (dom: Dom) => (y: number) => {
    let t = ph === 0 ? 0 : (py + ph - y) / ph
    if (dom.reversed) t = 1 - t
    if (!dom.log) return dom.min + t * (dom.max - dom.min)
    const lo = Math.log10(dom.min)
    return 10 ** (lo + t * (Math.log10(dom.max) - lo))
  }
  // A continuous x axis (time / number) places by value; a category axis by
  // index. `xOf(i)` on a continuous axis goes through the stored per-category
  // values, so a custom mark at "category 3" lands where the built-in one did
  // even when the categories are unevenly spaced in time.
  const cx = a.x
  const span = cx ? cx.max - cx.min || 1 : 1
  const logSpan = cx?.log ? Math.log10(cx.max) - Math.log10(cx.min) || 1 : 1
  const xOfNum = (v: number) => {
    if (!cx || !Number.isFinite(v)) return Number.NaN
    if (cx.log && v <= 0) return Number.NaN
    let t = cx.log ? (Math.log10(v) - Math.log10(cx.min)) / logSpan : (v - cx.min) / span
    if (cx.reversed) t = 1 - t
    return px + t * pw
  }
  const xOfIndex = (i: number) => {
    if (cx?.values) {
      const v = cx.values[Math.round(i)]
      if (v != null && Number.isFinite(v)) return xOfNum(v)
    }
    const t = px + a.slot * i + a.slot / 2
    return a.xReversed ? px + pw - (t - px) : t
  }
  const xOfValue = (value: number | string | Date): number => {
    if (cx) {
      if (value instanceof Date) return xOfNum(value.getTime())
      if (typeof value === 'number') return xOfNum(value)
      const n = cx.type === 'time' ? Date.parse(value) : Number(value)
      if (Number.isFinite(n)) return xOfNum(n)
      // A label that did not parse can still be one of the categories.
      const i = geo.xTicks.findIndex((t) => t.label === value)
      return i >= 0 ? geo.xTicks[i]!.x : Number.NaN
    }
    if (typeof value === 'number') return xOfIndex(value)
    const label = value instanceof Date ? value.toISOString() : value
    const i = a.labels ? a.labels.indexOf(label) : -1
    return i >= 0 ? xOfIndex(i) : Number.NaN
  }
  const xInvertValue = (x: number): number => {
    let t = pw === 0 ? 0 : (x - px) / pw
    if (cx ? cx.reversed : a.xReversed) t = 1 - t
    if (cx?.log) return Math.pow(10, Math.log10(cx.min) + t * logSpan)
    if (cx) return cx.min + t * span
    return Math.max(0, Math.min(a.count - 1, t * a.count - 0.5))
  }
  return {
    xOf: xOfIndex,
    yOf: (value, axis) => (axis === 'right' ? right(value) : left(value)),
    xInvert: (x) => {
      if (cx?.values) {
        // Nearest category by value, which is what a hover on a time axis means.
        const v = xInvertValue(x)
        let best = 0
        let bestD = Infinity
        cx.values.forEach((cv, i) => {
          const d = Math.abs(cv - v)
          if (d < bestD) { bestD = d; best = i }
        })
        return best
      }
      const raw = Math.floor((x - px) / (a.slot || 1))
      const i = a.xReversed ? a.count - 1 - raw : raw
      return Math.max(0, Math.min(a.count - 1, i))
    },
    yInvert: (y, axis) => (axis === 'right' && a.y2 ? invFor(a.y2)(y) : invFor(a.y)(y)),
    xOfValue,
    xInvertValue,
  }
}

export type ChartScales = {
  /** Pixel x at the centre of category `i`. Fractional indices interpolate,
   *  so `xOf(2.5)` is the midpoint between the third and fourth categories. */
  xOf: (index: number) => number
  /** Pixel y for a value on the left axis (or the right, when asked). Returns
   *  NaN for a value the axis cannot express, e.g. zero on a log scale. */
  yOf: (value: number, axis?: 'left' | 'right') => number
  /** The inverse of `xOf`: which category a pixel x falls on. Clamped. */
  xInvert: (px: number) => number
  /** The inverse of `yOf`. */
  yInvert: (px: number, axis?: 'left' | 'right') => number
  /**
   * Pixel x for a VALUE on the x axis: a timestamp or ISO date on a time axis,
   * a number on a numeric axis, a category label on a category axis. NaN when
   * the value cannot be placed (an unknown label, a non-date on a time axis).
   */
  xOfValue: (value: number | string | Date) => number
  /** The inverse of `xOfValue`: the data-space x under a pixel. On a category
   *  axis this is the (fractional) category index. */
  xInvertValue: (px: number) => number
}

export type ChartSelection = {
  category: string
  series: string
  value: number
  rowIds?: Array<string | number>
}

export type ChartSpec = {
  /** Default type for series that don't set their own `type`. */
  type: ChartType
  /** X-axis labels (one per data point). */
  categories: string[]
  series: ChartSeries[]
  width?: number
  height?: number
  /** Palette used when a series has no explicit `color`. */
  palette?: string[]
  /** Per-category color overrides (by category label) - for pie / donut slice
   *  recolouring, where colour follows the category, not a series. */
  categoryColors?: Record<string, string>
  /** Number format for the value axis, tooltips, data labels and reference
   *  lines. Unset = the default compact `1.2k` / `1.2M` style. */
  valueFormat?: ChartValueFormat
  /** BCP-47 locale for value formatting. Setting this (or `currency`) switches
   *  formatting to `Intl.NumberFormat`, so thousands separators, the decimal
   *  mark and the compact suffixes follow the locale rather than the built-in
   *  English `1.2k` / `1.2M`. Unset = the locale-free default, which is why the
   *  default output has never changed under anyone's feet. */
  locale?: string | ReadonlyArray<string>;
  /** ISO 4217 code for `valueFormat: 'currency'` (`'EUR'`, `'JPY'`, ...). Unset
   *  means the axis reads `$`, which is wrong everywhere outside the dollar
   *  zone and was the only currency this chart could draw for a long time. */
  currency?: string
  /** Grouped (nested) category axis: a parent tier spanning consecutive leaf
   *  categories (spans must sum to `categories.length`). Vertical category
   *  charts only (ignored for time / horizontal / pie). */
  categoryGroups?: Array<{ label: string; span: number }>
  /** Stack bar / area series (per axis) instead of grouping them. */
  stacked?: boolean
  /** Stack to 100% (each category normalized to its total). Implies stacked. */
  stacked100?: boolean
  /**
   * Bar orientation. `'horizontal'` swaps the axes - categories run down the
   * left, bars grow rightward - which suits long category labels. Only applies
   * when every series is a bar (combo / line / area fall back to vertical).
   */
  orientation?: 'vertical' | 'horizontal'
  /** Pie only: inner radius as a fraction of the outer radius (0..1) -> donut. */
  innerRadius?: number
  /** Horizontal target / goal / average lines. */
  referenceLines?: ChartReferenceLine[]
  /**
   * How to read `categories` along the x axis.
   *
   * - `'category'` (default): evenly spaced labels, taken literally.
   * - `'time'`: parsed as dates and positioned by ACTUAL elapsed time, so an
   *   irregular gap renders as a proportional gap.
   * - `'ordinal-time'`: parsed as dates but spaced EVENLY, with date-derived
   *   ticks. This is what a series of trading sessions or business days needs:
   *   on a true time axis every weekend opens a hole a third as wide as the
   *   working week, which is noise rather than information.
   */
  xType?: 'category' | 'time' | 'ordinal-time' | 'number'
  /** Axis titles (reserve gutter space + render). */
  yAxisTitle?: string
  y2AxisTitle?: string
  xAxisTitle?: string
  /** Y-axis scale. `'log'` plots base-10 logarithmic - values <= 0 are
   *  treated as missing. Necessary for wide-range data (money, audience
   *  size, scientific). Default `'linear'`. */
  yScale?: 'linear' | 'log'
  /** Right (secondary) Y-axis scale. Default `'linear'`. */
  y2Scale?: 'linear' | 'log'
  /** The x axis in full: type, title, tick formatter, label rotation, grid
   *  lines, reversal. The flat `xType` / `xAxisTitle` fill in what is unset. */
  xAxis?: ChartAxisConfig
  /** The left value axis in full: min / max, tick count or interval, format,
   *  title, grid lines, reversal, scale. `yAxisTitle` / `yScale` fill in.
   *  A radar or radial column reads `min` / `max` as its rim. */
  yAxis?: ChartAxisConfig
  /** The right value axis, for series with `axis: 'right'`. */
  y2Axis?: ChartAxisConfig
  /** Chart title, drawn centred above the plot. Reserves its own room. */
  title?: string
  /** Smaller line under the title. */
  subtitle?: string
  /** Small text under the plot, left-aligned: a source, a note, a footnote. */
  caption?: string
  /** Shaded bands behind the marks, on a value axis or across the x axis. */
  referenceBands?: ChartReferenceBand[]
  /** What a `null` / `NaN` value means. `'gap'` (default) breaks the line and
   *  draws no mark; `'zero'` plots it as 0. Per-series `nullAs` beats this. */
  nullAs?: 'gap' | 'zero'
  /** Thin long line / area series before layout. Default `'auto'`: only when
   *  there are more points than pixels. See {@link ChartDecimateConfig}. */
  decimate?: ChartDecimateConfig
  /** Data labels as the spec's own default; the component's `dataLabels`
   *  prop, when set, replaces it. On a pie, `placement: 'outside'` draws
   *  callout labels with leader lines instead of percentages on the slices. */
  dataLabels?: ChartDataLabelConfig
  /** Pinned text labels at fixed data-space positions (callouts). */
  annotations?: ChartAnnotation[]
  /**
   * Name each line / area series at its last point, so a reader never has to
   * match colours against a legend. `true` writes the series label; a
   * formatter gets the label and the last value. Labels on a crowded right
   * edge are pushed apart so they stay legible. Cartesian charts only.
   */
  seriesLabels?: boolean | { formatter?: (series: string, value: number) => string }
  /**
   * Rules that patch the spec by the rendered size, checked top to bottom,
   * every matching rule applied in turn (later wins). A rule's `spec` is a
   * partial spec merged over this one; the axis objects merge one level deep,
   * everything else replaces. A rule cannot change `width`, `height` or
   * `responsive` itself. `{ maxWidth: 480, spec: { xAxis: { labelRotation: 90 }, seriesLabels: false } }`
   * keeps a phone-width chart readable; the `legend` field, when set, moves
   * or hides `SvChart`'s legend the same way.
   */
  responsive?: ChartResponsiveRule[]
  /** This chart's font, size, background and text / grid colours, over the
   *  theme tokens. See {@link ChartStyle}. */
  style?: ChartStyle
  /** Reader drawings (trend lines, rays, Fibonacci levels, notes) in data
   *  space. `SvChart`'s drawing tools produce these; see {@link ChartDrawing}. */
  drawings?: ChartDrawing[]
  /** A dashed line at the last close (or the last value of the first
   *  series) with its value in a pill on the axis, green when the last bar
   *  closed up and red when it closed down. */
  lastPriceLine?: boolean | { label?: string; color?: string }
  /** When true, automatically cycle through pattern fills for every series
   *  that doesn't set `pattern` explicitly. Useful as a one-flag colorblind
   *  fallback. Default false. */
  patternFallback?: boolean
  /** Calendar heatmap: array of date+value samples (one per day). Date
   *  strings are 'YYYY-MM-DD'. Missing days render as blank cells. */
  calendarValues?: Array<{ date: string; value: number }>
  /** Calendar heatmap: year window. Default: span the data. */
  calendarStart?: string
  calendarEnd?: string

  /** Gauge: the value to display. */
  gaugeValue?: number
  /** Gauge: min/max of the dial scale. Defaults [0, 100]. */
  gaugeMin?: number
  gaugeMax?: number
  /** Gauge: target marker (the line/notch on the arc). */
  gaugeTarget?: number
  /** Gauge: color bands along the arc (e.g. red/amber/green). */
  gaugeRanges?: Array<{ from: number; to: number; color: string }>
  /** Gauge: unit / suffix shown next to the value (e.g. '%', 'ms'). */
  gaugeUnit?: string

  /** Tree-map: hierarchical root. Leaves have `value`; parents are the
   *  sum of their children's totals. */
  treemap?: TreeNode

  /** Sankey: nodes + flow links between them. Link `source` / `target`
   *  reference node ids. */
  sankeyNodes?: Array<{ id: string; label?: string; color?: string }>
  sankeyLinks?: Array<{ source: string; target: string; value: number; color?: string }>

  /** Waterfall: per-category flag marking bars as totals / subtotals, drawn
   *  from 0 to the running sum. A total with a value of 0 shows the sum the
   *  steps before it reached; a total with a value sets the running sum to
   *  that value, which is how a bridge opens on "Revenue 4300". Same length
   *  as `categories`. */
  waterfallTotals?: boolean[]
  /** Waterfall: explicit colors for positive/negative/total bars. The
   *  series color is ignored when this is set. */
  waterfallColors?: { positive?: string; negative?: string; total?: string }
  /** Candlestick / OHLC colors. Direction beats series identity here, the same
   *  way `waterfallColors` overrides the series color. Defaults to the green /
   *  red pair from the palette's own vocabulary. */
  candleColors?: { up?: string; down?: string }
  /**
   * How candles are drawn. `'classic'` (default) fills a down candle and
   * leaves an up candle hollow. `'hollow'` colours by close vs the PREVIOUS
   * close and hollows by close vs open, the trader's four-state candle.
   * `'heikin-ashi'` replaces each candle with the smoothed average form
   * before drawing, so trends read as runs of one colour.
   */
  candleStyle?: 'classic' | 'hollow' | 'heikin-ashi'
  /** Funnel shape: stacked trapezoids (default), an inverted `'pyramid'`, or
   *  a `'cone'` that tapers to a point. */
  funnelShape?: 'trapezoid' | 'pyramid' | 'cone'
  /**
   * Baseline for stacked areas. `'zero'` (default) stacks up from the axis;
   * `'wiggle'` centres the stack on a baseline that minimises the wiggle of
   * the layers (a stream graph); `'silhouette'` centres it on zero.
   */
  stackOffset?: 'zero' | 'wiggle' | 'silhouette'
  /** Histogram: the bin edges, one more than there are categories. Set by
   *  `binValues`; the x axis labels the edges rather than the bin centres. */
  binEdges?: number[]
  /** Hierarchy for a sunburst. An alias of `treemap`: either field feeds
   *  either chart. */
  tree?: TreeNode
  /** Bullet chart: qualitative ranges behind the measure bars (poor / ok /
   *  good), shared by every category. Falls back to `gaugeRanges`. */
  bulletRanges?: Array<{ from: number; to: number; color: string }>
  /** Heatmap color scale. `'sequential'` maps min->max through one hue,
   *  `'diverging'` runs cold->neutral->warm around 0. A custom array
   *  (>=2 hex colors) defines an arbitrary gradient. Default `'sequential'`. */
  colorScale?: 'sequential' | 'diverging' | string[]
}

export function chartSpecToCsv(spec: ChartSpec): string {
  const series = spec.series ?? []
  // Scatter: one row per point. `categories` is empty for these, so the
  // category path below would return '' and the export button would do nothing.
  if (series.some((s) => s.points?.length)) {
    const header = ['Series', 'X', 'Y', 'Size', 'Label'].map(csvCell).join(',')
    const rows: string[] = []
    for (const s of series) {
      for (const p of s.points ?? []) {
        rows.push([s.label, p.x, p.y, p.r ?? '', p.label ?? ''].map(csvCell).join(','))
      }
    }
    return rows.length ? [header, ...rows].join('\n') : ''
  }

  const cats = spec.categories ?? []
  if (!cats.length || !series.length) return ''

  // One header cell per column a series contributes. A plain series keeps its
  // bare label, so an existing export is byte-identical.
  const header: string[] = ['Category']
  for (const s of series) {
    if (s.ohlc) header.push(`${s.label} Open`, `${s.label} High`, `${s.label} Low`, `${s.label} Close`, ...(s.volumes ? [`${s.label} Volume`] : []))
    else if (s.boxes) header.push(`${s.label} Min`, `${s.label} Q1`, `${s.label} Median`, `${s.label} Q3`, `${s.label} Max`, `${s.label} Outliers`)
    else if (s.errors) header.push(s.label, `${s.label} Low`, `${s.label} High`)
    else if (s.lowValues) header.push(`${s.label} low`, `${s.label} high`)
    else if (s.targets) header.push(s.label, `${s.label} target`)
    else header.push(s.label)
  }

  const rows = cats.map((cat, i) => {
    const cells: unknown[] = [cat]
    for (const s of series) {
      if (s.ohlc) {
        const k = s.ohlc[i]
        cells.push(k?.o ?? '', k?.h ?? '', k?.l ?? '', k?.c ?? '')
        if (s.volumes) cells.push(s.volumes[i] ?? '')
      } else if (s.boxes) {
        const b = s.boxes[i]
        // Outliers are a list inside one cell; csvCell quotes it.
        cells.push(b?.min ?? '', b?.q1 ?? '', b?.median ?? '', b?.q3 ?? '', b?.max ?? '', b?.outliers?.join(' ') ?? '')
      } else if (s.errors) {
        const v = s.values[i]
        const e = s.errors[i]
        const lo = e == null ? '' : typeof e === 'number' ? (v ?? 0) - Math.abs(e) : Math.min(e.lo, e.hi)
        const hi = e == null ? '' : typeof e === 'number' ? (v ?? 0) + Math.abs(e) : Math.max(e.lo, e.hi)
        cells.push(v ?? '', lo, hi)
      } else if (s.lowValues) {
        cells.push(s.lowValues[i] ?? '', s.values[i] ?? '')
      } else if (s.targets) {
        cells.push(s.values[i] ?? '', s.targets[i] ?? '')
      } else {
        cells.push(s.values[i] ?? '')
      }
    }
    return cells.map(csvCell).join(',')
  })
  return [header.map(csvCell).join(','), ...rows].join('\n')
}

export function chartSpecToTable(spec: ChartSpec): ChartTable {
  const fmt = formatOf(spec.valueFormat, spec)
  // A series on the right axis reads in that axis's format: a margin of 0.29
  // beside a revenue in dollars is "29%", not "$0.29".
  const fmt2 = formatOf(spec.y2Axis?.format, spec)
  const numCol = (field: string, header: string, right = false): ChartTableColumn => {
    const f = right ? fmt2 : fmt
    return { field, header, cellDataType: 'number', ...(f ? { format: f } : {}) }
  }
  const textCol = (field: string, header: string): ChartTableColumn => ({ field, header })
  const series = spec.series ?? []

  // Scatter and bubble: one row per point.
  if (series.some((s) => s.points?.length)) {
    const rows: Array<Record<string, unknown>> = []
    for (const s of series) for (const p of s.points ?? []) rows.push({ series: s.label, x: num(p.x), y: num(p.y), size: num(p.r), label: p.label ?? '' })
    return { columns: [textCol('series', 'Series'), numCol('x', 'X'), numCol('y', 'Y'), numCol('size', 'Size'), textCol('label', 'Label')], rows }
  }
  // Sankey and chord: one row per link.
  if (spec.sankeyLinks?.length) {
    const names = new Map((spec.sankeyNodes ?? []).map((n) => [n.id, n.label ?? n.id]))
    const rows = spec.sankeyLinks.map((l) => ({ source: names.get(l.source) ?? l.source, target: names.get(l.target) ?? l.target, value: num(l.value) }))
    return { columns: [textCol('source', 'Source'), textCol('target', 'Target'), numCol('value', 'Value')], rows }
  }
  // Tree map and sunburst: one row per leaf, a column per level.
  const tree = spec.tree ?? spec.treemap
  if (tree && (spec.type === 'treemap' || spec.type === 'sunburst' || !spec.categories?.length)) {
    const rows: Array<Record<string, unknown>> = []
    let depth = 0
    const walk = (n: TreeNode, path: string[]) => {
      if (n.children?.length) {
        for (const c of n.children) walk(c, [...path, c.name])
        return
      }
      depth = Math.max(depth, path.length)
      const row: Record<string, unknown> = { value: num(n.value) }
      path.forEach((seg, i) => (row[`level${i + 1}`] = seg))
      rows.push(row)
    }
    walk(tree, [])
    const columns: ChartTableColumn[] = []
    for (let i = 1; i <= depth; i += 1) columns.push(textCol(`level${i}`, depth === 1 ? 'Name' : `Level ${i}`))
    columns.push(numCol('value', 'Value'))
    return { columns, rows }
  }
  // Calendar: one row per day.
  if (spec.calendarValues?.length) {
    return {
      columns: [{ field: 'date', header: 'Date', cellDataType: 'date' }, numCol('value', 'Value')],
      rows: spec.calendarValues.map((d) => ({ date: d.date, value: num(d.value) })),
    }
  }
  // Gauge: the one reading and its scale.
  if (spec.type === 'gauge') {
    return {
      columns: [textCol('metric', 'Metric'), numCol('value', spec.gaugeUnit ? `Value (${spec.gaugeUnit})` : 'Value'), numCol('min', 'Min'), numCol('max', 'Max'), numCol('target', 'Target')],
      rows: [{ metric: spec.title ?? spec.series[0]?.label ?? 'Value', value: num(spec.gaugeValue), min: num(spec.gaugeMin ?? 0), max: num(spec.gaugeMax ?? 100), target: num(spec.gaugeTarget) }],
    }
  }

  // Everything else reads categories x series: one row per category, one
  // column per number a series carries.
  const cats = spec.categories ?? []
  if (!cats.length || !series.length) return { columns: [], rows: [] }
  const columns: ChartTableColumn[] = []
  const groups = spec.categoryGroups
  if (groups?.length) columns.push(textCol('group', 'Group'))
  const edges = spec.binEdges
  const xType = spec.xAxis?.type ?? spec.xType
  const dated = xType === 'time' || xType === 'ordinal-time'
  const catHeader = spec.xAxis?.title ?? spec.xAxisTitle ?? (dated ? 'Date' : 'Category')
  if (edges && edges.length === cats.length + 1) columns.push(numCol('from', 'From'), numCol('to', 'To'))
  else columns.push(dated ? { field: 'category', header: catHeader, cellDataType: 'date' } : textCol('category', catHeader))
  const fields: Array<{ field: string; pick: (i: number) => unknown }> = []
  series.forEach((s, si) => {
    const key = (suffix: string) => `s${si}${suffix}`
    const add = (suffix: string, header: string, pick: (i: number) => unknown) => {
      columns.push(numCol(key(suffix), header, s.axis === 'right'))
      fields.push({ field: key(suffix), pick })
    }
    if (s.ohlc) {
      add('o', `${s.label} Open`, (i) => num(s.ohlc![i]?.o))
      add('h', `${s.label} High`, (i) => num(s.ohlc![i]?.h))
      add('l', `${s.label} Low`, (i) => num(s.ohlc![i]?.l))
      add('c', `${s.label} Close`, (i) => num(s.ohlc![i]?.c))
      if (s.volumes) add('v', `${s.label} Volume`, (i) => num(s.volumes![i]))
    } else if (s.boxes) {
      add('min', `${s.label} Min`, (i) => num(s.boxes![i]?.min))
      add('q1', `${s.label} Q1`, (i) => num(s.boxes![i]?.q1))
      add('med', `${s.label} Median`, (i) => num(s.boxes![i]?.median))
      add('q3', `${s.label} Q3`, (i) => num(s.boxes![i]?.q3))
      add('max', `${s.label} Max`, (i) => num(s.boxes![i]?.max))
      columns.push(textCol(key('out'), `${s.label} Outliers`))
      fields.push({ field: key('out'), pick: (i) => s.boxes![i]?.outliers?.join(' ') ?? '' })
    } else if (s.errors) {
      add('', s.label, (i) => num(s.values[i]))
      add('lo', `${s.label} Low`, (i) => {
        const v = s.values[i], e = s.errors![i]
        return e == null || !Number.isFinite(v) ? null : typeof e === 'number' ? (v as number) - Math.abs(e) : Math.min(e.lo, e.hi)
      })
      add('hi', `${s.label} High`, (i) => {
        const v = s.values[i], e = s.errors![i]
        return e == null || !Number.isFinite(v) ? null : typeof e === 'number' ? (v as number) + Math.abs(e) : Math.max(e.lo, e.hi)
      })
    } else if (s.lowValues) {
      add('lo', `${s.label} Low`, (i) => num(s.lowValues![i]))
      add('hi', `${s.label} High`, (i) => num(s.values[i]))
    } else if (s.targets) {
      add('', s.label, (i) => num(s.values[i]))
      add('t', `${s.label} Target`, (i) => num(s.targets![i]))
    } else {
      add('', s.label, (i) => num(s.values[i]))
    }
  })
  // A category's group, from the spans.
  const groupOf: string[] = []
  if (groups?.length) for (const g of groups) for (let k = 0; k < g.span; k += 1) groupOf.push(g.label)
  const rows = cats.map((cat, i) => {
    const row: Record<string, unknown> = {}
    if (groups?.length) row.group = groupOf[i] ?? ''
    if (edges && edges.length === cats.length + 1) {
      row.from = num(edges[i])
      row.to = num(edges[i + 1])
    } else row.category = cat
    for (const f of fields) row[f.field] = f.pick(i)
    return row
  })
  return { columns, rows }
}

export type ChartStem = {
  xCenter: number
  /** The stem runs from y0 (the baseline or the low dot) to y1 (the value). */
  y0: number
  y1: number
  /** Dot radius. */
  r: number
  color: string
  /** Colour of the low dot of a dumbbell; the high dot uses `color`. */
  color2?: string
  label: string
  series: string
  value: number
  /** The low value of a dumbbell. */
  value2?: number
  /** A dumbbell draws a dot at both ends; a lollipop only at y1. */
  dumbbell: boolean
}

export type ChartStyle = {
  /** The font family for every label. Default: inherited. */
  fontFamily?: string
  /** The base type size in px; the chart's labels scale with it (12 is the
   *  default size, 14 makes every label a sixth larger). */
  fontSize?: number
  /** The plot background. Default: transparent over the page. */
  background?: string
  /** Titles, axis labels and data labels. */
  textColor?: string
  /** Grid lines and axis lines. */
  gridColor?: string
}

export function chartStyleVars(style: ChartStyle | undefined): string {
  if (!style) return ''
  const out: string[] = []
  if (style.background) out.push(`--sg-chart-bg:${style.background}`, `--sg-bg:${style.background}`)
  if (style.textColor) out.push(`--sg-fg:${style.textColor}`, `--sg-muted:${style.textColor}`)
  if (style.gridColor) out.push(`--sg-border:${style.gridColor}`)
  if (style.fontSize && Number.isFinite(style.fontSize) && style.fontSize > 0) out.push(`--sg-chart-font-scale:${Math.round((style.fontSize / 12) * 1000) / 1000}`)
  if (style.fontFamily) out.push(`font-family:${style.fontFamily}`)
  return out.join(';')
}

export function chartSummary(spec: ChartSpec, opts: ChartSummaryOptions = {}): string {
  const fmt = opts.formatValue ?? ((v: number) => formatChartValue(v, spec.valueFormat, spec))
  const max = opts.maxSeries ?? 4
  const cats = spec.categories ?? []
  const series = (spec.series ?? []).filter((s) => s.visible !== false)
  const type = spec.type
  try {
    if (type === 'pie' || type === 'radial-bar' || type === 'nightingale') {
      const s = series[0]
      if (!s || !s.values.some(finite)) return 'No data.'
      return shares(cats, s.values, fmt, 'slice')
    }
    if (type === 'treemap' || type === 'sunburst') {
      const root = spec.treemap ?? spec.tree
      const kids = root?.children ?? []
      if (!kids.length) return 'No data.'
      const total = (n: { value?: number; children?: Array<{ value?: number; children?: unknown[] }> }): number =>
        n.value ?? (n.children ?? []).reduce((a, c) => a + total(c as never), 0)
      return shares(kids.map((k) => k.name), kids.map((k) => total(k)), fmt, 'node')
    }
    if (type === 'gauge') {
      if (!finite(spec.gaugeValue)) return 'No data.'
      const lo = spec.gaugeMin ?? 0
      const hi = spec.gaugeMax ?? 100
      const share = hi > lo ? Math.round(((spec.gaugeValue - lo) / (hi - lo)) * 100) : 0
      const target = finite(spec.gaugeTarget) ? `, ${spec.gaugeValue >= spec.gaugeTarget ? 'above' : 'below'} the target of ${fmt(spec.gaugeTarget)}` : ''
      return `${fmt(spec.gaugeValue)}${spec.gaugeUnit ? ' ' + spec.gaugeUnit : ''}, ${share}% of the way from ${fmt(lo)} to ${fmt(hi)}${target}.`
    }
    if (type === 'scatter') {
      const pts = series.flatMap((s) => s.points ?? []).filter((p) => finite(p.x) && finite(p.y))
      if (!pts.length) return 'No data.'
      const r = pearson(pts.map((p) => p.x), pts.map((p) => p.y))
      const strength = Math.abs(r) >= 0.7 ? 'strong' : Math.abs(r) >= 0.4 ? 'moderate' : Math.abs(r) >= 0.2 ? 'weak' : 'no'
      const sign = r > 0 ? 'positive' : 'negative'
      const rel = strength === 'no' ? 'no clear correlation' : `a ${strength} ${sign} correlation (r ${r.toFixed(2)})`
      return `${pts.length} points in ${series.length} series with ${rel} between x and y.`
    }
    if (type === 'candlestick' || type === 'ohlc') {
      const s = series.find((x) => x.ohlc) ?? series[0]
      const bars = (s?.ohlc ?? []).filter((b): b is NonNullable<typeof b> => !!b)
      if (!s || !bars.length) return 'No data.'
      const last = bars[bars.length - 1]!
      const prev = bars.length > 1 ? bars[bars.length - 2]! : null
      const hi = Math.max(...bars.map((b) => b.h))
      const lo = Math.min(...bars.map((b) => b.l))
      const move = prev ? `, ${last.c >= prev.c ? 'up' : 'down'} ${pct(prev.c, last.c)} on the session` : ''
      return `${s.label}: last close ${fmt(last.c)}${move}, ranging ${fmt(lo)} to ${fmt(hi)} over ${bars.length} bars.`
    }
    if (type === 'heatmap') {
      let best: { v: number; row: string; col: string } | null = null
      for (const s of series) s.values.forEach((v, i) => { if (finite(v) && (!best || v > best.v)) best = { v, row: s.label, col: cats[i] ?? String(i) } })
      if (!best) return 'No data.'
      const b = best as { v: number; row: string; col: string }
      return `${series.length} rows by ${cats.length} columns; the highest cell is ${fmt(b.v)} at ${b.row} and ${b.col}.`
    }
    if (type === 'calendar') {
      const days = (spec.calendarValues ?? []).filter((d) => finite(d.value))
      if (!days.length) return 'No data.'
      const top = days.reduce((a, d) => (d.value > a.value ? d : a), days[0]!)
      const total = days.reduce((a, d) => a + d.value, 0)
      return `${days.length} days totalling ${fmt(total)}; the busiest is ${top.date} at ${fmt(top.value)}.`
    }
    if (type === 'funnel') {
      const s = series[0]
      const vals = (s?.values ?? []).filter(finite)
      if (!s || vals.length < 2) return s && vals.length === 1 ? `${cats[0] ?? s.label}: ${fmt(vals[0]!)}.` : 'No data.'
      const first = vals[0]!
      const last = vals[vals.length - 1]!
      const conv = first ? Math.round((last / first) * 100) : 0
      let worstDrop = 0
      let worstAt = ''
      for (let i = 1; i < vals.length; i += 1) {
        const drop = vals[i - 1]! ? 1 - vals[i]! / vals[i - 1]! : 0
        if (drop > worstDrop) { worstDrop = drop; worstAt = cats[i] ?? `step ${i + 1}` }
      }
      return `${conv}% of ${fmt(first)} at ${cats[0] ?? 'the top'} reach ${cats[vals.length - 1] ?? 'the bottom'}${worstAt ? `; the biggest drop is into ${worstAt} (${Math.round(worstDrop * 100)}% lost)` : ''}.`
    }
    if (type === 'boxplot') {
      let widest: { label: string; spread: number } | null = null
      for (const s of series) for (const b of s.boxes ?? []) {
        if (!b) continue
        const spread = b.q3 - b.q1
        if (!widest || spread > widest.spread) widest = { label: s.label, spread }
      }
      if (!widest) return 'No data.'
      return `${series.length} distributions over ${cats.length} categories; ${widest.label} has the widest interquartile range at ${fmt(widest.spread)}.`
    }
    if (type === 'sankey' || type === 'chord') {
      const links = spec.sankeyLinks ?? []
      if (!links.length) return 'No data.'
      const total = links.reduce((a, l) => a + (finite(l.value) ? l.value : 0), 0)
      const top = [...links].sort((a, b) => b.value - a.value)[0]!
      return `${links.length} flows totalling ${fmt(total)}; the largest is ${top.source} to ${top.target} at ${fmt(top.value)}.`
    }
    // Cartesian families: one sentence per series, up to the cap.
    const usable = series.filter((s) => s.values.some(finite) || s.ohlc)
    if (!usable.length) return 'No data.'
    const shown = usable.slice(0, max)
    const parts = shown.map((s) => describeSeries(s, cats, fmt))
    const more = usable.length > shown.length ? ` And ${usable.length - shown.length} more series.` : ''
    return `${parts.join(' ')}${more}`
  } catch {
    return 'No data.'
  }
}

