export type ClusterOptions = {
  /** Wording of the group labels (the `label*`, `case*`, `punct*` keys); English by default. */
  messages?: Partial<ReviewMessages>
  /** The header to show for a field in group labels. Default: the field itself. */
  fieldLabel?: (field: string) => string
  /** Fewest members a `scale` group needs. Default 5. */
  minScale?: number
  /** Below this, a judgment group sorts with the risky ones. Default 0.6. */
  lowConfidence?: number
}

export function clusterProposals(
  proposals: ReadonlyArray<Proposal>,
  opts: ClusterOptions = {},
): ProposalGroup[] {
  const fieldLabel = opts.fieldLabel ?? ((f: string) => f)
  const msg = reviewMessages(opts.messages)
  const minScale = opts.minScale ?? 5
  const low = opts.lowConfidence ?? 0.6
  const order = new Map<string, number>()
  proposals.forEach((p, i) => order.set(p.id, i))

  const buckets = new Map<string, Bucket>()
  const put = (p: Proposal, kind: GroupKind, param: string) => {
    const key = [p.source.id, p.field, kind, param].join(SEP)
    let b = buckets.get(key)
    if (!b) buckets.set(key, (b = { kind, param, field: p.field, sourceId: p.source.id, members: [] }))
    b.members.push(p)
  }
  const cell = (p: Proposal) => p.source.id + SEP + p.field

  // 1-3: provable per proposal.
  let rest: Proposal[] = []
  for (const p of proposals) {
    const r = ruleOf(p.before, p.after)
    if (r) put(p, r.kind, r.param)
    else rest.push(p)
  }

  // 4: scale, only once enough members share a ratio.
  rest = bucketPass(rest, (p) => {
    const r = ratioOf(p.before, p.after)
    return r == null ? null : cell(p) + SEP + r
  }, (members) => members.length >= minScale, (p, k) => put(p, 'scale', k.slice(k.lastIndexOf(SEP) + 1)))

  // 5: non-blank pairs seen at least twice, one group per target value.
  rest = bucketPass(rest, (p) => (isBlank(p.before) ? null : cell(p) + SEP + keyOf(p.before) + SEP + keyOf(p.after)),
    (members) => members.length >= 2,
    (p) => put(p, 'same-mapping', keyOf(p.after)))

  // 6: blank before, split by the value proposed; singletons go to one pooled group.
  rest = bucketPass(rest, (p) => (isBlank(p.before) ? cell(p) + SEP + keyOf(p.after) : null),
    () => true,
    (p, _k, members) => put(p, 'fill-empty', members.length >= 2 ? keyOf(p.after) : '*'))

  // 7: one target from at least three proposals.
  rest = bucketPass(rest, (p) => cell(p) + SEP + keyOf(p.after),
    (members) => members.length >= 3,
    (p) => put(p, 'constant-target', keyOf(p.after)))

  // 8: everything else, per field.
  for (const p of rest) put(p, 'unpatterned', '')

  const groups: ProposalGroup[] = []
  for (const [key, b] of buckets) {
    const members = b.members.sort((x, y) => order.get(x.id)! - order.get(y.id)!)
    const confs = members.map((m) => m.confidence).filter((c): c is number => typeof c === 'number')
    groups.push({
      key,
      kind: b.kind,
      rule: RULE_KINDS.has(b.kind),
      param: b.param,
      label: labelOf(b.kind, b.param, fieldLabel(b.field), members, msg),
      field: b.field,
      sourceId: b.sourceId,
      ids: members.map((m) => m.id),
      count: members.length,
      minConfidence: confs.length ? Math.min(...confs) : undefined,
      avgConfidence: confs.length ? confs.reduce((s, c) => s + c, 0) / confs.length : undefined,
      sample: sampleOf(members, low),
      beforeDistribution: b.kind === 'constant-target' || b.kind === 'same-mapping' ? distributionOf(members) : undefined,
    })
  }
  return groups.sort((a, b) => rankOf(a, low) - rankOf(b, low) || b.count - a.count || (a.key < b.key ? -1 : 1))
}

export function compareDay(a: Date, b: Date): number {
  const av = startOfDay(a).getTime()
  const bv = startOfDay(b).getTime()
  return av < bv ? -1 : av > bv ? 1 : 0
}

export function computeOverlay(values: number[], spec: SeriesOverlay, extra?: { ohlc?: ReadonlyArray<OhlcBar | null>; volumes?: ReadonlyArray<number> }): number[] {
  return computeOverlayFit(values, spec, extra).values
}

export function computeOverlayFit(values: number[], spec: SeriesOverlay, extra?: { ohlc?: ReadonlyArray<OhlcBar | null>; volumes?: ReadonlyArray<number> }): { values: number[]; r2?: number; equation?: string } {
  const fit = (f: { fitted: number[]; r2: number; equation: string }) => (f.equation ? { values: f.fitted, r2: f.r2, equation: f.equation } : { values: f.fitted })
  const reg = regressionFit(values, spec)
  if (reg) return fit(reg)
  return { values: computeOverlayPlain(values, spec, extra) }
}

export function computePosition(
  reference: Rect,
  floating: Viewport,
  options: ComputePositionOptions = {},
): ComputePositionResult {
  const offset = options.offset ?? 6
  const pad = options.padding ?? 8
  const doFlip = options.flip !== false
  const doShift = options.shift !== false
  const v = resolveViewport(options.viewport)
  const preferred = options.placement ?? 'bottom-start'

  // ---- flip: pick the placement whose main-axis overflow is smallest ----
  const candidates: Placement[] = [preferred]
  if (doFlip) {
    candidates.push(opposite(preferred))
    for (const fb of options.fallbackPlacements ?? []) candidates.push(fb)
  }
  let chosen = preferred
  let best = Infinity
  for (const cand of candidates) {
    const { side, align } = parsePlacement(cand)
    const { x, y } = coordsFor(side, align, reference, floating, offset)
    const overflow = mainAxisOverflow(side, x, y, floating, v, pad)
    if (overflow <= 0) {
      chosen = cand
      best = overflow
      break
    }
    if (overflow < best) {
      best = overflow
      chosen = cand
    }
  }

  const { side, align } = parsePlacement(chosen)
  let { x, y } = coordsFor(side, align, reference, floating, offset)

  // ---- shift: clamp along the CROSS axis so the floating stays in view ----
  if (doShift) {
    if (side === 'top' || side === 'bottom') {
      x = clamp(x, pad, v.width - pad - floating.width)
    } else {
      y = clamp(y, pad, v.height - pad - floating.height)
    }
  }

  // ---- size: available room on the chosen side ----
  const minMain = options.minMainAxis ?? 0
  let maxWidth: number
  let maxHeight: number
  if (side === 'top' || side === 'bottom') {
    const avail = side === 'top' ? reference.y - offset - pad : v.height - pad - (reference.y + reference.height + offset)
    maxHeight = Math.max(minMain, Math.floor(avail))
    maxWidth = Math.max(0, v.width - 2 * pad)
  } else {
    const avail = side === 'left' ? reference.x - offset - pad : v.width - pad - (reference.x + reference.width + offset)
    maxWidth = Math.max(minMain, Math.floor(avail))
    maxHeight = Math.max(0, v.height - 2 * pad)
  }

  const result: ComputePositionResult = { x, y, placement: chosen, side, align, maxWidth, maxHeight }

  // ---- arrow: point at the reference center, clamped inside the floating ----
  if (options.arrow) {
    const a = options.arrow.size
    if (side === 'top' || side === 'bottom') {
      const center = reference.x + reference.width / 2
      const ax = clamp(center - x - a / 2, pad, floating.width - a - pad)
      result.arrow = { x: ax }
    } else {
      const center = reference.y + reference.height / 2
      const ay = clamp(center - y - a / 2, pad, floating.height - a - pad)
      result.arrow = { y: ay }
    }
  }

  return result
}

export type ComputePositionOptions = {
  /** Preferred placement. Default `'bottom-start'`. */
  placement?: Placement
  /** Main-axis gap between reference and floating. Default 6. */
  offset?: number
  /** Viewport edge kept clear on every side. Default 8. */
  padding?: number
  /** Flip to the opposite side when the preferred side overflows. Default true. */
  flip?: boolean
  /** Shift along the cross axis to stay in view (without flipping). Default true. */
  shift?: boolean
  /** Compute `maxWidth`/`maxHeight` for the chosen side. Default true. */
  size?: boolean
  /** When set, compute the arrow offset for an arrow element of this size (px). */
  arrow?: { size: number }
  /** Extra placements to try (after the automatic opposite) before giving up. */
  fallbackPlacements?: Placement[]
  /** Viewport to fit within. Defaults to the window; pure callers pass it. */
  viewport?: Viewport
  /** Floor for the available main-axis size returned by `size`. Default 0. */
  minMainAxis?: number
}

export type ComputePositionResult = {
  /** Floating left, in viewport (fixed-position) coordinates. */
  x: number
  /** Floating top, in viewport (fixed-position) coordinates. */
  y: number
  /** The resolved placement after flip. */
  placement: Placement
  /** The resolved side after flip. */
  side: Side
  /** The resolved cross-axis alignment. */
  align: Align
  /** Space available for the floating on the chosen side's main axis (+cross). */
  maxWidth: number
  maxHeight: number
  /**
   * Arrow offset within the floating box: `x` for top/bottom placements, `y` for
   * left/right. Only present when `options.arrow` is set. Clamped so the arrow
   * stays inside the floating (minus padding).
   */
  arrow?: { x?: number; y?: number }
}

export async function copyExportToClipboard<
  TFeatures extends TableFeatures,
  TData extends RowData,
>(api: SvGridApi<TFeatures, TData>, opts: ClipboardExportOptions<TData> = {}): Promise<void> {
  assertEnterpriseLicensed('Export')
  const format: ClipboardFormat = opts.format ?? 'tsv'
  const sourceRows = resolveRowSource(api, opts.rows)
  if (sourceRows.length === 0) {
    throw new Error('@svgrid/enterprise: nothing to copy - the grid has no rows')
  }
  const cols = resolveColumns(api, opts, sourceRows)
  const projectOpts =
    format === 'json' ? { ...opts, rawValues: opts.rawValues ?? true } : opts
  const projected = await projectRows(sourceRows, cols, projectOpts)
  const { text } = await serializeNative(format, projected, cols, opts)
  await writeClipboard(text, format)
}

export function createBlockCache<TData>(options: BlockCacheOptions<TData>): BlockCache<TData> {
  const blockSize = Math.max(1, options.blockSize ?? 100)
  const maxBlocks = options.maxBlocksInCache ?? Infinity
  const maxConcurrent = Math.max(1, options.maxConcurrentRequests ?? 2)
  const debounceMs = Math.max(0, options.blockLoadDebounceMs ?? 0)
  const initialRowCount = Math.max(0, options.initialRowCount ?? 1)
  const overflowRows = Math.max(0, options.overflowRows ?? 1)
  const schedule = options.schedule ?? defaultSchedule

  const blocks = new Map<number, Block<TData>>()
  /** Block indices waiting for a slot, in the order the viewport asked for them. */
  const queue: number[] = []
  let inFlight = 0
  let touchClock = 0
  let count: number | null = null
  let countKnown = false
  let disposed = false

  let viewStart = 0
  let viewEnd = 0
  let debounceTimer: ReturnType<typeof setTimeout> | null = null

  let emitScheduled = false
  let rowsCache: TData[] | null = null
  let windowedCache: TData[] | null = null

  const blockOf = (rowIndex: number): number => Math.floor(rowIndex / blockSize)
  const startOf = (blockIndex: number): number => blockIndex * blockSize

  /**
   * How many rows to claim we have.
   *
   * With a known count that is simply the count. Without one it is the last row
   * we have touched plus `overflowRows`, so there is always somewhere to scroll
   * that will ask for the next block - this is what makes the list grow as you
   * go rather than ending at the first unloaded row.
   */
  function currentLength(): number {
    if (countKnown && count != null) return count
    let highestEnd = 0
    let anySettled = false
    for (const b of blocks.values()) if (b.status !== 'loading') anySettled = true
    for (const [index, block] of blocks) {
      // A block in flight extends the list only once some block has settled.
      // Before that the list is `initialRowCount` long: the few skeleton
      // rows a level shows while it waits, not a hundred of them. The first
      // block failing says nothing about how long the list is either, so it
      // keeps those few rows (its Retry sits on them); a failed block further
      // in was scrolled to, so its slots stay and the scrollbar holds still.
      const end = block.status === 'loaded'
        ? startOf(index) + block.rows.length
        : block.status === 'failed'
          ? index === 0 ? 0 : startOf(index) + blockSize
          : anySettled
            ? startOf(index) + blockSize
            : 0
      if (end > highestEnd) highestEnd = end
    }
    if (!anySettled) return initialRowCount
    return Math.max(initialRowCount, highestEnd + overflowRows)
  }

  function state(): BlockCacheState {
    const failed: number[] = []
    for (const [index, block] of blocks) if (block.status === 'failed') failed.push(index)
    return {
      rowCount: countKnown ? count : null,
      lastRowKnown: countKnown,
      loading: inFlight > 0,
      failedBlocks: failed.sort((a, b) => a - b),
    }
  }

  /**
   * Something changed: forget the row array NOW, so a synchronous read after
   * a mutation sees the new state, and notify on the next tick, so a burst of
   * mutations notifies once. Every mutating path ends here.
   */
  function emit(): void {
    rowsCache = windowedCache = null // rebuilt lazily, on the next read
    if (disposed || emitScheduled) return
    emitScheduled = true
    schedule(() => {
      emitScheduled = false
      if (disposed) return
      options.onChange(state())
    })
  }

  function ensureBlock(blockIndex: number): void {
    if (disposed) return
    const existing = blocks.get(blockIndex)
    // Loading or loaded blocks are left alone; a failed one only retries when
    // asked, so a broken backend is not hammered once per scroll frame.
    if (existing) return
    if (queue.includes(blockIndex)) return
    queue.push(blockIndex)
    pump()
  }

  function pump(): void {
    while (!disposed && inFlight < maxConcurrent && queue.length > 0) {
      const blockIndex = queue.shift()!
      if (blocks.has(blockIndex)) continue
      void load(blockIndex)
    }
  }

  async function load(blockIndex: number): Promise<void> {
    const controller = new AbortController()
    const block: Block<TData> = {
      status: 'loading',
      rows: [],
      lastTouched: (touchClock += 1),
      controller,
    }
    blocks.set(blockIndex, block)
    inFlight += 1
    emit()

    const startRow = startOf(blockIndex)
    const endRow = startRow + blockSize
    try {
      const result = await options.fetch(startRow, endRow, controller.signal)
      if (disposed || controller.signal.aborted || blocks.get(blockIndex) !== block) return
      block.rows = [...result.rows]
      block.status = 'loaded'
      block.controller = null
      applyCountFrom(blockIndex, block.rows.length, result.rowCount)
      evictIfNeeded()
    } catch {
      if (disposed || controller.signal.aborted || blocks.get(blockIndex) !== block) return
      block.status = 'failed'
      block.rows = []
      block.controller = null
    } finally {
      if (!disposed && !controller.signal.aborted) {
        inFlight -= 1
        emit()
        pump()
      }
    }
  }

  /**
   * Learn the total from a block that just landed.
   *
   * An explicit non-negative `rowCount` settles it. Otherwise a SHORT block is
   * the proof that we hit the end: fewer rows came back than were asked for, so
   * the data stops where they stop.
   */
  function applyCountFrom(blockIndex: number, received: number, reported: number | undefined): void {
    if (typeof reported === 'number' && reported >= 0) {
      count = reported
      countKnown = true
      return
    }
    if (received < blockSize) {
      count = startOf(blockIndex) + received
      countKnown = true
    }
  }

  /**
   * Evict loaded blocks over the limit, least-recently-seen first, never one
   * the viewport is currently on - dropping a visible block would swap real
   * rows for skeletons under the user's eyes and immediately re-fetch them.
   */
  function evictIfNeeded(): void {
    if (!Number.isFinite(maxBlocks)) return
    const firstVisible = blockOf(viewStart)
    const lastVisible = blockOf(Math.max(viewStart, viewEnd))
    const evictable = [...blocks.entries()]
      .filter(([index, b]) => b.status === 'loaded' && (index < firstVisible || index > lastVisible))
      .sort((a, b) => a[1].lastTouched - b[1].lastTouched)

    let loaded = 0
    for (const b of blocks.values()) if (b.status === 'loaded') loaded += 1

    for (const [index] of evictable) {
      if (loaded <= maxBlocks) break
      blocks.delete(index)
      loaded -= 1
    }
  }

  function fetchViewport(): void {
    if (disposed) return
    const first = blockOf(viewStart)
    const last = blockOf(Math.max(viewStart, viewEnd))
    for (let i = first; i <= last; i += 1) {
      const block = blocks.get(i)
      if (block) block.lastTouched = touchClock += 1
      else ensureBlock(i)
    }
  }

  function rowAt(index: number): TData | typeof LOADING_ROW | typeof FAILED_ROW {
    const block = blocks.get(blockOf(index))
    if (!block) return LOADING_ROW
    if (block.status === 'failed') return FAILED_ROW
    const row = block.rows[index - startOf(blockOf(index))]
    return row ?? LOADING_ROW
  }

  function abortAll(): void {
    for (const block of blocks.values()) block.controller?.abort()
    inFlight = 0
    queue.length = 0
  }

  return {
    setViewport(startIndex, endIndex) {
      if (disposed) return
      viewStart = Math.max(0, startIndex)
      viewEnd = Math.max(viewStart, endIndex)
      if (debounceMs === 0) {
        fetchViewport()
        return
      }
      if (debounceTimer) clearTimeout(debounceTimer)
      debounceTimer = setTimeout(() => {
        debounceTimer = null
        fetchViewport()
      }, debounceMs)
    },

    rows() {
      if (rowsCache) return rowsCache
      const length = currentLength()
      const out = new Array<TData>(length)
      // Fill from the blocks we have, then pad the rest with placeholders. One
      // pass per block beats one lookup per row: at a million rows the
      // difference is the frame budget.
      out.fill(LOADING_ROW as unknown as TData)
      for (const [index, block] of blocks) {
        const start = startOf(index)
        if (start >= length) continue
        if (block.status === 'failed') {
          const end = Math.min(start + blockSize, length)
          for (let i = start; i < end; i += 1) out[i] = FAILED_ROW as unknown as TData
          continue
        }
        for (let i = 0; i < block.rows.length && start + i < length; i += 1) {
          out[start + i] = block.rows[i]!
        }
      }
      rowsCache = out
      return out
    },

    windowedRows() {
      if (windowedCache) return windowedCache
      windowedCache = createWindowedData<TData>(currentLength(), (i) => rowAt(i) as TData)
      return windowedCache
    },

    getRow: rowAt,

    rowCount: () => (countKnown ? count : null),
    lastRowKnown: () => countKnown,

    retryFailed() {
      let any = false
      for (const [index, block] of [...blocks]) {
        if (block.status !== 'failed') continue
        blocks.delete(index)
        ensureBlock(index)
        any = true
      }
      if (any) emit()
    },

    retryFailedAt(rowIndex) {
      const index = blockOf(Math.max(0, rowIndex))
      if (blocks.get(index)?.status !== 'failed') return
      blocks.delete(index)
      ensureBlock(index)
      emit()
    },

    refresh() {
      // Keep the count and the scroll position: drop the DATA, re-request the
      // same blocks. The user sees skeletons where they were, not a jump home.
      for (const [index, block] of [...blocks]) {
        block.controller?.abort()
        blocks.delete(index)
        ensureBlock(index)
      }
      emit()
    },

    purge() {
      abortAll()
      blocks.clear()
      count = null
      countKnown = false
      rowsCache = windowedCache = null
      fetchViewport()
      emit()
    },

    setRowCount(next, known = next != null) {
      count = next
      countKnown = known && next != null
      emit()
    },

    applyRows(startRow, rows, rowCount) {
      if (startRow % blockSize !== 0) {
        throw new Error(
          `createBlockCache.applyRows: startRow ${startRow} is not a multiple of blockSize ${blockSize}`,
        )
      }
      const firstBlock = blockOf(startRow)
      const blockCount = Math.ceil(rows.length / blockSize)
      for (let i = 0; i < blockCount; i += 1) {
        const index = firstBlock + i
        blocks.get(index)?.controller?.abort() // ours now, whatever was in flight
        blocks.set(index, {
          status: 'loaded',
          rows: rows.slice(i * blockSize, (i + 1) * blockSize),
          lastTouched: (touchClock += 1),
          controller: null,
        })
      }
      const lastBlock = blocks.get(firstBlock + blockCount - 1)
      if (lastBlock) applyCountFrom(firstBlock + blockCount - 1, lastBlock.rows.length, rowCount)
      else if (typeof rowCount === 'number' && rowCount >= 0) {
        count = rowCount
        countKnown = true
      }
      emit()
    },

    patch(index, row) {
      const block = blocks.get(blockOf(index))
      if (!block || block.status !== 'loaded') return false
      const offset = index - startOf(blockOf(index))
      if (offset < 0 || offset >= block.rows.length) return false
      block.rows[offset] = row
      emit()
      return true
    },

    findIndex(predicate) {
      for (const [blockIndex, block] of blocks) {
        if (block.status !== 'loaded') continue
        const start = startOf(blockIndex)
        for (let i = 0; i < block.rows.length; i += 1) {
          if (predicate(block.rows[i]!, start + i)) return start + i
        }
      }
      return -1
    },

    insert(index, rows) {
      if (rows.length === 0) return false
      const clamped = Math.max(0, Math.min(index, currentLength()))
      const run = loadedRunAt(clamped)
      if (run) {
        // Rows shift across block boundaries, so re-slice the run from its
        // first block; everything loaded past it is dropped (offsets moved).
        run.flat.splice(clamped - startOf(run.startBlock), 0, ...rows)
        reseat(run.startBlock, run.flat)
      } else {
        dropLoadedFrom(blockOf(clamped))
      }
      if (countKnown && count != null) count += rows.length
      emit()
      return run != null
    },

    remove(index, removeCount = 1) {
      if (removeCount <= 0) return 0
      const run = loadedRunAt(index)
      if (!run) return 0
      const removed = run.flat.splice(index - startOf(run.startBlock), removeCount).length
      reseat(run.startBlock, run.flat)
      if (countKnown && count != null) count = Math.max(0, count - removed)
      emit()
      return removed
    },

    getCacheState() {
      return [...blocks.entries()]
        .map(([blockIndex, block]) => ({
          blockIndex,
          startRow: startOf(blockIndex),
          endRow: startOf(blockIndex) + blockSize,
          status: block.status,
          lastTouched: block.lastTouched,
        }))
        .sort((a, b) => a.blockIndex - b.blockIndex)
    },

    dispose() {
      disposed = true
      if (debounceTimer) clearTimeout(debounceTimer)
      debounceTimer = null
      abortAll()
      blocks.clear()
    },
  }

  /**
   * The run of consecutive loaded blocks containing `index`, flattened, with
   * the block it starts at. Null when the block at `index` is not loaded -
   * an index-shifting edit there would have nothing to shift.
   */
  function loadedRunAt(index: number): { startBlock: number; flat: TData[] } | null {
    const at = blockOf(index)
    if (blocks.get(at)?.status !== 'loaded') return null
    let startBlock = at
    while (blocks.get(startBlock - 1)?.status === 'loaded') startBlock -= 1
    const flat: TData[] = []
    for (let i = startBlock; ; i += 1) {
      const block = blocks.get(i)
      if (!block || block.status !== 'loaded') break
      flat.push(...block.rows)
      if (block.rows.length < blockSize) break // the last block, by definition
    }
    return { startBlock, flat }
  }

  /**
   * Lay a flat run back out into blocks from `startBlock`, and drop every
   * block after the run: their rows have shifted, and re-fetching them at
   * the new offsets is the honest outcome. Blocks before it are untouched.
   */
  function reseat(startBlock: number, flat: TData[]): void {
    const blockCount = Math.ceil(flat.length / blockSize)
    dropLoadedFrom(startBlock)
    for (let i = 0; i < blockCount; i += 1) {
      blocks.set(startBlock + i, {
        status: 'loaded',
        rows: flat.slice(i * blockSize, (i + 1) * blockSize),
        lastTouched: (touchClock += 1),
        controller: null,
      })
    }
    rowsCache = windowedCache = null
  }

  /** Forget every block from `fromBlock` on, aborting any in flight. */
  function dropLoadedFrom(fromBlock: number): void {
    for (const [index, block] of [...blocks]) {
      if (index < fromBlock) continue
      block.controller?.abort()
      blocks.delete(index)
    }
    rowsCache = windowedCache = null
  }
}

export function createCoreRowModel<TData extends RowData>(): RowModelFactory<TData> {
  return ({ rows }) => rows
}

export function createExpandedRowModel<TData extends RowData>(): RowModelFactory<TData> {
  return ({ table, rows }) => {
    const expanded: ExpandedState = table.getState().expanded ?? {}
    // Nothing expanded means every collapsed row hides its children and the
    // output is the input, element for element. Returning it as is keeps the
    // array identity the stages downstream and the render window key on, and
    // skips a 100k-element copy per data change on a flat grid.
    let anyExpanded = false
    for (const id in expanded) {
      if (expanded[id]) { anyExpanded = true; break }
    }
    if (!anyExpanded) return rows
    const flattened: Array<Row<TData>> = []
    const visit = (row: Row<TData>) => {
      flattened.push(row)
      if (row.subRows?.length && expanded[row.id]) {
        for (const sub of row.subRows) visit(sub)
      }
    }
    for (const row of rows) visit(row)
    return flattened
  }
}

export function createFilteredRowModel<TData extends RowData>(): RowModelFactory<TData> {
  /**
   * The last full filter, so a tick can repair it. When `getRowModel`
   * reports which rows were replaced (`replacedRowsOf`) and the filter state
   * and columns are the same objects as last time, each replacement is tested
   * on its own: a row that stays in keeps its slot, a row that stays out
   * stays out, and a row whose membership flips sends the whole thing back
   * through the full pass, because an insertion has to land in data order.
   * Positions come from stamps on the rows (ROW_FILTER_GEN / ROW_FILTER_POS)
   * written by the full pass; no map is built.
   */
  let cache: { input: Array<Row<TData>>; output: Array<Row<TData>>; filters: ColumnFiltersState; columns: Array<Column<TData>>; gen: number } | null = null
  let generation = 0

  return ({ table, rows }) => {
    const filters: ColumnFiltersState = table.getState().columnFilters ?? []
    if (!filters.length) {
      cache = null
      return rows
    }
    const columns = table.getAllColumns()

    // Resolve each filter's match function once, outside the row loop.
    const compiled = filters.map((filter) => ({
      id: filter.id,
      value: filter.value,
      fn: filter.fn ? filterFns[filter.fn] : filterFns.includesString,
    }))
    const passes = (row: Row<TData>) => {
      for (let i = 0; i < compiled.length; i++) {
        const filter = compiled[i]!
        // `getCellValueByColumnId` rather than `getAllCells().find(...)`.
        // Both read the same lazily-built `cachedValues` array, but the latter
        // also builds and caches the row's whole `Cell[]` - one object per
        // column - purely to reach one field. On a 100k-row grid that is
        // 100,000 cell arrays the filter never looks at again, and it defeats
        // the laziness the row factory exists to provide.
        if (!filter.fn(row.getCellValueByColumnId(filter.id), filter.value as any)) return false
      }
      return true
    }

    if (cache && cache.filters === filters && cache.columns === columns) {
      if (cache.input === rows) return cache.output
      const replaced = replacedRowsOf(table)
      if (replaced && rows.length === cache.input.length) {
        let out: Array<Row<TData>> | null = null
        let ok = true
        for (let i = 0; i < rows.length && ok; i++) {
          const prev = cache.input[i]! as BaseRowState<TData>
          const next = rows[i]! as BaseRowState<TData>
          if (next === prev) continue
          if (replaced.get(prev) !== next) { ok = false; break }
          const wasIn = prev[ROW_FILTER_GEN] === cache.gen
          const isIn = passes(next)
          if (wasIn !== isIn) { ok = false; break }
          if (!isIn) continue
          out ??= cache.output.slice()
          const pos = prev[ROW_FILTER_POS]
          out[pos] = next
          next[ROW_FILTER_GEN] = cache.gen
          next[ROW_FILTER_POS] = pos
        }
        if (ok) {
          const output = out ?? cache.output
          cache = { ...cache, input: rows, output }
          return output
        }
      }
    }

    const gen = ++generation
    const output: Array<Row<TData>> = []
    for (let i = 0; i < rows.length; i++) {
      const row = rows[i]! as BaseRowState<TData>
      if (!passes(row)) continue
      row[ROW_FILTER_GEN] = gen
      row[ROW_FILTER_POS] = output.length
      output.push(row)
    }
    cache = { input: rows, output, filters, columns, gen }
    return output
  }
}

export function createGridTools(opts: GridToolsOptions): GridTool[] {
  const prefix = opts.prefix ?? 'grid_'
  const source = opts.source ?? { kind: 'agent', id: 'agent', label: 'Agent' }
  const maxRows = opts.maxRows ?? 200
  const maxEdits = opts.maxEdits ?? 500
  const api = (): ToolApi => {
    const a = typeof opts.api === 'function' ? (opts.api as () => ToolApi | null | undefined)() : opts.api
    if (!a) throw new Error('the grid is not ready yet')
    return a
  }
  const rowIdOf = (a: ToolApi) => {
    const fn = a.getOption('getRowId') as ((row: unknown, i: number) => string) | undefined
    if (!fn) throw new Error('the grid needs a getRowId prop')
    return fn
  }
  const columns = (a: ToolApi) => a.getColumns().filter((c) => c.field)
  const writable = (a: ToolApi) => new Set(opts.fields ?? columns(a).map((c) => c.field!))

  const describe: GridTool = {
    name: `${prefix}describe`,
    description:
      'Describe the table: its columns (field, header, data type), how many rows it has, and which fields you may propose edits to. ' +
      'Edits you propose are not applied: a person reviews them in groups and accepts or rejects them.',
    inputSchema: { type: 'object', properties: {}, additionalProperties: false },
    async execute() {
      const a = api()
      const canWrite = writable(a)
      return {
        rowCount: a.getData().length,
        columns: columns(a).map((c) => ({ field: c.field, header: c.header, type: c.cellDataType ?? 'text', writable: canWrite.has(c.field!) })),
      }
    },
  }

  const query: GridTool = {
    name: `${prefix}query_rows`,
    description:
      `Read rows of the table. Filter with "where" (all conditions must hold), pick fields, page with offset/limit (at most ${maxRows}). ` +
      'Every row comes with its rowId, which grid_propose_edits needs.',
    inputSchema: {
      type: 'object',
      properties: {
        where: {
          type: 'array',
          items: {
            type: 'object',
            properties: { field: { type: 'string' }, op: { type: 'string', enum: OPS }, value: {} },
            required: ['field', 'op'],
          },
        },
        fields: { type: 'array', items: { type: 'string' } },
        offset: { type: 'integer', minimum: 0 },
        limit: { type: 'integer', minimum: 1, maximum: maxRows },
      },
      additionalProperties: false,
    },
    async execute(input: { where?: Where[]; fields?: string[]; offset?: number; limit?: number } = {}) {
      const a = api()
      const id = rowIdOf(a)
      const known = new Set(columns(a).map((c) => c.field!))
      for (const w of input.where ?? []) {
        if (!known.has(w.field)) throw new Error(`unknown field "${w.field}"`)
        if (!OPS.includes(w.op)) throw new Error(`unknown op "${w.op}"`)
      }
      const fields = (input.fields ?? [...known]).filter((f) => known.has(f))
      const hits = a.getData().flatMap((row, i) =>
        (input.where ?? []).every((w) => matches((row as Record<string, unknown>)[w.field], w)) ? [{ row, i }] : [],
      )
      // The schema says integers; a model can still send "10" or -5.
      const offset = Math.max(0, Math.trunc(Number(input.offset) || 0))
      const limit = Math.min(Math.max(1, Math.trunc(Number(input.limit) || maxRows)), maxRows)
      return {
        total: hits.length,
        offset,
        rows: hits.slice(offset, offset + limit).map(({ row, i }) => ({
          rowId: String(id(row, i)),
          ...Object.fromEntries(fields.map((f) => [f, (row as Record<string, unknown>)[f]])),
        })),
      }
    },
  }

  const propose: GridTool = {
    name: `${prefix}propose_edits`,
    description:
      'Propose new values for cells. Nothing is written: each edit becomes a proposal a person reviews. ' +
      'Give a short reason per edit, and a confidence from 0 to 1 when you are unsure. ' +
      'Edits to unknown rows, to fields you may not edit, or that change nothing are skipped and reported.',
    inputSchema: {
      type: 'object',
      properties: {
        title: { type: 'string', description: 'What this batch does, in a few words.' },
        edits: {
          type: 'array',
          minItems: 1,
          maxItems: maxEdits,
          items: {
            type: 'object',
            properties: {
              rowId: { type: 'string' },
              field: { type: 'string' },
              value: {},
              reason: { type: 'string' },
              confidence: { type: 'number', minimum: 0, maximum: 1 },
            },
            required: ['rowId', 'field', 'value'],
          },
        },
      },
      required: ['edits'],
      additionalProperties: false,
    },
    async execute(input: { title?: string; edits: Array<{ rowId: string; field: string; value: unknown; reason?: string; confidence?: number }> }) {
      const a = api()
      const edits = Array.isArray(input?.edits) ? input.edits : []
      if (edits.length > maxEdits) throw new Error(`at most ${maxEdits} edits per call; send the rest in another call`)
      const id = rowIdOf(a)
      const canWrite = writable(a)
      const typeOf = new Map(a.getColumns().filter((c) => c.field).map((c) => [c.field!, c.cellDataType ?? 'text']))
      const rows = new Map(a.getData().map((row, i) => [String(id(row, i)), row as Record<string, unknown>]))
      const skipped: Array<{ index: number; why: string }> = []
      const proposals: ProposalInput[] = []
      edits.forEach((e, index) => {
        const row = rows.get(String(e?.rowId))
        if (!row) return skipped.push({ index, why: `no row with rowId "${e?.rowId}"` })
        if (!canWrite.has(e.field)) return skipped.push({ index, why: `field "${e.field}" is not writable` })
        const why = wrongType(typeOf.get(e.field), row[e.field], e.value)
        if (why) return skipped.push({ index, why: `${e.field} ${why}` })
        if (sameValue(row[e.field], e.value)) return skipped.push({ index, why: 'the cell already holds this value' })
        const confidence = typeof e.confidence === 'number' ? Math.min(1, Math.max(0, e.confidence)) : undefined
        proposals.push({ rowId: String(e.rowId), field: e.field, before: row[e.field], after: e.value, reason: e.reason, confidence })
      })
      const set = proposals.length ? opts.review.add({ source, title: input.title, proposals }) : null
      return {
        proposed: set?.proposals.length ?? 0,
        setId: set?.id ?? null,
        skipped,
        note: 'Proposed, not applied. A person will review these; call grid_review_status to see what was decided.',
      }
    },
  }

  const status: GridTool = {
    name: `${prefix}review_status`,
    description:
      'What happened to your proposals: how many are still pending, accepted, rejected, or stale (the cell changed before review), ' +
      'and the pending groups as the reviewer sees them.',
    inputSchema: { type: 'object', properties: {}, additionalProperties: false },
    async execute() {
      const mine = opts.review.proposals().filter((p) => p.source.id === source.id)
      const count = (s: Proposal['status']) => mine.filter((p) => p.status === s).length
      return {
        pending: count('pending'),
        accepted: count('accepted'),
        rejected: count('rejected'),
        stale: count('stale'),
        conflicts: count('conflict'),
        groups: opts.review.groups().filter((g) => g.sourceId === source.id).map((g) => ({ label: g.label, kind: g.kind, count: g.count })),
      }
    },
  }

  return [describe, query, propose, status]
}

export function createGroupedRowModel<TData extends RowData>(): RowModelFactory<TData> {
  return ({ table, rows }) => {
    const grouping: GroupingState = table.getState().grouping ?? []
    if (!grouping.length) return rows
    const columns = table.getAllColumns()

    // Recursively bucket rows by each grouping column in turn. At every level a
    // group row is built that stands in for its children - a non-group column
    // resolves to the value shared by every leaf row, or to undefined when the
    // leaves disagree.
    function buildGroups(
      input: Array<Row<TData>>,
      levelIndex: number,
      depth: number,
      idPrefix: string,
      /** Grouping columns already fixed by an ancestor bucket, and their raw
       *  values - `undefined` where that bucket mixed several. */
      fixedValues: ReadonlyMap<string, unknown>,
    ): Array<Row<TData>> {
      if (levelIndex >= grouping.length) {
        // Leaves: actual data rows, with their nesting depth recorded.
        return input.map((row) => ({ ...row, depth }))
      }
      const groupKey = grouping[levelIndex]
      if (!groupKey) return input

      // Buckets carry the RAW grouping value alongside the rows, plus whether
      // the bucket saw more than one distinct raw value. Both are needed to let
      // deeper levels skip re-scanning this column: buckets are keyed by
      // `String(value ?? '')`, so `null`, `undefined` and `''` collapse into one
      // bucket, and a scan of such a bucket would report disagreement. Tracking
      // it here costs one comparison per row and keeps the shortcut honest.
      type Bucket = { rows: Array<Row<TData>>; raw: unknown; mixed: boolean }
      const buckets = new Map<string, Bucket>()
      for (const row of input) {
        const value = row.getCellValueByColumnId(groupKey)
        const key = String(value ?? '')
        const bucket = buckets.get(key)
        if (bucket) {
          bucket.rows.push(row)
          if (!bucket.mixed && bucket.raw !== value) bucket.mixed = true
        } else {
          buckets.set(key, { rows: [row], raw: value, mixed: false })
        }
      }

      const groupRows: Array<Row<TData>> = []
      let index = 0
      buckets.forEach((bucket, key) => {
        const children = bucket.rows
        const id = `${idPrefix}_${groupKey}_${key}`
        // Record this column as fixed for deeper levels ONLY when the bucket is
        // homogeneous. If all rows here share a raw value, so does every subset
        // of them, which is what makes the shortcut sound.
        //
        // A MIXED bucket must not be recorded at all - not even as "undefined".
        // `null`, `undefined` and `''` share a bucket key, so a mixed bucket can
        // still split into homogeneous children one level down, and those
        // children have a real shared value that a scan would find. Marking the
        // column resolved here would hand them the parent's disagreement.
        const nextFixed = bucket.mixed ? fixedValues : new Map(fixedValues).set(groupKey, bucket.raw)
        const subRows = buildGroups(children, levelIndex + 1, depth + 1, id, nextFixed)
        const isDeepest = levelIndex + 1 >= grouping.length
        const leafCount = isDeepest
          ? subRows.length
          : subRows.reduce((sum, sub) => sum + (sub.leafCount ?? 0), 0)

        // Every grouping column ABOVE this level is already resolved: bucketing
        // by it is what made it constant, so scanning the children to rediscover
        // it is pure waste. Only the current level's key short-circuited before,
        // so a second-level group walked all of its children to re-derive the
        // first level's value - about 100,000 reads on the 100k x 9 two-level
        // case, for an answer already in hand.
        //
        // The current level still returns the stringified bucket key rather than
        // the raw value, because that is what it has always returned and the
        // group row's display depends on it.
        const resolveColumnValue = (columnId: string): unknown => {
          if (columnId === groupKey) return key
          if (fixedValues.has(columnId)) return fixedValues.get(columnId)
          let resolved: unknown
          let hasResolved = false
          for (const child of children) {
            const childValue = child.getCellValueByColumnId(columnId)
            if (!hasResolved) {
              resolved = childValue
              hasResolved = true
            } else if (childValue !== resolved) {
              return undefined
            }
          }
          return resolved
        }

        const groupOriginal: Record<string, unknown> = {}
        columns.forEach((column) => {
          const field = column.columnDef.field
          if (!field) return
          const agg = column.columnDef.aggregate
          groupOriginal[field] = agg
            ? applyGroupAggregate(agg, column.id, children)
            : resolveColumnValue(column.id)
        })

        const groupRow: Row<TData> = {
          id,
          index: index++,
          original: groupOriginal as TData,
          depth,
          subRows,
          leafCount,
          getCanExpand: () => true,
          getIsExpanded: () => Boolean((table.getState().expanded ?? {})[id]),
          toggleExpanded: () => {
            table.setExpanded((prev) => ({ ...prev, [id]: !prev[id] }))
          },
          getIsSelected: () => Boolean((table.getState().rowSelection ?? {})[id]),
          toggleSelected: () => {
            table.setRowSelection((prev) => ({ ...prev, [id]: !prev[id] }))
          },
          getAllCells: () => [],
          // Prefer the precomputed group value (which carries aggregates)
          // and fall back to the shared-value resolver for columns without
          // a field.
          getCellValueByColumnId: (columnId: string) => {
            const col = columns.find((c) => c.id === columnId)
            const field = col?.columnDef.field
            if (field && field in groupOriginal) return groupOriginal[field]
            return resolveColumnValue(columnId)
          },
        }
        groupRows.push(groupRow)
      })
      return groupRows
    }

    return buildGroups(rows, 0, 0, 'group', new Map())
  }
}

export function createPaginatedRowModel<TData extends RowData>(): RowModelFactory<TData> {
  return ({ table, rows }) => {
    const pagination = table.getState().pagination ?? { pageIndex: 0, pageSize: rows.length || 10 }
    const start = pagination.pageIndex * pagination.pageSize
    return rows.slice(start, start + pagination.pageSize)
  }
}

export function createPivotModel<
  TFeatures extends TableFeatures,
  TData extends RowData,
>(
  data: ReadonlyArray<TData>,
  config: PivotConfig<TData>,
): PivotResult<TFeatures> {
  if (config.values.length === 0) {
    throw new Error('pivot: at least one value config is required')
  }

  const rowFields = config.rows as ReadonlyArray<string>
  const colFields = config.cols as ReadonlyArray<string>
  const values    = config.values as ReadonlyArray<PivotValueConfig<unknown>>

  // 1. axis trees
  const rowRoot = buildAxisTree(data, rowFields, config.rowSort)
  const colRoot = buildAxisTree(data, colFields, config.colSort)

  // 2. collect col-axis leaf paths (one per value column header chain)
  const colLeafPaths: Array<ReadonlyArray<unknown>> = []
  collectColLeafPaths(colRoot, colLeafPaths)

  // 3. flatten row-axis to pivot rows
  const rows: PivotRow[] = []
  if (rowFields.length === 0) {
    // No row dims: one synthetic "All" row.
    rows.push({
      __pivotId: 'row__all',
      __pivotKind: 'leaf',
      __pivotDepth: 0,
      __pivotLabel: '(All)',
      __pivotParentId: null,
      __pivotExpandable: false,
      ...computeRowValues(
        data as unknown as ReadonlyArray<Record<string, unknown>>,
        colLeafPaths,
        colFields,
        values,
        config.grandTotalCol !== false,
      ),
    })
  } else {
    walkRowTree(
      rowRoot, rows, colLeafPaths, colFields, values,
      config as PivotConfig<unknown>, rowFields, null,
    )
  }

  // 4. grand-total row at bottom
  if (config.grandTotalRow !== false) {
    rows.push({
      __pivotId: 'row__grand_total',
      __pivotKind: 'grandTotal',
      __pivotDepth: 0,
      __pivotLabel: 'Grand total',
      __pivotParentId: null,
      __pivotExpandable: false,
      ...computeRowValues(
        data as unknown as ReadonlyArray<Record<string, unknown>>,
        colLeafPaths,
        colFields,
        values,
        config.grandTotalCol !== false,
      ),
    })
  }

  // 5. column tree
  const columns = buildColumnTree<TFeatures>(
    colRoot,
    values,
    config as PivotConfig<unknown>,
    rowFields.length > 0 ? rowFields.join(' / ') : '',
  )

  return { rows, columns }
}

export function createReview<TData = unknown>(opts: ReviewOptions<TData>) {
  if (!opts.setRows && !opts.server) throw new Error('[svgrid review] pass setRows (client data) or server (server row model)')
  if (opts.server && !opts.onCommit) throw new Error('[svgrid review] onCommit is required with a server row model')
  const msg = reviewMessages(opts.messages)
  // Without a key: watermark and a one-time nudge. The review still runs.
  nudgeEnterprise('Change review')
  // Proposed values beside rich cells (selects, ratings): registered by the
  // first review, so grids in apps without one keep the plain fast path.
  registerRichCellMarks()

  const all = new Map<string, Proposal>()
  const sets = new Map<string, Omit<ChangeSet, 'proposals'> & { ids: string[] }>()
  /** Live proposals (pending or in conflict) per cell. */
  const byCell = new Map<string, Set<string>>()
  const inFlight = new Set<string>()
  /** Decision order for the log: timestamps tie within one millisecond. */
  const decidedOrder = new Map<string, number>()
  let lastError = $state<{ error: unknown; during: 'undo' | 'redo'; at: number } | null>(null)
  function failed(error: unknown, during: 'undo' | 'redo') {
    lastError = { error, during, at: Date.now() }
    opts.onError?.(error, during)
  }
  let decisionSeq = 0
  const stamp = (p: Proposal) => decidedOrder.set(p.id, ++decisionSeq)
  let version = $state(0)
  // "Only rows with changes": our node ANDed onto the advanced filter. Put on
  // again after every change so the grid filters with the new pending set.
  const filterToken = nextId('rv-')
  let pendingOnly = $state(false)
  let filterNonce = 0
  let pendingRows: { v: number; ids: Set<string> } | null = null
  const pendingSource = { hasPendingRow: (rowId: string) => hasPendingRow(rowId) }
  function hasPendingRow(rowId: string): boolean {
    if (pendingRows?.v !== version) {
      const ids = new Set<string>()
      for (const p of all.values()) if (p.status === 'pending' || p.status === 'conflict') ids.add(p.rowId)
      pendingRows = { v: version, ids }
    }
    return pendingRows.ids.has(rowId)
  }
  function applyPendingFilter() {
    const api = getApi()
    if (!api) return
    const current = api.getAdvancedFilter()
    // The user's own filter tools may have dropped the node: then the toggle is off.
    if (filterNonce > 0 && !hasPending(current)) {
      pendingOnly = false
      return
    }
    api.setAdvancedFilter(withPending(current, filterToken, ++filterNonce))
  }
  const bump = () => {
    version += 1
    if (pendingOnly) applyPendingFilter()
  }

  /**
   * Show only rows with a pending or conflicting proposal, on top of the
   * user's own filters; off takes our condition back out and leaves theirs.
   * Rows leave the view as their proposals are decided.
   */
  function showPendingOnly(on: boolean): void {
    const api = getApi()
    if (!api) return
    if (on) {
      trackPendingSource(filterToken, pendingSource)
      filterNonce = 0
      pendingOnly = true
      api.setAdvancedFilter(withPending(api.getAdvancedFilter(), filterToken, ++filterNonce))
    } else {
      pendingOnly = false
      api.setAdvancedFilter(stripPending(api.getAdvancedFilter()))
    }
  }

  const getApi = (): ReviewGridApi | null =>
    (typeof opts.api === 'function' ? (opts.api as () => ReviewGridApi | undefined | null)() : opts.api) ?? null

  function rowIdFn(api: ReviewGridApi): (row: TData, index: number) => string {
    const fn = api.getOption('getRowId') as ((row: TData, index: number) => string) | undefined
    if (!fn) throw new Error('[svgrid review] the grid needs a getRowId prop: proposals are keyed by row id, and positions move on sort and filter')
    return fn
  }

  function indexRows(api: ReviewGridApi): Map<string, number> {
    const id = rowIdFn(api)
    const map = new Map<string, number>()
    api.getData().forEach((row, i) => map.set(String(id(row as TData, i)), i))
    return map
  }

  // ---- adding -------------------------------------------------------------

  function add(input: AddInput): ChangeSet {
    const linked = getApi()
    if (linked) linkCards(linked)
    const setId = input.id ?? nextId('cs-')
    const createdAt = Date.now()
    const ids: string[] = []
    for (const raw of input.proposals) {
      if (sameValue(raw.before, raw.after)) continue
      const p: Proposal = {
        ...raw,
        rowId: String(raw.rowId),
        id: raw.id ?? nextId('pr-'),
        op: 'update',
        source: input.source,
        // A merged proposal keeps when it was made.
        createdAt: typeof (raw as { createdAt?: unknown }).createdAt === 'number' ? (raw as unknown as { createdAt: number }).createdAt : createdAt,
        status: 'pending',
      }
      const key = cellKey(p.rowId, p.field)
      const live = byCell.get(key) ?? new Set<string>()
      for (const otherId of [...live]) {
        const other = all.get(otherId)!
        // Being accepted right now: leave it be. If it lands, the stale check
        // catches this one.
        if (inFlight.has(otherId)) continue
        if (other.source.id === p.source.id && other.status === 'pending') {
          // A newer proposal from the same producer replaces the older one
          // and keeps what the cell held when the first was made.
          p.before = other.before
          live.delete(otherId)
          all.delete(otherId)
          for (const set of sets.values()) {
            const at = set.ids.indexOf(otherId)
            if (at >= 0) set.ids.splice(at, 1)
          }
        } else {
          other.status = 'conflict'
          other.note = msg.noteConflict
          p.status = 'conflict'
          p.note = other.note
        }
      }
      if (p.status === 'pending' && sameValue(p.before, p.after)) continue
      live.add(p.id)
      byCell.set(key, live)
      all.set(p.id, p)
      ids.push(p.id)
    }
    sets.set(setId, { id: setId, title: input.title ?? input.source.label, source: input.source, createdAt, ids })
    bump()
    return { id: setId, title: input.title ?? input.source.label, source: input.source, createdAt, proposals: ids.map((i) => all.get(i)!) }
  }

  const leaveCell = (p: Proposal) => {
    const live = byCell.get(cellKey(p.rowId, p.field))
    live?.delete(p.id)
    if (live && !live.size) byCell.delete(cellKey(p.rowId, p.field))
  }
  const enterCell = (p: Proposal) => {
    const key = cellKey(p.rowId, p.field)
    byCell.set(key, (byCell.get(key) ?? new Set()).add(p.id))
  }

  // ---- reading ------------------------------------------------------------

  let groupCache: { v: number; groups: ProposalGroup[] } | null = null

  function fieldLabels(): (field: string) => string {
    const api = getApi()
    const cols = api?.getColumns() ?? []
    const map = new Map(cols.map((c) => [c.field ?? c.id, c.header || c.id]))
    return (f) => map.get(f) ?? f
  }

  const list = (status?: Proposal['status']) => {
    void version
    const out = [...all.values()]
    return status ? out.filter((p) => p.status === status) : out
  }

  function groups(): ProposalGroup[] {
    const v = version
    if (groupCache?.v === v) return groupCache.groups
    const g = clusterProposals(list('pending'), { fieldLabel: fieldLabels(), ...opts.cluster, messages: { ...opts.messages, ...opts.cluster?.messages } })
    groupCache = { v, groups: g }
    return g
  }

  function pendingFor(rowId: string, field: string): Proposal | undefined {
    void version
    for (const id of byCell.get(cellKey(rowId, field)) ?? []) {
      const p = all.get(id)
      if (p?.status === 'pending') return p
    }
    return undefined
  }

  // ---- deciding -----------------------------------------------------------

  const outcome = (): ReviewOutcome => ({ accepted: [], rejected: [], stale: [], skipped: [], committedStale: [] })

  /** Drop proposals whose cell no longer holds `before`. */
  function freshOnly(ps: Proposal[], out: ReviewOutcome, api: ReviewGridApi | null): Proposal[] {
    if (!api) return ps
    const data = api.getData()
    const index = indexRows(api)
    return ps.filter((p) => {
      const i = index.get(p.rowId)
      if (i === undefined) {
        // A server row model only holds the loaded rows; the backend decides there.
        if (opts.server) return true
        markStale(p, msg.noteRowGone, out)
        return false
      }
      const current = (data[i] as Record<string, unknown>)[p.field]
      if (sameValue(current, p.before)) return true
      markStale(p, msg.noteCellChanged, out)
      return false
    })
  }

  function markStale(p: Proposal, note: string, out: ReviewOutcome) {
    p.status = 'stale'
    p.note = note
    p.decidedAt = Date.now()
    stamp(p)
    leaveCell(p)
    out.stale.push(p.id)
  }

  /** Write `value` per (rowId, field) into a copy of the grid's current data. */
  function writeValues(api: ReviewGridApi, writes: ReadonlyArray<readonly [string, string, unknown]>, beforeSet?: (next: TData[]) => void) {
    const data = api.getData()
    const index = indexRows(api)
    const next = data.slice() as TData[]
    const copied = new Set<number>()
    for (const [rowId, field, value] of writes) {
      const i = index.get(rowId)
      if (i === undefined) continue
      if (!copied.has(i)) {
        next[i] = { ...(next[i] as object) } as TData
        copied.add(i)
      }
      ;(next[i] as Record<string, unknown>)[field] = value
    }
    if (!copied.size) return
    beforeSet?.(next)
    opts.setRows!(next)
  }

  function currentValue(api: ReviewGridApi, index: Map<string, number>, p: Proposal): unknown {
    const i = index.get(p.rowId)
    return i === undefined ? undefined : (api.getData()[i] as Record<string, unknown>)[p.field]
  }

  /**
   * What an open editor could write back over. A cell editor is committed
   * first (`stopEditing`), so its value lands and the stale check sees it. A
   * full-row draft has no public commit, so its row is left alone.
   */
  function editedRow(api: ReviewGridApi | null): string | null {
    if (!api) return null
    api.stopEditing(false)
    if (!api.getOption('fullRowEditing')) return null
    const active = api.getActiveCell()
    return active ? api.getRowId(active.rowIndex) : null
  }

  async function accept(ids: ReadonlyArray<string>): Promise<ReviewOutcome> {
    const out = outcome()
    const api = getApi()
    if (!api && !opts.server) {
      for (const id of ids) {
        const p = all.get(id)
        if (p?.status !== 'pending') continue
        p.note = msg.noteGridNotReady
        out.skipped.push(id)
      }
      bump()
      return out
    }
    const busyRow = editedRow(api)
    let take: Proposal[] = []
    for (const id of ids) {
      const p = all.get(id)
      if (!p || p.status !== 'pending') continue
      if (inFlight.has(id) || (busyRow !== null && p.rowId === busyRow)) {
        if (!inFlight.has(id)) p.note = msg.noteRowEditing
        out.skipped.push(id)
        continue
      }
      take.push(p)
    }
    take = freshOnly(take, out, api)
    if (!take.length) {
      bump()
      return out
    }
    for (const p of take) inFlight.add(p.id)
    try {
      if (opts.onCommit) await opts.onCommit(take.map((p) => ({ ...p })))
    } catch (error) {
      for (const p of take) inFlight.delete(p.id)
      bump()
      return { ...out, error }
    }
    for (const p of take) inFlight.delete(p.id)
    // The await let other writes in: check again before writing. What
    // onCommit already saved but cannot be written now is told apart.
    if (!opts.server) {
      const saved = take.filter((p) => p.status === 'pending')
      const late = outcome()
      take = freshOnly(saved, late, api)
      for (const id of late.stale) {
        const p = all.get(id)!
        if (opts.onCommit) {
          p.note = msg.noteSavedStale
          out.committedStale.push(id)
        } else out.stale.push(id)
      }
    }
    if (!take.length) {
      bump()
      return out
    }
    if (opts.setRows && api) writeValues(api, take.map((p) => [p.rowId, p.field, p.after] as const), (next) => opts.onApply?.(take, 'accept', next))
    else {
      opts.server?.refresh()
      opts.onApply?.(take, 'accept')
    }
    const at = Date.now()
    for (const p of take) {
      p.status = 'accepted'
      p.note = undefined
      p.decidedBy = opts.user
      p.decidedAt = at
      stamp(p)
      leaveCell(p)
      out.accepted.push(p.id)
    }
    recordUndo(api, take, 'accepted')
    decided('accept', take)
    bump()
    return out
  }

  function decided(action: ReviewDecision['action'], ps: Proposal[], of?: ReviewDecision['of']) {
    if (ps.length) opts.onDecision?.({ action, of, proposals: ps.map((p) => ({ ...p })), by: opts.user, at: Date.now() })
  }

  function reject(ids: ReadonlyArray<string>): ReviewOutcome {
    const out = outcome()
    const at = Date.now()
    const taken: Proposal[] = []
    // What each proposal was before, so an undo puts a conflict back as one.
    const was = new Map<string, ProposalStatus>()
    for (const id of ids) {
      const p = all.get(id)
      if (!p || (p.status !== 'pending' && p.status !== 'conflict') || inFlight.has(id)) continue
      was.set(p.id, p.status)
      p.status = 'rejected'
      p.decidedBy = opts.user
      p.decidedAt = at
      stamp(p)
      leaveCell(p)
      taken.push(p)
      out.rejected.push(id)
    }
    if (taken.length) recordUndo(getApi(), taken, 'rejected', was)
    decided('reject', taken)
    bump()
    return out
  }

  /**
   * One Ctrl+Z for the whole decision, by row id, so it works with paging and
   * filters on. Undoing an accept writes `before` back only where the cell
   * still holds `after`; anything edited since is left as it is. With
   * `onCommit`, the reversed values are saved first and written once that
   * resolves, the way an accept is.
   */
  function recordUndo(api: ReviewGridApi | null, ps: Proposal[], kind: 'accepted' | 'rejected', was?: Map<string, ProposalStatus>) {
    if (!api) return
    const prior = new Map(ps.map((p) => [p.id, { decidedBy: p.decidedBy, decidedAt: p.decidedAt }]))
    const undecided = (p: Proposal): ProposalStatus => was?.get(p.id) ?? 'pending'
    const flip = (undo: boolean, which: Proposal[]) => {
      for (const p of which) {
        if (undo) {
          p.status = undecided(p)
          p.decidedBy = undefined
          p.decidedAt = undefined
          // A proposal dropped since (clear, load) stays out of the cell index.
          if (all.get(p.id) === p) enterCell(p)
        } else {
          p.status = kind
          Object.assign(p, prior.get(p.id))
          leaveCell(p)
        }
      }
      decided(undo ? 'undo' : 'redo', which, kind === 'accepted' ? 'accept' : 'reject')
      bump()
    }
    const move = (undo: boolean) => {
      const live = ps.filter((p) => (undo ? p.status === kind : p.status === undecided(p)))
      if (kind === 'rejected') return flip(undo, live)
      const from = undo ? 'after' : 'before'
      const to = undo ? 'before' : 'after'
      const how = undo ? 'undo' : 'redo'
      if (opts.server) {
        const inverse = live.map((p) => ({ ...p, before: p[from], after: p[to] }))
        Promise.resolve(opts.onCommit!(inverse)).then(() => {
          opts.server!.refresh()
          flip(undo, live)
          opts.onApply?.(live, how)
        }, (error) => failed(error, how))
        return
      }
      // One row index per pass (rebuilt after an async save), not one per proposal.
      const holdsIn = () => {
        const index = indexRows(api)
        return (p: Proposal) => sameValue(currentValue(api, index, p), p[from])
      }
      const write = (ok: Proposal[]) => {
        if (!ok.length) return
        writeValues(api, ok.map((p) => [p.rowId, p.field, p[to]] as const), (next) => opts.onApply?.(ok, how, next))
        flip(undo, ok)
      }
      const ok = live.filter(holdsIn())
      if (!opts.onCommit) return write(ok)
      // The backend holds the accepted values: save the reverse there first.
      Promise.resolve(opts.onCommit(ok.map((p) => ({ ...p, before: p[from], after: p[to] })))).then(
        () => write(ok.filter(holdsIn())),
        (error) => failed(error, how),
      )
    }
    api.getCommandContext().recordUndo(
      () => move(true),
      () => move(false),
    )
  }

  function groupIds(key: string, shownIds: ReadonlyArray<string>): string[] {
    const g = groups().find((x) => x.key === key)
    if (!g) return []
    const members = new Set(g.ids)
    return shownIds.filter((id) => members.has(id))
  }

  /**
   * Keep one of a cell's conflicting proposals (it becomes pending) and reject
   * the rest, as one undo step that puts all of them back in conflict.
   */
  function resolveConflict(keepId: string): void {
    const keep = all.get(keepId)
    if (!keep || keep.status !== 'conflict') return
    const rivals = [...(byCell.get(cellKey(keep.rowId, keep.field)) ?? [])]
      .filter((id) => id !== keepId && !inFlight.has(id))
      .map((id) => all.get(id))
      .filter((p): p is Proposal => p?.status === 'conflict')
    const note = keep.note
    const apply = (resolved: boolean) => {
      const at = Date.now()
      for (const r of rivals) {
        if (resolved) {
          r.status = 'rejected'
          r.decidedBy = opts.user
          r.decidedAt = at
          stamp(r)
          leaveCell(r)
        } else {
          r.status = 'conflict'
          r.decidedBy = undefined
          r.decidedAt = undefined
          if (all.get(r.id) === r) enterCell(r)
        }
      }
      keep.status = resolved ? 'pending' : 'conflict'
      keep.note = resolved ? undefined : note
      bump()
    }
    apply(true)
    decided('reject', rivals)
    getApi()?.getCommandContext().recordUndo(
      () => apply(false),
      () => apply(true),
    )
  }

  // ---- serialising --------------------------------------------------------

  /**
   * Every set with its proposals and their status, as plain JSON. Pass
   * `setIds` to export only some, to hand them to someone else to decide.
   */
  function toJSON(opts: { setIds?: ReadonlyArray<string> } = {}): ReviewJSON {
    const only = opts.setIds ? new Set(opts.setIds) : null
    return {
      v: 1,
      sets: [...sets.values()].filter((set) => !only || only.has(set.id)).map(({ ids, ...meta }) => ({
        ...meta,
        proposals: ids.map((i) => all.get(i)).filter((p): p is Proposal => !!p).map((p) => ({ ...p })),
      })),
    }
  }

  /**
   * Replace everything with an export. The export is checked first: a wrong
   * shape throws and leaves the review as it was; a malformed proposal is
   * dropped. Returns how many were dropped.
   */
  function load(json: ReviewJSON): { dropped: number } {
    const { sets: valid, dropped } = checkExport(json)
    clear()
    for (const set of valid) {
      sets.set(set.id, { id: set.id, title: set.title, source: set.source, createdAt: set.createdAt, ids: set.proposals.map((p) => p.id) })
      for (const p of set.proposals) {
        all.set(p.id, { ...p })
        if (p.status === 'pending' || p.status === 'conflict') enterCell(p)
      }
    }
    bump()
    return { dropped }
  }

  /**
   * Add the sets of an export to this review, keeping what is here: an
   * approver's page merges what the author exported. A set already present is
   * skipped. Pending proposals go through the same rules as `add` (a cell
   * with a live proposal from another source becomes a conflict); decided ones
   * are kept as history.
   */
  function merge(json: ReviewJSON): { dropped: number } {
    const { sets: valid, dropped } = checkExport(json)
    for (const set of valid) {
      if (sets.has(set.id)) continue
      const live = set.proposals.filter((p) => p.status === 'pending' || p.status === 'conflict')
      const history = set.proposals.filter((p) => !live.includes(p) && !all.has(p.id))
      add({ id: set.id, title: set.title, source: set.source, proposals: live.filter((p) => !all.has(p.id)) })
      sets.get(set.id)!.createdAt = set.createdAt
      for (const p of history) all.set(p.id, { ...p })
      sets.get(set.id)!.ids.push(...history.map((p) => p.id))
    }
    bump()
    return { dropped }
  }

  // ---- history ------------------------------------------------------------

  /** Every decided proposal (accepted, rejected or stale), oldest decision first. */
  function log(): Proposal[] {
    void version
    return [...all.values()]
      .filter((p) => p.status === 'accepted' || p.status === 'rejected' || p.status === 'stale')
      .sort((a, b) => (a.decidedAt ?? 0) - (b.decidedAt ?? 0) || (decidedOrder.get(a.id) ?? 0) - (decidedOrder.get(b.id) ?? 0))
      .map((p) => ({ ...p }))
  }

  /**
   * Propose undoing what a set wrote, after the fact: a new set with each
   * accepted proposal reversed (`after` back to `before`). It is reviewed and
   * accepted like any other set, so the stale check keeps a later edit.
   * Returns null when nothing of the set was accepted.
   */
  function revertSet(setId: string): ChangeSet | null {
    const set = sets.get(setId)
    if (!set) return null
    const accepted = set.ids.map((id) => all.get(id)).filter((p): p is Proposal => p?.status === 'accepted')
    if (!accepted.length) return null
    return add({
      source: { kind: 'user', id: `revert:${setId}`, label: `Revert: ${set.title}` },
      title: `Revert: ${set.title}`,
      proposals: accepted.map((p) => ({ rowId: p.rowId, field: p.field, before: p.after, after: p.before, reason: `reverts ${p.source.label}` })),
    })
  }

  /** The sets in this review, newest last, without their proposals. */
  function sets_(): Array<Omit<ChangeSet, 'proposals'> & { count: number }> {
    void version
    return [...sets.values()].map(({ ids, ...meta }) => ({ ...meta, count: ids.length }))
  }

  function clear(): void {
    all.clear()
    sets.clear()
    byCell.clear()
    bump()
  }

  // ---- grid display -------------------------------------------------------

  /** A card's mark (board, gallery): how many proposals its row has and what they set. */
  let liveByRow: { v: number; rows: Map<string, Proposal[]> } | null = null
  function cardMark(rowId: string): CardMark | null {
    if (liveByRow?.v !== version) {
      const rows = new Map<string, Proposal[]>()
      for (const p of all.values()) {
        if (p.status !== 'pending' && p.status !== 'conflict') continue
        const list = rows.get(p.rowId)
        if (list) list.push(p)
        else rows.set(p.rowId, [p])
      }
      liveByRow = { v: version, rows }
    }
    const ps = liveByRow.rows.get(rowId)
    if (!ps) return null
    const labels = fieldLabels()
    return {
      count: ps.length,
      label: fill(msg.cardProposed, { count: ps.length }),
      text: ps.map((p) => `${labels(p.field)} → ${showValue(p.after, msg.empty)}`).join(', '),
    }
  }
  /** Whether a row object is in the grid's data (cached per data array). */
  let owned: { data: ReadonlyArray<unknown>; rows: WeakSet<object> } | null = null
  function owns(row: unknown): boolean {
    const data = getApi()?.getData()
    if (!data || !row || typeof row !== 'object') return false
    if (owned?.data !== data) owned = { data, rows: new WeakSet(data.filter((r): r is object => !!r && typeof r === 'object')) }
    return owned.rows.has(row)
  }
  let marksFor: unknown = null
  /** Register for the board and gallery cards of the grid, once its getRowId is known. */
  function linkCards(api: ReviewGridApi) {
    const fn = api.getOption('getRowId') as object | undefined
    if (fn && fn !== marksFor) {
      marksFor = fn
      registerCardMarks(fn, {
        cardMark,
        owns,
        cellProposal: (rowId, field) => {
          const p = pendingFor(rowId, field)
          return p ? { after: p.after, source: p.source.label, reason: p.reason, proposes: msg.proposes, empty: msg.empty } : null
        },
      })
    }
  }

  /** The row "Show in grid" just landed on; it flashes for a moment so the eye finds it. */
  let flashRow = $state<string | null>(null)
  let flashTimer: ReturnType<typeof setTimeout> | undefined
  function flash(rowId: string) {
    flashRow = rowId
    clearTimeout(flashTimer)
    flashTimer = setTimeout(() => (flashRow = null), 1600)
  }

  const formats = $derived.by((): ConditionalFormat<any>[] => {
    void version
    const api = getApi()
    if (!api || !api.getOption('getRowId')) return []
    linkCards(api)
    const idOf = rowIdFn(api)
    const cols = api.getColumns()
    const out = pendingFormats(list('pending'), idOf, cols)
    // After the pending tint, so a disputed cell reads as disputed.
    out.push(...pendingFormats(list('conflict'), idOf, cols, { background: CONFLICT_BG, icon: CONFLICT_ICON }))
    const lit = flashRow
    // Last, so it wins over the pending tint; every column of the row.
    if (lit !== null) out.push({ type: 'rule', when: ({ row }: { row: TData }) => String(idOf(row, 0)) === lit, background: FLASH_BG })
    return out
  })

  /** Pending-field set as a string, so `columns()` rebuilds only when it changes. */
  const pendingFields = $derived.by(() => {
    void version
    return [...new Set(list('pending').map((p) => p.field))].sort().join(SEP)
  })

  /** The first non-blank value of `field`, so a boolean column is never wrapped. */
  function sampleValue(field: string): unknown {
    for (const row of getApi()?.getData() ?? []) {
      const v = (row as Record<string, unknown>)[field]
      if (v != null && v !== '') return v
    }
    return undefined
  }

  let columnsCache: { input: unknown; fields: string; output: unknown } | null = null
  function columns<C extends ReadonlyArray<any>>(cols: C): C {
    // The grid reads its columns in every view (table, board, gallery), so cards link here too.
    const linked = getApi()
    if (linked) linkCards(linked)
    const fields = pendingFields
    if (columnsCache && columnsCache.input === cols && columnsCache.fields === fields) return columnsCache.output as C
    const output = wrapColumns(cols, new Set(fields ? fields.split(SEP) : []), review, sampleValue)
    columnsCache = { input: cols, fields, output }
    return output
  }

  // ---- navigation ---------------------------------------------------------

  /**
   * Show the next proposal of `ids` after `fromId`, on whatever page it is:
   * with client paging the grid moves to its page (`api.getRowPosition`),
   * then scrolls to it. Does not move the active cell. With grouping, where
   * pages are counted in groups, it stays on the current page. Returns the id
   * shown and how many of `ids` cannot be shown (filtered out, or on another
   * page of a grouped grid).
   */
  function reveal(ids: ReadonlyArray<string>, fromId?: string): { id: string | null; hidden: number } {
    const api = getApi()
    if (!api) return { id: null, hidden: ids.length }
    const proposals = ids.map((i) => all.get(i)).filter((p): p is Proposal => !!p)
    const grouped = (api.getState().grouping?.length ?? 0) > 0
    // The grid pages with `pageable`, or the older `showPagination`.
    const paged = !!(api.getOption('pageable') ?? api.getOption('showPagination')) && !api.getOption('externalPagination')
    let reachable: Array<{ p: Proposal; position: number }>
    if (grouped) {
      const idFn = rowIdFn(api)
      const onPage = new Set(api.getDisplayedRows().map((r, i) => String(idFn(r as TData, i))))
      reachable = proposals.filter((p) => onPage.has(p.rowId)).map((p) => ({ p, position: -1 }))
    } else {
      reachable = proposals
        .map((p) => ({ p, position: api.getRowPosition(p.rowId) }))
        .filter((x): x is { p: Proposal; position: number } => x.position !== null)
    }
    const hidden = proposals.length - reachable.length
    if (!reachable.length) return { id: null, hidden }
    const start = fromId ? reachable.findIndex((x) => x.p.id === fromId) + 1 : 0
    const target = reachable[start % reachable.length]!
    if (!grouped) {
      let index = target.position
      if (paged) {
        const { pageIndex, pageSize } = api.getPageInfo()
        const page = Math.floor(index / pageSize)
        if (page !== pageIndex) api.setPage(page)
        index -= page * pageSize
      }
      api.scrollToRow(index)
      flash(target.p.rowId)
      return { id: target.p.id, hidden }
    }
    // The display index counts group banners, which getDisplayedRows skips:
    // walk the display rows until the id matches.
    const limit = api.getDisplayedRows().length * 2 + 64
    for (let i = 0; i < limit; i++) {
      if (api.getRowId(i) === target.p.rowId) {
        api.scrollToRow(i)
        flash(target.p.rowId)
        break
      }
    }
    return { id: target.p.id, hidden }
  }

  // Row index for labels, rebuilt when the grid's data array changes.
  let labelIndex: { data: unknown; map: Map<string, number> } | null = null
  function rowLabel(p: Proposal): string | null {
    const api = getApi()
    if (!api || !api.getOption('getRowId')) return null
    const data = api.getData()
    if (labelIndex?.data !== data) labelIndex = { data, map: indexRows(api) }
    const i = labelIndex.map.get(p.rowId)
    if (i === undefined) return null
    const row = data[i] as TData
    if (opts.rowLabel) return opts.rowLabel(row) || null
    for (const c of api.getColumns()) {
      if (!c.visible || !c.field) continue
      const v = (row as Record<string, unknown>)[c.field]
      if (typeof v === 'string' && v.trim()) return c.field === p.field ? null : v.trim()
    }
    return null
  }

  const review = {
    get version() {
      return version
    },
    /** The wording in effect: English with `messages` laid over it. */
    messages: msg,
    /** The last undo or redo whose save failed, or null. */
    get lastError() {
      return lastError
    },
    add,
    get: (id: string) => {
      void version
      return all.get(id)
    },
    proposals: () => list(),
    /** What names the proposal's row (`rowLabel`), or null. */
    rowLabel,
    /** A field's column header, as the group labels show it. */
    fieldLabel: (field: string) => fieldLabels()(field),
    pending: () => list('pending'),
    conflicts: () => list('conflict'),
    groups,
    pendingFor,
    accept,
    reject,
    acceptGroup: (key: string, shownIds: ReadonlyArray<string>) => accept(groupIds(key, shownIds)),
    rejectGroup: (key: string, shownIds: ReadonlyArray<string>) => reject(groupIds(key, shownIds)),
    resolveConflict,
    get formats() {
      return formats
    },
    columns,
    reveal,
    showPendingOnly,
    /** On while our condition is in the grid's advanced filter (the grid's own Clear takes it out too). */
    get pendingOnly() {
      return pendingOnly && hasPending(getApi()?.getAdvancedFilter() ?? null)
    },
    toJSON,
    load,
    merge,
    log,
    revertSet,
    sets: sets_,
    clear,
  }
  return review
}

export function createRowPlaceholder<T extends object>(
  state: 'loading' | 'failed',
  fields: T,
): Readonly<T & { readonly [PLACEHOLDER]: 'loading' | 'failed' }> {
  return Object.freeze({ ...fields, [PLACEHOLDER]: state })
}

export function createServerDataSource<TData>(
  source: ServerDataSource<TData>,
  options: ServerControllerOptions<TData>,
): ServerController<TData> {
  const state: ServerState<TData> = {
    rows: [],
    total: 0,
    loading: false,
    saving: false,
    error: null,
    pageIndex: 0,
    pageSize: options.pageSize ?? 50,
    pageCount: 1,
    sortModel: [],
    filterModel: {},
    expressionUnapplied: false,
  }

  const infinite = options.mode === 'infinite'
  // `onChange` is the one-callback API this controller shipped with;
  // `subscribe` is the many-listener one `GridRowModel` needs. Both fire
  // from `emit`, so a grid driven by `rowModel` and an app reading
  // `onChange` stay in step.
  const subscribers = new Set<() => void>()
  let cache: BlockCache<TData> | null = null

  // Monotonic request id: only the latest fetch is allowed to land, so a slow
  // response for an old sort/filter can't clobber a newer one.
  let requestSeq = 0
  /** The page fetch in flight; a newer one, or dispose, aborts it. */
  let pageAbort: AbortController | null = null
  let disposed = false
  // Once per controller: a misconfigured backend would otherwise log on every
  // page, scroll and filter change.
  let warnedExpressionUnapplied = false

  const emit = () => {
    state.pageCount = Math.max(1, Math.ceil(state.total / state.pageSize))
    options.onChange?.({ ...state })
    for (const notify of subscribers) notify()
  }

  /**
   * Pull the block cache's view of the world into `state` and emit.
   *
   * `total` stays a plain number because the pager and the footer have
   * always read it as one; while the end is undiscovered it holds the
   * current optimistic length, which is exactly what the scrollbar needs.
   * `rowCount` is the honest answer, null and all.
   */
  function emitFromCache(): void {
    if (!cache || disposed) return
    // Windowed: the grid reads only the rows it shows, so a block landing
    // costs the same at 100M rows as at 10K.
    const rows = cache.windowedRows()
    state.rows = rows
    state.rowCount = cache.rowCount()
    state.lastRowKnown = cache.lastRowKnown()
    state.total = cache.rowCount() ?? rows.length
    emit()
  }

  function buildCache(): BlockCache<TData> {
    return createBlockCache<TData>({
      blockSize: options.blockSize ?? 100,
      maxBlocksInCache: options.maxBlocksInCache,
      maxConcurrentRequests: options.maxConcurrentRequests,
      blockLoadDebounceMs: options.blockLoadDebounceMs,
      initialRowCount: options.initialRowCount,
      fetch: async (startRow, endRow, signal) => {
        const result = await source.getRows({
          startRow,
          endRow,
          // A block is a page of its own size, so a backend that only knows
          // how to page still works unchanged.
          pageIndex: Math.floor(startRow / Math.max(1, endRow - startRow)),
          pageSize: endRow - startRow,
          sortModel: state.sortModel,
          filterModel: state.filterModel,
          groupBy: [],
          groupKeys: [],
          aggregations: [],
          signal,
        })
        noteExpressionApplied(result)
        return { rows: result.rows, rowCount: result.rowCount }
      },
      onChange: (s) => {
        state.loading = s.loading
        state.failedBlocks = s.failedBlocks
        emitFromCache()
      },
    })
  }

  /** Reload from scratch: new sort, new filter, or an explicit purge. */
  function resetCache(): void {
    if (disposed) return
    cache?.dispose()
    cache = buildCache()
    cache.setViewport(viewStart, viewEnd)
    emitFromCache()
  }

  /**
   * An expression was sent but the backend did not acknowledge applying it,
   * so these rows are a SUPERSET of what was asked for. Say so instead of
   * filtering here: filtering one page would turn "3 of 1,000,000 match"
   * into a confident lie and make paging incoherent, since the next page
   * would re-filter a different slice.
   */
  function noteExpressionApplied(result: ServerResult<TData>): void {
    state.expressionUnapplied =
      state.filterModel.expression != null && result.appliedExpression !== true
    if (!state.expressionUnapplied || warnedExpressionUnapplied) return
    warnedExpressionUnapplied = true
    console.warn(
      '[svgrid] The data source was sent filterModel.expression but did not ' +
        'return `appliedExpression: true`, so the advanced filter is NOT applied ' +
        'and the rows shown are unfiltered. Apply the whole expression and ' +
        'acknowledge it, or clear the advanced filter. ' +
        'See https://svgrid.com/docs/help/server/server-filtering',
    )
  }

  async function fetchPage() {
    if (disposed) return
    const id = ++requestSeq
    pageAbort?.abort()
    const controller = new AbortController()
    pageAbort = controller
    state.loading = true
    state.error = null
    emit()
    const startRow = state.pageIndex * state.pageSize
    try {
      const result = await source.getRows({
        startRow,
        endRow: startRow + state.pageSize,
        pageIndex: state.pageIndex,
        pageSize: state.pageSize,
        sortModel: state.sortModel,
        filterModel: state.filterModel,
        // Flat mode: no grouping. Server-side grouping and tree data live in
        // `createServerGroupModel` from @svgrid/enterprise, which fills these in.
        groupBy: [],
        groupKeys: [],
        aggregations: [],
        signal: controller.signal,
      })
      if (disposed || id !== requestSeq) return // stale
      state.rows = result.rows
      state.total = result.rowCount
      state.rowCount = result.rowCount
      state.lastRowKnown = true
      noteExpressionApplied(result)
      state.loading = false
      emit()
    } catch (err) {
      if (disposed || id !== requestSeq) return
      state.rows = []
      state.error = err
      state.loading = false
      emit()
    }
  }

  // Shared mutation lifecycle: flip `saving`, run the write, refresh the
  // current page on success, and always clear `saving`. A missing source
  // method (or a disposed controller) rejects before anything is emitted.
  function mutate<T>(name: string, thunk: (() => Promise<T>) | null): Promise<T> {
    if (disposed) {
      return Promise.reject(new Error('createServerDataSource: controller is disposed'))
    }
    if (!thunk) {
      return Promise.reject(
        new Error(`createServerDataSource: the datasource does not implement ${name}()`),
      )
    }
    state.saving = true
    emit()
    return (async () => {
      try {
        const result = await thunk()
        // Page mode re-reads the page. Infinite mode re-reads the blocks it
        // holds, in place: the list keeps its length and its scroll.
        if (infinite) cache?.refresh()
        else await fetchPage()
        return result
      } finally {
        state.saving = false
        emit()
      }
    })()
  }

  const optimistic = !!options.optimistic && !!options.getRowId
  const getRowId = options.getRowId

  // The last range the grid reported, so a sort / filter / purge can
  // re-request what the user is actually looking at rather than row 0.
  let viewStart = 0
  let viewEnd = 0

  // Optimistic update: patch the local row, reconcile with the server result,
  // roll back on error. Falls back to the plain refresh path when the row
  // isn't on the current page (nothing local to update).
  async function optimisticUpdate(
    id: string,
    patch: Partial<TData>,
    fn: (id: string, patch: Partial<TData>) => Promise<TData>,
  ): Promise<TData> {
    if (disposed) throw new Error('createServerDataSource: controller is disposed')
    if (infinite && cache) {
      // The cache owns the rows here; patch it, not a copy the next block
      // to land would overwrite.
      const at = cache.findIndex((r) => !rowPlaceholderState(r) && getRowId!(r) === id)
      if (at < 0) return mutate('updateRow', () => fn(id, patch))
      const prev = cache.getRow(at) as TData
      cache.patch(at, { ...prev, ...patch })
      state.saving = true
      emit()
      try {
        const result = await fn(id, patch)
        cache.patch(at, result)
        return result
      } catch (err) {
        cache.patch(at, prev)
        throw err
      } finally {
        state.saving = false
        emit()
      }
    }
    const prevRows = state.rows
    const idx = prevRows.findIndex((r) => getRowId!(r) === id)
    if (idx < 0) return mutate('updateRow', () => fn(id, patch))

    state.rows = [...prevRows.slice(0, idx), { ...prevRows[idx]!, ...patch }, ...prevRows.slice(idx + 1)]
    state.saving = true
    emit()
    try {
      const result = await fn(id, patch)
      state.rows = state.rows.map((r) => (getRowId!(r) === id ? result : r))
      return result
    } catch (err) {
      state.rows = prevRows
      throw err
    } finally {
      state.saving = false
      emit()
    }
  }

  // Optimistic delete: drop the local row + decrement total, restore on error.
  async function optimisticDelete(
    id: string,
    fn: (id: string) => Promise<void>,
  ): Promise<void> {
    if (disposed) throw new Error('createServerDataSource: controller is disposed')
    if (infinite && cache) {
      const at = cache.findIndex((r) => !rowPlaceholderState(r) && getRowId!(r) === id)
      if (at < 0) return mutate('deleteRow', () => fn(id))
      const prev = cache.getRow(at) as TData
      cache.remove(at, 1)
      state.saving = true
      emit()
      try {
        await fn(id)
      } catch (err) {
        cache.insert(at, [prev])
        throw err
      } finally {
        state.saving = false
        emit()
      }
      return
    }
    const prevRows = state.rows
    const prevTotal = state.total
    const next = prevRows.filter((r) => getRowId!(r) !== id)
    if (next.length === prevRows.length) return mutate('deleteRow', () => fn(id))

    state.rows = next
    state.total = Math.max(0, prevTotal - (prevRows.length - next.length))
    state.saving = true
    emit()
    try {
      await fn(id)
    } catch (err) {
      state.rows = prevRows
      state.total = prevTotal
      throw err
    } finally {
      state.saving = false
      emit()
    }
  }

  // In infinite mode the first blocks are requested as soon as the grid
  // reports a viewport; `refresh()` is what arms the cache before that.
  if (infinite) cache = buildCache()

  return {
    refresh: () => {
      if (!infinite) return void fetchPage()
      // Keep the count and the scroll position, re-request what is held.
      cache?.refresh()
    },
    setViewport(startIndex, endIndex) {
      viewStart = startIndex
      viewEnd = endIndex
      cache?.setViewport(startIndex, endIndex)
    },
    retryLoads: () => cache?.retryFailed(),
    purge: () => cache?.purge(),
    getCacheState: () => cache?.getCacheState() ?? [],

    // --- GridRowModel -----------------------------------------------
    subscribe(onChange) {
      subscribers.add(onChange)
      return () => {
        subscribers.delete(onChange)
      }
    },
    getRows: () => state.rows,
    isLoading: () => state.loading,
    getRowId: options.getRowId ? (row: TData) => options.getRowId!(row) : undefined,
    // Only infinite mode has unloaded rows to stand in for.
    rowPlaceholder: infinite ? (row: TData) => rowPlaceholderState(row) : undefined,
    retryRow: infinite ? (_row: TData, rowIndex: number) => cache?.retryFailedAt(rowIndex) : undefined,
    /**
     * A getter, not a snapshot: the grid re-reads this after every change
     * notification, and a frozen object would leave the pager on page 1
     * forever. Absent in infinite mode, where there are no pages.
     */
    get pagination() {
      if (infinite) return undefined
      return {
        pageIndex: state.pageIndex,
        pageSize: state.pageSize,
        rowCount: state.total,
        setPage: (pageIndex: number) => this.setPage(pageIndex),
        setPageSize: (pageSize: number) => this.setPageSize(pageSize),
      }
    },
    createRow: (input) =>
      mutate('createRow', source.createRow ? () => source.createRow!(input) : null),
    updateRow: (id, patch) => {
      if (!source.updateRow) return mutate('updateRow', null)
      const fn = source.updateRow
      return optimistic ? optimisticUpdate(id, patch, fn) : mutate('updateRow', () => fn(id, patch))
    },
    deleteRow: (id) => {
      if (!source.deleteRow) return mutate('deleteRow', null)
      const fn = source.deleteRow
      return optimistic ? optimisticDelete(id, fn) : mutate('deleteRow', () => fn(id))
    },
    setSort(sortModel) {
      state.sortModel = sortModel
      state.pageIndex = 0
      if (infinite) return resetCache()
      void fetchPage()
    },
    setFilter(filterModel) {
      state.filterModel = Array.isArray(filterModel.columns)
        ? {
            global: filterModel.global,
            columns: toServerFilterColumns(filterModel as GridFilterState),
            ...(filterModel.custom ? { custom: filterModel.custom } : {}),
          }
        : (filterModel as ServerFilterModel)
      state.pageIndex = 0
      if (infinite) return resetCache()
      void fetchPage()
    },
    setPage(pageIndex) {
      // There are no pages to move between when the whole result is one
      // scrollable list; the grid scrolls instead.
      if (infinite) return
      const clamped = Math.max(0, pageIndex)
      if (clamped === state.pageIndex) return
      state.pageIndex = clamped
      void fetchPage()
    },
    setPageSize(pageSize) {
      state.pageSize = Math.max(1, pageSize)
      state.pageIndex = 0
      if (infinite) return
      void fetchPage()
    },
    getState: () => ({ ...state }),
    dispose() {
      disposed = true
      pageAbort?.abort()
      pageAbort = null
      cache?.dispose()
      cache = null
      // An in-flight fetch's resolution short-circuits on `disposed`, so it
      // never clears `loading`. Clear it here (and emit) so a disposed
      // controller doesn't report a permanent loading state.
      if (state.loading) {
        state.loading = false
        emit()
      }
    },
  }
}

export function createServerRowModel<TData>(
  source: ServerDataSource<TData>,
  options: ServerRowModelOptions<TData>,
): ServerRowModel<TData> {
  // Runs without a key; shows the watermark + one console notice.
  nudgeServerRowModel()

  let groupBy = [...(options.groupBy ?? [])]
  let aggregations = [...(options.aggregations ?? [])]
  let pivotBy = [...(options.pivotBy ?? [])]
  let pivotMode = !!options.pivotMode
  let pivotRowTotals: boolean | string = options.pivotRowTotals ?? false
  const pivotSeparator = options.pivotFieldSeparator ?? '_'
  /** The union of every `pivotResultFields` seen since the last reset, in order. */
  let pivotFields: string[] = []
  /** Verbatim column defs from the backend, when it sent them instead of fields. */
  let pivotColumnsFromSource: ReadonlyArray<unknown> | null = null
  const treeData = !!options.treeData
  if (treeData && (!options.getRowId || !options.hasChildren)) {
    throw new Error('createServerRowModel: treeData requires getRowId and hasChildren')
  }
  const getRowId = options.getRowId
  const hasChildren = options.hasChildren
  const childCountOf = options.childCount
  const skeletonRows = Math.max(1, options.skeletonRows ?? 3)
  const paging = options.pagination ?? null
  let pageIndex = 0
  let pageSize = Math.max(1, paging?.pageSize ?? 100)
  /** Rows the pager counts, as of the last flatten. */
  let pagerRowCount = 0
  const groupFooters = !!options.groupFooters
  const grandTotalRow = options.grandTotalRow
  const debug = !!options.debug

  let sortModel: ServerSortModel = []
  let filterModel: ServerFilterModel = {}

  const stores = new Map<string, Store<TData>>()
  const expanded = new Set<string>()
  /** Group routes that have been through `isGroupOpenByDefault` once. */
  const seenGroups = new Set<string>()
  let autoExpand = false

  let grandTotal: TData | null | undefined = undefined
  /**
   * The grand total on hand is from before an in-place refresh of the top
   * level or a bulk edit, so the next root block asks for a fresh one. The
   * old one stays on screen until it lands rather than blinking out.
   */
  let grandTotalStale = false
  /** Leaves whose detail panel is open, by the id `getRowId` gives them. */
  const openDetails = new Set<string>()
  let rootError: unknown = null
  let disposed = false
  /** Writes the server has not answered yet; `saving` is "any". */
  let writesInFlight = 0

  // Generation guard: bumped on any reset so responses for the previous shape
  // are discarded when they land.
  let generation = 0

  // A single in-flight budget across every level. The block cache caps
  // concurrency per instance; with one instance per route that would let ten
  // open groups fire twenty requests, so the gate lives here.
  const maxConcurrent = Math.max(1, options.maxConcurrentRequests ?? 2)
  let inFlight = 0
  const waiting: Array<() => void> = []
  const acquire = (): Promise<void> => {
    if (inFlight < maxConcurrent) {
      inFlight += 1
      return Promise.resolve()
    }
    return new Promise((resolve) => waiting.push(() => { inFlight += 1; resolve() }))
  }
  const release = (): void => {
    inFlight -= 1
    waiting.shift()?.()
  }

  const subscribers = new Set<() => void>()
  let lastViewport: [number, number] = [0, 0]
  let segments: Segment<TData>[] = []
  let emitScheduled = false

  // ----------------------------------------------------------- stores

  function levelOf(route: ReadonlyArray<string>): number {
    return route.length
  }

  function isLeafLevel(level: number): boolean {
    return !treeData && level >= groupBy.length
  }

  /** The group row `route` names, if its parent level has it loaded. */
  function parentRowOf(route: string[]): TData | undefined {
    if (route.length === 0) return undefined
    const parent = stores.get(routeKey(route.slice(0, -1)))
    if (!parent) return undefined
    const key = route[route.length - 1]
    const rows = parent.cache.rows()
    for (const child of rows) {
      if (rowPlaceholderState(child)) continue
      if (child.kind === 'group' && child.key === key) return child.data
    }
    return undefined
  }

  function toChildren(route: string[], startRow: number, rows: ReadonlyArray<TData>): Child<TData>[] {
    const level = levelOf(route)
    const groupField = groupBy[level]
    const storeKey = routeKey(route)
    return rows.map((data, i): Child<TData> => {
      const isGroup = treeData ? hasChildren!(data) : level < groupBy.length
      if (isGroup) {
        const key = treeData
          ? getRowId!(data)
          : ((v) => (v == null ? '' : String(v)))((data as Record<string, unknown>)[groupField!])
        const agg: Record<string, unknown> = {}
        for (const a of aggregations) agg[a.col] = (data as Record<string, unknown>)[a.col]
        return {
          kind: 'group',
          key,
          field: treeData ? '' : groupField!,
          aggregates: agg,
          childCount: childCountOf?.(data),
          data,
        }
      }
      const id = getRowId ? `${storeKey}:${getRowId(data)}` : `${storeKey}:${startRow + i}`
      return { kind: 'leaf', id, data }
    })
  }

  function createStore(route: string[]): Store<TData> {
    const level = levelOf(route)
    const params = options.levelParams?.(level, route) ?? {}
    const blockSize = Math.max(1, params.blockSize ?? options.blockSize ?? 100)
    const loadMore = !!params.loadMore
    const infinite = !loadMore && params.infinite !== false
    const key = routeKey(route)
    const gen = generation

    const store: Store<TData> = {
      route,
      key,
      level,
      infinite,
      loadMore,
      blockSize,
      refreshPending: false,
      seenBlocks: new Map(),
      cache: null as unknown as BlockCache<Child<TData>>,
    }

    store.cache = createBlockCache<Child<TData>>({
      blockSize,
      maxBlocksInCache: params.maxBlocksInCache ?? options.maxBlocksInCache,
      // The model gates concurrency itself, across levels.
      maxConcurrentRequests: Number.MAX_SAFE_INTEGER,
      blockLoadDebounceMs: options.blockLoadDebounceMs,
      initialRowCount: Math.max(1, params.initialRowCount ?? skeletonRows),
      fetch: async (startRow, endRow, signal) => {
        await acquire()
        try {
          if (disposed || gen !== generation || signal.aborted) {
            throw new Error('stale')
          }
          const needsGrandTotal =
            route.length === 0 && grandTotalRow != null && (grandTotal === undefined || grandTotalStale)
          const request: ServerRequest = {
            startRow,
            endRow,
            pageIndex: Math.floor(startRow / blockSize),
            pageSize: blockSize,
            sortModel,
            filterModel,
            groupBy,
            groupKeys: route,
            aggregations,
            ...(pivotMode ? { pivotBy, pivotMode: true } : {}),
            ...(needsGrandTotal ? { needsGrandTotal: true } : {}),
            ...(route.length ? { parentRow: parentRowOf(route) } : {}),
            ...(options.context !== undefined ? { context: options.context } : {}),
            signal,
          }
          let result
          try {
            result = await source.getRows(request)
          } catch (err) {
            if (!disposed && gen === generation) {
              if (route.length === 0) rootError = err
              options.onLoadError?.(route, err)
            }
            throw err
          }
          if (disposed || gen !== generation) throw new Error('stale')
          if (route.length === 0) {
            rootError = null
            if ('grandTotal' in result) {
              grandTotal = result.grandTotal ?? null
              grandTotalStale = false
            }
          }
          if (pivotMode) {
            if (result.pivotResultColumns) pivotColumnsFromSource = result.pivotResultColumns
            for (const f of result.pivotResultFields ?? []) {
              if (!pivotFields.includes(f)) pivotFields.push(f)
            }
          }
          return {
            rows: toChildren(route, startRow, result.rows),
            rowCount: result.rowCount >= 0 ? result.rowCount : undefined,
          }
        } finally {
          release()
        }
      },
      onChange: (s) => {
        if (disposed || gen !== generation) return
        // Runs once per block that just landed: open-by-default, and the
        // debug log. Scanning only those blocks keeps this O(blockSize)
        // rather than O(rows) on every change.
        for (const index of diffBlocks(store)) openByDefaultIn(store, index)
        if (store.refreshPending && !s.loading) {
          store.refreshPending = false
          options.onStoreRefreshed?.(route)
        }
        // A level that is not infinite loads itself completely once it knows
        // how big it is.
        if (!infinite && !loadMore && s.lastRowKnown && s.rowCount != null) {
          store.cache.setViewport(0, Math.max(0, s.rowCount - 1))
        }
        scheduleEmit()
      },
    })
    stores.set(key, store)
    return store
  }

  function ensureStore(route: string[]): Store<TData> {
    return stores.get(routeKey(route)) ?? createStore(route)
  }

  function dropSubtree(route: string[]): void {
    const prefix = routeKey(route)
    for (const [key, store] of [...stores]) {
      if (key === prefix || isUnder(key, route)) {
        store.cache.dispose()
        stores.delete(key)
      }
    }
  }

  function isUnder(key: string, route: string[]): boolean {
    // Routes are JSON arrays; a descendant's key starts with the parent's
    // elements. Compare structurally rather than by string prefix so that
    // ["a"] is not mistaken for a parent of ["ab"].
    const parsed = JSON.parse(key) as string[]
    if (parsed.length <= route.length) return false
    return route.every((seg, i) => parsed[i] === seg)
  }

  /** Block indices that became `loaded` since the last call. Logs when `debug`. */
  function diffBlocks(store: Store<TData>): number[] {
    const now = new Map(store.cache.getCacheState().map((b) => [b.blockIndex, b.status]))
    const landed: number[] = []
    for (const [index, status] of now) {
      const before = store.seenBlocks.get(index)
      if (before === status) continue
      if (status === 'loaded') landed.push(index)
      // eslint-disable-next-line no-console -- opt-in diagnostics, see the debug option
      if (debug) console.debug(`[svgrid ssrm] ${routeKey(store.route)} block ${index}: ${status}`)
    }
    if (debug) {
      for (const index of store.seenBlocks.keys()) {
        // eslint-disable-next-line no-console -- opt-in diagnostics, see the debug option
        if (!now.has(index)) console.debug(`[svgrid ssrm] ${routeKey(store.route)} block ${index}: evicted`)
      }
    }
    store.seenBlocks = now
    return landed
  }

  /**
   * Open the groups in a freshly landed block that should start open: by
   * `isGroupOpenByDefault`, by an `expandAll({ includeUnloaded })` in force,
   * or because they are unbalanced. Once per group, so a block that is
   * re-fetched does not re-open something the user closed.
   */
  function openByDefaultIn(store: Store<TData>, blockIndex: number): void {
    const start = blockIndex * store.blockSize
    for (let i = start; i < start + store.blockSize; i += 1) {
      const raw = store.cache.getRow(i)
      if (rowPlaceholderState(raw)) continue
      const child = raw as Child<TData>
      if (child.kind !== 'group') continue
      const childRoute = [...store.route, child.key]
      const ck = routeKey(childRoute)
      if (seenGroups.has(ck)) continue
      seenGroups.add(ck)
      const unbalanced = !!options.allowUnbalancedGroups && child.key === ''
      if (unbalanced || autoExpand || options.isGroupOpenByDefault?.(childRoute, child.data)) {
        expandGroup(childRoute)
      }
    }
  }

  // ---------------------------------------------------------- flatten

  /**
   * A level's rows as display and grid rows, kept from one emit to the next.
   *
   * A level of leaves maps each cached row to one display row that depends on
   * nothing but that row, so the mapping only has to be redone where the
   * cache changed - and every cache write (a landed block, a patch, a purge)
   * puts a new object at the index it touches. Comparing identities is a
   * tight loop; mapping a million rows per landed block of a hundred was most
   * of what a block cost on the main thread. Keeping the grid row objects also
   * lets the grid keep its own row objects for them.
   *
   * Null for a level holding groups (a group row's display depends on what is
   * expanded beneath it) and while any detail is open (a detail adds a row).
   */
  type LeafRun = {
    rows: ReadonlyArray<Child<TData>>
    display: Array<ServerRowModelDisplayRow<TData>>
    grid: Array<ServerRowModelGridRow<TData>>
  }
  const leafRuns = new WeakMap<Store<TData>, LeafRun>()

  function leafRun(store: Store<TData>, rows: ReadonlyArray<Child<TData>>): LeafRun | null {
    if (openDetails.size) return null
    const prev = leafRuns.get(store)
    if (prev && prev.rows === rows) return prev
    const n = rows.length
    // Same length (a block landed, a row was patched): update the kept
    // arrays in place. The flatten only ever copies out of them.
    const inPlace = !!prev && prev.rows.length === n
    const display = inPlace ? prev!.display : new Array<ServerRowModelDisplayRow<TData>>(n)
    const grid = inPlace ? prev!.grid : new Array<ServerRowModelGridRow<TData>>(n)
    const old = prev?.rows
    const oldLength = old ? old.length : 0
    for (let i = 0; i < n; i += 1) {
      const child = rows[i]!
      if (i < oldLength && old![i] === child) {
        if (!inPlace) {
          display[i] = prev!.display[i]!
          grid[i] = prev!.grid[i]!
        }
        continue
      }
      const ph = rowPlaceholderState(child)
      if (ph) {
        const d = ph === 'failed' ? FAILED_ROW : LOADING_ROW
        display[i] = d
        grid[i] = toGridRow(d)
        continue
      }
      if (child.kind !== 'leaf') {
        // Written in place up to here, so the kept run is no longer whole.
        leafRuns.delete(store)
        return null
      }
      const d: ServerLeafRow<TData> = { kind: 'leaf', id: child.id, level: store.level, route: store.route, data: child.data }
      display[i] = d
      grid[i] = toGridRow(d, child.data)
    }
    const run = { rows, display, grid }
    leafRuns.set(store, run)
    return run
  }

  /**
   * A level made only of data rows maps one to one: its i-th display row is
   * its i-th child. Such a level is not walked or copied - the flatten records
   * it as one lazy piece and `lazyLeafAt` builds a row when the grid reads it,
   * so a 100M-row level costs the rows on screen, not 100M. Groups, tree
   * data, pivot, load-more, detail rows and child-row paging still walk.
   */
  function isLazyLeafLevel(store: Store<TData>): boolean {
    return (
      !treeData &&
      !pivotMode &&
      store.level >= groupBy.length &&
      !store.loadMore &&
      openDetails.size === 0 &&
      !paging?.paginateChildRows
    )
  }
  type LazyEntry = {
    child: unknown
    d: ServerRowModelDisplayRow<TData>
    g: ServerRowModelGridRow<TData>
  }
  // Replaced when a write settles (see `saving`): the grid writes a cell edit
  // into the row object it was handed, so a row the server refused would keep
  // showing the refused value while its child, which nothing changed, still
  // matched the memo.
  let lazyMemo = new WeakMap<Store<TData>, Map<number, LazyEntry>>()
  const LAZY_MEMO_CAP = 20_000
  /** Row `index` of a lazy leaf level, built once per child object it holds. */
  function lazyLeafAt(store: Store<TData>, index: number): LazyEntry {
    const child = store.cache.getRow(index) as Child<TData>
    const ph = rowPlaceholderState(child)
    if (ph) {
      const d = ph === 'failed' ? FAILED_ROW : LOADING_ROW
      return { child, d, g: toGridRow(d) }
    }
    let memo = lazyMemo.get(store)
    if (!memo) {
      memo = new Map()
      lazyMemo.set(store, memo)
    }
    const hit = memo.get(index)
    if (hit && hit.child === child) return hit
    const leaf = child as Extract<Child<TData>, { kind: 'leaf' }>
    const d: ServerLeafRow<TData> = { kind: 'leaf', id: leaf.id, level: store.level, route: store.route, data: leaf.data }
    const entry: LazyEntry = { child, d, g: toGridRow(d, leaf.data) }
    memo.set(index, entry)
    if (memo.size > LAZY_MEMO_CAP) {
      let drop = LAZY_MEMO_CAP / 4
      for (const key of memo.keys()) {
        if (drop-- <= 0) break
        memo.delete(key)
      }
    }
    return entry
  }

  function flatten(): {
    display: ServerRowModelDisplayRow<TData>[]
    grid: ServerRowModelGridRow<TData>[]
  } {
    // The output is a list of pieces: explicit rows (group rows, footers, a
    // walked level) and lazy leaf levels. Small or walked lists come back as
    // plain arrays; a list with a lazy piece comes back windowed.
    type Piece = {
      start: number
      length: number
      display?: ServerRowModelDisplayRow<TData>[]
      grid?: ServerRowModelGridRow<TData>[]
      store?: Store<TData>
      from?: number
    }
    const pieces: Piece[] = []
    let total = 0
    let open: Piece | null = null
    segments = []

    const pushRow = (d: ServerRowModelDisplayRow<TData>, data?: TData): void => {
      if (!open) {
        open = { start: total, length: 0, display: [], grid: [] }
        pieces.push(open)
      }
      open.display!.push(d)
      open.grid!.push(toGridRow(d, data))
      open.length += 1
      total += 1
    }
    const pushPiece = (piece: Piece): void => {
      open = null
      pieces.push(piece)
      total += piece.length
    }

    if (grandTotalRow === 'top' && grandTotal) pushRow(grandTotalDisplay(grandTotal), grandTotal)
    const bodyStart = total

    /**
     * A `loadMore` level shows its loaded prefix and a "more" row; rows
     * past the first placeholder are not the grid's to scroll into.
     */
    const loadedPrefix = (rows: ReadonlyArray<Child<TData>>): number => {
      let n = 0
      while (n < rows.length && !rowPlaceholderState(rows[n])) n += 1
      return n
    }

    const walk = (store: Store<TData>, from = 0, to = Number.POSITIVE_INFINITY): void => {
      if (isLazyLeafLevel(store)) {
        // A pure leaf level: one lazy piece, nothing copied.
        const end = Math.min(store.cache.windowedRows().length, to)
        if (end > from) {
          segments.push({ store, displayStart: total, storeStart: from, length: end - from })
          pushPiece({ start: total, length: end - from, store, from })
        }
        return
      }
      const rows = store.cache.rows()
      const run = store.loadMore ? null : leafRun(store, rows)
      if (run) {
        // A level of leaves maps one to one: copy the range out of the run.
        const end = Math.min(rows.length, to)
        if (end > from) {
          segments.push({ store, displayStart: total, storeStart: from, length: end - from })
          pushPiece({
            start: total,
            length: end - from,
            display: run.display.slice(from, end),
            grid: run.grid.slice(from, end),
          })
        }
        return
      }
      const end = Math.min(rows.length, to, store.loadMore ? loadedPrefix(rows) : Number.POSITIVE_INFINITY)
      let segStart = from
      let dispStart = total
      const flushSegment = (upTo: number): void => {
        if (upTo > segStart) {
          segments.push({ store, displayStart: dispStart, storeStart: segStart, length: upTo - segStart })
        }
      }
      for (let i = from; i < end; i += 1) {
        const child = rows[i]!
        const ph = rowPlaceholderState(child)
        if (ph) {
          pushRow(ph === 'failed' ? FAILED_ROW : LOADING_ROW)
          continue
        }
        if (child.kind === 'leaf') {
          pushRow(
            { kind: 'leaf', id: child.id, level: store.level, route: store.route, data: child.data },
            child.data,
          )
          if (openDetails.size) {
            const masterId = childId(child)
            if (openDetails.has(masterId)) {
              pushRow(
                { kind: 'detail', id: `${child.id}:detail`, level: store.level, route: store.route, masterId, master: child.data },
                child.data,
              )
            }
          }
          continue
        }
        const childRoute = [...store.route, child.key]
        const ck = routeKey(childRoute)
        const childStore = stores.get(ck)
        const isExp = expanded.has(ck)
        const unbalanced = !!options.allowUnbalancedGroups && child.key === ''
        const hidden = isExp && (unbalanced || !!options.hideOpenParents)
        if (!hidden) {
          pushRow(
            {
              kind: 'group',
              id: ck,
              path: childRoute,
              field: child.field,
              key: child.key,
              level: store.level,
              expanded: isExp,
              ...(pivotMode && !treeData && childRoute.length >= groupBy.length ? { expandable: false } : {}),
              // The expander shows a spinner for the level opening, not for
              // a block far down an open level that a deep scroll asked for.
              loading: !!childStore && childStore.cache.getCacheState().some((b) => b.blockIndex === 0 && b.status === 'loading'),
              aggregates: child.aggregates,
              ...(child.childCount != null ? { childCount: child.childCount } : {}),
              data: child.data,
            },
            child.data,
          )
        }
        if (isExp && childStore) {
          // This store's run ends here; the child's rows follow, then a new
          // run of this store begins.
          flushSegment(i + 1)
          walk(childStore)
          if (groupFooters && !hidden) {
            pushRow(
              {
                kind: 'footer',
                id: GROUP_TOTAL_ROW_ID_PREFIX + ck,
                level: store.level + 1,
                path: childRoute,
                key: child.key,
                aggregates: child.aggregates,
                data: child.data,
              } as ServerFooterRow<TData>,
              child.data,
            )
          }
          segStart = i + 1
          dispStart = total
        }
      }
      flushSegment(end)
      if (store.loadMore) {
        const count = store.cache.rowCount()
        const loaded = end
        if (count == null || loaded < count) {
          pushRow({
            kind: 'more',
            id: `sv-more:${store.key}`,
            level: store.level,
            path: store.route,
            remaining: count == null ? store.blockSize : count - loaded,
            loading: store.cache.getCacheState().some((b) => b.status === 'loading'),
          })
        }
      }
    }

    const root = stores.get(routeKey([]))
    if (root) {
      if (paging && !paging.paginateChildRows) {
        // A page of top-level rows. The root rows array is already sized to
        // the count (placeholders for what has not loaded), so the page
        // exists before its block does.
        const count = root.cache.rowCount() ?? root.cache.windowedRows().length
        pagerRowCount = count
        const start = Math.min(pageIndex * pageSize, Math.max(0, count - 1))
        walk(root, start, start + pageSize)
      } else {
        walk(root)
      }
    }

    /** Every piece as plain arrays. Lazy pieces read through `lazyLeafAt`. */
    const materialize = (): { display: ServerRowModelDisplayRow<TData>[]; grid: ServerRowModelGridRow<TData>[] } => {
      if (pieces.length === 1 && pieces[0]!.display) return { display: pieces[0]!.display, grid: pieces[0]!.grid! }
      const display: ServerRowModelDisplayRow<TData>[] = []
      const grid: ServerRowModelGridRow<TData>[] = []
      for (const p of pieces) {
        if (p.display) {
          for (let i = 0; i < p.length; i += 1) {
            display.push(p.display[i]!)
            grid.push(p.grid![i]!)
          }
          continue
        }
        for (let i = 0; i < p.length; i += 1) {
          const e = lazyLeafAt(p.store!, p.from! + i)
          display.push(e.d)
          grid.push(e.g)
        }
      }
      return { display, grid }
    }

    if (paging?.paginateChildRows) {
      // Child-row paging cuts the flattened body, so it works on plain
      // arrays; no level is lazy in this mode (see isLazyLeafLevel).
      const { display, grid } = materialize()
      // A page of the flattened tree. Cut the body and re-base the segments
      // that cross into the page; the grand total stays on every page.
      const bodyLength = display.length - bodyStart
      pagerRowCount = bodyLength
      const start = Math.min(pageIndex * pageSize, Math.max(0, bodyLength - 1))
      const stop = Math.min(bodyLength, start + pageSize)
      display.splice(bodyStart + stop)
      display.splice(bodyStart, start)
      grid.splice(bodyStart + stop)
      grid.splice(bodyStart, start)
      const cut: Segment<TData>[] = []
      for (const seg of segments) {
        const a = Math.max(seg.displayStart, bodyStart + start)
        const b = Math.min(seg.displayStart + seg.length, bodyStart + stop)
        if (b <= a) continue
        cut.push({
          store: seg.store,
          displayStart: a - start,
          storeStart: seg.storeStart + (a - seg.displayStart),
          length: b - a,
        })
      }
      segments = cut
      if (grandTotalRow === 'bottom' && grandTotal) {
        const d = grandTotalDisplay(grandTotal)
        display.push(d)
        grid.push(toGridRow(d, grandTotal))
      }
      return { display, grid }
    }

    if (grandTotalRow === 'bottom' && grandTotal) pushRow(grandTotalDisplay(grandTotal), grandTotal)

    if (!pieces.some((p) => p.store)) return materialize()
    // At least one lazy piece: hand out windowed arrays that find the piece
    // holding an index by binary search on the piece starts.
    const pieceAt = (index: number): Piece | undefined => {
      let lo = 0
      let hi = pieces.length - 1
      while (lo <= hi) {
        const mid = (lo + hi) >> 1
        const p = pieces[mid]!
        if (index < p.start) hi = mid - 1
        else if (index >= p.start + p.length) lo = mid + 1
        else return p
      }
      return undefined
    }
    const entryAt = (index: number): { d: ServerRowModelDisplayRow<TData>; g: ServerRowModelGridRow<TData> } | undefined => {
      const p = pieceAt(index)
      if (!p) return undefined
      const offset = index - p.start
      if (p.display) return { d: p.display[offset]!, g: p.grid![offset]! }
      return lazyLeafAt(p.store!, p.from! + offset)
    }
    return {
      display: createWindowedData(total, (i) => entryAt(i)?.d),
      grid: createWindowedData(total, (i) => entryAt(i)?.g),
    }
  }

  function pagination(): ServerRowModelPagination | null {
    if (!paging) return null
    return {
      pageIndex,
      pageSize,
      rowCount: pagerRowCount,
      pageCount: Math.max(1, Math.ceil(pagerRowCount / pageSize)),
    }
  }

  /**
   * A display row as the grid sees it: the row's own fields at the top
   * level plus the `__group` marker. Footers and the grand total also carry
   * the flags the grid keys its `sv-grid-group-footer-row` /
   * `sv-grid-grand-total-row` styling on, so they look like the client
   * model's totals rather than like ordinary rows.
   */
  function toGridRow(d: ServerRowModelDisplayRow<TData>, data?: TData): ServerRowModelGridRow<TData> {
    if (d.kind === 'placeholder') return d as unknown as ServerRowModelGridRow<TData>
    const row = { ...(data as object), __group: d } as ServerRowModelGridRow<TData> & {
      __groupFooter?: boolean
      __grandTotal?: boolean
    }
    if (d.kind === 'footer') row.__groupFooter = true
    if (d.kind === 'grandTotal') {
      row.__groupFooter = true
      row.__grandTotal = true
    }
    return row
  }

  function grandTotalDisplay(data: TData): ServerGrandTotalRow<TData> {
    const agg: Record<string, unknown> = {}
    for (const a of aggregations) agg[a.col] = (data as Record<string, unknown>)[a.col]
    return { kind: 'grandTotal', id: GRAND_TOTAL_ROW_ID, level: 0, aggregates: agg, data }
  }

  function pinnedGrandTotal(): ReadonlyArray<ServerRowModelGridRow<TData>> | undefined {
    if (!grandTotal) return undefined
    return [toGridRow(grandTotalDisplay(grandTotal), grandTotal)]
  }

  // ------------------------------------------------------------- state

  let current: ServerRowModelState<TData> = {
    displayRows: [],
    gridRows: [],
    groupBy: [...groupBy],
    aggregations: [...aggregations],
    rowCount: null,
    loading: true,
    saving: false,
    error: null,
    sortModel,
    filterModel,
    expandedGroups: [],
    openDetails: [],
    grandTotal: null,
    pivotBy: [...pivotBy],
    pivotMode,
    pivotResultFields: [],
    pagination: pagination(),
  }

  function buildState(): ServerRowModelState<TData> {
    const root = stores.get(routeKey([]))
    const { display, grid } = flatten()
    const rootLoaded = !!root && root.cache.getCacheState().some((b) => b.status === 'loaded')
    return {
      displayRows: display,
      gridRows: grid,
      groupBy: [...groupBy],
      aggregations: [...aggregations],
      rowCount: root?.cache.rowCount() ?? null,
      loading: !!root && !rootLoaded && root.cache.getCacheState().some((b) => b.status === 'loading'),
      saving: writesInFlight > 0,
      error: rootError,
      sortModel,
      filterModel,
      expandedGroups: [...expanded],
      openDetails: [...openDetails],
      grandTotal: grandTotal ?? null,
      pivotBy: [...pivotBy],
      pivotMode,
      pivotResultFields: [...pivotFields],
      pagination: pagination(),
    }
  }

  // `keepRowsWhileLoading`: after a sort, a filter or a regroup, the rows on
  // screen stay until the new answer's first block lands or the time runs
  // out. `holdUntil` is that deadline, 0 when nothing is held.
  let holdUntil = 0
  let holdTimer: ReturnType<typeof setTimeout> | null = null
  let held = false

  function holdRows(): void {
    const ms = options.keepRowsWhileLoading ?? 0
    if (ms > 0 && current.displayRows.length > 0) {
      holdUntil = Date.now() + ms
      freezeCurrent()
    }
  }

  /**
   * Held rows must not change under the user, but a lazy list reads the live
   * caches, which the sort or filter that started the hold is about to purge.
   * Copy the rows around the last viewport into a snapshot and serve the held
   * lists from it. Only the grid's subscription is told (so it re-reads);
   * `onChange` still fires once, when the hold ends.
   */
  function freezeCurrent(): void {
    if (!isWindowedData(current.gridRows)) return // plain arrays are a snapshot already
    const n = current.gridRows.length
    const MARGIN = 200
    const from = Math.max(0, lastViewport[0] - MARGIN)
    const to = Math.min(n - 1, lastViewport[1] + MARGIN)
    const display = new Map<number, ServerRowModelDisplayRow<TData>>()
    const grid = new Map<number, ServerRowModelGridRow<TData>>()
    for (let i = from; i <= to; i += 1) {
      display.set(i, current.displayRows[i]!)
      grid.set(i, current.gridRows[i]!)
    }
    current = {
      ...current,
      displayRows: createWindowedData(n, (i) => display.get(i) ?? LOADING_ROW),
      gridRows: createWindowedData(n, (i) => grid.get(i) ?? toGridRow(LOADING_ROW)),
    }
    for (const notify of subscribers) notify()
  }

  /** Whether the rows on screen should stay a little longer. */
  function holding(): boolean {
    if (!holdUntil) return false
    const root = stores.get(routeKey([]))
    // A failed block ends the hold too: its Retry is the answer to show.
    const rootAnswered = !!root && root.cache.getCacheState().some((b) => b.status !== 'loading')
    let pending = false
    for (const s of stores.values()) if (s.refreshPending) pending = true
    if (Date.now() >= holdUntil || rootError || (rootAnswered && !pending)) {
      holdUntil = 0
      return false
    }
    return true
  }

  function scheduleEmit(): void {
    if (disposed || emitScheduled) return
    emitScheduled = true
    queueMicrotask(() => {
      emitScheduled = false
      if (disposed) return
      if (holding()) {
        held = true
        holdTimer ??= setTimeout(() => {
          holdTimer = null
          scheduleEmit()
        }, Math.max(0, holdUntil - Date.now()))
        return
      }
      if (holdTimer) {
        clearTimeout(holdTimer)
        holdTimer = null
      }
      current = buildState()
      // While rows were held the grid kept reporting positions in the old
      // list, mapped through the old segments; map them through the new.
      if (held) {
        held = false
        applyViewport()
      }
      options.onChange?.(current)
      for (const notify of subscribers) notify()
    })
  }

  // ------------------------------------------------------- operations

  function applyViewport(): void {
    const [start, end] = lastViewport
    for (const seg of segments) {
      if (seg.store.loadMore) continue
      const segEnd = seg.displayStart + seg.length - 1
      if (segEnd < start || seg.displayStart > end) continue
      const from = Math.max(start, seg.displayStart) - seg.displayStart + seg.storeStart
      const to = Math.min(end, segEnd) - seg.displayStart + seg.storeStart
      seg.store.cache.setViewport(from, to)
    }
  }

  /** Ask a level for its first block, so it shows something before any scroll. */
  function primeStore(store: Store<TData>): void {
    if (store.loadMore) {
      store.cache.setViewport(0, store.blockSize - 1)
      return
    }
    const from = store.level === 0 && paging && !paging.paginateChildRows ? pageIndex * pageSize : 0
    store.cache.setViewport(from, from + Math.min(store.blockSize, skeletonRows) - 1)
  }

  function expandGroup(route: string[]): void {
    if (disposed) return
    // Under pivot the innermost group rows ARE the result; there is nothing
    // beneath them to fetch.
    if (pivotMode && !treeData && route.length >= groupBy.length) return
    const key = routeKey(route)
    if (expanded.has(key)) return
    expanded.add(key)
    const store = ensureStore(route)
    // A known child count sizes the scrollbar (and the skeletons) right away.
    const parent = parentRowOf(route)
    const known = parent !== undefined ? childCountOf?.(parent) : undefined
    if (known != null && store.cache.rowCount() == null) store.cache.setRowCount(known, true)
    primeStore(store)
    options.onGroupOpened?.(route)
    scheduleEmit()
  }

  function collapseGroup(route: string[]): void {
    const key = routeKey(route)
    if (!expanded.delete(key)) return
    if (options.purgeClosedGroups) dropSubtree(route)
    scheduleEmit()
  }

  /** Start over below `route` (or everywhere), keeping the expansion set. */
  function rebuild(route: string[] = []): void {
    if (route.length === 0) {
      // A full reset. Disposing every cache aborts every request, and the
      // generation bump discards any that slipped past the abort.
      generation += 1
      for (const s of stores.values()) s.cache.dispose()
      stores.clear()
      grandTotal = undefined
      grandTotalStale = false
      pivotFields = []
      pivotColumnsFromSource = null
    } else {
      dropSubtree(route)
    }
    const target = ensureStore(route)
    primeStore(target)
    // Expanded descendants come back too, each priming its own first block.
    for (const key of expanded) {
      const r = JSON.parse(key) as string[]
      if (r.length > route.length && route.every((seg, i) => r[i] === seg)) primeStore(ensureStore(r))
    }
    scheduleEmit()
  }

  /** Which stores a sort touches, under the selective rules. */
  function storesAffectedBySort(next: ServerSortModel): Store<TData>[] {
    const all = [...stores.values()]
    if (options.sortAllLevels || treeData) return all
    const aggCols = new Set(aggregations.map((a) => a.col))
    const levels = new Set<number>()
    let everything = false
    let leaves = false
    for (const s of next) {
      const gi = groupBy.indexOf(s.id)
      if (aggCols.has(s.id)) everything = true
      else if (gi >= 0) levels.add(gi)
      else leaves = true
    }
    // Clearing the sort has to put every level back to server order.
    if (next.length === 0) everything = true
    if (everything) return all
    return all.filter((s) => levels.has(s.level) || (leaves && isLeafLevel(s.level)))
  }

  function sortLocally(store: Store<TData>): boolean {
    const st = store.cache.getCacheState()
    const count = store.cache.rowCount()
    if (!store.cache.lastRowKnown() || count == null) return false
    const loaded = st.filter((b) => b.status === 'loaded').length
    if (loaded * store.blockSize < count) return false
    const rows = store.cache.rows().filter((r) => !rowPlaceholderState(r)) as Child<TData>[]
    if (rows.length !== count) return false
    const valueOf = (c: Child<TData>, col: string): unknown => (c.data as Record<string, unknown>)[col]
    rows.sort((a, b) => {
      for (const s of sortModel) {
        const cmp = compareValues(valueOf(a, s.id), valueOf(b, s.id))
        if (cmp !== 0) return s.desc ? -cmp : cmp
      }
      return 0
    })
    store.cache.applyRows(0, rows, count)
    return true
  }

  function setSort(next: ServerSortModel): void {
    sortModel = next
    holdRows()
    for (const store of storesAffectedBySort(next)) {
      if (options.clientSideSort && sortLocally(store)) continue
      store.refreshPending = true
      store.cache.refresh()
    }
    scheduleEmit()
  }

  function setFilter(next: ServerFilterModel | GridFilterState): void {
    const previous = filterModel
    holdRows()
    filterModel = Array.isArray(next.columns)
      ? {
          global: next.global,
          columns: toServerFilterColumns(next as GridFilterState),
          ...(next.custom ? { custom: next.custom } : {}),
        }
      : (next as ServerFilterModel)
    if (!options.onlyRefreshFilteredGroups) return rebuild()

    // Selective: the levels whose column changed. Everything else keeps its
    // stale counts, which is the documented trade.
    const changed = new Set<string>()
    const prevCols = previous.columns ?? {}
    const nextCols = filterModel.columns ?? {}
    for (const c of new Set([...Object.keys(prevCols), ...Object.keys(nextCols)])) {
      if (JSON.stringify(prevCols[c]) !== JSON.stringify(nextCols[c])) changed.add(c)
    }
    const globalChanged = (previous.global ?? '') !== (filterModel.global ?? '')
    const exprChanged = JSON.stringify(previous.expression) !== JSON.stringify(filterModel.expression)
    const aggCols = new Set(aggregations.map((a) => a.col))
    if (globalChanged || exprChanged || [...changed].some((c) => aggCols.has(c))) return rebuild()

    const levels = new Set<number>()
    let leaves = false
    for (const c of changed) {
      const gi = groupBy.indexOf(c)
      if (gi >= 0) levels.add(gi)
      else leaves = true
    }
    for (const store of stores.values()) {
      if (levels.has(store.level) || (leaves && isLeafLevel(store.level))) {
        store.refreshPending = true
        store.cache.refresh()
      }
    }
    scheduleEmit()
  }

  function levelState(store: Store<TData>): ServerLevelState {
    const blocks = store.cache.getCacheState()
    return {
      route: store.route,
      level: store.level,
      rowCount: store.cache.rowCount(),
      lastRowKnown: store.cache.lastRowKnown(),
      loading: blocks.some((b) => b.status === 'loading'),
      failedBlocks: blocks.filter((b) => b.status === 'failed').map((b) => b.blockIndex),
      blocks,
    }
  }

  // ------------------------------------------------------ transactions

  /** The id a transaction row goes by at a level: key at a group level, row id at a leaf level. */
  function transactionId(store: Store<TData>, row: TData | string): string {
    if (typeof row === 'string') return row
    if (getRowId) {
      const id = getRowId(row)
      if (id === GRAND_TOTAL_ROW_ID) return id
    }
    if (isLeafLevel(store.level) || treeData) {
      if (!getRowId) throw new Error('createServerRowModel: transactions need getRowId')
      return getRowId(row)
    }
    const field = groupBy[store.level]!
    const v = (row as Record<string, unknown>)[field]
    return v == null ? '' : String(v)
  }

  /** The id a CACHED child goes by, in the same terms. */
  function childId(child: Child<TData>): string {
    if (child.kind === 'group') return child.key
    // Leaf ids are `${storeKey}:${rowId}`; the row id is the tail.
    return getRowId ? getRowId(child.data) : child.id.slice(child.id.lastIndexOf(':') + 1)
  }

  function storeStatus(store: Store<TData>): ServerTransactionStatus {
    const blocks = store.cache.getCacheState()
    if (blocks.length === 0) return 'storeWaitingToLoad'
    if (blocks.some((b) => b.status === 'loaded')) return 'applied'
    if (blocks.some((b) => b.status === 'loading')) return 'storeLoading'
    return 'storeLoadingFailed'
  }

  function applyTransaction(tx: ServerTransaction<TData>): ServerTransactionResult {
    const result: ServerTransactionResult = { status: 'applied', add: [], update: [], remove: [] }
    if (disposed) return { ...result, status: 'storeNotFound' }
    if (options.isApplyTransaction && !options.isApplyTransaction(tx)) {
      return { ...result, status: 'cancelled' }
    }
    const route = tx.route ?? []
    const store = stores.get(routeKey(route))
    if (!store) return { ...result, status: 'storeNotFound' }
    const status = storeStatus(store)
    if (status !== 'applied') return { ...result, status }

    // The grand total answers to its fixed id, on the root route only.
    const isTotal = (row: TData | string): boolean =>
      route.length === 0 && typeof row !== 'string' && !!getRowId && getRowId(row) === GRAND_TOTAL_ROW_ID

    for (const row of tx.update ?? []) {
      if (isTotal(row)) {
        grandTotal = row
        result.update.push(GRAND_TOTAL_ROW_ID)
        continue
      }
      const id = transactionId(store, row)
      const index = store.cache.findIndex((c) => childId(c) === id)
      if (index < 0) continue
      const [child] = toChildren(route, index, [row])
      store.cache.patch(index, child!)
      result.update.push(id)
    }

    for (const row of tx.remove ?? []) {
      if (isTotal(row)) {
        grandTotal = null
        result.remove.push(GRAND_TOTAL_ROW_ID)
        continue
      }
      const id = transactionId(store, row)
      const index = store.cache.findIndex((c) => childId(c) === id)
      // Outside the cache means outside what we can show; when the count is
      // known the row is simply not here, and the count stands until the
      // caller says otherwise with `rowCount`.
      if (index < 0) continue
      const wasGroup = (store.cache.getRow(index) as Child<TData>).kind === 'group'
      if (store.cache.remove(index, 1) > 0) {
        result.remove.push(id)
        // A removed group takes its expansion and its cached children with it.
        if (wasGroup) {
          const childRoute = [...route, id]
          expanded.delete(routeKey(childRoute))
          dropSubtree(childRoute)
        }
      }
    }

    if (tx.add && tx.add.length) {
      const total = store.cache.rowCount()
      const at = tx.addIndex ?? (total ?? store.cache.windowedRows().length)
      const children = toChildren(route, at, tx.add)
      const placed = store.cache.insert(at, children)
      if (placed) for (const c of children) result.add.push(childId(c))
      // Adding the grand total means setting it.
      for (const row of tx.add) if (isTotal(row)) grandTotal = row
    }

    if (typeof tx.rowCount === 'number') store.cache.setRowCount(tx.rowCount, true)
    // The parent group row shows this level's count beside its key; adds
    // and removes move it by the net change. Aggregates stay as they were:
    // a refresh of the parent recomputes them, as documented.
    const delta = result.add.length - result.remove.length
    if (delta !== 0 && route.length > 0) adjustChildCount(route, delta)
    scheduleEmit()
    return result
  }

  function adjustChildCount(route: string[], delta: number): void {
    const parent = stores.get(routeKey(route.slice(0, -1)))
    if (!parent) return
    const key = route[route.length - 1]
    const index = parent.cache.findIndex((c) => c.kind === 'group' && c.key === key)
    if (index < 0) return
    const child = parent.cache.getRow(index) as Child<TData>
    if (child.kind !== 'group' || child.childCount == null) return
    parent.cache.patch(index, { ...child, childCount: Math.max(0, child.childCount + delta) })
  }

  const asyncQueue: Array<{
    tx: ServerTransaction<TData>
    callback?: (result: ServerTransactionResult) => void
  }> = []
  let asyncTimer: ReturnType<typeof setTimeout> | null = null

  function flushAsyncTransactions(): void {
    if (asyncTimer) clearTimeout(asyncTimer)
    asyncTimer = null
    if (asyncQueue.length === 0) return
    const batch = asyncQueue.splice(0)
    const results: ServerTransactionResult[] = []
    for (const item of batch) {
      const result = applyTransaction(item.tx)
      // A level still loading gets its transaction back in the queue for
      // the next flush; nothing else is retried.
      if (result.status === 'storeLoading' || result.status === 'storeWaitingToLoad') {
        asyncQueue.push(item)
        continue
      }
      results.push(result)
      item.callback?.(result)
    }
    if (results.length) options.onAsyncTransactionsFlushed?.(results)
    if (asyncQueue.length) scheduleAsyncFlush()
  }

  function scheduleAsyncFlush(): void {
    if (asyncTimer || disposed) return
    asyncTimer = setTimeout(() => {
      asyncTimer = null
      flushAsyncTransactions()
    }, options.asyncTransactionWaitMs ?? 50)
  }

  /** Run one write with `saving` raised around it; the flag is "any write in flight". */
  async function saving<T>(write: () => Promise<T>): Promise<T> {
    writesInFlight += 1
    scheduleEmit()
    try {
      return await write()
    } finally {
      writesInFlight -= 1
      // Rows are rebuilt from the cache on the next read, so an edit the
      // server refused (and the model never applied) is gone from the grid.
      lazyMemo = new WeakMap()
      scheduleEmit()
    }
  }

  /** The level and index holding a leaf row with this id, searching loaded rows only. */
  function locate(id: string): { store: Store<TData>; index: number } | null {
    for (const store of stores.values()) {
      const index = store.cache.findIndex((c) => childId(c) === id)
      if (index >= 0) return { store, index }
    }
    return null
  }

  function updateRowData(id: string, patch: Partial<TData>, opts?: { replace?: boolean }): boolean {
    const hit = locate(id)
    if (!hit) return false
    const current = hit.store.cache.getRow(hit.index) as Child<TData>
    const next = (opts?.replace ? patch : { ...current.data, ...patch }) as TData
    const [child] = toChildren(hit.store.route, hit.index, [next])
    hit.store.cache.patch(hit.index, child!)
    scheduleEmit()
    return true
  }

  // --------------------------------------------------------- selection

  const selectionModel: ServerSelectionModel | null = options.selection
    ? createServerSelectionModel({
        groupSelects: options.selection.groupSelects,
        // The grid re-derives the header checkbox and the row ticks from a
        // row-model notification, so a selection change is one.
        onChange: scheduleEmit,
        leafCount: groupLeafCount,
      })
    : null

  /**
   * Leaves under a loaded group row, from its `count` aggregate (the same
   * one `leafTotal` reads on the grand total); null without one, or when
   * the group row is not loaded.
   */
  function groupLeafCount(route: ReadonlyArray<string>): number | null {
    const counter = aggregations.find((a) => a.fn === 'count')
    if (!counter || route.length === 0) return null
    const parent = stores.get(routeKey(route.slice(0, -1)))
    if (!parent) return null
    const key = route[route.length - 1]
    const index = parent.cache.findIndex((c) => c.kind === 'group' && c.key === key)
    if (index < 0) return null
    const child = parent.cache.getRow(index) as Child<TData>
    if (child.kind !== 'group') return null
    const n = Number(child.aggregates[counter.col])
    return Number.isFinite(n) ? n : null
  }

  /** Where a grid row lives in selection terms: its parent route and its own id. */
  function locateForSelection(
    row: ServerRowModelGridRow<TData>,
  ): { route: ReadonlyArray<string>; id: string; isGroup: boolean } | null {
    const d = row.__group
    if (!d) return null
    if (d.kind === 'group') return { route: d.path.slice(0, -1), id: d.key, isGroup: true }
    if (d.kind === 'leaf') {
      return { route: d.route ?? [], id: getRowId ? getRowId(d.data) : d.id, isGroup: false }
    }
    return null
  }

  /**
   * How many leaves the whole result holds, for an honest select-all count:
   * the root count when nothing is grouped, else the `count` aggregation
   * on the grand total (the only place the server says it), else unknown.
   */
  function leafTotal(): number | null {
    if (treeData || groupBy.length === 0) return current.rowCount
    const counter = aggregations.find((a) => a.fn === 'count')
    if (!counter || !grandTotal) return null
    const n = Number((grandTotal as Record<string, unknown>)[counter.col])
    return Number.isFinite(n) ? n : null
  }

  const selectionAdapter = selectionModel
    ? {
        isSelected: (_rowId: string, row: ServerRowModelGridRow<TData>) => {
          const at = locateForSelection(row)
          return at ? selectionModel.isSelected(at.route, at.id) : false
        },
        headerState: () => selectionModel.headerState(),
        toggle: (_rowId: string, row: ServerRowModelGridRow<TData>, next: boolean) => {
          const at = locateForSelection(row)
          if (at) selectionModel.toggle(at.route, at.id, next, at.isGroup)
        },
        toggleAll: (next: boolean) => selectionModel.setAll(next),
        selectedCount: () => selectionModel.selectedCount(leafTotal()),
        bulkUpdate: (patch: Record<string, unknown>) => bulkUpdate(patch as Partial<TData>),
      }
    : undefined

  async function bulkUpdate(patch: Partial<TData>): Promise<number> {
    if (!selectionModel) throw new Error('createServerRowModel: bulkUpdate needs the `selection` option')
    if (!source.updateWhere) {
      throw new Error(
        'createServerRowModel: the datasource does not implement updateWhere(), so a bulk edit ' +
          'cannot reach rows the grid has not loaded',
      )
    }
    const rule = selectionModel.getState()
    // A nested rule is keyed level by level by the group columns; say which.
    const changed = await source.updateWhere(
      filterModel,
      patch,
      'selectAllChildren' in rule ? { ...rule, groupBy: [...groupBy] } : rule,
    )
    if (disposed) return changed
    // Every level may have changed rows AND aggregates; reload them in place.
    for (const store of stores.values()) {
      store.refreshPending = true
      store.cache.refresh()
    }
    grandTotalStale = true
    scheduleEmit()
    return changed
  }

  // ------------------------------------------------------------ pivot

  /**
   * The columns that replace the grid's own while pivoting: the leading
   * columns the app named, then one header group per pivot key with a value
   * column per aggregation under it. Null outside pivot mode, or before the
   * first pivoted response has said what fields exist.
   */
  function pivotResultColumns(): ReadonlyArray<unknown> | null {
    if (!pivotMode) return null
    const leading = options.pivotLeadingColumns ?? []
    if (pivotColumnsFromSource) return [...leading, ...pivotColumnsFromSource]
    if (pivotFields.length === 0) return null
    return [
      ...leading,
      ...buildPivotResultColumns(pivotFields, aggregations, {
        separator: pivotSeparator,
        pivotResultColumn: options.pivotResultColumn,
        rowTotals: pivotRowTotals,
      }),
    ]
  }

  // ---------------------------------------------------- the controller

  // The id a leaf's detail is kept under: the app's row id, else the leaf's own.
  const leafDetailId = (g: { id: string; data: TData }) => (getRowId ? getRowId(g.data) : g.id.slice(g.id.lastIndexOf(':') + 1))
  const nav = {
    isGroup: (row: ServerRowModelGridRow<TData>) => row.__group?.kind === 'group',
    level: (row: ServerRowModelGridRow<TData>) =>
      row.__group && 'level' in row.__group ? row.__group.level : 0,
    expanded: (row: ServerRowModelGridRow<TData>) =>
      row.__group?.kind === 'group' ? row.__group.expanded : false,
    onToggle: (row: ServerRowModelGridRow<TData>) => {
      if (row.__group?.kind === 'group') model.toggleGroup(row.__group)
      else if (row.__group?.kind === 'more') model.loadMoreChildren(row.__group.path)
    },
    // A leaf's detail, by the id the app gave the row; a detail row toggles its master.
    toggleDetail: (row: ServerRowModelGridRow<TData>) => {
      const g = row.__group
      if (g?.kind === 'leaf') model.toggleDetail(leafDetailId(g))
      else if (g?.kind === 'detail') model.toggleDetail(g.masterId)
    },
    // Only a leaf has a detail to open; a group's expander is in the group column.
    hasDetail: (row: ServerRowModelGridRow<TData>) => row.__group?.kind === 'leaf',
    detailOpen: (row: ServerRowModelGridRow<TData>) => {
      const g = row.__group
      return g?.kind === 'leaf' ? model.isDetailOpen(leafDetailId(g)) : false
    },
  }

  const model: ServerRowModel<TData> = {
    refresh(opts) {
      if (disposed) return
      const route = opts?.route ?? []
      const store = stores.get(routeKey(route))
      if (opts?.purge || !store) return rebuild(route)
      store.refreshPending = true
      // The top level re-read in place brings its aggregates back fresh;
      // the grand total is one of them.
      if (route.length === 0) grandTotalStale = true
      store.cache.refresh()
      scheduleEmit()
    },
    retryLoads() {
      for (const store of stores.values()) store.cache.retryFailed()
    },
    setSort,
    setFilter,
    setGroupBy(next) {
      model.setLayout({ groupBy: next })
    },
    setAggregations(next) {
      model.setLayout({ aggregations: next })
    },
    setPivot(next) {
      model.setLayout(next)
    },
    setLayout(next) {
      if (disposed) return
      const same = (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b)
      const groupChanged = next.groupBy !== undefined && !same(next.groupBy, groupBy)
      const aggChanged = next.aggregations !== undefined && !same(next.aggregations, aggregations)
      const pivotChanged =
        (next.pivotBy !== undefined && !same(next.pivotBy, pivotBy)) ||
        (next.pivotMode !== undefined && next.pivotMode !== pivotMode)
      // The totals group is built from what is already loaded: no request.
      if (next.pivotRowTotals !== undefined && next.pivotRowTotals !== pivotRowTotals) {
        pivotRowTotals = next.pivotRowTotals
        if (!groupChanged && !aggChanged && !pivotChanged) {
          scheduleEmit()
          return
        }
      }
      if (!groupChanged && !aggChanged && !pivotChanged) return
      if (next.groupBy) groupBy = [...next.groupBy]
      if (next.aggregations) aggregations = [...next.aggregations]
      if (next.pivotBy) pivotBy = [...next.pivotBy]
      if (next.pivotMode !== undefined) pivotMode = next.pivotMode
      // New group columns make new rows, and pivoted group rows and plain
      // group rows are different rows: neither keeps its open state. A
      // change of aggregations alone keeps the tree open and refetches it.
      if (groupChanged || pivotChanged) {
        expanded.clear()
        seenGroups.clear()
      }
      holdRows()
      rebuild()
    },
    toggleGroup(row) {
      if (expanded.has(row.id)) collapseGroup(row.path)
      else expandGroup(row.path)
    },
    expandGroup,
    collapseGroup,
    toggleDetail(id, open) {
      const next = open ?? !openDetails.has(id)
      if (next === openDetails.has(id)) return
      if (next) openDetails.add(id)
      else openDetails.delete(id)
      scheduleEmit()
    },
    isDetailOpen(id) {
      return openDetails.has(id)
    },
    closeAllDetails() {
      if (!openDetails.size) return
      openDetails.clear()
      scheduleEmit()
    },
    expandAll(opts) {
      autoExpand = !!opts?.includeUnloaded
      for (const store of [...stores.values()]) {
        // A pure leaf level holds no groups to open; reading it would walk
        // every row it has.
        if (isLazyLeafLevel(store)) continue
        for (const child of store.cache.rows()) {
          if (rowPlaceholderState(child) || child.kind !== 'group') continue
          expandGroup([...store.route, child.key])
        }
      }
    },
    collapseAll() {
      autoExpand = false
      const open = [...expanded].map((k) => JSON.parse(k) as string[])
      expanded.clear()
      if (options.purgeClosedGroups) for (const r of open) dropSubtree(r)
      scheduleEmit()
    },
    isExpanded: (route) => expanded.has(routeKey(route)),
    applyRowData({ route = [], rows, rowCount, startRow = 0 }) {
      if (disposed) return
      const store = ensureStore(route)
      store.cache.applyRows(startRow, toChildren(route, startRow, rows), rowCount)
      scheduleEmit()
    },
    applyTransaction,
    applyTransactionAsync(tx, callback) {
      asyncQueue.push({ tx, callback })
      scheduleAsyncFlush()
    },
    flushAsyncTransactions,
    updateRowData,
    async createRow(input, route = [], addIndex) {
      if (!source.createRow) throw new Error('createServerRowModel: the datasource does not implement createRow()')
      const saved = await saving(() => source.createRow!(input))
      if (disposed) return saved
      applyTransaction({ route, add: [saved], ...(addIndex !== undefined ? { addIndex } : {}) })
      return saved
    },
    async updateRow(id, patch) {
      if (!source.updateRow) throw new Error('createServerRowModel: the datasource does not implement updateRow()')
      const before = options.optimistic ? locate(id) : null
      const previous = before ? ((before.store.cache.getRow(before.index) as Child<TData>).data as TData) : null
      // Show the patch now; the server answer replaces it, a rejection restores it.
      if (previous) updateRowData(id, patch)
      let saved: TData
      try {
        saved = await saving(() => source.updateRow!(id, patch))
      } catch (err) {
        if (previous && !disposed) updateRowData(id, previous, { replace: true })
        throw err
      }
      if (disposed) return saved
      const hit = locate(id)
      if (hit) applyTransaction({ route: hit.store.route, update: [saved] })
      return saved
    },
    async moveRow(id, toRoute, opts = {}) {
      const from = locate(id)
      if (!from) throw new Error(`createServerRowModel: moveRow: row ${id} is not loaded`)
      const child = from.store.cache.getRow(from.index) as Child<TData>
      let row = child.data
      if (opts.patch) {
        if (!source.updateRow) throw new Error('createServerRowModel: the datasource does not implement updateRow()')
        row = await saving(() => source.updateRow!(id, opts.patch!))
        if (disposed) return { row, status: 'cancelled' }
      }
      const fromRoute = [...from.store.route]
      // A moved group's children were cached under its old route.
      if (child.kind === 'group') dropSubtree([...fromRoute, child.key])
      applyTransaction({ route: fromRoute, remove: [id] })
      const res = applyTransaction({
        route: [...toRoute],
        add: [row],
        ...(opts.addIndex !== undefined ? { addIndex: opts.addIndex } : {}),
      })
      // A target level nothing has opened cannot take the row, but its group
      // row is on screen and the row did go there: the badge follows now
      // rather than at the next refresh.
      if (res.status === 'storeNotFound' && toRoute.length) adjustChildCount([...toRoute], 1)
      return { row, status: res.status }
    },
    async deleteRow(id) {
      if (!source.deleteRow) throw new Error('createServerRowModel: the datasource does not implement deleteRow()')
      const before = options.optimistic ? locate(id) : null
      const removed = before ? ((before.store.cache.getRow(before.index) as Child<TData>).data as TData) : null
      const route = before ? [...before.store.route] : []
      const index = before?.index ?? 0
      // Take the row out now; a rejection puts it back where it was.
      if (removed) applyTransaction({ route, remove: [id] })
      try {
        await saving(() => source.deleteRow!(id))
      } catch (err) {
        if (removed && !disposed) applyTransaction({ route, add: [removed], addIndex: index })
        throw err
      }
      if (disposed || removed) return
      const hit = locate(id)
      if (hit) applyTransaction({ route: hit.store.route, remove: [id] })
    },
    setViewport(startIndex, endIndex) {
      lastViewport = [Math.max(0, startIndex), Math.max(startIndex, endIndex)]
      // The first viewport starts the model. Its first load used to come from
      // the grid reporting its starting sort on mount (setSort -> rebuild);
      // the grid no longer reports a mount as a sort change, and a model that
      // nothing else touched (no sort, no filter, a layout equal to the one
      // it was built with) then never asked for a single block.
      if (!disposed && !stores.has(routeKey([]))) {
        rebuild()
        return
      }
      applyViewport()
    },
    setPage(next) {
      if (!paging || disposed) return
      const last = Math.max(0, Math.ceil(pagerRowCount / pageSize) - 1)
      const clamped = Math.max(0, Math.min(Math.floor(next), last))
      if (clamped === pageIndex) return
      pageIndex = clamped
      // The grid keeps reporting the same on-screen indices from page to
      // page, so the new page asks for its own blocks here.
      current = buildState()
      applyViewport()
      const root = stores.get(routeKey([]))
      if (root) primeStore(root)
      scheduleEmit()
    },
    setPageSize(next) {
      if (!paging || disposed) return
      const size = Math.max(1, Math.floor(next))
      if (size === pageSize) return
      const firstRow = pageIndex * pageSize
      pageSize = size
      pageIndex = Math.floor(firstRow / size)
      current = buildState()
      applyViewport()
      const root = stores.get(routeKey([]))
      if (root) primeStore(root)
      scheduleEmit()
    },
    loadMoreChildren(route) {
      const store = stores.get(routeKey(route))
      if (!store || disposed) return
      const rows = store.cache.rows()
      let loaded = 0
      while (loaded < rows.length && !rowPlaceholderState(rows[loaded])) loaded += 1
      store.cache.setViewport(loaded, loaded + store.blockSize - 1)
      scheduleEmit()
    },
    selectionModel,
    getSelectionState: () => selectionModel?.getState() ?? null,
    setSelectionState(state) {
      selectionModel?.setState(isCallbackSelectionState(state) ? fromCallbackSelectionState(state) : state)
    },
    bulkUpdate,
    getLevelState(route = []) {
      const store = stores.get(routeKey(route))
      return store ? levelState(store) : null
    },
    levelStates: () => [...stores.values()].map(levelState),
    getCacheState() {
      const out: Array<BlockState & { route: string[] }> = []
      for (const store of stores.values()) {
        for (const b of store.cache.getCacheState()) out.push({ ...b, route: store.route })
      }
      return out
    },
    // Fresh, not the last emitted snapshot: a caller reading state straight
    // after `collapseAll()` expects to see it collapsed, and the emit is a
    // microtask away. `getRows()` stays on the snapshot - it is the hot path.
    getState: () => (current = buildState()),
    dispose() {
      disposed = true
      generation += 1
      if (asyncTimer) clearTimeout(asyncTimer)
      asyncTimer = null
      if (holdTimer) clearTimeout(holdTimer)
      holdTimer = null
      asyncQueue.length = 0
      for (const s of stores.values()) s.cache.dispose()
      stores.clear()
      subscribers.clear()
      source.destroy?.()
    },
    get pinnedTopRows() {
      return grandTotalRow === 'pinnedTop' ? pinnedGrandTotal() : undefined
    },
    get pinnedBottomRows() {
      return grandTotalRow === 'pinnedBottom' ? pinnedGrandTotal() : undefined
    },
    get pivotResultColumns() {
      return pivotResultColumns()
    },
    // A getter: the grid re-reads it after every change notification.
    get pagination() {
      if (!paging) return undefined
      return {
        pageIndex,
        pageSize,
        rowCount: pagerRowCount,
        setPage: (i: number) => model.setPage(i),
        setPageSize: (n: number) => model.setPageSize(n),
        ...(paging.pageSizes ? { pageSizes: paging.pageSizes } : {}),
        ...(paging.autoPageSize ? { autoPageSize: true } : {}),
      }
    },

    // --- GridRowModel ---------------------------------------------------
    subscribe(onChange) {
      subscribers.add(onChange)
      return () => {
        subscribers.delete(onChange)
      }
    },
    getRows: () => current.gridRows,
    isLoading: () => current.loading,
    getRowId: (row, index) =>
      row.__group && 'id' in row.__group ? row.__group.id : `sv-ph:${index}`,
    rowPlaceholder: (row) => rowPlaceholderState(row),
    retryRow(_row, rowIndex) {
      // The block under the clicked row; every failed block only when the
      // index maps to no level (a stale index after a layout change).
      for (const seg of segments) {
        if (rowIndex < seg.displayStart || rowIndex >= seg.displayStart + seg.length) continue
        seg.store.cache.retryFailedAt(rowIndex - seg.displayStart + seg.storeStart)
        return
      }
      for (const store of stores.values()) store.cache.retryFailed()
    },
    group: nav,
    selection: selectionAdapter,
    filterValues: options.filterValues,
  }

  return model
}

export function createServerSelectionModel(
  options: ServerSelectionModelOptions = {},
): ServerSelectionModel {
  const groupSelects = options.groupSelects ?? 'self'
  const hierarchical = groupSelects !== 'self'
  const notify = () => options.onChange?.()

  // ------------------------------------------------------------- flat
  let selectAll = false
  const toggled = new Set<string>()

  // ------------------------------------------------------ hierarchical
  type Node = { selectAllChildren: boolean; toggled: Map<string, Node>; group: boolean }
  let root: Node = { selectAllChildren: false, toggled: new Map(), group: true }

  /** Walk the rule tree along `route`, returning the deepest node reached and the state it implies. */
  function resolve(route: ReadonlyArray<string>): { node: Node; state: boolean; exact: boolean } {
    let node = root
    let state = root.selectAllChildren
    for (const key of route) {
      const next = node.toggled.get(key)
      if (!next) return { node, state, exact: false }
      node = next
      state = next.selectAllChildren
    }
    return { node, state, exact: true }
  }

  /** Walk-or-create the rule tree along `route`, so an exception can be recorded beneath it. */
  function ensurePath(route: ReadonlyArray<string>): Node {
    let node = root
    for (const key of route) {
      let next = node.toggled.get(key)
      if (!next) {
        // A group we descend into without an explicit rule inherits its
        // parent's state, and records it so the exception below has a base.
        next = { selectAllChildren: node.selectAllChildren, toggled: new Map(), group: true }
        node.toggled.set(key, next)
      }
      node = next
    }
    return node
  }

  /** Drop nodes that no longer differ from their parent, so state stays minimal. */
  function prune(node: Node): void {
    for (const [key, child] of [...node.toggled]) {
      prune(child)
      if (child.toggled.size === 0 && child.selectAllChildren === node.selectAllChildren) {
        node.toggled.delete(key)
      }
    }
  }

  const toPlain = (node: Node): ServerGroupSelectionNode => ({
    selectAllChildren: node.selectAllChildren,
    toggled: Object.fromEntries([...node.toggled].map(([k, v]) => [k, toPlain(v)])),
    ...(node.group ? { group: true } : {}),
  })
  const fromPlain = (plain: ServerGroupSelectionNode, group = true): Node => ({
    selectAllChildren: !!plain.selectAllChildren,
    toggled: new Map(
      Object.entries(plain.toggled ?? {}).map(([k, v]) => [k, fromPlain(v, !!v.group)]),
    ),
    group,
  })

  /**
   * The number of rows the exceptions under `node` amount to, or null when
   * one of them is a flipped GROUP - its size was never counted here. A
   * group whose own state matches its parent is a pass-through; only what
   * sits beneath it counts.
   */
  /**
   * Leaves selected under `node`, whose own subtree holds `size` leaves
   * (`null` when unknown). A selected node is its size minus the exceptions
   * among its toggled children; an unselected one is the sum of what its
   * toggled children select. A flipped group needs its size, which comes
   * from `leafCount`; without it the answer is unknown.
   */
  function selectedUnder(node: Node, route: ReadonlyArray<string>, size: number | null): number | null {
    if (node.selectAllChildren) {
      if (size == null) return null
      let minus = 0
      for (const [key, child] of node.toggled) {
        if (child.group) {
          const childRoute = [...route, key]
          const childSize = options.leafCount?.(childRoute) ?? null
          const selected = selectedUnder(child, childRoute, childSize)
          if (childSize == null || selected == null) return null
          minus += childSize - selected
        } else if (!child.selectAllChildren) {
          minus += 1
        }
      }
      return Math.max(0, size - minus)
    }
    let n = 0
    for (const [key, child] of node.toggled) {
      if (child.group) {
        const childRoute = [...route, key]
        const selected = selectedUnder(child, childRoute, options.leafCount?.(childRoute) ?? null)
        if (selected == null) return null
        n += selected
      } else if (child.selectAllChildren) {
        n += 1
      }
    }
    return n
  }

  return {
    groupSelects,

    isSelected(route, id) {
      if (!hierarchical) return selectAll !== toggled.has(id)
      const { node, state } = resolve(route)
      const own = node.toggled.get(id)
      return own ? own.selectAllChildren : state
    },

    toggle(route, id, next, isGroup = false) {
      if (!hierarchical) {
        // The row differs from the rule when `next` disagrees with selectAll.
        if (next !== selectAll) toggled.add(id)
        else toggled.delete(id)
        notify()
        return
      }
      const parent = ensurePath(route)
      // A toggled row - group or leaf - becomes a node with no exceptions of
      // its own: ticking a group throws away whatever was recorded beneath it.
      if (next === parent.selectAllChildren) parent.toggled.delete(id)
      else parent.toggled.set(id, { selectAllChildren: next, toggled: new Map(), group: isGroup })
      prune(root)
      notify()
    },

    setAll(next) {
      if (!hierarchical) {
        selectAll = next
        toggled.clear()
      } else {
        root = { selectAllChildren: next, toggled: new Map(), group: true }
      }
      notify()
    },

    clear() {
      this.setAll(false)
    },

    headerState() {
      if (!hierarchical) {
        if (selectAll) return toggled.size === 0 ? 'all' : 'some'
        return toggled.size === 0 ? 'none' : 'some'
      }
      if (root.selectAllChildren) return root.toggled.size === 0 ? 'all' : 'some'
      return root.toggled.size === 0 ? 'none' : 'some'
    },

    selectedCount(rowCount) {
      if (!hierarchical) {
        if (!selectAll) return toggled.size
        return rowCount == null ? null : Math.max(0, rowCount - toggled.size)
      }
      return selectedUnder(root, [], rowCount)
    },

    isSelectAllWithoutExceptions() {
      return hierarchical ? root.selectAllChildren && root.toggled.size === 0 : selectAll && toggled.size === 0
    },

    getState() {
      if (!hierarchical) return { selectAll, toggled: [...toggled] }
      return toPlain(root)
    },

    setState(state) {
      if (!hierarchical) {
        const flat = state as ServerSelectionState
        selectAll = !!flat.selectAll
        toggled.clear()
        for (const id of flat.toggled ?? []) toggled.add(id)
      } else {
        root = fromPlain(state as ServerGroupSelectionNode)
      }
      notify()
    },
  }
}

export function createSortedRowModel<TData extends RowData>(
  localSortFns: typeof sortFns = sortFns,
): RowModelFactory<TData> {
  /**
   * What the last full sort produced, kept so a tick can repair it.
   *
   * A live feed replaces a few hundred row objects out of a hundred thousand
   * and hands the grid a new array. Re-sorting all of it costs the same as
   * the first sort did (115-149 ms in the browser for 100k rows, see
   * docs/help/benchmarks.md); the order it would produce differs from the
   * previous one only where the replaced rows land. So the previous output
   * is kept, with its sort keys aligned to it, and when `getRowModel` says
   * which rows were replaced (see `replacedRowsOf`) the stage drops those,
   * sorts the replacements among themselves and merges them back in one
   * linear pass: O(n + k log k) instead of O(n log n) key builds and
   * comparisons.
   *
   * The repair is only attempted when everything else is the same object as
   * last time - the sorting state, the columns, and every input row except
   * the replaced ones - and it produces exactly what the full sort would:
   * equal keys fall back to the data index, which is the order a stable sort
   * over data-ordered input keeps.
   */
  let cache: {
    input: Array<Row<TData>>
    output: Array<Row<TData>>
    sorting: SortingState
    columns: Array<Column<TData>>
    clauses: Array<SortClause>
  } | null = null

  type SortClause = {
    desc: boolean
    compare: (a: any, b: any) => number
    /** The key for one row, or `MISSING_KEY` when it cannot be produced incrementally. */
    keyOf: (row: Row<TData>) => any
  }
  const MISSING_KEY = Symbol('svgrid.sort.missing-key')

  function fullSort(rows: Array<Row<TData>>, sorting: SortingState, allColumns: Array<Column<TData>>) {
    // Resolve every clause ONCE, before sorting.
    //
    // This used to live inside the comparator, so `getAllColumns().find(...)`
    // ran per comparison per clause: a single-clause sort of 100k rows made
    // 1,528,947 array scans, and a three-clause sort made 3,933,751 (measured;
    // `pnpm bench --case=sort-1col`). The comparator is called O(n log n)
    // times, so anything inside it that is not O(1) sets the cost of the sort.
    const clauses: Array<{
      keys: Array<any>
      desc: boolean
      compare: (a: any, b: any) => number
      keyOf: (row: Row<TData>) => any
      /** Set when every key is an integer rank in [0, rankCount): the text rank path. */
      rankCount?: number
    }> = []

    for (const clause of sorting) {
      const column = allColumns.find((col) => col.id === clause.id)
      if (!column) continue
      // By the column's data type, not by what edits it: a number column
      // edited in a text box still sorts as numbers.
      const dataType = columnDataType(column.columnDef)
      // A column's own comparator takes the plain raw-value path below.
      const custom = column.columnDef.sortComparator
      const comparator = custom
        ? (a: unknown, b: unknown) => custom(a, b, clause.desc)
        : dataType === 'number'
          ? localSortFns.number
          : isDateDataType(dataType)
            ? localSortFns.date
            : localSortFns.auto

      // Precompute one sort key per row, so the comparator reads an array slot
      // instead of walking the row's column index on every comparison. For the
      // three built-in comparators the key is also cheaper to compare than the
      // raw value: a timestamp rather than two `new Date()` allocations, a
      // number rather than two `Number()` coercions, a collator rather than a
      // fresh one per `localeCompare` call.
      //
      // The identity checks against `sortFns` matter: `localSortFns` is a
      // public parameter, so a caller can substitute their own comparators.
      // When they have, we fall through to calling their function with the raw
      // values - still hoisted, just not specialised.
      const columnId = column.id
      const n = rows.length
      let keys: Array<any> = new Array(n)
      let compare: (a: any, b: any) => number
      let keyOf: (row: Row<TData>) => any
      let autoMode: 'number' | 'mixed' | 'text' | undefined
      let rankCount: number | undefined

      const sortValue = column.columnDef.sortValue
      if (typeof sortValue === 'function') {
        keyOf = (row) => numberSortKey(sortValue(row.getCellValueByColumnId(columnId)))
        for (let i = 0; i < n; i++) keys[i] = keyOf(rows[i]!)
        compare = compareNumericKeys
      } else if (comparator === sortFns.number) {
        keyOf = (row) => numberSortKey(row.getCellValueByColumnId(columnId))
        for (let i = 0; i < n; i++) keys[i] = keyOf(rows[i]!)
        compare = compareNumericKeys
      } else if (comparator === sortFns.date) {
        keyOf = (row) => dateSortKey(row.getCellValueByColumnId(columnId))
        for (let i = 0; i < n; i++) keys[i] = keyOf(rows[i]!)
        compare = compareNumericKeys
      } else if (comparator === sortFns.auto && (autoMode = autoSortMode(rows, columnId)) === 'number') {
        // A column with no declared type whose values are all numbers. Sorting
        // it as text put 10 before 2 (#104).
        keyOf = (row) => {
          const value = row.getCellValueByColumnId(columnId)
          // A text value arriving in a tick changes the mode; only a full sort
          // can place it.
          return typeof value === 'number' || isBlankSortValue(value)
            ? numberSortKey(value)
            : MISSING_KEY
        }
        for (let i = 0; i < n; i++) keys[i] = keyOf(rows[i]!)
        compare = compareNumericKeys
      } else if (autoMode === 'mixed') {
        // Numbers and text in one column. Rare, so no key tricks: the raw
        // values through the pairwise comparator, which orders by kind first.
        keyOf = (row) => row.getCellValueByColumnId(columnId)
        for (let i = 0; i < n; i++) keys[i] = keyOf(rows[i]!)
        compare = compareAutoValues
      } else if (comparator === sortFns.auto) {
        const strings: string[] = new Array(n)
        // Decide whether ranking is worth attempting BEFORE paying for it.
        //
        // Building the distinct set and then discarding it costs about 9 ms on
        // a 100k-row column where nearly every value is unique, and ranking
        // saves about 19 ms where they repeat - so guessing wrong in either
        // direction is measurable. A small stride sample answers it for well
        // under a millisecond.
        //
        // Strided rather than the first N rows: data arrives sorted or
        // clustered often enough that a prefix is a bad estimator of the whole
        // column. Reading every k-th row is no more expensive and does not care
        // how the rows are arranged.
        const rankLimit = n >> 1
        // Each distinct value's id (its insertion order), when ranking.
        let idOf: Map<string, number> | null = null
        if (n > 0) {
          // Ranking pays when the column has at most n/2 distinct values. A
          // small sample cannot see that by asking whether half of it repeats:
          // 1M rows of 80k values, each one 12 times over, gave 256 samples
          // with almost no repeats, so ranking was skipped and the sort made
          // 20M collator calls (1.75 s; ranked, it is a fraction of that).
          // Count the repeats in a larger sample instead. S samples from u
          // equally common values repeat about S^2 / 2u times, so u <= n/2
          // shows as at least S^2 / n repeats. Up to SAMPLE rows the whole
          // column is the sample and the test is exact.
          const SAMPLE = 2048
          const sampleTarget = Math.min(n, SAMPLE)
          const stride = Math.max(1, Math.floor(n / sampleTarget))
          const sample = new Set<string>()
          let sampled = 0
          for (let i = 0; i < n; i += stride) {
            sample.add(autoTextKey(rows[i]!.getCellValueByColumnId(columnId)))
            sampled++
          }
          const repeats = sampled - sample.size
          const worthRanking = stride === 1 ? sample.size <= rankLimit : repeats * n >= sampled * sampled
          if (worthRanking) idOf = new Map()
        }

        // One hash per row: the value's id is looked up (or assigned) as the
        // row is read, and the rank lookup further down is an array read by
        // id. It used to add every value to a Set and then look every value up
        // again in a rank Map, two hashes per row.
        const ids: Int32Array | null = idOf ? new Int32Array(n) : null
        for (let i = 0; i < n; i++) {
          const s = autoTextKey(rows[i]!.getCellValueByColumnId(columnId))
          strings[i] = s
          if (idOf) {
            let id = idOf.get(s)
            if (id === undefined) {
              id = idOf.size
              idOf.set(s, id)
              if (idOf.size > rankLimit) {
                idOf = null
                continue
              }
            }
            ids![i] = id
          }
        }

        // Collation is by far the most expensive comparison we do - a CPU
        // profile of a 100k text sort put 65% of the whole operation inside the
        // collator. But a column's DISTINCT values are usually far fewer than
        // its rows (statuses, regions, categories, owners), so rank the
        // distinct values once and sort by rank afterwards. That turns
        // O(n log n) collator calls into O(u log u), where u is the number of
        // distinct values, and the resulting order is identical because rank is
        // a monotone relabelling of the collated order - equal strings share a
        // rank, so ties still fall through to the stable sort exactly as before.
        //
        // Guarded on the uniqueness ratio: when nearly every value is distinct
        // the ranking pass cannot save any collator calls and would just add an
        // O(n) Map build, so that case keeps comparing directly.
        if (idOf) {
          // Map keys come back in insertion order, which is id order.
          const values = Array.from(idOf.keys())
          const byRank = values.map((_, id) => id).sort((a, b) => compareCollatedKeys(values[a]!, values[b]!))
          const rankById = new Int32Array(values.length)
          for (let r = 0; r < byRank.length; r++) rankById[byRank[r]!] = r
          for (let i = 0; i < n; i++) keys[i] = rankById[ids![i]!]!
          const rankIds = idOf
          rankCount = values.length
          compare = compareNumericKeys
          // A replacement whose text is not among the ranked values has no
          // rank; the repair path treats that as "sort everything again".
          keyOf = (row) => {
            const value = row.getCellValueByColumnId(columnId)
            // A number arriving in a tick makes the column mixed; resort fully.
            if (typeof value === 'number') return MISSING_KEY
            const id = rankIds.get(autoTextKey(value))
            return id === undefined ? MISSING_KEY : rankById[id]!
          }
        } else {
          keys = strings
          compare = compareCollatedKeys
          keyOf = (row) => {
            const value = row.getCellValueByColumnId(columnId)
            return typeof value === 'number' ? MISSING_KEY : autoTextKey(value)
          }
        }
      } else {
        keyOf = (row) => row.getCellValueByColumnId(columnId)
        for (let i = 0; i < n; i++) keys[i] = keyOf(rows[i]!)
        compare = comparator
      }

      clauses.push({ keys, desc: clause.desc, compare, keyOf, rankCount })
    }

    if (!clauses.length) return null

    // Sort an index array, then materialise. `Array.prototype.sort` is stable,
    // so equal keys keep their original relative order exactly as the previous
    // `[...rows].sort(...)` did.
    // An index array the comparator sorts in place, or a typed array from
    // countingOrder / radixOrder for a large one-column numeric sort.
    let order: ArrayLike<number> = new Array<number>(rows.length)
    for (let i = 0; i < order.length; i++) (order as number[])[i] = i

    // Single-clause sorts get a specialised comparator.
    //
    // Most sorts are one column, and that path runs O(n log n) times - 1.66
    // million comparisons for 100k rows. The general loop pays a clause-array
    // index, three property loads and an indirect call on every one of them,
    // none of which vary once the clause list is fixed. Hoisting them into a
    // closure and, for the numeric comparator, inlining the subtraction removes
    // the call entirely.
    //
    // `keys[ib] - keys[ia]` for descending is exactly `-(keys[ia] - keys[ib])`
    // as far as sorting is concerned: both are NaN for unorderable values,
    // which the spec coerces to 0, and they differ only in producing 0 versus
    // -0 for equal keys, which sorts identically.
    if (clauses.length === 1) {
      const { keys, compare, desc, rankCount } = clauses[0]!
      if (rankCount !== undefined && rows.length >= STABLE_NUMERIC_SORT_MIN) {
        order = countingOrder(keys as number[], rankCount, desc)
      } else if (compare === compareNumericKeys && rows.length >= STABLE_NUMERIC_SORT_MIN) {
        order = radixOrder(keys as number[], desc)
      } else if (compare === compareNumericKeys) {
        ;(order as number[]).sort(
          desc
            ? function compareOneNumericDesc(ia, ib) { return keys[ib] - keys[ia] }
            : function compareOneNumericAsc(ia, ib) { return keys[ia] - keys[ib] },
        )
      } else {
        ;(order as number[]).sort(
          desc
            ? function compareOneDesc(ia, ib) { return -compare(keys[ia], keys[ib]) }
            : function compareOneAsc(ia, ib) { return compare(keys[ia], keys[ib]) },
        )
      }
    } else {
      ;(order as number[]).sort(function compareRowsByClauses(ia, ib) {
        for (let k = 0; k < clauses.length; k++) {
          const clause = clauses[k]!
          const result = clause.compare(clause.keys[ia], clause.keys[ib])
          if (result !== 0) return clause.desc ? -result : result
        }
        return 0
      })
    }

    const sorted = new Array<Row<TData>>(rows.length)
    for (let i = 0; i < order.length; i++) sorted[i] = rows[order[i]!]!
    // Each row keeps its key(s), so a later tick can place a replacement
    // among the kept rows without reading any of them again. One property
    // write per row; an array per row only when there are several clauses.
    if (clauses.length === 1) {
      const keys = clauses[0]!.keys
      for (let i = 0; i < rows.length; i++) (rows[i] as any)[ROW_SORT_KEY] = keys[i]
    } else {
      for (let i = 0; i < rows.length; i++) {
        const per = new Array(clauses.length)
        for (let k = 0; k < clauses.length; k++) per[k] = clauses[k]!.keys[i]
        ;(rows[i] as any)[ROW_SORT_KEY] = per
      }
    }
    return { sorted, clauses: clauses.map(({ desc, compare, keyOf }) => ({ desc, compare, keyOf })) }
  }

  /**
   * The previous output with the replaced rows swapped for their
   * replacements, in sorted position. Null when the input is not the cached
   * input plus replacements, or a replacement has no incremental key.
   *
   * Every row carries the key(s) the last full sort computed for it
   * (ROW_SORT_KEY: the key itself for one clause, an array for several), so
   * the merge moves row references and nothing else. At 100k rows the loop
   * that also copied an aligned key array cost 3.7 ms; this one is the
   * reference copy alone.
   */
  function repair(rows: Array<Row<TData>>, replaced: ReadonlyMap<Row<any>, Row<any>>) {
    const c = cache!
    if (rows.length !== c.input.length) return null
    // Which rows of THIS stage's input changed. The map may name rows a
    // stage upstream filtered out; only the ones that reach here matter.
    const dropGen = ++sortDropGeneration
    const added: Array<Row<TData>> = []
    for (let i = 0; i < rows.length; i++) {
      const prev = c.input[i]!
      const next = rows[i]!
      if (next === prev) continue
      if (replaced.get(prev) !== next) return null
      ;(prev as any)[ROW_SORT_DROPPED] = dropGen
      added.push(next)
    }
    if (!added.length) return c.output

    const clauses = c.clauses
    const single = clauses.length === 1
    for (let j = 0; j < added.length; j++) {
      const row = added[j]! as any
      if (single) {
        const key = clauses[0]!.keyOf(row)
        if (key === MISSING_KEY) return null
        row[ROW_SORT_KEY] = key
      } else {
        const keys = new Array(clauses.length)
        for (let k = 0; k < clauses.length; k++) {
          const key = clauses[k]!.keyOf(row)
          if (key === MISSING_KEY) return null
          keys[k] = key
        }
        row[ROW_SORT_KEY] = keys
      }
    }

    // Keys first, then the data index: the tie-break a stable sort over
    // data-ordered input applies, so the merge lands where a full sort would.
    const prevOut = c.output
    const compareRows = single
      ? (() => {
          const { compare, desc } = clauses[0]!
          return (a: Row<TData>, b: Row<TData>) => {
            const r = compare((a as any)[ROW_SORT_KEY], (b as any)[ROW_SORT_KEY])
            if (r !== 0) return desc ? -r : r
            return a.index - b.index
          }
        })()
      : (a: Row<TData>, b: Row<TData>) => {
          const ka = (a as any)[ROW_SORT_KEY]
          const kb = (b as any)[ROW_SORT_KEY]
          for (let k = 0; k < clauses.length; k++) {
            const clause = clauses[k]!
            const r = clause.compare(ka[k], kb[k])
            if (r !== 0) return clause.desc ? -r : r
          }
          return a.index - b.index
        }

    // Sort the replacements among themselves (k log k)...
    added.sort(compareRows)

    // ...find where each one goes in the previous output by binary search
    // (k log n comparisons, against the dropped rows too - they are skipped
    // below, which does not move an insertion point)...
    const n = prevOut.length
    const insertAt = new Array<number>(added.length)
    let lo = 0
    for (let j = 0; j < added.length; j++) {
      // Monotone: the replacements are sorted, so each search starts where
      // the previous one landed.
      const row = added[j]!
      let hi = n
      while (lo < hi) {
        const mid = (lo + hi) >>> 1
        if (compareRows(row, prevOut[mid]!) < 0) hi = mid
        else lo = mid + 1
      }
      insertAt[j] = lo
    }

    // ...then one linear pass that only moves references.
    const out = new Array<Row<TData>>(rows.length)
    let w = 0
    let j = 0
    let nextInsert = insertAt[0] ?? -1
    for (let i = 0; i < n; i++) {
      while (nextInsert === i) {
        out[w++] = added[j++]!
        nextInsert = j < added.length ? insertAt[j]! : -1
      }
      const prev = prevOut[i]!
      if ((prev as any)[ROW_SORT_DROPPED] === dropGen) continue
      out[w++] = prev
    }
    while (j < added.length) out[w++] = added[j++]!
    return out
  }

  return function sortedRowModelStage({ table, rows }) {
    const sorting = table.getState().sorting ?? []
    if (!sorting.length) {
      cache = null
      return rows
    }
    const columns = table.getAllColumns()

    if (cache && cache.sorting === sorting && cache.columns === columns) {
      if (cache.input === rows) return cache.output
      const replaced = replacedRowsOf(table)
      if (replaced) {
        const repaired = repair(rows, replaced)
        if (repaired) {
          cache = { ...cache, input: rows, output: repaired }
          return repaired
        }
      }
    }

    const full = fullSort(rows, sorting, columns)
    if (!full) {
      cache = null
      return rows
    }
    cache = { input: rows, output: full.sorted, sorting, columns, clauses: full.clauses }
    return full.sorted
  }
}

export function createSvGridCore<TFeatures extends TableFeatures, TData extends RowData>(
  options: SvGridOptions<TFeatures, TData>,
): SvGrid<TData> {
  const internalState: Record<string, any> = {
    sorting: [],
    columnFilters: [],
    pagination: { pageIndex: 0, pageSize: options.data.length || 10 },
    grouping: [],
    expanded: {},
    rowSelection: {},
    activeCell: { rowIndex: 0, colIndex: 0, cellId: null },
    ...(options.state ?? {}),
  }
  const store = createStore(internalState)
  const optionsStore = createStore(options as Record<string, any>)
  let cachedColumnsInput: Array<ColumnDef<TFeatures, TData>> | null = null
  let cachedColumns: Array<Column<TData>> = []
  let cachedHeaderGroups: Array<HeaderGroup<TData>> = []
  let cachedBaseRowsInput: ReadonlyArray<TData> | null = null
  let cachedBaseRowsColumns: Array<Column<TData>> | null = null
  let cachedBaseRows: Array<Row<TData>> = []
  /** Old row -> new row for the rebuild the next pipeline run follows; see `replacedRowsOf`. */
  let replacedRows: Map<Row<TData>, Row<TData>> | null = null
  let cachedRowCtx: BaseRowCtx<TData> | null = null
  /** This grid's windowed-data row model, made on first use from the installed hook. */
  let windowedRowModel: WindowedRowModel<TData> | null = null

  /** The shared row context for `columns`, reused while they are the same. */
  function rowCtxFor(columns: Array<Column<TData>>): BaseRowCtx<TData> {
    if (cachedRowCtx && cachedRowCtx.columns === columns) return cachedRowCtx
    const columnIndexById = new Map<string, number>()
    for (let i = 0; i < columns.length; i++) columnIndexById.set(columns[i]!.id, i)
    cachedRowCtx = {
      grid: grid as SvGrid<TData>,
      store,
      columns,
      columnCount: columns.length,
      columnIndexById,
    }
    return cachedRowCtx
  }

  let cachedRowModel: RowModel<TData> | null = null
  let cachedRowModelBaseRows: Array<Row<TData>> | null = null
  let cachedPipeline = options._rowModels
  let cachedSlices: {
    sorting: SortingState | undefined
    columnFilters: ColumnFiltersState | undefined
    pagination: PaginationState | undefined
    grouping: GroupingState | undefined
    expanded: ExpandedState | undefined
  } | null = null

  const grid = {
    store,
    optionsStore,
    get state() {
      return store.state
    },
    getState() {
      return store.state
    },
    setOptions(updater: Updater<Record<string, any>>) {
      optionsStore.setState((prev) =>
        typeof updater === 'function' ? (updater as any)(prev) : updater,
      )
    },
    setColumnFilters(updater: Updater<ColumnFiltersState>) {
      store.setState((prev) => ({
        ...prev,
        columnFilters:
          typeof updater === 'function' ? (updater as any)(prev.columnFilters ?? []) : updater,
      }))
      options.onColumnFiltersChange?.(updater)
    },
    setPagination(updater: Updater<PaginationState>) {
      store.setState((prev) => ({
        ...prev,
        pagination:
          typeof updater === 'function'
            ? (updater as any)(prev.pagination ?? { pageIndex: 0, pageSize: 10 })
            : updater,
      }))
      options.onPaginationChange?.(updater)
    },
    setGrouping(updater: Updater<GroupingState>) {
      store.setState((prev) => ({
        ...prev,
        grouping: typeof updater === 'function' ? (updater as any)(prev.grouping ?? []) : updater,
      }))
      options.onGroupingChange?.(updater)
    },
    setExpanded(updater: Updater<ExpandedState>) {
      store.setState((prev) => ({
        ...prev,
        expanded: typeof updater === 'function' ? (updater as any)(prev.expanded ?? {}) : updater,
      }))
      options.onExpandedChange?.(updater)
    },
    setRowSelection(updater: Updater<RowSelectionState>) {
      store.setState((prev) => ({
        ...prev,
        rowSelection:
          typeof updater === 'function' ? (updater as any)(prev.rowSelection ?? {}) : updater,
      }))
      options.onRowSelectionChange?.(updater)
    },
    setActiveCell(updater: Updater<ActiveCellState>) {
      store.setState((prev) => {
        const previous: ActiveCellState = prev.activeCell ?? {
          rowIndex: 0,
          colIndex: 0,
          cellId: null,
        }
        const nextActive =
          typeof updater === 'function' ? updater(previous) : updater
        return {
          ...prev,
          activeCell: nextActive,
        }
      })
      options.onActiveCellChange?.(updater)
    },
    moveActiveCell(next: { rowDelta?: number; colDelta?: number }) {
      const rows = grid.getRowModel().rows
      const columns = grid.getAllColumns()
      const maxRow = Math.max(rows.length - 1, 0)
      const maxCol = Math.max(columns.length - 1, 0)
      const current: ActiveCellState = grid.getState().activeCell ?? {
        rowIndex: 0,
        colIndex: 0,
        cellId: null,
      }

      const rowIndex = Math.min(
        Math.max(current.rowIndex + (next.rowDelta ?? 0), 0),
        maxRow,
      )
      const colIndex = Math.min(
        Math.max(current.colIndex + (next.colDelta ?? 0), 0),
        maxCol,
      )
      const columnId = columns[colIndex]?.id ?? 'col_0'
      grid.setActiveCell({
        rowIndex,
        colIndex,
        cellId: `${rowIndex}_${columnId}`,
      })
    },
    getAllColumns() {
      // Cache hit: referentially identical columns array.
      if (cachedColumnsInput === options.columns && cachedColumns.length) {
        return cachedColumns
      }
      // Soft cache hit: consumers commonly recreate the columns array
      // inline on every render (e.g. `columns={[...]}`). If the new
      // array has the same length AND each entry has the same `field` /
      // `id` / `header` (the visibility-affecting structure of a
      // column), keep the previous build but point each column at its new
      // definition, so a changed `cell`, `sortable` or `editorOptions`
      // takes effect.
      if (
        cachedColumnsInput &&
        options.columns.length === cachedColumnsInput.length &&
        cachedColumns.length === options.columns.length &&
        options.columns.every((c, i) => {
          const prev = cachedColumnsInput![i]!
          return (
            c.field === prev.field &&
            c.id === prev.id &&
            c.header === prev.header &&
            c.editorType === prev.editorType &&
            // A field's options and format live in fieldProps; a reused
            // column would keep drawing the old ones.
            c.fieldType === prev.fieldType &&
            c.fieldProps === prev.fieldProps
          )
        })
      ) {
        // Update the stored input reference so the strict check hits
        // next time, but reuse the built column model.
        cachedColumnsInput = options.columns
        // Only without groups: a group of one child also passes the length
        // check, and its leaf must not take the group's definition.
        if (!options.columns.some((c) => c.columns?.length)) cachedColumns.forEach((c, i) => (c.columnDef = options.columns[i]!))
        return cachedColumns
      }

      cachedColumnsInput = options.columns
      cachedHeaderGroups = []
      const build = (
        defs: Array<ColumnDef<TFeatures, TData>>,
        depth: number,
        parentId?: string,
      ): Array<Column<TData>> => {
        const leaves: Array<Column<TData>> = []
        defs.forEach((columnDef, index) => {
          const id = resolveColumnId(columnDef, parentId, depth, index)
          if (columnDef.columns?.length) {
            leaves.push(...build(columnDef.columns, depth + 1, id))
            return
          }
          // The closures read `col.columnDef`, not the `columnDef` above: a
          // soft cache hit repoints the column at a newer definition.
          const col: Column<TData> = {
            id,
            depth,
            parentId,
            columnDef,
            getCanSort: () =>
              Boolean((options._features as any).rowSortingFeature) &&
              col.columnDef.sortable !== false,
            getCanFilter: () =>
              Boolean((options._features as any).columnFilteringFeature) &&
              col.columnDef.filterable !== false,
            getIsSorted: () => {
              const entry = store.state.sorting?.find((s: any) => s.id === id)
              if (!entry) return false
              return entry.desc ? 'desc' : 'asc'
            },
            getToggleSortingHandler: () => () => {
              const clauses: SortingState = store.state.sorting ?? []
              const current = clauses.find((s: any) => s.id === id)
              const nextClause: SortingState = !current
                ? [...clauses, { id, desc: false }]
                : current.desc
                  ? clauses.filter((s) => s.id !== id)
                  : clauses.map((s) => (s.id === id ? { ...s, desc: true } : s))
              store.setState((prev) => ({ ...prev, sorting: nextClause }))
              options.onSortingChange?.(nextClause)
            },
          }
          leaves.push(col)
        })
        return leaves
      }
      cachedColumns = build(options.columns, 0)
      return cachedColumns
    },
    getHeaderGroups() {
      if (cachedHeaderGroups.length) return cachedHeaderGroups
      const headers = grid.getAllColumns().map((column) => {
        const header: Header<TData> = {
          id: column.id,
          isPlaceholder: false,
          colSpan: 1,
          column,
          getContext: () => ({ header, column, table: grid }),
        }
        return header
      })
      cachedHeaderGroups = [{ id: 'header_group_0', headers }]
      return cachedHeaderGroups
    },
    getFooterGroups() {
      return grid.getHeaderGroups()
    },
    getRowModel() {
      const columns = grid.getAllColumns()
      // Read once. `options.data` is a getter when <SvGrid> drives the engine
      // (a $state.raw signal), and the rebuild below touched it twice per row:
      // 200k tracked reads per 100k-row tick, 11 ms of a 65 ms tick.
      const data = options.data
      if (installWindowedRowModel) {
        windowedRowModel ??= installWindowedRowModel<TData>({ rowCtxFor, getRowId: () => options.getRowId })
        const model = windowedRowModel(data, columns)
        if (model) return model
      }
      if (cachedBaseRowsInput !== data || cachedBaseRowsColumns !== columns) {
        // Same columns as last time: the shared context still describes them,
        // and a row whose data object sits at the same index can keep its
        // row object. A row model that streams blocks hands the grid a new
        // array of 60k entries per block where 100 changed; building 60k
        // fresh row objects each time was most of the cost of a block
        // landing. The reused row drops its memoised values and cells, since
        // an app may have changed the object in place before passing a new
        // array - that is the case the old rebuild covered by accident.
        // A lazy row list (lazyRows below) is read through its backing array,
        // so reusing rows never makes the ones nobody looked at.
        const previous = cachedBaseRowsColumns === columns && cachedRowCtx ? (lazyRowsBacking(cachedBaseRows) ?? cachedBaseRows) : null
        const previousInput = cachedBaseRowsInput
        // Same length as last time: a replacement, not an add or remove, so
        // each new row stands in for the old row at its index and the stages
        // can repair rather than recompute. Anything else is structural.
        replacedRows = previous && previous.length === data.length ? new Map() : null
        cachedBaseRowsInput = data
        cachedBaseRowsColumns = columns
        // O(1) column-id → index lookup so getCellValueByColumnId doesn't do
        // a linear `findIndex` on every cell read (was O(rows × cells × cols)).
        let rowCtx: BaseRowCtx<TData>
        if (previous && cachedRowCtx) {
          rowCtx = cachedRowCtx
        } else {
          const columnIndexById = new Map<string, number>()
          for (let i = 0; i < columns.length; i++) columnIndexById.set(columns[i]!.id, i)
          // One shared context for every row in this table, so a row carries a
          // pointer rather than a closure scope. See BASE_ROW_METHODS.
          rowCtx = {
            grid: grid as SvGrid<TData>,
            store,
            columns,
            columnCount: columns.length,
            columnIndexById,
          }
          cachedRowCtx = rowCtx
        }

        const getRowId = options.getRowId
        const m = BASE_ROW_METHODS as unknown as {
          getCanExpand: Row<TData>['getCanExpand']
          getIsExpanded: Row<TData>['getIsExpanded']
          toggleExpanded: Row<TData>['toggleExpanded']
          getIsSelected: Row<TData>['getIsSelected']
          toggleSelected: Row<TData>['toggleSelected']
          getAllCells: Row<TData>['getAllCells']
          getCellValueByColumnId: Row<TData>['getCellValueByColumnId']
        }
        // `_values` and `_cells` stay null until something reads them - a
        // 100k-row grid showing twenty rows must not materialise every row's
        // values or cell objects to paint.
        const makeRow = (index: number): BaseRowState<TData> => {
          const original = data[index]!
          return {
            id: getRowId ? getRowId(original, index) : String(index),
            index,
            original,
            depth: 0,
            [ROW_CTX]: rowCtx,
            [ROW_VALUES]: null,
            [ROW_CELLS]: null,
            [ROW_FILTER_GEN]: 0,
            [ROW_FILTER_POS]: -1,
            [ROW_SORT_DROPPED]: 0,
            [ROW_SORT_KEY]: undefined,
            getCanExpand: m.getCanExpand,
            getIsExpanded: m.getIsExpanded,
            toggleExpanded: m.toggleExpanded,
            getIsSelected: m.getIsSelected,
            toggleSelected: m.toggleSelected,
            getAllCells: m.getAllCells,
            getCellValueByColumnId: m.getCellValueByColumnId,
          }
        }
        if (!previous) {
          // A first build has nothing to reuse or repair: make each row the
          // first time something reads it. A grid that only shows the first
          // screen makes ~40 row objects, not 100k; a sort or a filter reads
          // every row and makes them then. Building them all up front was
          // most of a 100k-row mount (~24 ms, plus the garbage).
          cachedBaseRows = lazyRows(data.length, makeRow)
        } else cachedBaseRows = new Array(data.length)
        for (let index = 0; previous && index < data.length; index++) {
          const original = data[index]!
          const kept = previous[index] as BaseRowState<TData> | undefined
          if (kept && kept.original === original) {
            // Read before writing: a row nobody rendered (a million off-screen
            // placeholders under a row model) has nothing memoised, and a
            // store per row was a measurable share of each block landing.
            if (kept[ROW_VALUES] !== null) kept[ROW_VALUES] = null
            if (kept[ROW_CELLS] !== null) kept[ROW_CELLS] = null
            cachedBaseRows[index] = kept
            continue
          }
          // Past a quarter of the rows the merge stops being cheaper than a
          // sort with the ranking pass; let the stages do the full work.
          if (replacedRows && replacedRows.size * 4 >= data.length) replacedRows = null
          const row = makeRow(index)
          // The previous list was lazy and never made this row, but its data
          // object is the same one: hand the old list this row too, so a
          // caller still holding it gets the same object for the same data,
          // as when every row was built up front.
          if (kept === undefined && previousInput?.[index] === original) previous[index] = row
          cachedBaseRows[index] = row
          if (replacedRows && kept) replacedRows.set(kept, row)
        }
        // A new array with every object the same is the documented way to
        // say "I changed rows in place, re-read them" (docs/help/cells/
        // view-refresh.md). Nothing was replaced, so there is nothing to
        // repair around: the stages recompute from the current values. A
        // repair assumes the rows it keeps are unchanged in value as well as
        // identity, which is the immutable-update contract a tick follows.
        if (replacedRows && replacedRows.size === 0) replacedRows = null
      }

      // Only the slices a pipeline stage actually READS belong in this key.
      //
      // `rowSelection` used to be here, which meant ticking one checkbox on a
      // 100k-row grid re-filtered and re-sorted the entire dataset to rebuild a
      // row array that was identical by construction. Nothing reads it: the two
      // consumers are `getIsSelected` closures (on data rows and on group rows)
      // that read `store.state` when called, so they observe a selection change
      // without the model being rebuilt.
      //
      // `_rowModels` is a closed set of six named slots, so no consumer stage
      // can be inserted that might read selection. A caller CAN supply a custom
      // function for one of those slots; if one ever needs a slice that is not
      // listed here, add it here rather than reinstating all of them.
      const currentSlices = {
        sorting: store.state.sorting,
        columnFilters: store.state.columnFilters,
        pagination: store.state.pagination,
        grouping: store.state.grouping,
        expanded: store.state.expanded,
      }
      if (
        cachedRowModel &&
        cachedRowModelBaseRows === cachedBaseRows &&
        cachedPipeline === options._rowModels &&
        cachedSlices?.sorting === currentSlices.sorting &&
        cachedSlices?.columnFilters === currentSlices.columnFilters &&
        cachedSlices?.pagination === currentSlices.pagination &&
        cachedSlices?.grouping === currentSlices.grouping &&
        cachedSlices?.expanded === currentSlices.expanded
      ) {
        return cachedRowModel
      }

      // A stage with work to do reads every row; give it the dense array.
      const anyStageActive =
        (currentSlices.sorting?.length ?? 0) > 0 ||
        (currentSlices.columnFilters?.length ?? 0) > 0 ||
        (currentSlices.grouping?.length ?? 0) > 0 ||
        (currentSlices.expanded as unknown) === true ||
        Object.keys(currentSlices.expanded ?? {}).length > 0
      let rows: Array<Row<TData>> = anyStageActive ? denseRows(cachedBaseRows) : cachedBaseRows

      const pipeline = options._rowModels ?? {}
      const ordered: Array<RowModelFactory<TData> | undefined> = [
        pipeline.coreRowModel,
        pipeline.filteredRowModel,
        pipeline.sortedRowModel,
        pipeline.groupedRowModel,
        pipeline.expandedRowModel,
        pipeline.paginatedRowModel,
      ]
      // The stages read the replacements through `replacedRowsOf` while the
      // run lasts; a stage that runs outside one sees null.
      replacedRowsByGrid.set(grid, replacedRows)
      try {
        ordered.forEach((fn) => {
          if (fn) rows = fn({ table: grid, rows })
        })
      } finally {
        replacedRowsByGrid.set(grid, null)
        replacedRows = null
      }
      cachedPipeline = options._rowModels
      cachedSlices = currentSlices
      cachedRowModelBaseRows = cachedBaseRows
      cachedRowModel = { rows }
      return cachedRowModel
    },
  } as InternalGrid<TData>

  return grid
}

export function createTree(config: TreeConfig) {
  const nodes = () => config.nodes()
  const checkable = () => config.checkable?.() ?? false
  const selected = () => config.selected?.() ?? null

  // Internal expanded set, seeded from the prop once (then self-managed).
  let expanded = $state<Set<string>>(new Set())
  let seeded = false
  $effect(() => {
    if (!seeded) { seeded = true; const ids = config.expandedIds?.(); if (ids) expanded = new Set(ids) }
  })

  // When filtering, precompute which nodes to show (a match, or an ancestor of a
  // match) and which to force-open so matches are revealed.
  const filterInfo = $derived.by(() => {
    const q = config.filter?.()?.trim().toLowerCase()
    if (!q) return null
    const visible = new Set<string>()
    const forceOpen = new Set<string>()
    const walk = (node: TreeNode): boolean => {
      let childMatch = false
      for (const c of node.children ?? []) childMatch = walk(c) || childMatch
      const selfMatch = node.label.toLowerCase().includes(q)
      if (selfMatch || childMatch) { visible.add(node.id); if (childMatch) forceOpen.add(node.id) }
      return selfMatch || childMatch
    }
    for (const n of nodes()) walk(n)
    return { visible, forceOpen }
  })

  const rows = $derived.by<TreeRow[]>(() => {
    const out: TreeRow[] = []
    const fi = filterInfo
    const walk = (list: ReadonlyArray<TreeNode>, depth: number, parentId: string | null) => {
      for (const node of list) {
        if (fi && !fi.visible.has(node.id)) continue
        const hasChildren = !!node.children?.length || !!node.lazy
        const open = fi ? fi.forceOpen.has(node.id) || expanded.has(node.id) : expanded.has(node.id)
        out.push({ node, depth, hasChildren, open, parentId, index: out.length })
        if (open && node.children?.length) walk(node.children, depth + 1, node.id)
      }
    }
    walk(nodes(), 0, null)
    return out
  })

  let active = $state(0)
  $effect(() => { if (active >= rows.length) active = Math.max(0, rows.length - 1) })

  const checkedSet = $derived(new Set(config.checked?.() ?? []))

  // Roving focus target; `focusTick` bumps only on keyboard moves.
  let focusTick = $state(0)
  function setActive(i: number, focus = false) { active = i; if (focus) focusTick++ }

  const checkStateOf = (node: TreeNode): CheckState => treeCheckState(node, checkedSet)
  const isExpanded = (id: string) => expanded.has(id)
  const isSelected = (id: string) => id === selected()

  function toggleExpand(node: TreeNode) {
    // Lazy nodes have no children *yet* - they must still be expandable so the
    // toggle fires onToggle and the host can fetch children on demand.
    if (!node.children?.length && !node.lazy) return
    const next = new Set(expanded)
    const willOpen = !next.has(node.id)
    willOpen ? next.add(node.id) : next.delete(node.id)
    expanded = next
    config.onToggle?.(node.id, willOpen)
  }
  const toggle = (id: string) => { const n = findNode(nodes(), id); if (n) toggleExpand(n) }

  function select(node: TreeNode) {
    if (node.disabled) return
    config.onSelect?.(node.id)
  }
  const selectId = (id: string) => { const n = findNode(nodes(), id); if (n) select(n) }

  function toggleCheck(node: TreeNode) {
    if (node.disabled) return
    const next = new Set(checkedSet)
    const ids = [node.id, ...treeDescendantIds(node)]
    const currentlyOn = checkStateOf(node) === 'checked'
    for (const id of ids) currentlyOn ? next.delete(id) : next.add(id)
    config.onCheck?.([...next])
  }

  // Step from `from` towards `dir` (+1/-1), skipping disabled rows, so roving
  // focus never lands on a node with zero semantic affordance for AT users.
  // Falls back to `from` if every row in that direction is disabled.
  function stepEnabled(from: number, dir: 1 | -1): number {
    let i = from
    while (i + dir >= 0 && i + dir <= rows.length - 1) {
      i += dir
      if (!rows[i]?.node.disabled) return i
    }
    return from
  }

  function onKeydown(e: KeyboardEvent) {
    const item = rows[active]
    if (!item) return
    // "expand" opens the node or steps into the first child; "collapse" closes it
    // or jumps to the parent. Under RTL the physical Left/Right keys are swapped.
    const expand = () => {
      if (item.hasChildren && !item.open) toggleExpand(item.node)
      else if (item.hasChildren && item.open) setActive(Math.min(active + 1, rows.length - 1), true)
    }
    const collapse = () => {
      if (item.hasChildren && item.open) toggleExpand(item.node)
      else if (item.parentId) { const pi = rows.findIndex((r) => r.node.id === item.parentId); if (pi >= 0) setActive(pi, true) }
    }
    const rtl = config.dir?.() === 'rtl'
    switch (e.key) {
      case 'ArrowDown': e.preventDefault(); setActive(stepEnabled(active, 1), true); break
      case 'ArrowUp': e.preventDefault(); setActive(stepEnabled(active, -1), true); break
      case 'ArrowRight': e.preventDefault(); (rtl ? collapse : expand)(); break
      case 'ArrowLeft': e.preventDefault(); (rtl ? expand : collapse)(); break
      case 'Enter': e.preventDefault(); select(item.node); break
      case ' ': e.preventDefault(); checkable() ? toggleCheck(item.node) : select(item.node); break
      case 'Home': e.preventDefault(); setActive(0, true); break
      case 'End': e.preventDefault(); setActive(rows.length - 1, true); break
    }
  }

  return {
    /** Internally-managed set of expanded node ids. */
    get expanded() { return expanded },
    /** Selected node id (single-select highlight). */
    get selected() { return selected() },
    /** Flattened list of visible rows. */
    get rows() { return rows },
    /** Roving-focus row index. */
    get activeIndex() { return active },
    /** Monotonic counter; changes only on keyboard navigation. */
    get focusTick() { return focusTick },
    isExpanded,
    isSelected,
    checkStateOf,
    toggle,
    toggleExpand,
    select: selectId,
    toggleCheck,
    setActive,
    onKeydown,
    /** Spread onto the tree container element. */
    treeProps: () => ({
      role: 'tree' as const,
      'aria-label': config.ariaLabel?.(),
      'aria-multiselectable': checkable(),
    }),
    /** Spread onto the treeitem element for a flattened `row`. */
    itemProps: (row: TreeRow) => {
      const cs = checkable() ? checkStateOf(row.node) : 'unchecked'
      const ariaChecked: 'true' | 'mixed' | 'false' | undefined =
        checkable() ? (cs === 'checked' ? 'true' : cs === 'indeterminate' ? 'mixed' : 'false') : undefined
      return {
        role: 'treeitem' as const,
        'aria-level': row.depth + 1,
        'aria-selected': row.node.id === selected(),
        'aria-expanded': row.hasChildren ? row.open : undefined,
        'aria-checked': ariaChecked,
        'aria-disabled': row.node.disabled || undefined,
        'data-row': row.index,
        tabindex: row.index === active ? 0 : -1,
        onclick: () => { setActive(row.index); select(row.node) },
        onkeydown: onKeydown,
      }
    },
  }
}

export function createTreeRowModel<TData extends RowData>(
  options: TreeRowModelOptions,
): RowModelFactory<TData> {
  const { parentField, idField = 'id' } = options
  return ({ table, rows }) => {
    if (!rows.length) return rows
    const keyOf = (row: Row<TData>) => (row.original as any)?.[idField]
    const parentOf = (row: Row<TData>) => (row.original as any)?.[parentField]

    const present = new Set<unknown>()
    for (const row of rows) present.add(keyOf(row))

    const childrenByParent = new Map<unknown, Array<Row<TData>>>()
    const roots: Array<Row<TData>> = []
    for (const row of rows) {
      const parent = parentOf(row)
      // A row whose parent is absent (filtered out, or never existed) becomes a
      // root rather than disappearing - silently dropping rows is worse than a
      // shallower tree. Self-parenting is treated the same way.
      if (parent == null || parent === keyOf(row) || !present.has(parent)) {
        roots.push(row)
        continue
      }
      const list = childrenByParent.get(parent) ?? []
      list.push(row)
      childrenByParent.set(parent, list)
    }

    // Guards a cycle in the parent chain from recursing forever.
    const seen = new Set<unknown>()
    const build = (row: Row<TData>, depth: number): Row<TData> => {
      const key = keyOf(row)
      const id = row.id
      if (seen.has(key)) {
        return { ...row, depth, subRows: [], getCanExpand: () => false } as Row<TData>
      }
      seen.add(key)
      const subRows = (childrenByParent.get(key) ?? []).map((child) => build(child, depth + 1))
      return {
        ...row,
        depth,
        subRows,
        leafCount: subRows.reduce((n, sub) => n + 1 + (sub.leafCount ?? 0), 0),
        __treeRow: true,
        getCanExpand: () => subRows.length > 0,
        getIsExpanded: () => Boolean((table.getState().expanded ?? {})[id]),
        toggleExpanded: () => {
          table.setExpanded((prev) => ({ ...prev, [id]: !prev[id] }))
        },
      } as Row<TData>
    }

    return roots.map((root) => build(root, 0))
  }
}

export function createTypeaheadBuffer(timeout = 600) {
  let buffer = ''
  let timer: ReturnType<typeof setTimeout> | undefined
  return {
    get value() { return buffer },
    /** Append a character and (re)arm the reset timer. Returns the new buffer. */
    push(char: string): string {
      buffer += char
      if (timer) clearTimeout(timer)
      timer = setTimeout(() => { buffer = '' }, timeout)
      return buffer
    },
    clear() { buffer = ''; if (timer) clearTimeout(timer) },
  }
}

export type CustomFilterContext<TData extends RowData, TModel = any> = {
  column: Column<TData>
  /** The column's current model, or `undefined` when none is set. */
  model: TModel | undefined
  /** Replace the model. `null` or `undefined` clears the filter. */
  setModel: (next: TModel | null | undefined) => void
  /**
   * Which surface is rendering the control: the filter menu, the floating
   * filter row, or the tool panel's Filters tab.
   */
  surface: 'menu' | 'floating' | 'panel'
  /**
   * The column's distinct values under every OTHER column's filter, the
   * same list the menu's Values checklist shows. Computed on call, so a
   * control that never asks pays nothing.
   */
  values: () => Array<string>
  /** Close the filter menu. Does nothing on the other surfaces. */
  close: () => void
}

export type DayLayout<TData = unknown> = {
  events: PositionedEvent<TData>[]
  overflows: OverflowMarker<TData>[]
}

export function daysForView(view: SchedulerView, anchor: Date, weekStartsOn = 0): Date[] {
  if (view === 'day') return [startOfDay(anchor)]
  const start = startOfWeek(anchor, weekStartsOn)
  return Array.from({ length: 7 }, (_, i) => addDays(start, i))
}

export function daysInMonth(d: Date): number {
  return endOfMonth(d).getDate()
}

export function decadeRange(year: number): { start: number; end: number } {
  const start = Math.floor(year / 10) * 10
  return { start, end: start + 9 }
}

export function decimateSpec(spec: ChartSpec, plotW: number, cfg: ChartDecimateConfig | undefined = spec.decimate): ChartSpec {
  const opt = resolveDecimate(cfg, plotW)
  if (!opt) return spec
  const n = spec.categories.length
  if (n <= opt.threshold || !spec.series.length) return spec
  const lineLike = (t: string | undefined) => t === 'line' || t === 'area'
  if (!lineLike(spec.type) && !spec.series.every((s) => lineLike(s.type))) return spec
  if (spec.series.some((s) => (s.type && !lineLike(s.type)) || s.ohlc || s.boxes)) return spec
  // On a numeric axis the points sit where their values are, so the
  // triangles are measured in those positions (log10 of them on a log axis).
  const numeric = (spec.xAxis?.type ?? spec.xType) === 'number'
  const isLog = numeric && spec.xAxis?.scale === 'log'
  const xs = numeric
    ? spec.categories.map((c) => { const v = Number(c); return isLog ? (v > 0 ? Math.log10(v) : Number.NaN) : v })
    : undefined
  const keep = new Set<number>()
  for (const s of spec.series) {
    const idx = opt.method === 'minmax' ? minMaxIndices(s.values, Math.floor(opt.target / 2)) : lttb(s.values, opt.target, xs)
    for (const i of idx) keep.add(i)
  }
  const indices = [...keep].sort((a, b) => a - b)
  if (indices.length >= n) return spec
  return pickCategories(spec, indices)
}

export function dedupeManagerNodeIds(state: DockManagerState): DockManagerState {
  const seen = new Set<string>()
  let n = 1
  const fresh = (): string => { let id = `dm-d${n++}`; while (seen.has(id)) id = `dm-d${n++}`; return id }
  const uniq = (id: string): string => {
    const next = seen.has(id) ? fresh() : id
    seen.add(next)
    return next
  }
  const walk = (node: DockNode): DockNode => {
    const id = uniq(node.id)
    if (node.type === 'tabs') return id === node.id ? node : { ...node, id }
    const children = node.children.map(walk)
    const same = id === node.id && children.every((c, i) => c === node.children[i])
    return same ? node : { ...node, id, children }
  }
  const main = state.main ? walk(state.main) : state.main
  let floatChanged = false
  const floating = state.floating.map((w) => {
    const id = uniq(w.id)
    const leaf = walk(w.leaf) as DockTabs
    if (id === w.id && leaf === w.leaf) return w
    floatChanged = true
    return { ...w, id, leaf }
  })
  let hideChanged = false
  const autoHide = state.autoHide.map((e) => {
    const id = uniq(e.id)
    const leaf = walk(e.leaf) as DockTabs
    if (id === e.id && leaf === e.leaf) return e
    hideChanged = true
    return { ...e, id, leaf }
  })
  // Preserve identity when nothing was duplicated - keeps the effect that seeds
  // the manager from re-running and avoids needless re-renders.
  if (main === state.main && !floatChanged && !hideChanged) return state
  return { ...state, main, floating: floatChanged ? floating : state.floating, autoHide: hideChanged ? autoHide : state.autoHide }
}

