}

export type DockGroup = {
  type: 'group'
  id: string
  direction: 'row' | 'column'
  children: DockNode[]
  /** Size weight per child; parallel to `children`, normalized to sum ~1. */
  sizes: number[]
}

export function dockInto(
  root: DockNode,
  targetTabsId: string,
  movingPane: DockPane,
  zone: DockZone,
  genId: IdGen,
): DockNode {
  const dir: 'row' | 'column' = zone === 'left' || zone === 'right' ? 'row' : 'column'
  const before = zone === 'left' || zone === 'top'

  const transform = (node: DockNode): DockNode => {
    if (node.type === 'tabs') {
      if (node.id !== targetTabsId) return node
      if (zone === 'center') {
        const panes = [...node.panes, movingPane]
        return { ...node, panes, active: panes.length - 1 }
      }
      // Edge on a bare leaf: wrap it in a new group with the new leaf beside it.
      const leaf = tabs(genId, [movingPane], 0)
      const kids = before ? [leaf, node] : [node, leaf]
      return group(genId, dir, kids)
    }

    // Group: if it directly contains the target leaf and matches the edge
    // direction, insert a sibling in place (keeps the tree flat).
    const idx = node.children.findIndex((c) => c.type === 'tabs' && c.id === targetTabsId)
    if (idx >= 0 && zone !== 'center' && node.direction === dir) {
      const leaf = tabs(genId, [movingPane], 0)
      const children = node.children.slice()
      const sizes = node.sizes.slice()
      const half = (node.sizes[idx] ?? 1 / node.children.length) / 2
      const insertAt = before ? idx : idx + 1
      children.splice(insertAt, 0, leaf)
      sizes.splice(idx, 1, half, half) // split the target's slot in two
      // splice above replaced 1 with 2 at idx; the new leaf takes `before`/after
      if (before) {
        // children: [..., leaf, target, ...]; sizes already [half(leaf), half(target)]
      } else {
        // we inserted leaf AFTER target but sizes are [half, half] at idx/idx+1 - correct
      }
      return { ...node, children, sizes: normalizeSizes(sizes, children.length) }
    }

    return { ...node, children: node.children.map(transform) }
  }

  return normalize(transform(root)) ?? root
}

export function dockLeafToEdge(
  root: DockNode | null,
  leaf: DockTabs,
  side: Exclude<DockZone, 'center'>,
  genId: IdGen,
  fraction = 0.25,
): DockNode {
  if (!root) return leaf
  const dir: 'row' | 'column' = side === 'left' || side === 'right' ? 'row' : 'column'
  const before = side === 'left' || side === 'top'
  const f = Math.min(0.6, Math.max(0.1, fraction))
  const kids = before ? [leaf, root] : [root, leaf]
  const sizes = before ? [f, 1 - f] : [1 - f, f]
  return normalize(group(genId, dir, kids, sizes)) ?? leaf
}

export type DockManagerState = {
  main: DockNode | null
  floating: FloatWindow[]
  autoHide: AutoHideEntry[]
  /** A tiled leaf shown maximized (filling the docked area), or null. */
  maximizedLeaf?: string | null
}

export function dockPane(
  id: string,
  title: string,
  opts?: boolean | { closable?: boolean; minSize?: number },
): DockPane {
  const o = typeof opts === 'boolean' ? { closable: opts } : (opts ?? {})
  return { id, title, closable: o.closable ?? true, ...(o.minSize != null ? { minSize: o.minSize } : {}) }
}

export type DockPane = {
  id: string
  title: string
  /** Show a close (x) affordance on the tab. Default true. */
  closable?: boolean
  /** Minimum size (px) for this pane's leaf along the split axis. */
  minSize?: number
}

export function dockPaneOnto(
  state: DockManagerState,
  paneId: string,
  targetTabsId: string,
  zone: DockZone,
  genId: IdGen,
): DockManagerState {
  const moving = findPaneObject(state, paneId)
  if (!moving) return state
  const targetSurface = surfaceOfTabs(state, targetTabsId)
  if (!targetSurface) return state

  const stripped = stripPane(state, paneId)
  // The target leaf might have dissolved (it was the pane's own single leaf).
  if (surfaceOfTabs(stripped, targetTabsId) === null) return state

  if (targetSurface === 'main') {
    const base = stripped.main
    if (!base) return state
    return { ...stripped, main: dockInto(base, targetTabsId, moving, zone, genId) }
  }
  // Docking into a floating window: centre only (add as a tab).
  return {
    ...stripped,
    floating: stripped.floating.map((w) => {
      if (w.id !== targetSurface) return w
      const panes = [...w.leaf.panes, moving]
      return { ...w, leaf: { ...w.leaf, panes, active: panes.length - 1 } }
    }),
  }
}

export function dockPaneToEmptyMain(state: DockManagerState, paneId: string, genId: IdGen): DockManagerState {
  const moving = findPaneObject(state, paneId)
  if (!moving) return state
  const stripped = stripPane(state, paneId)
  if (stripped.main) return { ...stripped, main: stripped.main } // main not empty; caller should dock onto a leaf
  return { ...stripped, main: tabs(genId, [moving], 0) }
}

export function dockTabs(panes: DockPane[], active = 0): DockTabs {
  return tabs(autoId, panes, active)
}

export type DockTabs = {
  type: 'tabs'
  id: string
  panes: DockPane[]
  active: number
}

export function dockWindowOnto(
  state: DockManagerState,
  windowId: string,
  targetTabsId: string,
  zone: DockZone,
  genId: IdGen,
): DockManagerState {
  const win = state.floating.find((w) => w.id === windowId)
  if (!win) return state
  if (surfaceOfTabs(state, targetTabsId) !== 'main' || !state.main) return state
  const rest = state.floating.filter((w) => w.id !== windowId)
  if (zone === 'center') {
    return {
      ...state,
      floating: rest,
      main: state.main
        ? mergePanesInto(state.main, targetTabsId, win.leaf.panes)
        : state.main,
    }
  }
  // Edge: drop the window's whole leaf beside the target.
  const leaf = tabs(genId, win.leaf.panes, win.leaf.active)
  const dir = zone === 'left' || zone === 'right' ? 'row' : 'column'
  const before = zone === 'left' || zone === 'top'
  return {
    ...state,
    floating: rest,
    main: insertLeafBeside(state.main, targetTabsId, leaf, dir, before, genId),
  }
}

export function downloadChartCsv(spec: ChartSpec, filename = 'chart.csv'): boolean {
  const csv = chartSpecToCsv(spec)
  if (!csv) return false
  const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }))
  triggerDownload(url, filename)
  setTimeout(() => URL.revokeObjectURL(url), 1000)
  return true
}

export async function downloadChartPdf(source: SVGSVGElement | HTMLElement, filename = 'chart.pdf', options: ChartPdfOptions = {}): Promise<void> {
  const blob = await chartToPdfBlob(source, options)
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = filename
  document.body.appendChild(a)
  a.click()
  a.remove()
  setTimeout(() => URL.revokeObjectURL(url), 1000)
}

export async function downloadChartPng(
  source: SVGSVGElement | HTMLElement,
  filename = 'chart.png',
