): Promise<void> {
  const blob = await chartToPngBlob(source, options)
  const url = URL.createObjectURL(blob)
  triggerDownload(url, filename)
  setTimeout(() => URL.revokeObjectURL(url), 1000)
}

export function downloadChartSvg(
  source: SVGSVGElement | HTMLElement,
  filename = 'chart.svg',
  options: ChartExportOptions = {},
): void {
  const svg = chartToSvgString(source, options)
  const url = URL.createObjectURL(new Blob([svg], { type: 'image/svg+xml' }))
  triggerDownload(url, filename)
  setTimeout(() => URL.revokeObjectURL(url), 1000)
}

export function drillTree(tree: TreeNode, path: ReadonlyArray<string>): TreeNode | null {
  let node: TreeNode | undefined = tree
  for (const name of path) {
    node = node?.children?.find((c) => c.name === name)
    if (!node) return null
  }
  return node ?? null
}

