export function eventsOnDay<TData>(
  events: ReadonlyArray<ResolvedEvent<TData>>,
  day: Date,
): ResolvedEvent<TData>[] {
  const dayStart = startOfDay(day)
  const dayEnd = addDays(dayStart, 1)
  return events.filter((e) => rangesOverlap(e.start, e.end, dayStart, dayEnd))
}

