export function filterOptions(options: ReadonlyArray<ListOption>, query: string): ListOption[] {
  const q = query.trim().toLowerCase()
  if (!q) return [...options]
  return options.filter((o) => o.label.toLowerCase().includes(q))
}

export function findLeafById(state: DockManagerState, tabsId: string): DockTabs | null {
  const scan = (n: DockNode): DockTabs | null => {
    if (n.type === 'tabs') return n.id === tabsId ? n : null
    for (const c of n.children) { const hit = scan(c); if (hit) return hit }
    return null
  }
  if (state.main) { const m = scan(state.main); if (m) return m }
  const w = state.floating.find((f) => f.leaf.id === tabsId)
  if (w) return w.leaf
  const e = state.autoHide.find((x) => x.leaf.id === tabsId)
  return e ? e.leaf : null
}

export function findTabsWithPane(root: DockNode, paneId: string): DockTabs | null {
  if (root.type === 'tabs') return root.panes.some((p) => p.id === paneId) ? root : null
  for (const c of root.children) {
    const hit = findTabsWithPane(c, paneId)
    if (hit) return hit
  }
  return null
}

export function flattenForVirtual(
  options: ReadonlyArray<ListOption>,
  opts: { rowHeight: RowHeight; groupHeaderHeight?: number },
): FlatVirtualModel {
  const headerH = Math.max(1, opts.groupHeaderHeight ?? 28)
  const rh = opts.rowHeight
  const sizeOf = (o: IndexedOption) => Math.max(1, typeof rh === 'function' ? rh(o, o.index) : rh)

  const entries: VirtualListRow[] = []
  const optionFlatIndex = new Array<number>(options.length)
  let anyGroups = false

  for (const g of groupOptions(options)) {
    if (g.group != null) {
      anyGroups = true
      entries.push({ type: 'group', label: g.group, size: headerH })
    }
    for (const opt of g.options) {
      optionFlatIndex[opt.index] = entries.length
      entries.push({ type: 'option', opt, size: sizeOf(opt) })
    }
  }

  return {
    entries,
    hasGroups: anyGroups,
    sizeAt: (i) => entries[i]?.size ?? 0,
    optionFlatIndex,
  }
}

export function flattenTreeData<T extends RowData>(
  data: ReadonlyArray<T>,
  options: FlattenTreeOptions,
): T[] {
  const { childrenField, idField = 'id', parentField = '__parentId' } = options
  const out: T[] = []
  const walk = (nodes: ReadonlyArray<T>, parentId: unknown) => {
    for (const node of nodes) {
      const flat = { ...node, [parentField]: parentId } as T
      out.push(flat)
      const kids = (node as any)[childrenField]
      if (Array.isArray(kids) && kids.length) walk(kids as ReadonlyArray<T>, (node as any)[idField])
    }
  }
  walk(data, null)
  return out
}

export type FlattenTreeOptions = {
  /** Field holding an array of child objects. */
  childrenField: string
  /** Field holding each object's id. Defaults to `'id'`. */
  idField?: string
  /** Field to WRITE the resolved parent id onto. Defaults to `'__parentId'`. */
  parentField?: string
}

export type FlatVirtualModel = {
  /** Group headings + options in render order, each with its px height. */
  entries: VirtualListRow[]
  /** Whether any group heading rows are present. */
  hasGroups: boolean
  /** Height (px) of the entry at flat index `i` - feeds the virtualizer's `estimateSize`. */
  sizeAt: (i: number) => number
  /** Maps an OPTION index (position in the source options array, as used by
   *  `optionProps(index)`) to its flat entry index - so the active option can
   *  be scrolled into view even with group rows interleaved. */
  optionFlatIndex: number[]
}

export function floatPane(
  state: DockManagerState,
  paneId: string,
  rect: { x: number; y: number; width: number; height: number },
  genId: IdGen,
): DockManagerState {
  const moving = findPaneObject(state, paneId)
  if (!moving) return state
  const loc = locatePane(state, paneId)
  // Already the sole pane of its own float - nothing to pop out.
  if (loc?.kind === 'floating') {
    const w = state.floating.find((f) => f.id === loc.windowId)
    if (w && w.leaf.panes.length === 1) return state
  }
  const stripped = stripPane(state, paneId)
  const win: FloatWindow = {
    id: genId(),
    leaf: tabs(genId, [moving], 0),
    x: rect.x,
    y: rect.y,
    width: rect.width,
    height: rect.height,
    z: maxZ(state) + 1,
  }
  return { ...stripped, floating: [...stripped.floating, win] }
}

export type FloatWindow = {
  id: string
  leaf: DockTabs
  x: number
  y: number
  width: number
  height: number
  /** Stacking order; higher is on top. */
  z: number
  /** Collapsed to just its title bar. */
  minimized?: boolean
  /** Expanded to fill the manager (its x/y/w/h are kept for restore). */
  maximized?: boolean
}

export function formatChartValue(
  n: number,
  format?: ChartValueFormat,
  opts?: ChartFormatLocale,
): string {
  if (!Number.isFinite(n)) return ''
  const localized = opts && (opts.locale || opts.currency)
  if (localized) {
    // Compact notation because these are axis ticks and data labels, where a
    // full-precision number is what makes an axis unreadable.
    const style = format === 'currency' ? 'currency' : format === 'percent' ? 'percent' : 'decimal'
    const o: Intl.NumberFormatOptions = { notation: 'compact', maximumFractionDigits: 1 }
    if (style === 'currency') {
      o.style = 'currency'
      // `style: 'currency'` throws without a code, so fall back to the symbol
      // this used to hard-code rather than refusing to draw the chart.
      o.currency = opts!.currency || 'USD'
    } else if (style === 'percent') {
      o.style = 'percent'
    }
    return getNumberFormatter(opts!.locale, o).format(n)
  }
  if (format === 'currency') return `${n < 0 ? '-' : ''}$${fmtTick(Math.abs(n))}`
  if (format === 'percent') {
    const p = n * 100
    return `${Math.round(p * 10) / 10}%`
  }
  return fmtTick(n)
}

export function formatDuration(minutes: number, style: 'colon' | 'units' = 'colon'): string {
  if (!Number.isFinite(minutes) || minutes < 0) return ''
  const h = Math.floor(minutes / 60)
  const m = Math.round(minutes % 60)
  if (style === 'units') {
    if (h && m) return `${h}h ${m}m`
    if (h) return `${h}h`
    return `${m}m`
  }
  return `${h}:${String(m).padStart(2, '0')}`
}

export function formatNumericWithConfig(value: unknown, config: NumericFormatInput): string {
  // An empty cell stays empty. Number(null) and Number('') are 0, so a cleared
  // value in a currency column used to render as "$0", a number nobody entered.
  if (value == null || (typeof value === 'string' && value.trim() === '')) return ''
  const n = typeof value === 'number' ? value : Number(value)
  if (!Number.isFinite(n)) return String(value ?? '')

  const locales = config.locales

  if (config.type === 'currency') {
    return getNumberFormatter(locales, {
      style: 'currency',
      currency: config.currency ?? 'USD',
      ...config.options,
    }).format(n)
  }

  if (config.type === 'percent') {
    const frac = config.valueIsPercentPoints === true ? n / 100 : n
    return getNumberFormatter(locales, {
      style: 'percent',
      minimumFractionDigits: 0,
      maximumFractionDigits: 2,
      ...config.options,
    }).format(frac)
  }

  return getNumberFormatter(locales, config.options ?? {}).format(n)
}

export function fromCallbackFilterModel(model: Record<string, CallbackColumnFilter> | null | undefined): ServerFilterModel {
  const columns: NonNullable<ServerFilterModel['columns']> = {}
  for (const [id, f] of Object.entries(model ?? {})) {
    if (!f) continue
    if (f.filterType === 'set' && Array.isArray(f.values)) {
      columns[id] = { operator: 'in', value: '', selectedValues: f.values.map(asString) }
      continue
    }
    const operator = CALLBACK_TO_GRID_OPERATOR[f.type ?? ''] ?? f.type ?? 'equals'
    columns[id] = {
      operator,
      value: asString(f.filter),
      ...(f.filterTo != null ? { valueTo: asString(f.filterTo) } : {}),
    }
  }
  return Object.keys(columns).length ? { columns } : {}
}

export function fromCallbackRequest(req: CallbackServerRequest, extra: Partial<ServerRequest> = {}): ServerRequest {
  const startRow = req.startRow ?? 0
  const endRow = req.endRow ?? startRow + 100
  const pageSize = Math.max(1, endRow - startRow)
  const sortModel: ServerSortModel = req.sortModel.map((s) => ({ id: s.colId, desc: s.sort === 'desc' }))
  const out: ServerRequest = {
    startRow,
    endRow,
    pageIndex: Math.floor(startRow / pageSize),
    pageSize,
    sortModel,
    filterModel: fromCallbackFilterModel(req.filterModel),
    ...extra,
  }
  if (req.rowGroupCols.length) {
    out.groupBy = req.rowGroupCols.map((c) => c.id)
    out.groupKeys = [...req.groupKeys]
  }
  if (req.valueCols.length) {
    out.aggregations = req.valueCols.map((c) => ({
      col: c.id,
      fn: (c.aggFunc ?? 'sum') as 'sum' | 'avg' | 'min' | 'max' | 'count',
    }))
  }
  if (req.pivotMode && req.pivotCols.length) {
    out.pivotBy = req.pivotCols.map((c) => c.id)
    out.pivotMode = true
  }
  return out
}

export function fromCallbackSelectionState(
  state: CallbackSelectionState | CallbackGroupSelectionState,
  mapping: SelectionStateMapping = {},
): ServerSelectionState | ServerGroupSelectionNode {
  if ('selectAll' in state) {
    const flat = state as CallbackSelectionState
    return { selectAll: !!flat.selectAll, toggled: (flat.toggledNodes ?? []).map(String) }
  }
  const walk = (node: CallbackGroupSelectionState, route: string[]): ServerGroupSelectionNode => {
    const toggled: Record<string, ServerGroupSelectionNode> = {}
    for (const child of node.toggledNodes ?? []) {
      if (child.nodeId == null) continue
      const id = String(child.nodeId)
      const group = mapping.isGroup?.(id, route) ?? (child.toggledNodes?.length ?? 0) > 0
      const key = group ? (mapping.groupKey?.(id, route) ?? id) : id
      const plain = walk(child, [...route, key])
      toggled[key] = group ? { ...plain, group: true } : plain
    }
    return { selectAllChildren: !!node.selectAllChildren, toggled }
  }
  return walk(state, [])
}

export function fromClassify<TData>(
  result: AIClassifyResult,
  snapshot: ReadonlyArray<TData>,
  opts: { api: RowIdApi; targets?: ReadonlyArray<number>; source?: ProposalSource },
): AdapterResult {
  const targets = opts.targets ?? snapshot.map((_, i) => i)
  const { proposals, dropped } = fromPredictions(result.predictions, result.outputField, snapshot, targets, opts.api, `classified from ${result.inputField}`)
  const source = opts.source ?? { kind: 'ai', id: `classify:${result.outputField}`, label: 'Classify' }
  return { source, title: `Classify: ${result.outputField}`, proposals, dropped }
}

export function fromICS(text: string): ICalEvent[] {
  // Unfold: a line starting with space/tab continues the previous one.
  const raw = text.replace(/\r\n/g, '\n').split('\n')
  const unfolded: string[] = []
  for (const line of raw) {
    if ((line.startsWith(' ') || line.startsWith('\t')) && unfolded.length) {
      unfolded[unfolded.length - 1] += line.slice(1)
    } else unfolded.push(line)
  }
  const out: ICalEvent[] = []
  let cur: Partial<ICalEvent> & { _allDayStart?: boolean } = {}
  let inEvent = false
  for (const line of unfolded) {
    if (line === 'BEGIN:VEVENT') {
      inEvent = true
      cur = {}
      continue
    }
    if (line === 'END:VEVENT') {
      if (cur.title && cur.start && cur.end) out.push({ title: cur.title, start: cur.start, end: cur.end, allDay: cur.allDay, uid: cur.uid, description: cur.description, location: cur.location, status: cur.status, rrule: cur.rrule ?? null })
      inEvent = false
      continue
    }
    if (!inEvent) continue
    const ci = line.indexOf(':')
    if (ci < 0) continue
    const nameAndParams = line.slice(0, ci)
    const value = line.slice(ci + 1)
    const name = nameAndParams.split(';')[0]!.toUpperCase()
    if (name === 'UID') cur.uid = value
    else if (name === 'SUMMARY') cur.title = unescText(value)
    else if (name === 'DESCRIPTION') cur.description = unescText(value)
    else if (name === 'LOCATION') cur.location = unescText(value)
    else if (name === 'STATUS') cur.status = value.toLowerCase() as ICalEvent['status']
    else if (name === 'DTSTART') {
      const { date, allDay } = parseICalDate(value)
      cur.start = date
      cur.allDay = allDay
    } else if (name === 'DTEND') {
      cur.end = parseICalDate(value).date
    } else if (name === 'RRULE') {
      cur.rrule = rruleToRule(value) ?? undefined
    }
  }
  return out
}

export function fromRows<TData>(
  incoming: ReadonlyArray<Partial<TData>>,
  opts: {
    api: Pick<ReviewGridApi, 'getOption' | 'getData'>
    key: keyof TData & string
    source: ProposalSource
    title?: string
    fields?: ReadonlyArray<keyof TData & string>
  },
): AdapterResult & { unmatched: Array<Partial<TData>> } {
  const id = rowIdOf<TData>(opts.api)
  const data = opts.api.getData() as ReadonlyArray<TData>
  const byKey = new Map<unknown, { row: TData; index: number }>()
  data.forEach((row, index) => byKey.set((row as Record<string, unknown>)[opts.key], { row, index }))
  const proposals: ProposalInput[] = []
  const unmatched: Array<Partial<TData>> = []
  for (const next of incoming) {
    const hit = byKey.get((next as Record<string, unknown>)[opts.key])
    if (!hit) {
      unmatched.push(next)
      continue
    }
    const rowId = id(hit.row, hit.index)
    const fields = opts.fields ?? (Object.keys(next) as Array<keyof TData & string>)
    for (const field of fields) {
      if (field === opts.key || !(field in (next as object))) continue
      const before = (hit.row as Record<string, unknown>)[field]
      const after = (next as Record<string, unknown>)[field]
      if (!sameValue(before, after)) proposals.push({ rowId, field, before, after })
    }
  }
  return { source: opts.source, title: opts.title ?? opts.source.label, proposals, dropped: 0, unmatched }
}

export function fromSmartFill<TData>(
  result: AISmartFillResult,
  snapshot: ReadonlyArray<TData>,
  opts: { api: RowIdApi; targets?: ReadonlyArray<number>; source?: ProposalSource },
): AdapterResult {
  const targets = opts.targets ?? blankTargets(snapshot, result.field)
  const { proposals, dropped } = fromPredictions(result.predictions, result.field, snapshot, targets, opts.api, result.rationale || undefined)
  const source = opts.source ?? { kind: 'ai', id: `smart-fill:${result.field}`, label: 'Smart fill' }
  return { source, title: `Smart fill: ${result.field}`, proposals, dropped }
}

export function fromStaged(
  changes: ReadonlyArray<{ rowId: string; columnId: string; original: unknown; staged: unknown }>,
  opts: { api: Pick<ReviewGridApi, 'getColumns'>; source: ProposalSource; title?: string },
): AdapterResult {
  const fieldOf = new Map(opts.api.getColumns().map((c) => [c.id, c.field ?? c.id]))
  const proposals: ProposalInput[] = changes
    .filter((c) => !sameValue(c.original, c.staged))
    .map((c) => ({ rowId: c.rowId, field: fieldOf.get(c.columnId) ?? c.columnId, before: c.original, after: c.staged }))
  return { source: opts.source, title: opts.title ?? opts.source.label, proposals, dropped: 0 }
}

export function fromZonedLocal(pseudo: Date, timeZone?: string): Date {
  if (!timeZone) return pseudo
  return instantFromWallClock(
    pseudo.getFullYear(),
    pseudo.getMonth() + 1,
    pseudo.getDate(),
    pseudo.getHours(),
    pseudo.getMinutes(),
    pseudo.getSeconds(),
    timeZone,
    pseudo.getMilliseconds(),
  )
}

