export function indicatorPane(spec: ChartSpec, ind: ChartIndicatorSpec): ChartSpec {
  const src = sourceSeries(spec, ind)
  const n = spec.categories.length
  const closes = src ? closesOf(src) : nanArray(n)
  const ohlc = src?.ohlc ?? closes.map((c) => (Number.isFinite(c) ? { o: c, h: c, l: c, c } : null))
  const volumes = src?.volumes ?? nanArray(n)
  const params = ind.params ?? {}
  const base: Pick<ChartSpec, 'categories' | 'xType' | 'xAxis' | 'height' | 'palette' | 'valueFormat' | 'locale'> = {
    categories: spec.categories,
    xType: spec.xType,
    xAxis: spec.xAxis,
    height: ind.height ?? Math.max(90, Math.round((spec.height ?? 300) / 3)),
    palette: spec.palette,
    valueFormat: 'number',
    locale: spec.locale,
  }
  const refs = (lines: Array<[number, string]>): ChartReferenceLine[] =>
    lines.map(([value, label]) => ({ value, label, dashed: true }))
  switch (ind.kind) {
    case 'rsi': {
      const p = params.period ?? 14
      return { ...base, type: 'line', title: `RSI ${p}`, series: [{ label: `RSI ${p}`, values: rsi(closes, p), marker: 'none' }],
        yAxis: { min: 0, max: 100, tickInterval: 50, nice: false }, referenceLines: refs([[30, '30'], [70, '70']]) }
    }
    case 'stochastic': {
      const p = params.period ?? 14
      const sm = params.smooth ?? 3
      const { k, d } = stochastic(ohlc, p, sm)
      return { ...base, type: 'line', title: `Stochastic ${p}, ${sm}`, series: [
        { label: '%K', values: k, marker: 'none' }, { label: '%D', values: d, marker: 'none', dash: [4, 3] },
      ], yAxis: { min: 0, max: 100, tickInterval: 50, nice: false }, referenceLines: refs([[20, '20'], [80, '80']]) }
    }
    case 'macd': {
      const fast = params.fast ?? 12
      const slow = params.slow ?? 26
      const signal = params.signal ?? 9
      const m = macd(closes, fast, slow, signal)
      return { ...base, type: 'bar', title: `MACD ${fast}, ${slow}, ${signal}`, series: [
        { label: 'Histogram', values: m.histogram, colors: m.histogram.map((v) => (v < 0 ? '#ef4444' : '#16a34a')) },
        { label: 'MACD', values: m.macd, type: 'line', marker: 'none' },
        { label: 'Signal', values: m.signal, type: 'line', marker: 'none', dash: [4, 3] },
      ], referenceLines: refs([[0, '']]) }
    }
    case 'atr': {
      const p = params.period ?? 14
      return { ...base, type: 'line', title: `ATR ${p}`, series: [{ label: `ATR ${p}`, values: atr(ohlc, p), marker: 'none' }], yAxis: { min: 0 } }
    }
    case 'obv':
      return { ...base, type: 'line', title: 'OBV', series: [{ label: 'OBV', values: obv(closes, volumes), marker: 'none' }], valueFormat: 'compact' }
    case 'volume':
    default: {
      // Up bars in the up colour, down bars in the down colour, like the candles.
      const colors = ohlc.map((b, i) => {
        if (!b) return null
        const prev = i > 0 ? ohlc[i - 1] : null
        const up = prev ? b.c >= prev.c : b.c >= b.o
        return up ? '#16a34a' : '#ef4444'
      })
      return { ...base, type: 'bar', title: 'Volume', series: [{ label: 'Volume', values: volumes.slice(), colors }], yAxis: { min: 0 }, valueFormat: 'compact' }
    }
  }
}

export function inferImportColumnTypes(
  columns: ReadonlyArray<ImportGridColumn>,
): ImportColumnTypes {
  const types: ImportColumnTypes = {}
  for (const c of columns) {
    if (!c.field) continue
    const t = c.format?.type
    if (t === 'number' || t === 'currency' || t === 'percent') types[c.field] = 'number'
    else if (t === 'date') types[c.field] = 'date'
    else if (t === 'datetime') types[c.field] = 'datetime'
  }
  return types
}

export function installEnterprise<
  TFeatures extends TableFeatures,
  TData extends RowData,
>(api: SvGridApi<TFeatures, TData>): EnterpriseGridApi<TFeatures, TData> {
  const pro = api as EnterpriseGridApi<TFeatures, TData>
  pro.exportData = (opts) => exportGrid(pro, opts)
  pro.copyExport = (opts) => copyExportToClipboard(pro, opts)
  pro.print = (opts) => printGrid(pro, opts)
  pro.importData = (opts) => importData(pro, opts)
  pro.ai = {
    filter: (query, opts) => aiFilter(pro, query, opts),
    smartFill: (opts) => aiSmartFill(pro, opts),
    summarize: (opts) => aiSummarize(pro, opts),
    classify: (opts) => aiClassify(pro, opts),
    export: (query, opts) => aiExport(pro, query, opts),
    findAnomalies: (opts) => aiFindAnomalies(pro, opts),
    chart: (query, opts) => aiChart(pro, query, opts),
  }
  // Wire the built-in chart panel's AI button (no-op without the `charting` prop).
  enableAiCharting(pro)
  // Register the scheduler / calendar view (no-op without the `scheduler` prop).
  enableSchedulerView()
  // Register the Kanban board view (no-op without the `board` prop).
  enableBoardView()
  // Register the gallery view (no-op without the `gallery` prop).
  enableGalleryView()
  // Register the Gantt view (no-op without the `gantt` prop).
  enableGanttView()
  enableSelectionBar()
  // Relative date operators, cell-text checklist labels and the status-bar row
  // count (each a no-op until a grid uses it).
  enableRelativeDateFilters()
  enableFilterLabels()
  enableRowCount()
  // Register the export engine so built-in AI exports (aiExport) can write the
  // enterprise formats (xlsx / pdf / ...); free grids without it get the plan only.
  registerExportProvider(exportGrid as never)
  enablePivot()
  enableAdvancedFilter()
  // Register the Excel keymap (Ctrl+Arrow, Ctrl+D, Ctrl+A and the rest). The
  // grid interprets a key itself only when nothing claims it, so a free grid
  // is unaffected. No spreadsheet nudge: this app may only export or pivot.
  registerSheetKeymap()
  // Raise the unlicensed nudge for the server-side row model. No registry to fill -
  // the model hands the grid ordinary rows - so this only nudges when unlicensed.
  enableServerRowModel()
  pro.pivot = {
    build: (config) =>
      createPivotModel<TFeatures, TData>(pro.getData(), config),
    buildFrom: <TIn extends RowData>(data: ReadonlyArray<TIn>, config: PivotConfig<TIn>) =>
      // PivotConfig is variance-strict in TIn; the runtime call only needs
      // the row shape to match config.rows / config.cols field names, which
      // the caller-side generic enforces.
      createPivotModel<TFeatures, TIn>(data, config),
  }
  // Surface the unlicensed state at install time so the watermark appears
  // alongside the grid, not just after the user clicks Export.
  if (!hasValidLicense()) emitUnlicensedNudge()
  return pro
}

export function instantFromWallClock(
  year: number,
  month: number, // 1-12
  day: number,
  hour: number,
  minute: number,
  second = 0,
  timeZone?: string,
  ms = 0,
): Date {
  if (!timeZone) return new Date(year, month - 1, day, hour, minute, second, ms)
  const wallUtc = Date.UTC(year, month - 1, day, hour, minute, second, ms)
  // Assume the wall-clock is UTC, subtract the offset there, then correct once
  // in case the candidate instant lands on the other side of a DST transition.
  const off1 = zoneOffsetMs(new Date(wallUtc), timeZone)
  let inst = new Date(wallUtc - off1)
  const off2 = zoneOffsetMs(inst, timeZone)
  if (off2 !== off1) inst = new Date(wallUtc - off2)
  return inst
}

export function interpolateGeometry(from: ChartGeometry, to: ChartGeometry, t: number): ChartGeometry {
  if (t >= 1) return to
  if (t <= 0 && from.type === to.type) return from
  if (from.type !== to.type) return to
  return {
    ...to,
    bars: tweenBars(from.bars, to.bars, t, to.plot.y + to.plot.h),
    lines: tweenLines(from.lines, to.lines, t),
    candles: tweenCandles(from.candles, to.candles, t),
    slices: tweenSlices(from.slices, to.slices, t),
    arcs: tweenArcs(from.arcs, to.arcs, t),
    yTicks: to.yTicks.map((tick) => {
      const prev = from.yTicks.find((p) => p.value === tick.value)
      return prev ? { ...tick, y: r2(mix(prev.y, tick.y, t)) } : tick
    }),
  }
}

export function isCallbackSelectionState(
  state: unknown,
): state is CallbackSelectionState | CallbackGroupSelectionState {
  return typeof state === 'object' && state !== null && 'toggledNodes' in state
}

export function isDisabledDay(d: Date, opts: RestrictOptions): boolean {
  return isOutOfRange(d, opts.min, opts.max) || isRestricted(d, opts.restrictedDates)
}

export function isFunction(value: unknown): value is (...args: Array<any>) => any {
  return typeof value === 'function'
}

export function isImportant(
  d: Date,
  importantDates?: ReadonlyArray<DateLike> | ((day: Date) => boolean) | null,
): boolean {
  if (!importantDates) return false
  if (typeof importantDates === 'function') return importantDates(d)
  return normalizeList(importantDates).some((r) => isSameDay(r, d))
}

export function isMaskComplete(value: string, pattern: string): boolean {
  const tokenCount = [...pattern].filter(isToken).length
  return unmask(value, pattern).length >= tokenCount
}

export function isOutOfRange(d: Date, min?: DateLike | null, max?: DateLike | null): boolean {
  const lo = toDate(min ?? null)
  const hi = toDate(max ?? null)
  if (lo && compareDay(d, lo) < 0) return true
  if (hi && compareDay(d, hi) > 0) return true
  return false
}

export function isoWeek(d: Date): number {
  // Shift to the Thursday of this week, then count weeks from Jan 1.
  const date = startOfDay(d)
  const day = (date.getDay() + 6) % 7 // Mon=0..Sun=6
  date.setDate(date.getDate() - day + 3) // Thursday of this week
  const firstThursday = new Date(date.getFullYear(), 0, 4)
  const firstDay = (firstThursday.getDay() + 6) % 7
  firstThursday.setDate(firstThursday.getDate() - firstDay + 3)
  const diffMs = date.getTime() - firstThursday.getTime()
  return 1 + Math.round(diffMs / (7 * 24 * 3600 * 1000))
}

export function isRangeOperator(op: ExcelFilterOperator): boolean {
  return RANGE_OPERATOR_IDS.includes(op)
}

export function isRestricted(
  d: Date,
  restrictedDates?: ReadonlyArray<DateLike> | ((day: Date) => boolean) | null,
): boolean {
  if (!restrictedDates) return false
  if (typeof restrictedDates === 'function') return restrictedDates(d)
  return normalizeList(restrictedDates).some((r) => isSameDay(r, d))
}

export function isSameDay(a: Date | null, b: Date | null): boolean {
  if (!a || !b) return false
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  )
}

export function isSameMonth(a: Date | null, b: Date | null): boolean {
  if (!a || !b) return false
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth()
}

export function isSetOperator(op: ExcelFilterOperator): boolean {
  return SET_OPERATOR_IDS.includes(op)
}

export function isTypeaheadKey(e: KeyboardEvent): boolean {
  return e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey && e.key !== ' '
}

export function isValuelessOperator(op: ExcelFilterOperator): boolean {
  return VALUELESS_OPERATOR_IDS.includes(op)
}

export function layoutDataLabels(
  geo: ChartGeometry,
  cfg: ChartDataLabelConfig,
  fmt: (v: number, series?: string) => string,
  opts: { stacked?: boolean; dense?: boolean; share?: boolean } = {},
): ChartDataLabel[] {
  if (cfg.show === false) return []
  const out: ChartDataLabel[] = []
  // On a 100% chart the axis reads shares whatever `valueFormat` says, and a
  // label on the bar reads the same: "18%", not the "$18" (or, with a percent
  // format, the "1800%") the raw value gave. A formatter still gets the raw
  // value; the tooltip keeps it too.
  const totals = opts.share ? new Map<string, number>() : null
  if (totals) {
    for (const b of geo.bars) {
      const key = b.index === undefined ? b.label : String(b.index)
      totals.set(key, (totals.get(key) ?? 0) + Math.abs(b.value))
    }
  }
  const shareOf = (b: ChartBar) => {
    const total = totals!.get(b.index === undefined ? b.label : String(b.index)) || 0
    return total ? `${Math.round((Math.abs(b.value) / total) * 100)}%` : ''
  }
  const text = (v: number, category: string, series: string, bar?: ChartBar) =>
    cfg.formatter ? cfg.formatter(v, { category, series }) : totals && bar ? shareOf(bar) : fmt(v, series)
  const horizontal = geo.orientation === 'horizontal'
  const placement = cfg.placement ?? (opts.stacked ? 'inside' : horizontal ? 'outside' : 'top')
  const inside = placement === 'inside' || placement === 'center'
  for (const b of geo.bars) {
    const t = text(b.value, b.label, b.series, b)
    if (!t) continue
    if (horizontal) {
      if (inside) {
        if (b.w <= 18 || b.h < 8) continue
        out.push({ x: b.x + b.w / 2, y: b.y + b.h / 2 + 3, text: t, anchor: 'middle', onBar: true, series: b.series })
      } else {
        if (b.h < 8) continue
        const pos = b.value >= 0
        out.push({ x: pos ? b.x + b.w + 3 : b.x - 3, y: b.y + b.h / 2 + 3, text: t, anchor: pos ? 'start' : 'end', onBar: false, series: b.series })
      }
    } else if (inside) {
      if (b.h <= 13 || b.w < 14) continue
      out.push({ x: b.x + b.w / 2, y: b.y + b.h / 2 + 3, text: t, anchor: 'middle', onBar: true, series: b.series })
    } else {
      if (b.w < 6) continue
      const pos = b.value >= 0
      out.push({ x: b.x + b.w / 2, y: pos ? b.y - 3 : b.y + b.h + 11, text: t, anchor: 'middle', onBar: false, series: b.series })
    }
  }
  if (!opts.dense) {
    for (const line of geo.lines) {
      for (const p of line.points) {
        if (!p.defined) continue
        const t = text(p.value, p.label, line.label)
        if (!t) continue
        out.push({ x: p.x, y: inside ? p.y + 3 : p.y - 7, text: t, anchor: 'middle', onBar: false, series: line.label })
      }
    }
  }
  const angle = cfg.rotation ?? 0
  if (angle) for (const l of out) l.angle = angle
  if (cfg.hideOverlap === false && !cfg.connector) return out
  // Greedy thinning in draw order: a label is kept only when its estimated
  // box (10px type, ~5.6px a glyph) misses every box already kept. A rotated
  // label past 45 degrees stands more than it lies, so its box is turned.
  // With `connector`, a label that collides is pushed away from its mark in
  // 12px steps (up, or right on a horizontal chart) and keeps a leader back
  // to where it started; after four steps it gives up and is dropped.
  const kept: Array<{ x0: number; y0: number; x1: number; y1: number }> = []
  const steep = Math.abs(angle) >= 45
  const boxOf = (l: ChartDataLabel) => {
    const len = l.text.length * 5.6 + 2
    const w = steep ? 10 : len
    const h = steep ? len : 11
    const x0 = l.anchor === 'middle' ? l.x - w / 2 : l.anchor === 'end' ? l.x - w : l.x
    const y0 = steep ? l.y - h : l.y - 10
    return { x0, y0, x1: x0 + w, y1: y0 + h }
  }
  const hits = (b: { x0: number; y0: number; x1: number; y1: number }) =>
    kept.some((k) => b.x0 < k.x1 && b.x1 > k.x0 && b.y0 < k.y1 && b.y1 > k.y0)
  const STEP = 12
  const MAX_STEPS = 4
  const pushed: ChartDataLabel[] = []
  for (const l of out) {
    let box = boxOf(l)
    if (!hits(box)) { kept.push(box); pushed.push(l); continue }
    if (!cfg.connector || l.onBar) continue
    const from = { x: l.x, y: l.y }
    let moved: ChartDataLabel | null = null
    for (let step = 1; step <= MAX_STEPS; step += 1) {
      const cand: ChartDataLabel = horizontal
        ? { ...l, x: l.x + STEP * step }
        : { ...l, y: l.y - STEP * step }
      box = boxOf(cand)
      if (!hits(box)) { moved = cand; break }
    }
    if (!moved) continue
    // The leader runs from the mark's edge (where the label started) to the
    // near edge of the moved label.
    moved.leader = horizontal
      ? { x1: from.x, y1: from.y - 3, x2: moved.x - 2, y2: moved.y - 3 }
      : { x1: from.x, y1: from.y + 1, x2: moved.x, y2: moved.y + 2 }
    kept.push(box)
    pushed.push(moved)
  }
  return pushed
}

export function layoutDayEvents<TData>(
  dayEvents: ReadonlyArray<ResolvedEvent<TData>>,
  day: Date,
  opts: LayoutOptions = {},
): DayLayout<TData> {
  const dayStartHour = opts.dayStartHour ?? 0
  const dayEndHour = opts.dayEndHour ?? 24
  const mode = opts.mode ?? 'split'
  const maxColumns = Math.max(2, Math.floor(opts.maxColumns ?? 3))
  const stackOffset = opts.stackOffsetPct ?? 14
  const stackMinWidth = opts.stackMinWidthPct ?? 42

  const base = startOfDay(day)
  const bandStartMin = dayStartHour * 60
  const bandEndMin = dayEndHour * 60
  const bandLen = Math.max(1, bandEndMin - bandStartMin)

  type Item = { event: ResolvedEvent<TData>; startMin: number; endMin: number; col: number }
  const items: Item[] = []
  for (const e of dayEvents) {
    if (e.allDay) continue
    const s = Math.max(bandStartMin, (e.start.getTime() - base.getTime()) / MS_MIN)
    const en = Math.min(bandEndMin, (e.end.getTime() - base.getTime()) / MS_MIN)
    if (en <= bandStartMin || s >= bandEndMin) continue
    items.push({ event: e, startMin: s, endMin: Math.max(s + 1, en), col: 0 })
  }
  items.sort((a, b) => a.startMin - b.startMin || a.endMin - b.endMin)

  const events: PositionedEvent<TData>[] = []
  const overflows: OverflowMarker<TData>[] = []
  const topOf = (min: number) => ((min - bandStartMin) / bandLen) * 100
  const heightOf = (a: number, b: number) => ((b - a) / bandLen) * 100
  const maxStackShift = Math.max(0, Math.floor((100 - stackMinWidth) / stackOffset))

  // Walk clusters of transitively-overlapping events; within each cluster assign
  // greedy columns, then resolve horizontal geometry for the chosen mode.
  let cluster: Item[] = []
  let clusterEnd = -Infinity
  const flush = () => {
    if (!cluster.length) return
    const colEnds: number[] = []
    for (const it of cluster) {
      let c = 0
      for (; c < colEnds.length; c++) if (it.startMin >= (colEnds[c] ?? Infinity)) break
      colEnds[c] = it.endMin
      it.col = c
    }
    const colCount = colEnds.length

    if (mode === 'stack' && colCount > 1) {
      for (const it of cluster) {
        const shift = Math.min(it.col, maxStackShift) * stackOffset
        events.push({
          event: it.event,
          topPct: topOf(it.startMin),
          heightPct: heightOf(it.startMin, it.endMin),
          col: it.col,
          colCount,
          leftPct: shift,
          widthPct: 100 - shift,
          zIndex: it.col + 1,
        })
      }
    } else if (mode === 'cap' && colCount > maxColumns) {
      const realCols = maxColumns - 1 // reserve the last visible slot for overflow
      const hidden: Item[] = []
      for (const it of cluster) {
        if (it.col < realCols) {
          events.push({
            event: it.event,
            topPct: topOf(it.startMin),
            heightPct: heightOf(it.startMin, it.endMin),
            col: it.col,
            colCount: maxColumns,
            leftPct: (it.col / maxColumns) * 100,
            widthPct: 100 / maxColumns,
            zIndex: 1,
          })
        } else {
          hidden.push(it)
        }
      }
      if (hidden.length) {
        const start = Math.min(...hidden.map((h) => h.startMin))
        const end = Math.max(...hidden.map((h) => h.endMin))
        overflows.push({
          topPct: topOf(start),
          heightPct: heightOf(start, end),
          leftPct: (realCols / maxColumns) * 100,
          widthPct: 100 / maxColumns,
          count: hidden.length,
          events: hidden.map((h) => h.event),
        })
      }
    } else {
      // split (and cap when the cluster fits within maxColumns): each event
      // starts in its greedy column, then EXPANDS rightward across any columns
      // that hold no event overlapping it in time - so an event with free space
      // beside it fills the gap instead of staying a narrow 1/colCount sliver.
      for (const it of cluster) {
        let span = 1
        for (let c = it.col + 1; c < colCount; c++) {
          const blocked = cluster.some(
            (o) => o !== it && o.col === c && o.startMin < it.endMin && o.endMin > it.startMin,
          )
          if (blocked) break
          span++
        }
        events.push({
          event: it.event,
          topPct: topOf(it.startMin),
          heightPct: heightOf(it.startMin, it.endMin),
          col: it.col,
          colCount,
          leftPct: (it.col / colCount) * 100,
          widthPct: (span / colCount) * 100,
          zIndex: 1,
        })
      }
    }

    cluster = []
    clusterEnd = -Infinity
  }
  for (const it of items) {
    if (cluster.length && it.startMin >= clusterEnd) flush()
    cluster.push(it)
    clusterEnd = Math.max(clusterEnd, it.endMin)
  }
  flush()
  return { events, overflows }
}

export type LayoutOptions = {
  dayStartHour?: number
  dayEndHour?: number
  /** Collision layout mode. Default `split`. */
  mode?: SchedulerCollisionMode
  /** `cap` mode: max columns before overflow (min 2). Default 3. */
  maxColumns?: number
  /** `stack` mode: horizontal offset per overlapping event, in % of column. */
  stackOffsetPct?: number
  /** `stack` mode: the narrowest a stacked event may get, in % of column. */
  stackMinWidthPct?: number
}

export function leafMinSize(node: DockTabs): number {
  return node.panes.reduce((m, p) => Math.max(m, p.minSize ?? 0), 0)
}

export function linearFit(values: ReadonlyArray<number>, xs?: ReadonlyArray<number>): RegressionFit {
  const X = xsOf(values, xs)
  const { slope, intercept, ok } = lineThrough(X, values)
  if (!ok) return NO_FIT(values)
  const predict = (x: number) => slope * x + intercept
  const fitted = values.map((v, i) => (Number.isFinite(v) && Number.isFinite(X[i]) ? predict(X[i]!) : NaN))
  return { fitted, r2: rSquared(values, fitted), equation: `y = ${fmtCoef(slope)} x + ${fmtCoef(intercept)}`, predict }
}

export function linearTrend(values: number[]): number[] {
  let n = 0, sumX = 0, sumY = 0, sumXX = 0, sumXY = 0
  for (let i = 0; i < values.length; i += 1) {
    const y = values[i]!
    if (!Number.isFinite(y)) continue
    n += 1; sumX += i; sumY += y; sumXX += i * i; sumXY += i * y
  }
  if (n < 2) return values.map(() => NaN)
  const denom = n * sumXX - sumX * sumX
  if (denom === 0) return values.map(() => sumY / n)
  const slope = (n * sumXY - sumX * sumY) / denom
  const intercept = (sumY - slope * sumX) / n
  return values.map((_, i) => slope * i + intercept)
}

export type ListOption = {
  value: string | number
  label: string
  disabled?: boolean
  /** Optional group heading this option belongs under. */
  group?: string
  /** Optional color swatch (any CSS color) shown before the label. */
  color?: string
  /**
   * Optional muted text pinned to the trailing edge of the row - a count, a
   * shortcut, a unit. Not part of the label, so it does not affect matching
   * or the accessible name.
   */
  hint?: string
}

export function locatePane(state: DockManagerState, paneId: string): PaneLocation | null {
  if (state.main && findTabsWithPane(state.main, paneId)) return { kind: 'main' }
  for (const w of state.floating) {
    if (w.leaf.panes.some((p) => p.id === paneId)) return { kind: 'floating', windowId: w.id }
  }
  for (const e of state.autoHide) {
    if (e.leaf.panes.some((p) => p.id === paneId)) return { kind: 'autoHide', entryId: e.id }
  }
  return null
}

export function logarithmicFit(values: ReadonlyArray<number>, xs?: ReadonlyArray<number>): RegressionFit {
  const shift = xs ? 0 : 1
  const lx = xsOf(values, xs).map((x) => (x + shift > 0 ? Math.log(x + shift) : NaN))
  const { slope, intercept, ok } = lineThrough(lx, values)
  if (!ok) return NO_FIT(values)
  const predict = (x: number) => (x + shift > 0 ? intercept + slope * Math.log(x + shift) : NaN)
  const fitted = values.map((v, i) => (Number.isFinite(v) && Number.isFinite(lx[i]) ? intercept + slope * lx[i]! : NaN))
  const arg = xs ? 'x' : 'x + 1'
  return { fitted, r2: rSquared(values, fitted), equation: `y = ${fmtCoef(intercept)} + ${fmtCoef(slope)} ln(${arg})`, predict }
}

export function lttb(values: ReadonlyArray<number>, target: number, xs?: ReadonlyArray<number>): number[] {
  const n = values.length
  // The x of point j: its index unless the caller positions points by value
  // (a numeric or log axis), where the triangles must use the real spacing.
  const xAt = (j: number) => (xs && Number.isFinite(xs[j]) ? xs[j]! : j)
  if (target >= n || n <= 2) return values.map((_, i) => i)
  if (target < 3) return [0, n - 1]
  const out: number[] = [0]
  const every = (n - 2) / (target - 2)
  let a = 0
  for (let i = 0; i < target - 2; i += 1) {
    // The next bucket's centroid is the far corner of every candidate triangle.
    const nextStart = Math.floor((i + 1) * every) + 1
    const nextEnd = Math.min(Math.floor((i + 2) * every) + 1, n)
    let avgX = 0
    let avgY = 0
    let cnt = 0
    for (let j = nextStart; j < nextEnd; j += 1) {
      const v = values[j]!
      if (!Number.isFinite(v)) continue
      avgX += xAt(j)
      avgY += v
      cnt += 1
    }
    if (cnt) { avgX /= cnt; avgY /= cnt } else { avgX = (xAt(nextStart) + xAt(Math.min(nextEnd, n - 1))) / 2; avgY = values[a]! }
    const start = Math.floor(i * every) + 1
    const end = Math.min(Math.floor((i + 1) * every) + 1, n)
    const ax = xAt(a)
    const ay = Number.isFinite(values[a]!) ? values[a]! : 0
    let best = -1
    let bestArea = -1
    for (let j = start; j < end; j += 1) {
      const v = values[j]!
      if (!Number.isFinite(v)) continue
      const area = Math.abs((ax - avgX) * (v - ay) - (ax - xAt(j)) * (avgY - ay))
      if (area > bestArea) { bestArea = area; best = j }
    }
    if (best < 0) best = start
    out.push(best)
    a = best
  }
  out.push(n - 1)
  return out
}

export function macd(values: ReadonlyArray<number>, fast = 12, slow = 26, signal = 9): { macd: number[]; signal: number[]; histogram: number[] } {
  const n = values.length
  const f = exponentialMovingAverage(values as number[], fast)
  const s = exponentialMovingAverage(values as number[], slow)
  const line = nanArray(n)
  // The slow EMA is only meaningful once it has seen `slow` values; before
  // that both averages are still warming up and the difference is noise.
  for (let i = slow - 1; i < n; i += 1) line[i] = f[i]! - s[i]!
  const sig = nanArray(n)
  const hist = nanArray(n)
  const alpha = 2 / (Math.max(1, signal) + 1)
  let prev: number | null = null
  let seen = 0
  for (let i = 0; i < n; i += 1) {
    const v = line[i]!
    if (!Number.isFinite(v)) continue
    seen += 1
    prev = prev == null ? v : alpha * v + (1 - alpha) * prev
    if (seen >= signal) {
      sig[i] = prev
      hist[i] = v - prev
    }
  }
  return { macd: line, signal: sig, histogram: hist }
}

export function mapImportMatrix<TData extends RowData>(
  matrix: string[][],
  opts: MapMatrixOptions<TData> = {},
): MapMatrixResult<TData> {
  const built = buildRecords<TData>(matrix, opts.columnMap, opts.columnTypes, opts.maxErrors)
  const errors = built.errors
  // Type-coercion errors come first; the validator runs on the rows we
  // managed to build, so its errors share the same `rowIndex` basis.
  let errorsTruncated = built.errorsTruncated
  if (applyValidator(built.rows, errors, opts.validator, opts.maxErrors)) errorsTruncated = true
  let rows = built.rows
  let deduped = 0
  if (opts.dedupeBy) {
    const r = dedupeRows(rows, opts.dedupeBy as string)
    rows = r.rows
    deduped = r.deduped
  }
  return {
    headers: built.headers,
    rows,
    errors,
    skipped: built.skipped,
    total: matrix.length > 0 ? matrix.length - 1 : 0,
    errorsTruncated,
    deduped,
  }
}

export async function mapImportMatrixAsync<TData extends RowData>(
  matrix: string[][],
  opts: MapMatrixOptions<TData> & {
    signal?: AbortSignal
    onProgress?: (progress: ImportProgress) => void
    /** Rows per chunk before yielding. Default 5000. */
    chunkSize?: number
  } = {},
): Promise<MapMatrixResult<TData>> {
  const headers = (matrix[0] ?? []).map((h) => h.trim())
  const fields = computeFields(headers, opts.columnMap)
  const dataRows = matrix.slice(1)
  const total = dataRows.length
  const chunk = Math.max(1, opts.chunkSize ?? 5000)
  const rows: TData[] = []
  const errors: ImportRowError[] = []
  let skipped = 0
  let outRowIndex = 0
  let errorsTruncated = false

  for (let i = 0; i < total; i += 1) {
    if (opts.signal?.aborted) throw abortError()
    const cells = dataRows[i]!
    if (isBlankRow(cells)) { skipped += 1 } else {
      const { rec, errors: rowErrs } = buildRecord(cells, headers.length, fields, opts.columnTypes, outRowIndex)
      if (rowErrs.length && collectErrors(errors, rowErrs, opts.maxErrors)) errorsTruncated = true
      rows.push(rec as unknown as TData)
      outRowIndex += 1
    }
    if ((i + 1) % chunk === 0) {
      opts.onProgress?.({ phase: 'map', ratio: total ? (i + 1) / total : 1, done: i + 1, total })
      await nextTick()
    }
  }

  if (applyValidator(rows, errors, opts.validator, opts.maxErrors)) errorsTruncated = true

  let finalRows = rows
  let deduped = 0
  if (opts.dedupeBy) {
    const r = dedupeRows(rows, opts.dedupeBy as string)
    finalRows = r.rows
    deduped = r.deduped
  }
  opts.onProgress?.({ phase: 'map', ratio: 1, done: total, total })
  return {
    headers,
    rows: finalRows,
    errors,
    skipped,
    total: matrix.length > 0 ? matrix.length - 1 : 0,
    errorsTruncated,
    deduped,
  }
}

export function markerPath(shape: ChartMarkerShape, cx: number, cy: number, size: number): string {
  const s = Math.max(0.5, size)
  switch (shape) {
    case 'square':
      return `M${round(cx - s)},${round(cy - s)} h${round(2 * s)} v${round(2 * s)} h${round(-2 * s)} Z`
    case 'diamond':
      return `M${round(cx)},${round(cy - s * 1.3)} L${round(cx + s * 1.3)},${round(cy)} L${round(cx)},${round(cy + s * 1.3)} L${round(cx - s * 1.3)},${round(cy)} Z`
    case 'triangle':
      return `M${round(cx)},${round(cy - s * 1.2)} L${round(cx + s * 1.2)},${round(cy + s)} L${round(cx - s * 1.2)},${round(cy + s)} Z`
    case 'cross':
      return `M${round(cx - s)},${round(cy - s)} L${round(cx + s)},${round(cy + s)} M${round(cx - s)},${round(cy + s)} L${round(cx + s)},${round(cy - s)}`
    default:
      return ''
  }
}

export function matchResponsiveRules(rules: ChartResponsiveRule[] | undefined, width: number, height: number): ChartResponsiveRule[] {
  if (!rules?.length) return []
  return rules.filter(
    (r) =>
      (r.maxWidth == null || width <= r.maxWidth) &&
      (r.minWidth == null || width >= r.minWidth) &&
      (r.maxHeight == null || height <= r.maxHeight),
  )
}

symbols.doc:
A merge declaration. The cell at (rowIndex, columnId) is the ORIGIN;
 it spans `colspan` columns to the right + `rowspan` rows downward.
 Covered cells are hidden so the origin visually fills the region.

symbols.signature:
export type MergeSpec = {
  /** Display-row index — the same value the grid puts on
   *  `data-svgrid-row`. After sorting/filtering, recompute the spec
   *  against the new display order. */
  rowIndex: number
  columnId: string
  /** Default 1. */
  rowspan?: number
  /** Default 1. */
  colspan?: number
}

export function minMaxIndices(values: ReadonlyArray<number>, buckets: number): number[] {
  const n = values.length
  if (buckets >= n || n <= 2) return values.map((_, i) => i)
  const keep = new Set<number>([0, n - 1])
  const size = n / Math.max(1, buckets)
  for (let b = 0; b < buckets; b += 1) {
    const start = Math.floor(b * size)
    const end = Math.min(n, Math.floor((b + 1) * size))
    let lo = -1
    let hi = -1
    for (let j = start; j < end; j += 1) {
      const v = values[j]!
      if (!Number.isFinite(v)) continue
      if (lo < 0 || v < values[lo]!) lo = j
      if (hi < 0 || v > values[hi]!) hi = j
    }
    if (lo >= 0) keep.add(lo)
    if (hi >= 0) keep.add(hi)
  }
  return [...keep].sort((x, y) => x - y)
}

export const mockAIProvider: AIProvider = async (req) => {
  // Tiny artificial delay so the UI's "thinking" state is visible.
  await new Promise((r) => setTimeout(r, 350 + Math.random() * 400))

  if (req.task === 'filter') {
    const q = extractUserQuery(req.prompt)
    return JSON.stringify(buildMockFilter(req.prompt, q))
  }
  if (req.task === 'smart-fill') {
    return JSON.stringify(buildMockSmartFill(req.prompt))
  }
  if (req.task === 'summarize') {
    return JSON.stringify(buildMockSummary(req.prompt))
  }
  if (req.task === 'classify') {
    return JSON.stringify(buildMockClassify(req.prompt))
  }
  if (req.task === 'export') {
    return JSON.stringify(buildMockExport(req.prompt))
  }
  if (req.task === 'anomaly') {
    return JSON.stringify(buildMockAnomaly(req.prompt))
  }
  if (req.task === 'chart') {
    return JSON.stringify(buildMockChart(req.prompt))
  }
  if (req.task === 'explain-chart') {
    // Two canned observations round the reading the prompt was grounded on.
    const reading = /Reading of the chart: ([^\n]+)/.exec(req.prompt)?.[1] ?? ''
    const rises = /rises/.test(reading)
    return JSON.stringify({
      insights: [
        rises ? 'The growth is front-loaded: the early categories carry most of the change.' : 'The movement is gradual with no single category driving it.',
        'Compare the peak against the same category a period earlier before reading it as a trend.',
      ],
    })
  }
  return '{}'
}

export function monthMatrix(
  monthDate: Date,
  firstDayOfWeek = 0,
  weeks = 6,
): MonthMatrixCell[][] {
  const first = startOfMonth(monthDate)
  const gridStart = startOfWeek(first, firstDayOfWeek)
  const rows: MonthMatrixCell[][] = []
  let cursor = gridStart
  for (let r = 0; r < weeks; r++) {
    const row: MonthMatrixCell[] = []
    const weekNo = isoWeek(cursor)
    for (let c = 0; c < 7; c++) {
      row.push({
        date: cursor,
        inMonth: cursor.getMonth() === first.getMonth() && cursor.getFullYear() === first.getFullYear(),
        week: weekNo,
      })
      cursor = addDays(cursor, 1)
    }
    rows.push(row)
  }
  return rows
}

export type MonthMatrixCell = {
  date: Date
  /** In the displayed month (vs. leading/trailing days of adjacent months). */
  inMonth: boolean
  /** ISO week number of the row this cell sits in. */
  week: number
}

export function monthWeekSegments<TData>(
  events: ReadonlyArray<ResolvedEvent<TData>>,
  weekStart: Date,
): { segments: MonthSegment<TData>[]; laneCount: number } {
  const ws = startOfDay(weekStart)
  const we = addDays(ws, 7)
  const colOf = (d: Date) => Math.floor((startOfDay(d).getTime() - ws.getTime()) / MS_DAY)

  const out: MonthSegment<TData>[] = []
  for (const e of events) {
    const firstDay = startOfDay(e.start)
    // Last covered day: the day of (end - 1ms), so an end at exact midnight does
    // not spill onto the next day. Guard against zero/negative-length events.
    const lastDay = startOfDay(new Date(Math.max(e.start.getTime(), e.end.getTime() - 1)))
    if (lastDay.getTime() < ws.getTime() || firstDay.getTime() >= we.getTime()) continue
    const startCol = Math.max(0, colOf(firstDay))
    const endCol = Math.min(6, colOf(lastDay))
    if (endCol < startCol) continue
    out.push({
      event: e,
      startCol,
      endCol,
      lane: 0,
      continuesLeft: firstDay.getTime() < ws.getTime(),
      continuesRight: lastDay.getTime() >= we.getTime(),
    })
  }

  // Order: earliest start, then longest, then all-day before timed, then start time.
  out.sort(
    (a, b) =>
      a.startCol - b.startCol ||
      b.endCol - b.startCol - (a.endCol - a.startCol) ||
      (a.event.allDay === b.event.allDay
        ? a.event.start.getTime() - b.event.start.getTime()
        : a.event.allDay
          ? -1
          : 1),
  )

  // Greedy lane packing: a lane tracks the last column it is occupied through.
  const laneEnd: number[] = []
  for (const seg of out) {
    let lane = 0
    for (; lane < laneEnd.length; lane++) if (seg.startCol > (laneEnd[lane] ?? -1)) break
    laneEnd[lane] = seg.endCol
    seg.lane = lane
  }
  return { segments: out, laneCount: laneEnd.length }
}

export function movePane(
  root: DockNode,
  paneId: string,
  targetTabsId: string,
  zone: DockZone,
  genId: IdGen,
): DockNode {
  const { root: without, pane: moved } = removePane(root, paneId)
  if (!without || !moved) return root
  // If removing the pane dissolved the target leaf (it was the pane's own
  // single-pane leaf), there is nothing to dock against - leave the tree as-is.
  if (!containsTabs(without, targetTabsId)) return root
  return dockInto(without, targetTabsId, moved, zone, genId)
}

export function moveTreeNode(
  nodes: ReadonlyArray<TreeNode>,
  dragId: string,
  targetId: string,
  position: TreeDropPosition,
): TreeNode[] {
  if (dragId === targetId) return [...nodes]
  const dragged = findNode(nodes, dragId)
  if (!dragged) return [...nodes]
  if (dragId === targetId || treeContains(dragged, targetId)) return [...nodes]

  const without = (list: ReadonlyArray<TreeNode>): TreeNode[] => {
    const out: TreeNode[] = []
    for (const n of list) {
      if (n.id === dragId) continue
      out.push(n.children ? { ...n, children: without(n.children) } : n)
    }
    return out
  }
  const insert = (list: ReadonlyArray<TreeNode>): TreeNode[] => {
    const out: TreeNode[] = []
    for (const n of list) {
      if (n.id === targetId) {
        if (position === 'before') { out.push(dragged, n) }
        else if (position === 'after') { out.push(n, dragged) }
        else out.push({ ...n, children: [...(n.children ?? []), dragged] })
      } else if (n.children) {
        out.push({ ...n, children: insert(n.children) })
      } else out.push(n)
    }
    return out
  }
  return insert(without(nodes))
}

export function moveWindow(state: DockManagerState, windowId: string, x: number, y: number): DockManagerState {
  return { ...state, floating: state.floating.map((w) => (w.id === windowId ? { ...w, x, y } : w)) }
}

export function navigateAnchor(view: SchedulerView, anchor: Date, dir: number): Date {
  switch (view) {
    case 'month':
      return addMonths(anchor, dir)
    case 'week':
      return addDays(anchor, 7 * dir)
    case 'day':
      return addDays(anchor, dir)
    case 'agenda':
      return addDays(anchor, 30 * dir)
    case 'timelineDay':
      return addDays(anchor, dir)
    case 'timelineWeek':
      return addDays(anchor, 7 * dir)
    case 'timelineMonth':
      return addMonths(anchor, dir)
    case 'timelineYear':
      return new Date(anchor.getFullYear() + dir, anchor.getMonth(), anchor.getDate())
  }
}

symbols.doc:
The category whose date is nearest to `t`, for syncing a hover between two
charts whose categories differ. Categories that do not parse are skipped;
returns -1 when none do.

symbols.signature:
export function nearestIndexByTime(categories: ReadonlyArray<string>, t: number): number {
  let best = -1
  let bestD = Infinity
  for (let i = 0; i < categories.length; i += 1) {
    const ct = Date.parse(categories[i]!)
    if (!Number.isFinite(ct)) continue
    const d = Math.abs(ct - t)
    if (d < bestD) { bestD = d; best = i }
  }
  return best
}

export function nearestKey(key: string, known: ReadonlyArray<string>): string | null {
  let best: string | null = null
  let bestD = Infinity
  for (const k of known) {
    const d = distance(key.toLowerCase(), k.toLowerCase())
    if (d < bestD) { bestD = d; best = k }
  }
  return best !== null && bestD <= Math.max(1, Math.floor(key.length / 3)) ? best : null
}

export function nextTypeaheadIndex(
  options: ReadonlyArray<ListOption>,
  buffer: string,
  from: number,
): number {
  const b = buffer.trim().toLowerCase()
  if (!b || !options.length) return -1
  const n = options.length
  for (let k = 1; k <= n; k++) {
    const i = (from + k) % n
    const o = options[i]
    if (o && !o.disabled && o.label.toLowerCase().startsWith(b)) return i
  }
  return -1
}

export function niceLogScale(min: number, max: number): NiceScale {
  // Only positive values are plottable on a log scale; callers should
  // strip non-positive values before passing them in.
  if (!Number.isFinite(min) || min <= 0) min = 1
  if (!Number.isFinite(max) || max <= min) max = min * 10
  const lo = Math.floor(Math.log10(min))
  const hi = Math.ceil(Math.log10(max))
  const ticks: number[] = []
  for (let p = lo; p <= hi; p += 1) ticks.push(Math.pow(10, p))
  return { min: Math.pow(10, lo), max: Math.pow(10, hi), step: 10, ticks }
}

export function niceScale(min: number, max: number, tickCount = 4): NiceScale {
  if (!Number.isFinite(min) || !Number.isFinite(max)) {
    min = 0
    max = 1
  }
  if (min === max) {
    if (min === 0) max = 1
    else {
      min = Math.min(0, min)
      max = Math.max(0, max)
    }
    if (min === max) max = min + 1
  }
  const range = niceNum(max - min, false)
  const step = niceNum(range / Math.max(1, tickCount), true)
  const nMin = Math.floor(min / step) * step
  const nMax = Math.ceil(max / step) * step
  const ticks: number[] = []
  for (let v = nMin; v <= nMax + step * 0.5; v += step) ticks.push(round(v))
  return { min: nMin, max: nMax, step, ticks }
}

export function normalize(node: DockNode): DockNode | null {
  if (node.type === 'tabs') {
    if (node.panes.length === 0) return null
    return { ...node, active: clampIndex(node.active, node.panes.length) }
  }

  // Normalize children first, dropping the empties.
  const kept: DockNode[] = []
  const keptSizes: number[] = []
  node.children.forEach((child, i) => {
    const n = normalize(child)
    if (n) {
      kept.push(n)
      keptSizes.push(node.sizes[i] ?? 1)
    }
  })

  if (kept.length === 0) return null
  if (kept.length === 1) return kept[0]! // unwrap single-child group

  // Flatten same-direction child groups into this one.
  const flatChildren: DockNode[] = []
  const flatSizes: number[] = []
  kept.forEach((child, i) => {
    if (child.type === 'group' && child.direction === node.direction) {
      const share = keptSizes[i]!
      child.children.forEach((gc, j) => {
        flatChildren.push(gc)
        flatSizes.push(share * (child.sizes[j] ?? 1 / child.children.length))
      })
    } else {
      flatChildren.push(child)
      flatSizes.push(keptSizes[i]!)
    }
  })

  return { ...node, children: flatChildren, sizes: normalizeSizes(flatSizes, flatChildren.length) }
}

export function normalizeOptions(raw: ReadonlyArray<ListOption | string | number> | null | undefined): ListOption[] {
  if (!raw) return []
  return raw.map((o) => {
    if (o != null && typeof o === 'object') {
      const opt = o as Partial<ListOption>
      const value = opt.value ?? opt.label ?? ''
      return { ...(opt as ListOption), value, label: opt.label ?? String(value) }
    }
    return { value: o, label: String(o) }
  })
}

export function normalizeSizes(sizes: number[] | undefined, count: number): number[] {
  if (count <= 0) return []
  const src = sizes && sizes.length === count ? sizes.slice() : new Array(count).fill(1)
  const total = src.reduce((a, b) => a + (b > 0 ? b : 0), 0)
  if (total <= 0) return new Array(count).fill(1 / count)
  return src.map((s) => (s > 0 ? s : 0) / total)
}

export function normalizeTimeZone(timeZone?: string): string | undefined {
  if (!timeZone) return undefined
  try {
    new Intl.DateTimeFormat('en-US', { timeZone })
    return timeZone
  } catch {
    return undefined
  }
}

export function obv(closes: ReadonlyArray<number>, volumes: ReadonlyArray<number>): number[] {
  const n = closes.length
  const out = nanArray(n)
  let total = 0
  for (let i = 0; i < n; i += 1) {
    const v = volumes[i]
    if (!Number.isFinite(closes[i]) || !Number.isFinite(v)) { out[i] = total; continue }
    if (i > 0 && Number.isFinite(closes[i - 1])) {
      if (closes[i]! > closes[i - 1]!) total += v!
      else if (closes[i]! < closes[i - 1]!) total -= v!
    }
    out[i] = total
  }
  return out
}

export function ohlcDirectOptions(
  fieldOf: (id: string | null) => string | null | undefined,
  dateId: string | null,
  cols: OhlcColumns,
  extra: { bucket?: ChartTimeBucket | null; candleStyle?: ChartSpec['candleStyle'] | null },
): { category: string; ohlc: NonNullable<Parameters<typeof import('./chart').rowsToDirectSpec>[2]['ohlc']> } | null {
  const date = fieldOf(dateId)
  const open = fieldOf(cols.open)
  const high = fieldOf(cols.high)
  const low = fieldOf(cols.low)
  const close = fieldOf(cols.close)
  if (!date || !open || !high || !low || !close) return null
  const volume = fieldOf(cols.volume)
  return {
    category: date,
    ohlc: {
      open, high, low, close,
      ...(volume ? { volume } : {}),
      ...(extra.bucket ? { bucket: extra.bucket } : {}),
      ...(extra.candleStyle ? { candleStyle: extra.candleStyle } : {}),
      lastPriceLine: true,
    },
  }
}

export function ordinalDateTicks(times: number[], target = 6): number[] {
  if (times.length <= 1) return times.length ? [0] : []
  const keyOf: Record<string, (d: Date) => number | string> = {
    day: (d) => `${d.getUTCFullYear()}-${d.getUTCMonth()}-${d.getUTCDate()}`,
    // Weeks start on Monday: day 0 of the epoch was a Thursday, so +3 puts
    // the boundary there (+4 put it on Sunday, and weekly ticks sat on Sundays).
    week: (d) => Math.floor((Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()) / DAY + 3) / 7),
    month: (d) => `${d.getUTCFullYear()}-${d.getUTCMonth()}`,
    year: (d) => d.getUTCFullYear(),
  }
  let chosen: number[] | null = null
  for (const unit of ['day', 'week', 'month', 'year'] as const) {
    const at: number[] = []
    let prev: number | string | null = null
    for (let i = 0; i < times.length; i += 1) {
      const t = times[i]!
      if (!Number.isFinite(t)) continue
      const k = keyOf[unit]!(new Date(t))
      if (k !== prev) at.push(i)
      prev = k
    }
    chosen = at
    if (at.length <= target * 2) break
  }
  let out = chosen ?? []
  // Even the coarsest unit can be too dense (a decade of yearly points), and a
  // single trading day yields one boundary. Thin, or fall back to plain strides.
  if (out.length > target) {
    const stride = Math.ceil(out.length / target)
    out = out.filter((_, i) => i % stride === 0)
  }
  if (out.length < 2) {
    const stride = Math.max(1, Math.ceil(times.length / target))
    out = times.map((_, i) => i).filter((i) => i % stride === 0)
  }
  return out
}

export type OverflowMarker<TData = unknown> = {
  topPct: number
  heightPct: number
  leftPct: number
  widthPct: number
  /** Number of hidden events this tile stands for. */
  count: number
  /** The hidden events (chronological), for the "+N more" popover. */
  events: ResolvedEvent<TData>[]
}

export function overlapCount<TData>(
  start: Date,
  end: Date,
  resourceId: string | undefined,
  events: ReadonlyArray<ResolvedEvent<TData>>,
  excludeRowKey?: string,
): number {
  let n = 0
  for (const e of events) {
    if (e.rowKey === excludeRowKey) continue
    if ((e.resourceId ?? undefined) !== (resourceId ?? undefined)) continue
    if (rangesOverlap(start, end, e.start, e.end)) n++
  }
  return n
}

export function overlapsBands(
  sMin: number,
  eMin: number,
  bands: ReadonlyArray<{ start: number; end: number }>,
): boolean {
  for (const b of bands) {
    if (sMin < b.end * 60 && eMin > b.start * 60) return true
  }
  return false
}

export function overlayName(spec: SeriesOverlay): string {
  const m = /^(sma|ema|wma|bb|poly):(\d+)/.exec(spec)
  if (!m) return spec === 'linear' ? 'trend' : spec
  return `${m[1] === 'poly' ? 'poly' : m[1]!.toUpperCase()} ${m[2]}`
}

export function pane(id: string, title: string, closable = true): DockPane {
  return { id, title, closable }
}

export type PaneLocation =
  | { kind: 'main' }
  | { kind: 'floating'; windowId: string }
  | { kind: 'autoHide'; entryId: string }

export function panWindow(win: ChartZoomWindow | null, n: number, delta: number): ChartZoomWindow | null {
  if (!win || !delta) return win
  const span = win.i1 - win.i0
  let a = win.i0 + Math.round(delta)
  a = Math.max(0, Math.min(n - 1 - span, a))
  return clampWindow(a, a + span, n)
}

export function paretoSpec(spec: ChartSpec, threshold = 80): ChartSpec {
  const src = spec.series[0]
  if (!src) return { ...spec, type: 'bar' }
  const order = spec.categories.map((_, i) => i).sort((a, b) => (src.values[b] ?? 0) - (src.values[a] ?? 0))
  const sorted = pickCategories(spec, order)
  const values = sorted.series[0]!.values.map((v) => (Number.isFinite(v) ? Math.max(0, v) : 0))
  const total = values.reduce((a, b) => a + b, 0) || 1
  let cum = 0
  const share = values.map((v) => {
    cum += v
    return Math.round((cum / total) * 1000) / 10
  })
  return {
    ...sorted,
    type: 'bar',
    series: [
      { ...sorted.series[0]!, type: 'bar' },
      { label: 'Cumulative %', values: share, type: 'line', axis: 'right', marker: 'circle', color: sorted.series[0]!.overlayColor ?? '#ef4444' },
    ],
    y2Axis: { min: 0, max: 100, tickInterval: 25, formatter: (v) => `${v}%`, ...(spec.y2Axis ?? {}) },
    referenceLines: [
      ...(spec.referenceLines ?? []),
      ...(threshold > 0 ? [{ value: threshold, axis: 'right' as const, label: `${threshold}%`, dashed: true }] : []),
    ],
  }
}

export function parseDate(
  str: string,
  mask: string,
  locale = 'en-US',
  yearCutoff = 2029,
  base?: Date,
): Date | null {
  const parts = tokenizeMask(mask)
  const acc: Acc = {}
  let i = 0
  const s = str
  for (const p of parts) {
    if ('literal' in p) {
      // Literals must match (whitespace-insensitive at the boundary).
      for (const ch of p.literal) {
        if (ch === ' ') {
          while (s[i] === ' ') i++
          continue
        }
        if (s[i] !== ch) return null
        i++
      }
      continue
    }
    const tok = p.token
    switch (tok) {
      case 'ddd':
      case 'dddd': {
        const m = matchName(s, i, weekdayNames(locale)[tok === 'ddd' ? 'short' : 'long'])
        if (!m) return null
        i += m.len // weekday is informational; day-of-month drives the date
        break
      }
      case 'MMM':
      case 'MMMM': {
        const m = matchName(s, i, monthNames(locale)[tok === 'MMM' ? 'short' : 'long'])
        if (!m) return null
        acc.month = m.index
        i += m.len
        break
      }
      case 't':
      case 'tt': {
        const dp = dayPeriods(locale)
        const lower = s.slice(i).toLowerCase()
        if (lower.startsWith(dp.pm.toLowerCase())) { acc.isPm = true; i += dp.pm.length }
        else if (lower.startsWith(dp.am.toLowerCase())) { acc.isPm = false; i += dp.am.length }
        else if (lower.startsWith(dp.pm.slice(0, 1).toLowerCase())) { acc.isPm = true; i += 1 }
        else if (lower.startsWith(dp.am.slice(0, 1).toLowerCase())) { acc.isPm = false; i += 1 }
        else return null
        break
      }
      default: {
        const r = readDigits(s, i, MAX_DIGITS[tok] ?? 2)
        if (!r) return null
        i += r.len
        const v = r.value
        switch (tok) {
          case 'd': case 'dd': acc.day = v; break
          case 'M': case 'MM': acc.month = v - 1; break
          case 'yy': acc.year = v <= yearCutoff % 100 ? 2000 + v : 1900 + v; break
          case 'yyyy': acc.year = v; break
          case 'H': case 'HH': acc.hour = v; break
          case 'h': case 'hh': acc.hour12 = v; break
          case 'm': case 'mm': acc.minute = v; break
          case 's': case 'ss': acc.second = v; break
          case 'f': acc.ms = v * 100; break
          case 'ff': acc.ms = v * 10; break
          case 'fff': acc.ms = v; break
        }
      }
    }
  }
  // Trailing input that the mask did not consume is a mismatch.
  if (i !== s.length && s.slice(i).trim() !== '') return null

  const b = base ?? new Date(1970, 0, 1)
  let hour = acc.hour
  if (hour == null && acc.hour12 != null) {
    hour = acc.hour12 % 12
    if (acc.isPm) hour += 12
  }
  const year = acc.year ?? b.getFullYear()
  const month = acc.month ?? b.getMonth()
  const day = acc.day ?? b.getDate()
  const result = new Date(
    year,
    month,
    day,
    hour ?? b.getHours(),
    acc.minute ?? b.getMinutes(),
    acc.second ?? b.getSeconds(),
    acc.ms ?? b.getMilliseconds(),
  )
  // Reject impossible dates the constructor silently rolls over (e.g. Feb 31).
  if (
    (acc.day != null && result.getDate() !== day) ||
    (acc.month != null && result.getMonth() !== month)
  ) {
    return null
  }
  return isNaN(result.getTime()) ? null : result
}

export function parseDateValue(value: unknown): Date | null {
  if (value instanceof Date) return Number.isNaN(value.getTime()) ? null : value
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) return null
    const d = new Date(value)
    return Number.isNaN(d.getTime()) ? null : d
  }
  if (typeof value !== 'string') return null
  const s = value.trim()
  if (s === '') return null
  const ymd = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s)
  if (ymd) {
    const [y, m, day] = [Number(ymd[1]), Number(ymd[2]) - 1, Number(ymd[3])]
    const d = new Date(0)
    d.setFullYear(y, m, day)
    d.setHours(0, 0, 0, 0)
    // Reject a rollover ('2026-02-30' is not March 2nd), as `new Date` does.
    return d.getMonth() === m && d.getDate() === day ? d : null
  }
  const d = new Date(s)
  return Number.isNaN(d.getTime()) ? null : d
}

export function parseDuration(input: string): number | null {
  const s = input.trim().toLowerCase()
  if (!s) return null

  const colon = s.match(/^(\d+):(\d{1,2})$/)
  if (colon) {
    const mm = parseInt(colon[2]!, 10)
    if (mm > 59) return null
    return parseInt(colon[1]!, 10) * 60 + mm
  }

  const units = s.match(/\d+(?:\.\d+)?\s*[hm]/g)
  if (units && units.join('').replace(/\s/g, '').length === s.replace(/\s/g, '').length) {
    let total = 0
    for (const part of units) {
      const m = part.match(/(\d+(?:\.\d+)?)\s*([hm])/)!
      const n = parseFloat(m[1]!)
      total += m[2] === 'h' ? n * 60 : n
    }
    return Math.round(total)
  }

  const num = Number(s)
  return Number.isFinite(num) ? Math.round(num) : null
}

export function parsePlacement(p: Placement): { side: Side; align: Align } {
  const [side, align] = p.split('-') as [Side, 'start' | 'end' | undefined]
  return { side, align: align ?? 'center' }
}

export function pathTo(tree: TreeNode, name: string): string[] | null {
  const walk = (n: TreeNode, acc: string[]): string[] | null => {
    for (const c of n.children ?? []) {
      const next = [...acc, c.name]
      if (c.name === name) return next
      const deeper = walk(c, next)
      if (deeper) return deeper
    }
    return null
  }
  return walk(tree, [])
}

export function pearson(xs: ReadonlyArray<number>, ys: ReadonlyArray<number>): number {
  let n = 0, sx = 0, sy = 0
  const len = Math.min(xs.length, ys.length)
  for (let i = 0; i < len; i += 1) if (Number.isFinite(xs[i]) && Number.isFinite(ys[i])) { n += 1; sx += xs[i]!; sy += ys[i]! }
  if (n < 2) return 0
  const mx = sx / n, my = sy / n
  let sxy = 0, sxx = 0, syy = 0
  for (let i = 0; i < len; i += 1) {
    if (!Number.isFinite(xs[i]) || !Number.isFinite(ys[i])) continue
    const dx = xs[i]! - mx, dy = ys[i]! - my
    sxy += dx * dy; sxx += dx * dx; syy += dy * dy
  }
  return sxx === 0 || syy === 0 ? 0 : sxy / Math.sqrt(sxx * syy)
}

export function pendingFormats<TData>(
  pending: ReadonlyArray<Proposal>,
  rowId: (row: TData, index: number) => string,
  columns: ReadonlyArray<{ id: string; field?: string }>,
  look: { background: string; icon: string } = { background: PENDING_BG, icon: PENDING_ICON },
): ConditionalFormat<any>[] {
  const rowsByField = new Map<string, Set<string>>()
  for (const p of pending) {
    let ids = rowsByField.get(p.field)
    if (!ids) rowsByField.set(p.field, (ids = new Set()))
    ids.add(p.rowId)
  }
  const out: ConditionalFormat<any>[] = []
  for (const [field, ids] of rowsByField) {
    const cols = columns.filter((c) => (c.field ?? c.id) === field).map((c) => c.id)
    out.push({
      type: 'rule',
      columns: cols.length ? cols : [field],
      when: ({ row }: { row: TData }) => ids.has(String(rowId(row, 0))),
      background: look.background,
      icon: look.icon,
    })
  }
  return out
}

export function percentile(samples: ReadonlyArray<number>, p: number): number {
  const v = samples.filter((n) => Number.isFinite(n)).slice().sort((a, b) => a - b)
  if (!v.length) return Number.NaN
  const pos = (v.length - 1) * Math.max(0, Math.min(100, p)) / 100
  const lo = Math.floor(pos)
  const hi = Math.ceil(pos)
  return lo === hi ? v[lo]! : v[lo]! + (v[hi]! - v[lo]!) * (pos - lo)
}

export function pickCategories(spec: ChartSpec, indices: ReadonlyArray<number>): ChartSpec {
  const pick = <T,>(arr: T[] | undefined): T[] | undefined => {
    if (!arr) return undefined
    const out: T[] = new Array(indices.length)
    for (let k = 0; k < indices.length; k += 1) out[k] = arr[indices[k]!]!
    return out
  }
  const series = spec.series.map((s) => {
    const next: ChartSeries = { ...s, values: pick(s.values) ?? [] }
    for (const key of PER_CATEGORY_SERIES_KEYS) {
      if (key === 'values') continue
      const arr = s[key] as unknown[] | undefined
      if (arr) (next as unknown as Record<string, unknown>)[key] = pick(arr)
    }
    return next
  })
  const out: ChartSpec = { ...spec, categories: pick(spec.categories) ?? [], series }
  for (const key of PER_CATEGORY_SPEC_KEYS) {
    const arr = spec[key] as unknown[] | undefined
    if (arr) (out as unknown as Record<string, unknown>)[key] = pick(arr)
  }
  return out
}

export function pickContrastText(bgHex: string): string {
  const rgb = hexToRgb(bgHex)
  if (!rgb) return '#0f172a'
  const lin = (c: number) => {
    const s = c / 255
    return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4)
  }
  const L = 0.2126 * lin(rgb.r) + 0.7152 * lin(rgb.g) + 0.0722 * lin(rgb.b)
  return L > 0.5 ? '#0f172a' : '#ffffff'
}

export function pinAutoHidden(
  state: DockManagerState,
  entryId: string,
  genId: IdGen,
  fraction = 0.25,
): DockManagerState {
  const entry = state.autoHide.find((e) => e.id === entryId)
  if (!entry) return state
  const leaf = tabs(genId, entry.leaf.panes, entry.leaf.active)
  return {
    ...state,
    autoHide: state.autoHide.filter((e) => e.id !== entryId),
    main: dockLeafToEdge(state.main, leaf, entry.side, genId, fraction),
  }
}

export function pinchWindow(win: ChartZoomWindow | null, n: number, midpoint: number, scale: number): ChartZoomWindow | null {
  if (!Number.isFinite(scale) || scale <= 0) return win
  return wheelWindow(win, n, midpoint, 1 / scale)
}

export type PivotChartOptions = {
