export function polynomialFit(values: ReadonlyArray<number>, degree: number, xs?: ReadonlyArray<number>): RegressionFit {
  const d = Math.max(1, Math.min(6, Math.round(degree)))
  const n = values.length
  const nan = NO_FIT(values)
  const X = xsOf(values, xs)
  const idx: number[] = []
  for (let i = 0; i < n; i += 1) if (Number.isFinite(values[i]) && Number.isFinite(X[i])) idx.push(i)
  if (idx.length <= d) return nan
  let lo = Infinity
  let hi = -Infinity
  for (const i of idx) { lo = Math.min(lo, X[i]!); hi = Math.max(hi, X[i]!) }
  if (!xs) { lo = 0; hi = Math.max(1, n - 1) }
  const scale = Math.max(hi - lo, 1e-12)
  const nx = (x: number) => (2 * (x - lo)) / scale - 1
  // Normal equations: sum x^(j+k) c_k = sum x^j y.
  const a: number[][] = Array.from({ length: d + 1 }, () => new Array(d + 1).fill(0))
  const b: number[] = new Array(d + 1).fill(0)
  for (const i of idx) {
    const x = nx(X[i]!)
    const y = values[i]!
    const pow: number[] = [1]
    for (let k = 1; k <= 2 * d; k += 1) pow.push(pow[k - 1]! * x)
    for (let j = 0; j <= d; j += 1) {
      b[j]! += pow[j]! * y
      for (let k = 0; k <= d; k += 1) a[j]![k]! += pow[j + k]!
    }
  }
  const c = solve(a, b)
  if (!c) return nan
  const predict = (x: number) => {
    const u = nx(x)
    let y = 0
    let p = 1
    for (let k = 0; k <= d; k += 1) { y += c[k]! * p; p *= u }
    return y
  }
  const fitted = values.map((v, i) => (Number.isFinite(v) && Number.isFinite(X[i]) ? predict(X[i]!) : NaN))
  const terms = c.map((ck, k) => (k === 0 ? fmtCoef(ck) : `${fmtCoef(ck)} u^${k}`)).reverse()
  const u = xs ? `u = 2(x - ${fmtCoef(lo)})/${fmtCoef(scale)} - 1` : `u = 2x/${scale} - 1`
  return { fitted, r2: rSquared(values, fitted), equation: `y = ${terms.join(' + ')} (${u})`, predict }
}

export function powerFit(values: ReadonlyArray<number>, xs?: ReadonlyArray<number>): RegressionFit {
  const shift = xs ? 0 : 1
  const lx = xsOf(values, xs).map((x) => (x + shift > 0 ? Math.log(x + shift) : NaN))
  const logs = values.map((v) => (Number.isFinite(v) && v > 0 ? Math.log(v) : NaN))
  const { slope, intercept, ok } = lineThrough(lx, logs)
  if (!ok) return NO_FIT(values)
  const a = Math.exp(intercept)
  const predict = (x: number) => (x + shift > 0 ? a * Math.pow(x + shift, slope) : NaN)
  const fitted = values.map((v, i) => (Number.isFinite(v) && v > 0 && Number.isFinite(lx[i]) ? a * Math.exp(slope * lx[i]!) : NaN))
  const arg = xs ? 'x' : '(x + 1)'
  return { fitted, r2: rSquared(values, fitted), equation: `y = ${fmtCoef(a)} ${arg}^${fmtCoef(slope)}`, predict }
}

export function presetWindow(categories: ReadonlyArray<string>, preset: ChartRangePreset, now?: number): ChartZoomWindow | null {
  const n = categories.length
  if (!n) return null
  const times = categories.map((c) => Date.parse(c))
  const last = [...times].reverse().find(Number.isFinite)
  if (last == null) return null
  const end = now ?? last
  const DAY = 86_400_000
  let from: number
  let to = end
  if (typeof preset === 'object') {
    if (preset.from) from = Date.parse(preset.from)
    else if (preset.days) from = end - preset.days * DAY
    else return null
    if (preset.to) to = Date.parse(preset.to)
  } else {
    switch (preset) {
      case '1W': from = end - 7 * DAY; break
      case '1M': from = shiftMonths(end, -1); break
      case '3M': from = shiftMonths(end, -3); break
      case '6M': from = shiftMonths(end, -6); break
      case '1Y': from = shiftMonths(end, -12); break
      case 'YTD': { const d = new Date(end); from = Date.UTC(d.getUTCFullYear(), 0, 1); break }
      default: return null
    }
  }
  if (!Number.isFinite(from) || !Number.isFinite(to)) return null
  let i0 = -1
  let i1 = -1
  for (let i = 0; i < n; i += 1) {
    const t = times[i]!
    if (!Number.isFinite(t)) continue
    if (t >= from && i0 < 0) i0 = i
    if (t <= to) i1 = i
  }
  if (i0 < 0 || i1 < 0 || i1 < i0) return null
  return clampWindow(i0, i1, n)
}

export function printChart(source: SVGSVGElement | HTMLElement, options: ChartExportOptions & { title?: string } = {}): boolean {
  const svg = chartToSvgString(source, options)
  const win = window.open('', '_blank', 'width=900,height=700')
  if (!win) return false
  const esc = (s: string) => s.replace(/[&<>]/g, (m) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[m]!)
  win.document.write(
    `<!doctype html><html><head><meta charset="utf-8"><title>${esc(options.title ?? 'Chart')}</title>` +
      `<style>body{margin:24px;font-family:system-ui,sans-serif}h1{font-size:16px;margin:0 0 12px}svg{max-width:100%;height:auto}@page{margin:12mm}</style></head><body>` +
      (options.title ? `<h1>${esc(options.title)}</h1>` : '') +
      svg +
      `</body></html>`,
  )
  win.document.close()
  const go = () => { win.focus(); win.print() }
  if (win.document.readyState === 'complete') setTimeout(go, 50)
  else win.addEventListener('load', () => setTimeout(go, 50))
  return true
}

export async function projectRows<TData extends RowData>(
  sourceRows: ReadonlyArray<TData>,
  cols: ReadonlyArray<ExportColumn<TData>>,
  opts: Pick<ExportOptions<TData>, 'rawValues' | 'onProgress' | 'signal'>,
): Promise<Array<Record<string, unknown>>> {
  const rawValues = opts.rawValues === true
  const headerRow: Record<string, unknown> = {}
  for (const c of cols) headerRow[c.field] = c.header ?? c.field

  const projected: Array<Record<string, unknown>> = [headerRow]
  const total = sourceRows.length
  const CHUNK = 5000
  for (let i = 0; i < total; i++) {
    if (opts.signal?.aborted) throw new DOMException('Export aborted', 'AbortError')
    const r = sourceRows[i]!
    const row: Record<string, unknown> = {}
    for (const c of cols) row[c.field] = cellValueFor(c, r, rawValues)
    projected.push(row)
    if (i > 0 && i % CHUNK === 0) {
      opts.onProgress?.({ phase: 'project', ratio: i / total, row: i, total })
      await new Promise((resolve) => setTimeout(resolve, 0))
    }
  }
  opts.onProgress?.({ phase: 'project', ratio: 1, row: total, total })
  return projected
}

