export function rangeForView(
  view: SchedulerView,
  anchor: Date,
  weekStartsOn = 0,
  agendaDays = 30,
): { start: Date; end: Date } {
  switch (view) {
    case 'month': {
      const start = startOfWeek(startOfMonth(anchor), weekStartsOn)
      return { start, end: addDays(start, 42) } // fixed 6-week grid
    }
    case 'week': {
      const start = startOfWeek(anchor, weekStartsOn)
      return { start, end: addDays(start, 7) }
    }
    case 'day': {
      const start = startOfDay(anchor)
      return { start, end: addDays(start, 1) }
    }
    case 'agenda': {
      const start = startOfDay(anchor)
      return { start, end: addDays(start, Math.max(1, agendaDays)) }
    }
    case 'timelineDay':
      return { start: startOfDay(anchor), end: addDays(startOfDay(anchor), 1) }
    case 'timelineWeek': {
      const start = startOfWeek(anchor, weekStartsOn)
      return { start, end: addDays(start, 7) }
    }
    case 'timelineMonth': {
      const start = startOfMonth(anchor)
      return { start, end: startOfMonth(addMonths(anchor, 1)) }
    }
    case 'timelineYear': {
      const start = new Date(anchor.getFullYear(), 0, 1)
      return { start, end: new Date(anchor.getFullYear() + 1, 0, 1) }
    }
  }
}

export async function readImportMatrix(
  file: File | Blob | string,
  format: ImportFormat = 'auto',
  opts: { maxBytes?: number; encoding?: string; signal?: AbortSignal } = {},
): Promise<{ format: Exclude<ImportFormat, 'auto'>; matrix: string[][] }> {
  if (opts.signal?.aborted) throw abortError()
  // Guard the byte size BEFORE reading, so an oversized upload never lands
  // in memory.
  if (opts.maxBytes != null && file instanceof Blob && file.size > opts.maxBytes) {
    throw new Error(
      `@svgrid/enterprise: file is ${file.size.toLocaleString()} bytes, ` +
        `over the ${opts.maxBytes.toLocaleString()}-byte import limit.`,
    )
  }
  const fmt = sniffFormat(file, format)
  let matrix: string[][]
  if (fmt === 'xlsx') {
    if (typeof file === 'string') {
      throw new Error(
        '@svgrid/enterprise: xlsx import expects a File or Blob, not a string. ' +
          'Use format: "csv" or "tsv" for inline text.',
      )
    }
    matrix = await parseXlsx(file)
  } else if (fmt === 'json') {
    const text = typeof file === 'string' ? file : await readText(file, opts.encoding)
    matrix = jsonToMatrix(text)
  } else {
    const sep = fmt === 'tsv' ? '\t' : ','
    const text = typeof file === 'string' ? file : await readText(file, opts.encoding)
    matrix = parseDelimited(text, sep)
  }
  if (opts.signal?.aborted) throw abortError()
  return { format: fmt, matrix }
}

export function reducerNeedsSamples(reducer: ChartReducer): boolean {
  return !(reducer === 'sum' || reducer === 'avg' || reducer === 'count')
}

export function reduceValues(samples: ReadonlyArray<number>, reducer: ChartReducer): number {
  const n = samples.length
  switch (reducer) {
    case 'count':
      return n
    case 'sum': {
      let s = 0
      for (const v of samples) s += v
      return s
    }
    case 'avg': {
      if (!n) return 0
      let s = 0
      for (const v of samples) s += v
      return s / n
    }
    case 'min':
      return n ? Math.min(...samples) : Number.NaN
    case 'max':
      return n ? Math.max(...samples) : Number.NaN
    case 'first':
      return n ? samples[0]! : Number.NaN
    case 'last':
      return n ? samples[n - 1]! : Number.NaN
    case 'countDistinct':
      return new Set(samples).size
    case 'median':
      return percentile(samples, 50)
    default: {
      const m = /^p(\d+(?:\.\d+)?)$/.exec(reducer)
      return m ? percentile(samples, Number(m[1])) : Number.NaN
    }
  }
}

