      .filter((k) => !k.startsWith('_'))
      .map((field) => ({ field }) as ExportColumn<TData>)
  }
  return []
}

export function resolveDatePattern(
  pattern: string | undefined,
  kind: 'date' | 'datetime',
): Intl.DateTimeFormatOptions | undefined {
  if (!pattern) return undefined

  const p = pattern.trim()

  switch (p) {
    /** Short numeric local date (no weekday). */
    case 'd':
      return kind === 'datetime'
        ? {
            year: 'numeric',
            month: 'numeric',
            day: 'numeric',
            hour: 'numeric',
            minute: 'numeric',
          }
        : { year: 'numeric', month: 'numeric', day: 'numeric' }
    /** Long spelled-out date (+ time if datetime). */
    case 'D':
      return kind === 'datetime'
        ? {
            weekday: 'long',
            year: 'numeric',
            month: 'long',
            day: 'numeric',
            hour: 'numeric',
            minute: 'numeric',
          }
        : { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }
    /** ISO-friendly yyyy-mm-dd (with time when datetime). */
    case 'y-m-d':
      return kind === 'datetime'
        ? {
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
            hour12: false,
          }
        : { year: 'numeric', month: '2-digit', day: '2-digit' }
    case 'medium':
      return { dateStyle: 'medium', timeStyle: kind === 'datetime' ? 'short' : undefined }
    case 'short':
      return { dateStyle: 'short', timeStyle: kind === 'datetime' ? 'short' : undefined }
    case 'long':
      return { dateStyle: 'long', timeStyle: kind === 'datetime' ? 'short' : undefined }
    default:
      return undefined
  }
}

export type ResolvedEvent<TData = unknown> = {
  key: string
  rowKey: string
  row: TData
  title: string
  start: Date
  end: Date
