export function resolveEvents<TData>(
  rows: ReadonlyArray<TData>,
  spec: EventSpec<TData>,
  rangeStart: Date,
  rangeEnd: Date,
): ResolvedEvent<TData>[] {
  const defDur = Math.max(1, spec.defaultDurationMin ?? 60)
  const out: ResolvedEvent<TData>[] = []

  for (const row of rows) {
    const start = toDate(spec.getStart(row))
    if (!start) continue
    const rawEnd = spec.getEnd ? toDate(spec.getEnd(row)) : null
    const end =
      rawEnd && rawEnd.getTime() > start.getTime()
        ? rawEnd
        : new Date(start.getTime() + defDur * MS_MIN)
    const durationMs = end.getTime() - start.getTime()

    const rowKey = spec.getKey(row)
    const title = spec.getTitle?.(row) ?? ''
    const allDay = spec.getAllDay?.(row) ?? false
    const color = spec.getColor?.(row)
    const color2 = spec.getSecondaryColor?.(row)
    const status = spec.getStatus?.(row)
    const resourceId = spec.getResource?.(row)
    const rule = spec.getRecurrence?.(row)

    if (rule) {
      // One instance per matching day, carrying the base time-of-day + duration.
      // Recurrence begins at the event's OWN start - never emit an occurrence
      // before it, so clip the expansion's lower bound to the start date (a rule
      // like "weekly on Mon-Fri" must not back-fill days before the event began).
      const from = start.getTime() > rangeStart.getTime() ? start : rangeStart
      const days = expandRecurrence(rule, from, rangeEnd)
      // Per-occurrence overrides keyed by the occurrence's canonical start time.
      const exs = spec.getExceptions?.(row)
      const exMap = exs?.length
        ? new Map(exs.map((e) => [toDate(e.occurrenceStart)?.getTime() ?? NaN, e]))
        : null
      for (const day of days) {
        const occStart = allDay ? startOfDay(day) : withTime(day, start)
        const ex = exMap?.get(occStart.getTime())
        if (ex?.deleted) continue // this occurrence was removed
        let iStart = occStart
        let iEnd = new Date(occStart.getTime() + durationMs)
        let iTitle = title
        let iAllDay = allDay
        // Per-occurrence overrides of ANY other field: merge onto a copy of the
        // row for this instance, then re-derive the surfaced props from it so a
        // "This event" change to attendees / calendar / color / resource shows.
        let iRow = row
        let iColor = color
        let iColor2 = color2
        let iStatus = status
        let iResource = resourceId
        if (ex) {
          const exS = toDate(ex.start)
          const exE = toDate(ex.end)
          if (exS) {
            iStart = exS
            iEnd = exE && exE.getTime() > exS.getTime() ? exE : new Date(exS.getTime() + durationMs)
          } else if (exE) {
            iEnd = exE
          }
          if (ex.title != null) iTitle = ex.title
          if (ex.allDay != null) iAllDay = ex.allDay
          if (ex.fields) {
            iRow = { ...(row as Record<string, unknown>), ...ex.fields } as TData
            iColor = spec.getColor?.(iRow) ?? color
            iColor2 = spec.getSecondaryColor?.(iRow) ?? color2
            iStatus = spec.getStatus?.(iRow) ?? status
            iResource = spec.getResource?.(iRow) ?? resourceId
            if (ex.title == null) iTitle = spec.getTitle?.(iRow) ?? iTitle
          }
        }
        if (!rangesOverlap(iStart, iEnd, rangeStart, rangeEnd)) continue
        out.push({
          // Key on the CANONICAL occurrence start so a moved occurrence keeps its identity.
          key: `${rowKey}#${occStart.getFullYear()}-${occStart.getMonth() + 1}-${occStart.getDate()}T${occStart.getHours()}:${occStart.getMinutes()}`,
          rowKey,
          row: iRow,
          title: iTitle,
          start: iStart,
          end: iEnd,
          allDay: iAllDay,
          color: iColor,
          color2: iColor2,
          status: iStatus,
          resourceId: iResource,
          recurring: true,
          occurrenceStart: occStart,
          isException: !!ex,
        })
      }
    } else if (rangesOverlap(start, end, rangeStart, rangeEnd)) {
      out.push({
        key: rowKey,
        rowKey,
        row,
        title,
        start,
        end,
        allDay,
        color,
        color2,
        status,
        resourceId,
        recurring: false,
      })
    }
  }

  out.sort((a, b) => {
    const d = a.start.getTime() - b.start.getTime()
    if (d !== 0) return d
    if (a.allDay !== b.allDay) return a.allDay ? -1 : 1
    return a.end.getTime() - b.end.getTime()
  })
  return out
}

export function resolveGridMessages(overrides?: Partial<GridMessages> | null): GridChromeMessages {
  return resolveMessages(defaultGridMessages, overrides)
}

export function resolveMessages<T extends Record<string, string>>(
  defaults: T,
  overrides?: Partial<T> | null,
): T {
  if (!overrides) return defaults
  const out = { ...defaults }
  for (const k in overrides) {
    const v = overrides[k]
    if (v != null && v !== '') out[k] = v as T[Extract<keyof T, string>]
  }
  return out
}

export function resolveResponsive(spec: ChartSpec, width: number, height: number): ChartSpec {
  const hits = matchResponsiveRules(spec.responsive, width, height)
  if (!hits.length) return spec
  let out: ChartSpec = spec
  for (const rule of hits) {
    if (!rule.spec) continue
    const { width: _w, height: _h, responsive: _r, ...patch } = rule.spec
    const merged: ChartSpec = { ...out, ...patch }
    for (const k of ['xAxis', 'yAxis', 'y2Axis'] as const) {
      if (patch[k]) merged[k] = { ...(out[k] ?? {}), ...patch[k] }
    }
    out = merged
  }
  return out
}

export function resolveRowSource<TFeatures extends TableFeatures, TData extends RowData>(
  api: SvGridApi<TFeatures, TData>,
  source: ExportRowSource<TData> | undefined,
): ReadonlyArray<TData> {
