export type SpanColumn<TData = Record<string, unknown>> = {
  id: string
  field?: string
  colSpan?: (params: { data: TData; rowIndex: number; columnId: string; value: unknown }) => number
  rowSpan?: (params: { data: TData; rowIndex: number; columnId: string; value: unknown }) => number
}

export function spansToMerges<TData = Record<string, unknown>>(
  rows: ReadonlyArray<TData>,
  columns: ReadonlyArray<SpanColumn<TData>>,
  getValue?: (row: TData, columnId: string) => unknown,
): MergeSpec[] {
  const merges: MergeSpec[] = []
  const covered = new Set<string>()
  for (let r = 0; r < rows.length; r += 1) {
    const row = rows[r]!
    for (let ci = 0; ci < columns.length; ci += 1) {
      const col = columns[ci]!
      if (!col.colSpan && !col.rowSpan) continue
      const key = `${r}:${ci}`
      if (covered.has(key)) continue
      const value = getValue
        ? getValue(row, col.id)
        : (row as Record<string, unknown>)[col.field ?? col.id]
      const params = { data: row, rowIndex: r, columnId: col.id, value }
      const cs = Math.max(1, Math.floor(col.colSpan?.(params) ?? 1))
      const rs = Math.max(1, Math.floor(col.rowSpan?.(params) ?? 1))
      if (cs <= 1 && rs <= 1) continue
      merges.push({
        rowIndex: r,
        columnId: col.id,
        colspan: cs > 1 ? cs : undefined,
        rowspan: rs > 1 ? rs : undefined,
      })
      for (let dr = 0; dr < rs; dr += 1) {
        for (let dc = 0; dc < cs; dc += 1) {
          if (dr === 0 && dc === 0) continue
          covered.add(`${r + dr}:${ci + dc}`)
        }
      }
    }
  }
  return merges
}

export function specToCalendar(spec: ChartSpec): Array<{ date: string; value: number }> {
  const s = spec.series[0]
  const out: Array<{ date: string; value: number }> = []
  spec.categories.forEach((c, i) => {
    const t = Date.parse(c)
    if (!Number.isFinite(t)) return
    const v = s?.values[i]
    if (typeof v !== 'number' || !Number.isFinite(v)) return
    out.push({ date: new Date(t).toISOString().slice(0, 10), value: v })
  })
  return out
}

export function specToSankey(spec: ChartSpec): {
  nodes: Array<{ id: string; label?: string }>
  links: Array<{ source: string; target: string; value: number }>
} {
  const links: Array<{ source: string; target: string; value: number }> = []
  const ids = new Set<string>()
  spec.categories.forEach((from, i) => {
    for (const s of spec.series) {
      const v = s.values[i]
      if (typeof v !== 'number' || !Number.isFinite(v) || v <= 0) continue
      // Sources and targets share a namespace, so a value appearing on both
      // sides would otherwise become one node with a cycle through it.
      const source = `from:${from}`
      const target = `to:${s.label}`
      if (source === target) continue
      ids.add(source)
      ids.add(target)
      links.push({ source, target, value: v })
    }
  })
  return {
    nodes: [...ids].map((id) => ({ id, label: id.slice(id.indexOf(':') + 1) })),
    links,
  }
}

export function specToTreemap(spec: ChartSpec, rootName = 'Total'): TreeNode {
  const positive = (v: unknown) => (typeof v === 'number' && Number.isFinite(v) && v > 0 ? v : 0)
  if (spec.series.length <= 1) {
    const s = spec.series[0]
    return {
      name: rootName,
      children: spec.categories
        .map((name, i) => ({ name, value: positive(s?.values[i]) }))
        .filter((n) => n.value > 0),
    }
  }
  return {
    name: rootName,
    children: spec.categories
      .map((name, i) => ({
        name,
        children: spec.series
          .map((s) => ({ name: s.label, value: positive(s.values[i]) }))
          .filter((n) => n.value > 0),
      }))
      .filter((n) => n.children.length > 0),
  }
}

export function splitPanelIndicators(kinds: ReadonlyArray<ChartPanelIndicator>): { panes: ChartIndicatorSpec[]; overlay: SeriesOverlay | null } {
  const OVERLAY: Partial<Record<ChartPanelIndicator, SeriesOverlay>> = { sma: 'sma:20', ema: 'ema:20', bb: 'bb:20:2', vwap: 'vwap' }
  const panes: ChartIndicatorSpec[] = []
  let overlay: SeriesOverlay | null = null
  for (const k of kinds) {
    const o = OVERLAY[k]
    if (o) { overlay ??= o; continue }
    if (k === 'volume' || k === 'rsi' || k === 'macd' || k === 'stochastic' || k === 'atr' || k === 'obv') panes.push({ kind: k })
  }
  return { panes, overlay }
}

export type SpreadsheetActionOptions = {
  merges?: ReadonlyArray<MergeSpec> | null
  borders?: ReadonlyArray<CellBorderSpec> | null
