   *  Pass `columns.map((c) => c.id)` from the consumer. */
  columnOrder: ReadonlyArray<string>
}

export function spreadsheetLayout(node: HTMLElement, opts: SpreadsheetActionOptions) {
  let current = opts
  let frame = 0
  const OBSERVE_OPTIONS: MutationObserverInit = {
    childList: true,
    subtree: true,
    attributes: true,
    attributeFilter: [
      'data-svgrid-row', 'data-col-id', 'style',
      // Watch selection-range attrs so we can transfer them from
      // hidden covered cells to merge origins.
      'data-range-top', 'data-range-bottom', 'data-range-left',
      'data-range-right', 'data-selected-range',
    ],
  }
  // The MutationObserver fires for EVERY DOM change inside the grid -
  // batch them into one rAF so a big virtualization scroll doesn't run
  // apply() dozens of times in a tick.
  function schedule() {
    if (frame) return
    frame = requestAnimationFrame(() => {
      frame = 0
      // Stop observing while apply() mutates the DOM itself (it writes cell
      // `style.display`/`position` and appends overlay children). Otherwise
      // those writes re-trigger this observer and loop at 60fps on merged
      // cells (#50). A full apply() recomputes from the live DOM, so discarding
      // the queued records here loses nothing.
      observer.disconnect()
      apply(node, current)
      observer.observe(node, OBSERVE_OPTIONS)
    })
  }
  const observer = new MutationObserver(schedule)
  observer.observe(node, OBSERVE_OPTIONS)
  // First-paint pass: schedule the same way so we don't run before the
  // grid's initial render landed.
  schedule()
  return {
    update(next: SpreadsheetActionOptions) {
      current = next
      schedule()
    },
    destroy() {
      observer.disconnect()
      if (frame) cancelAnimationFrame(frame)
    },
  }
}

export function startOfDay(d: Date): Date {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate())
}

export function startOfMonth(d: Date): Date {
  return new Date(d.getFullYear(), d.getMonth(), 1)
}

export function startOfWeek(d: Date, firstDayOfWeek = 0): Date {
  const start = startOfDay(d)
  const diff = (start.getDay() - firstDayOfWeek + 7) % 7
  start.setDate(start.getDate() - diff)
  return start
}

export function stochastic(ohlc: ReadonlyArray<OhlcBar | null | undefined>, period = 14, smooth = 3): { k: number[]; d: number[] } {
  const n = ohlc.length
  const p = Math.max(1, Math.floor(period))
  const k = nanArray(n)
  for (let i = p - 1; i < n; i += 1) {
    let hi = -Infinity
    let lo = Infinity
    let ok = true
    for (let j = i - p + 1; j <= i; j += 1) {
      const b = ohlc[j]
      if (!b) { ok = false; break }
      if (b.h > hi) hi = b.h
      if (b.l < lo) lo = b.l
    }
    const c = ohlc[i]?.c
    if (!ok || c == null) continue
    k[i] = hi === lo ? 50 : ((c - lo) / (hi - lo)) * 100
  }
  // %D is a strict average: it starts once `smooth` %K values exist, rather
  // than averaging whatever is there (which is what the tolerant SMA does).
  const sm = Math.max(1, Math.floor(smooth))
  const d = nanArray(n)
  for (let i = sm - 1; i < n; i += 1) {
    let sum = 0
    let ok = true
    for (let j = i - sm + 1; j <= i; j += 1) {
      if (!Number.isFinite(k[j])) { ok = false; break }
      sum += k[j]!
    }
    if (ok) d[i] = sum / sm
  }
  return { k, d }
}

